window.__YIJING_READINGS__=[{"id":1,"name":"乾","pinyin":"qián","theme":"主动、创造与自律","reflection":"适合把想法落实为第一步；保持谦逊，别让用力过猛遮住他人的声音。","source_note":"据《周易》乾卦意象整理","upper_trigram":1,"lower_trigram":1,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：这一爻处在起步处，“开创需要主动，也需要让力量受责任约束”仍需低成本试探 若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大行动速度可能快过他人的承接能力 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若把坚定变成强推会在此时放大，行动应当收束。","classic":"潛龍勿用。","source":"《周易》爻辞","modern":{"image":"“潛龍勿用。”是乾在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“开创需要主动，也需要让力量受责任约束”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大行动速度可能快过他人的承接能力。","warning":"把坚定变成强推会在此时放大。","advice":["把目标压成一个可交付的小步骤。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"暂停","meaning":"在乾第1爻里，爻辞给出明确的收势信号，眼下不宜把意愿直接变成大动作，可用“这一步是在创造条件，还是只想证明自己”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"暂停","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实条件尚不足以支持扩大动作”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把坚定变成强推会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录乾初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"局面正从内部准备转向真实互动，关系与条件逐渐可见 当前拉扯在于：此时一面是自己的节奏需要与现实反馈相互校准，另一面是行动速度可能快过他人的承接能力，两者要放在同一次权衡里 当关键条件开始出现可利用的现实回应时，变化才有现实依据。先做“把目标压成一个可交付的小步骤”；若出现“把坚定变成强推”，就暂停扩大动作。","classic":"見龍在田，利見大人。","source":"《周易》爻辞","modern":{"image":"“見龍在田，利見大人。”是乾在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是行动速度可能快过他人的承接能力，两者要放在同一次权衡里。","warning":"把坚定变成强推。","advice":["把目标压成一个可交付的小步骤。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"有利","meaning":"在乾第2爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“这一步是在创造条件，还是只想证明自己”核对判断"},"tone":"接触","extended":{"trigger":{"label":"有利","observe":"完成“把目标压成一个可交付的小步骤”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“把目标压成一个可交付的小步骤”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把目标压成一个可交付的小步骤”，可以保持小步推进。","pause_if":"若出现“把坚定变成强推”，先暂停扩大投入。"},"action":{"do":"把目标压成一个可交付的小步骤","review":"完成后记录乾九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻把变化落在具体环节：局面来到内外转换处，“主动、创造与自律”开始承受压力测试 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意把坚定变成强推。","classic":"君子終日乾乾，夕惕若，厲无咎。","source":"《周易》爻辞","modern":{"image":"“君子終日乾乾，夕惕若，厲无咎。”是乾在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“主动、创造与自律”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大行动速度可能快过他人的承接能力。","warning":"把坚定变成强推。","advice":["把目标压成一个可交付的小步骤。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"守正","meaning":"在乾第3爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“这一步是在创造条件，还是只想证明自己”核对判断"},"tone":"转折","extended":{"trigger":{"label":"守正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把坚定变成强推”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录乾九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：乾来到四位，跨出原有边界之前要先说明责任 此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是行动速度可能快过他人的承接能力，两者要放在同一次权衡里 可以用“把目标压成一个可交付的小步骤”做一次验证；若把坚定变成强推，而不是把用更大力度掩盖信息不足当成解决办法，而乾第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位，行动应当收束。","classic":"或躍在淵，无咎。","source":"《周易》爻辞","modern":{"image":"“或躍在淵，无咎。”是乾在“越界”阶段留下的具体图景。","situation":"乾来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是行动速度可能快过他人的承接能力，两者要放在同一次权衡里。","warning":"把坚定变成强推，而不是把用更大力度掩盖信息不足当成解决办法，而乾第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位。","advice":["把目标压成一个可交付的小步骤。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在乾第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“这一步是在创造条件，还是只想证明自己”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“把目标压成一个可交付的小步骤”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“把目标压成一个可交付的小步骤”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把目标压成一个可交付的小步骤”，可以保持小步推进。","pause_if":"若出现“把坚定变成强推，而不是把用更大力度掩盖信息不足当成解决办法，而乾第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位”，先暂停扩大投入。"},"action":{"do":"把目标压成一个可交付的小步骤","review":"完成后记录乾九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一阶段已进入主位，选择会放大为规则或示范 当前拉扯在于：若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大行动速度可能快过他人的承接能力 当关键条件开始出现可利用的现实回应时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“把坚定变成强推会在此时放大”，就暂停扩大动作。","classic":"飛龍在天，利見大人。","source":"《周易》爻辞","modern":{"image":"“飛龍在天，利見大人。”是乾在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大行动速度可能快过他人的承接能力。","warning":"把坚定变成强推会在此时放大。","advice":["把目标压成一个可交付的小步骤。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"有利","meaning":"在乾第5爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“这一步是在创造条件，还是只想证明自己”核对判断"},"tone":"担当","extended":{"trigger":{"label":"有利","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把坚定变成强推会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录乾九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"这一爻把变化落在具体环节：局面走到极处，继续延长旧办法未必带来同等收益 原有做法显出明确代价，需要及时调整，是接下来值得核对的信号。完成“把目标压成一个可交付的小步骤”后再看反馈；同时留意把坚定变成强推。","classic":"亢龍有悔。","source":"《周易》爻辞","modern":{"image":"“亢龍有悔。”是乾在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是行动速度可能快过他人的承接能力，两者要放在同一次权衡里。","warning":"把坚定变成强推。","advice":["把目标压成一个可交付的小步骤。","列出应当停止、保留和移交的事项。"],"signal":{"label":"修正","meaning":"在乾第6爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“这一步是在创造条件，还是只想证明自己”核对判断"},"tone":"收束","extended":{"trigger":{"label":"修正","observe":"完成“把目标压成一个可交付的小步骤”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把目标压成一个可交付的小步骤”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把目标压成一个可交付的小步骤”，可以保持小步推进。","pause_if":"若出现“把坚定变成强推”，先暂停扩大投入。"},"action":{"do":"把目标压成一个可交付的小步骤","review":"完成后记录乾上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"开创需要主动，也需要让力量受责任约束","strengths":["已有推动事情向前的意愿与创造力","适合把想法落实为第一步"],"tensions":["行动速度可能快过他人的承接能力"],"risks":["把坚定变成强推"],"actions":["把目标压成一个可交付的小步骤"],"avoid":["用更大力度掩盖信息不足"],"questions":["这一步是在创造条件，还是只想证明自己？"],"extended":{"situation":{"direct":"眼下的重点是开创需要主动，也需要让力量受责任约束。","support":"已经可以利用的是：已有推动事情向前的意愿与创造力。","constraint":"仍需核实的是：行动速度可能快过他人的承接能力。"},"relationship":{"inner":"下卦乾，内部动力偏向主动、原则与承担。","outer":"上卦乾，外部处境更受主动、原则与承担影响。","interaction":"内部想以“主动、原则与承担”回应外部的“主动、原则与承担”；两边能否对接，要看“行动速度可能快过他人的承接能力”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“已有推动事情向前的意愿与创造力”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“把目标压成一个可交付的小步骤”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用更大力度掩盖信息不足”，风险会被放大。","effect":"最需要防止的是：把坚定变成强推。"},"paths":{"ready":"如果关键条件得到确认，可以继续“把目标压成一个可交付的小步骤”，但仍以小步反馈决定是否扩大。","not_ready":"如果“行动速度可能快过他人的承接能力”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"把目标压成一个可交付的小步骤","observe":"这一步是在创造条件，还是只想证明自己？","continue_if":"出现与“已有推动事情向前的意愿与创造力”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用更大力度掩盖信息不足”或“把坚定变成强推”的迹象。"}}}},{"id":2,"name":"坤","pinyin":"kūn","theme":"承载、配合与厚德","reflection":"先观察环境、接住现实，再稳稳推进；柔韧并不等于没有边界。","source_note":"据《周易》坤卦意象整理","upper_trigram":8,"lower_trigram":8,"lines":{"1":{"title":"初六","interpretation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分 当前拉扯在于：内在意愿已经出现，外部条件尚未完全成形，而配合他人与守住自身位置之间需要平衡也会在这一爻变得具体 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“为了维持和气而过度承担，而不是把把退让当成唯一的相处方式当成解决办法，而坤第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，就暂停扩大动作。","classic":"履霜，堅冰至。","source":"《周易》爻辞","modern":{"image":"“履霜，堅冰至。”是坤在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而配合他人与守住自身位置之间需要平衡也会在这一爻变得具体。","warning":"为了维持和气而过度承担，而不是把把退让当成唯一的相处方式当成解决办法，而坤第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["列清自己愿意承接与不能承接的部分。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"观察","meaning":"在坤第1爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪些责任确实属于你，哪些只是习惯性接下”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"观察","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“为了维持和气而过度承担，而不是把把退让当成唯一的相处方式当成解决办法，而坤第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录坤初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"这一爻把变化落在具体环节：事情开始进入现实协作，“承载、配合与厚德”要接受反馈检验 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“列清自己愿意承接与不能承接的部分”后再看反馈；同时留意为了维持和气而过度承担会在此时放大。","classic":"直方大，不習无不利。","source":"《周易》爻辞","modern":{"image":"“直方大，不習无不利。”是坤在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“承载、配合与厚德”要接受反馈检验。","tension":"真正的拉扯来自配合他人与守住自身位置之间需要平衡，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"为了维持和气而过度承担会在此时放大。","advice":["列清自己愿意承接与不能承接的部分。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"通达","meaning":"在坤第2爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“哪些责任确实属于你，哪些只是习惯性接下”核对判断"},"tone":"接触","extended":{"trigger":{"label":"通达","observe":"完成“列清自己愿意承接与不能承接的部分”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“列清自己愿意承接与不能承接的部分”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“列清自己愿意承接与不能承接的部分”，可以保持小步推进。","pause_if":"若出现“为了维持和气而过度承担会在此时放大”，先暂停扩大投入。"},"action":{"do":"列清自己愿意承接与不能承接的部分","review":"完成后记录坤六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面正在显出边界：坤行至三位，旧方法的边界和新选择的代价同时出现 继续原路与承认需要调整之间发生冲突，而配合他人与守住自身位置之间需要平衡也会在这一爻变得具体 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若为了维持和气而过度承担，行动应当收束。","classic":"含章可貞，或從王事，无成有終。","source":"《周易》爻辞","modern":{"image":"“含章可貞，或從王事，无成有終。”是坤在“转折”阶段留下的具体图景。","situation":"坤行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而配合他人与守住自身位置之间需要平衡也会在这一爻变得具体。","warning":"为了维持和气而过度承担。","advice":["列清自己愿意承接与不能承接的部分。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在坤第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪些责任确实属于你，哪些只是习惯性接下”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“为了维持和气而过度承担”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录坤六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 当前拉扯在于：真正的拉扯来自配合他人与守住自身位置之间需要平衡，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“列清自己愿意承接与不能承接的部分”；若出现“为了维持和气而过度承担”，就暂停扩大动作。","classic":"括囊，无咎无譽。","source":"《周易》爻辞","modern":{"image":"“括囊，无咎无譽。”是坤在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自配合他人与守住自身位置之间需要平衡，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"为了维持和气而过度承担。","advice":["列清自己愿意承接与不能承接的部分。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在坤第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“哪些责任确实属于你，哪些只是习惯性接下”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“列清自己愿意承接与不能承接的部分”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“列清自己愿意承接与不能承接的部分”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“列清自己愿意承接与不能承接的部分”，可以保持小步推进。","pause_if":"若出现“为了维持和气而过度承担”，先暂停扩大投入。"},"action":{"do":"列清自己愿意承接与不能承接的部分","review":"完成后记录坤六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"这一爻把变化落在具体环节：局面要求从个人得失转向整体结果和持续责任 现实反馈与当前方向开始相互支持，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意为了维持和气而过度承担，而不是把把退让当成唯一的相处方式当成解决办法，而坤第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","classic":"黃裳，元吉。","source":"《周易》爻辞","modern":{"image":"“黃裳，元吉。”是坤在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而配合他人与守住自身位置之间需要平衡也会在这一爻变得具体。","warning":"为了维持和气而过度承担，而不是把把退让当成唯一的相处方式当成解决办法，而坤第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["列清自己愿意承接与不能承接的部分。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"顺势","meaning":"在坤第5爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“哪些责任确实属于你，哪些只是习惯性接下”核对判断"},"tone":"担当","extended":{"trigger":{"label":"顺势","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“为了维持和气而过度承担，而不是把把退让当成唯一的相处方式当成解决办法，而坤第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录坤六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"局面正在显出边界：当前循环接近上限，“承载、配合与厚德”需要从继续加力转向收束复盘 真正的拉扯来自配合他人与守住自身位置之间需要平衡，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题 可以用“列清自己愿意承接与不能承接的部分”做一次验证；若为了维持和气而过度承担会在此时放大，行动应当收束。","classic":"龍戰于野，其血玄黃。","source":"《周易》爻辞","modern":{"image":"“龍戰于野，其血玄黃。”是坤在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“承载、配合与厚德”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自配合他人与守住自身位置之间需要平衡，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"为了维持和气而过度承担会在此时放大。","advice":["列清自己愿意承接与不能承接的部分。","列出应当停止、保留和移交的事项。"],"signal":{"label":"观察","meaning":"在坤第6爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪些责任确实属于你，哪些只是习惯性接下”核对判断"},"tone":"收束","extended":{"trigger":{"label":"观察","observe":"完成“列清自己愿意承接与不能承接的部分”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“列清自己愿意承接与不能承接的部分”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“列清自己愿意承接与不能承接的部分”，可以保持小步推进。","pause_if":"若出现“为了维持和气而过度承担会在此时放大”，先暂停扩大投入。"},"action":{"do":"列清自己愿意承接与不能承接的部分","review":"完成后记录坤上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"承接现实并不被动，关键是让柔韧带着边界","strengths":["能够观察环境并容纳不同需要","先观察环境、接住现实，再稳稳推进"],"tensions":["配合他人与守住自身位置之间需要平衡"],"risks":["为了维持和气而过度承担"],"actions":["列清自己愿意承接与不能承接的部分"],"avoid":["把退让当成唯一的相处方式"],"questions":["哪些责任确实属于你，哪些只是习惯性接下？"],"extended":{"situation":{"direct":"眼下的重点是承接现实并不被动，关键是让柔韧带着边界。","support":"已经可以利用的是：能够观察环境并容纳不同需要。","constraint":"仍需核实的是：配合他人与守住自身位置之间需要平衡。"},"relationship":{"inner":"下卦坤，内部动力偏向承载、配合与现实基础。","outer":"上卦坤，外部处境更受承载、配合与现实基础影响。","interaction":"内部想以“承载、配合与现实基础”回应外部的“承载、配合与现实基础”；两边能否对接，要看“配合他人与守住自身位置之间需要平衡”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“能够观察环境并容纳不同需要”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“列清自己愿意承接与不能承接的部分”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把退让当成唯一的相处方式”，风险会被放大。","effect":"最需要防止的是：为了维持和气而过度承担。"},"paths":{"ready":"如果关键条件得到确认，可以继续“列清自己愿意承接与不能承接的部分”，但仍以小步反馈决定是否扩大。","not_ready":"如果“配合他人与守住自身位置之间需要平衡”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"列清自己愿意承接与不能承接的部分","observe":"哪些责任确实属于你，哪些只是习惯性接下？","continue_if":"出现与“能够观察环境并容纳不同需要”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把退让当成唯一的相处方式”或“为了维持和气而过度承担”的迹象。"}}}},{"id":3,"name":"屯","pinyin":"zhūn","theme":"初创的艰难","reflection":"开端的混乱很正常。把目标拆小，优先建立秩序与支持。","source_note":"据《周易》屯卦意象整理","upper_trigram":6,"lower_trigram":4,"lines":{"1":{"title":"初九","interpretation":"这一爻把变化落在具体环节：事情刚在“初创的艰难”的起点露出端倪，可用条件还不多 关键条件开始出现可利用的现实回应，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意把开端的不顺误判为方向错误。","classic":"磐桓，利居貞，利建侯。","source":"《周易》爻辞","modern":{"image":"“磐桓，利居貞，利建侯。”是屯在“潜藏”阶段留下的具体图景。","situation":"事情刚在“初创的艰难”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是方向尚未稳定，资源与方法也在磨合，两者要放在同一次权衡里。","warning":"把开端的不顺误判为方向错误。","advice":["先建立一条最小流程和一个可靠支点。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"有利","meaning":"在屯第1爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“当前最缺的是方向、资源，还是协作方式”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"有利","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把开端的不顺误判为方向错误”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录屯初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：屯来到二位，个人判断正与资源、规则或他人发生接触 若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大方向尚未稳定，资源与方法也在磨合 可以用“先建立一条最小流程和一个可靠支点”做一次验证；若把开端的不顺误判为方向错误，而不是把同时启动太多未经验证的事项当成解决办法，而屯第2爻处在“接触”阶段，行动应当收束。","classic":"屯如邅如，乘馬班如，匪寇婚媾，女子貞不字，十年乃字。","source":"《周易》爻辞","modern":{"image":"“屯如邅如，乘馬班如，匪寇婚媾，女子貞不字，十年乃字。”是屯在“接触”阶段留下的具体图景。","situation":"屯来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大方向尚未稳定，资源与方法也在磨合。","warning":"把开端的不顺误判为方向错误，而不是把同时启动太多未经验证的事项当成解决办法，而屯第2爻处在“接触”阶段。","advice":["先建立一条最小流程和一个可靠支点。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在屯第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“当前最缺的是方向、资源，还是协作方式”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“先建立一条最小流程和一个可靠支点”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先建立一条最小流程和一个可靠支点”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先建立一条最小流程和一个可靠支点”，可以保持小步推进。","pause_if":"若出现“把开端的不顺误判为方向错误，而不是把同时启动太多未经验证的事项当成解决办法，而屯第2爻处在“接触”阶段”，先暂停扩大投入。"},"action":{"do":"先建立一条最小流程和一个可靠支点","review":"完成后记录屯六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻处在容易用力过度的位置，调整比加码更重要 当前拉扯在于：此时一面是继续原路与承认需要调整之间发生冲突，另一面是方向尚未稳定，资源与方法也在磨合，两者要放在同一次权衡里 当原有做法显出明确代价，需要及时调整时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“把开端的不顺误判为方向错误会在此时放大”，就暂停扩大动作。","classic":"即鹿无虞，惟入于林中。君子幾不如舍。往吝。","source":"《周易》爻辞","modern":{"image":"“即鹿无虞，惟入于林中。君子幾不如舍。往吝。”是屯在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是方向尚未稳定，资源与方法也在磨合，两者要放在同一次权衡里。","warning":"把开端的不顺误判为方向错误会在此时放大。","advice":["先建立一条最小流程和一个可靠支点。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"修正","meaning":"在屯第3爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“当前最缺的是方向、资源，还是协作方式”核对判断"},"tone":"转折","extended":{"trigger":{"label":"修正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把开端的不顺误判为方向错误会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录屯六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：局面已经接近新的层级，旧角色未必还能容纳当前变化 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“先建立一条最小流程和一个可靠支点”后再看反馈；同时留意把开端的不顺误判为方向错误。","classic":"乘馬班如，求婚媾，往，吉无不利。","source":"《周易》爻辞","modern":{"image":"“乘馬班如，求婚媾，往，吉无不利。”是屯在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大方向尚未稳定，资源与方法也在磨合。","warning":"把开端的不顺误判为方向错误。","advice":["先建立一条最小流程和一个可靠支点。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"通达","meaning":"在屯第4爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“当前最缺的是方向、资源，还是协作方式”核对判断"},"tone":"越界","extended":{"trigger":{"label":"通达","observe":"完成“先建立一条最小流程和一个可靠支点”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先建立一条最小流程和一个可靠支点”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先建立一条最小流程和一个可靠支点”，可以保持小步推进。","pause_if":"若出现“把开端的不顺误判为方向错误”，先暂停扩大投入。"},"action":{"do":"先建立一条最小流程和一个可靠支点","review":"完成后记录屯六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面正在显出边界：关键资源与决定权趋向集中，“初创的艰难”开始影响更多人 此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是方向尚未稳定，资源与方法也在磨合，两者要放在同一次权衡里 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若把开端的不顺误判为方向错误，行动应当收束。","classic":"屯其膏，小貞吉，大貞凶。","source":"《周易》爻辞","modern":{"image":"“屯其膏，小貞吉，大貞凶。”是屯在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“初创的艰难”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是方向尚未稳定，资源与方法也在磨合，两者要放在同一次权衡里。","warning":"把开端的不顺误判为方向错误。","advice":["先建立一条最小流程和一个可靠支点。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"止损","meaning":"在屯第5爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“当前最缺的是方向、资源，还是协作方式”核对判断"},"tone":"担当","extended":{"trigger":{"label":"止损","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把开端的不顺误判为方向错误”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录屯九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"屯来到上位，已有路径可能完成使命，也可能因过度而失衡 当前拉扯在于：若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大方向尚未稳定，资源与方法也在磨合 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“先建立一条最小流程和一个可靠支点”；若出现“把开端的不顺误判为方向错误，而不是把同时启动太多未经验证的事项当成解决办法，而屯第6爻处在“收束”阶段”，就暂停扩大动作。","classic":"乘馬班如，泣血漣如。","source":"《周易》爻辞","modern":{"image":"“乘馬班如，泣血漣如。”是屯在“收束”阶段留下的具体图景。","situation":"屯来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大方向尚未稳定，资源与方法也在磨合。","warning":"把开端的不顺误判为方向错误，而不是把同时启动太多未经验证的事项当成解决办法，而屯第6爻处在“收束”阶段。","advice":["先建立一条最小流程和一个可靠支点。","列出应当停止、保留和移交的事项。"],"signal":{"label":"观察","meaning":"在屯第6爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“当前最缺的是方向、资源，还是协作方式”核对判断"},"tone":"收束","extended":{"trigger":{"label":"观察","observe":"完成“先建立一条最小流程和一个可靠支点”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先建立一条最小流程和一个可靠支点”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先建立一条最小流程和一个可靠支点”，可以保持小步推进。","pause_if":"若出现“把开端的不顺误判为方向错误，而不是把同时启动太多未经验证的事项当成解决办法，而屯第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"先建立一条最小流程和一个可靠支点","review":"完成后记录屯上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"新局面的混乱需要秩序，而不是过早追求完整","strengths":["事情已经出现生长的动力","开端的混乱很正常。把目标拆小，优先建立秩序与支持"],"tensions":["方向尚未稳定，资源与方法也在磨合"],"risks":["把开端的不顺误判为方向错误"],"actions":["先建立一条最小流程和一个可靠支点"],"avoid":["同时启动太多未经验证的事项"],"questions":["当前最缺的是方向、资源，还是协作方式？"],"extended":{"situation":{"direct":"眼下的重点是新局面的混乱需要秩序，而不是过早追求完整。","support":"已经可以利用的是：事情已经出现生长的动力。","constraint":"仍需核实的是：方向尚未稳定，资源与方法也在磨合。"},"relationship":{"inner":"下卦震，内部动力偏向启动、震动与迅速反应。","outer":"上卦坎，外部处境更受风险、试探与信息缺口影响。","interaction":"内部想以“启动、震动与迅速反应”回应外部的“风险、试探与信息缺口”；两边能否对接，要看“方向尚未稳定，资源与方法也在磨合”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“事情已经出现生长的动力”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“先建立一条最小流程和一个可靠支点”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“同时启动太多未经验证的事项”，风险会被放大。","effect":"最需要防止的是：把开端的不顺误判为方向错误。"},"paths":{"ready":"如果关键条件得到确认，可以继续“先建立一条最小流程和一个可靠支点”，但仍以小步反馈决定是否扩大。","not_ready":"如果“方向尚未稳定，资源与方法也在磨合”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"先建立一条最小流程和一个可靠支点","observe":"当前最缺的是方向、资源，还是协作方式？","continue_if":"出现与“事情已经出现生长的动力”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“同时启动太多未经验证的事项”或“把开端的不顺误判为方向错误”的迹象。"}}}},{"id":4,"name":"蒙","pinyin":"méng","theme":"学习与启蒙","reflection":"不必急着证明自己全懂；提出好问题、求助可靠的人，会让迷雾变清。","source_note":"据《周易》蒙卦意象整理","upper_trigram":7,"lower_trigram":6,"lines":{"1":{"title":"初六","interpretation":"局面正在显出边界：蒙落在初位，眼下更像在辨认方向，而不是兑现结果 真正的拉扯来自求知欲与急于证明自己之间互相拉扯，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若重复追问却不消化已有答案，行动应当收束。","classic":"發蒙。利用刑人，用說桎梏，以往吝。","source":"《周易》爻辞","modern":{"image":"“發蒙。利用刑人，用說桎梏，以往吝。”是蒙在“潜藏”阶段留下的具体图景。","situation":"蒙落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自求知欲与急于证明自己之间互相拉扯，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"重复追问却不消化已有答案。","advice":["带着一个具体问题向可信的人求证。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"修正","meaning":"在蒙第1爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“你缺的是答案，还是分辨答案的方法”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"修正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“重复追问却不消化已有答案”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录蒙初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一阶段不再只靠设想，回应和基本功开始决定走向 当前拉扯在于：自己的节奏需要与现实反馈相互校准，而求知欲与急于证明自己之间互相拉扯也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“带着一个具体问题向可信的人求证”；若出现“重复追问却不消化已有答案”，就暂停扩大动作。","classic":"包蒙，吉。納婦吉，子克家。","source":"《周易》爻辞","modern":{"image":"“包蒙，吉。納婦吉，子克家。”是蒙在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而求知欲与急于证明自己之间互相拉扯也会在这一爻变得具体。","warning":"重复追问却不消化已有答案。","advice":["带着一个具体问题向可信的人求证。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在蒙第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你缺的是答案，还是分辨答案的方法”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“带着一个具体问题向可信的人求证”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“带着一个具体问题向可信的人求证”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“带着一个具体问题向可信的人求证”，可以保持小步推进。","pause_if":"若出现“重复追问却不消化已有答案”，先暂停扩大投入。"},"action":{"do":"带着一个具体问题向可信的人求证","review":"完成后记录蒙九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻把变化落在具体环节：事情跨入转折带，焦虑可能比事实更快推动决定 现实条件尚不足以支持扩大动作，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意重复追问却不消化已有答案，而不是把把模糊包装成已经理解当成解决办法，而蒙第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","classic":"勿用取女，見金夫，不有躬，无攸利。","source":"《周易》爻辞","modern":{"image":"“勿用取女，見金夫，不有躬，无攸利。”是蒙在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自求知欲与急于证明自己之间互相拉扯，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"重复追问却不消化已有答案，而不是把把模糊包装成已经理解当成解决办法，而蒙第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","advice":["带着一个具体问题向可信的人求证。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"暂停","meaning":"在蒙第3爻里，爻辞给出明确的收势信号，眼下不宜把意愿直接变成大动作，可用“你缺的是答案，还是分辨答案的方法”核对判断"},"tone":"转折","extended":{"trigger":{"label":"暂停","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实条件尚不足以支持扩大动作”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“重复追问却不消化已有答案，而不是把把模糊包装成已经理解当成解决办法，而蒙第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录蒙六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"局面正在显出边界：事情正由内部走向外部，“学习与启蒙”需要重新确认位置和权限 向外推进的需要与边界尚未说清之间互相牵制，而求知欲与急于证明自己之间互相拉扯也会在这一爻变得具体 可以用“带着一个具体问题向可信的人求证”做一次验证；若重复追问却不消化已有答案会在此时放大，行动应当收束。","classic":"困蒙，吝。","source":"《周易》爻辞","modern":{"image":"“困蒙，吝。”是蒙在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“学习与启蒙”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而求知欲与急于证明自己之间互相拉扯也会在这一爻变得具体。","warning":"重复追问却不消化已有答案会在此时放大。","advice":["带着一个具体问题向可信的人求证。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"修正","meaning":"在蒙第4爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“你缺的是答案，还是分辨答案的方法”核对判断"},"tone":"越界","extended":{"trigger":{"label":"修正","observe":"完成“带着一个具体问题向可信的人求证”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“带着一个具体问题向可信的人求证”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“带着一个具体问题向可信的人求证”，可以保持小步推进。","pause_if":"若出现“重复追问却不消化已有答案会在此时放大”，先暂停扩大投入。"},"action":{"do":"带着一个具体问题向可信的人求证","review":"完成后记录蒙六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"蒙来到五位，能力之外还要衡量整体承接和长期后果 当前拉扯在于：真正的拉扯来自求知欲与急于证明自己之间互相拉扯，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“重复追问却不消化已有答案”，就暂停扩大动作。","classic":"童蒙，吉。","source":"《周易》爻辞","modern":{"image":"“童蒙，吉。”是蒙在“担当”阶段留下的具体图景。","situation":"蒙来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自求知欲与急于证明自己之间互相拉扯，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"重复追问却不消化已有答案。","advice":["带着一个具体问题向可信的人求证。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在蒙第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你缺的是答案，还是分辨答案的方法”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“重复追问却不消化已有答案”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录蒙六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"这一爻把变化落在具体环节：这一爻处在阶段末端，下一步先要判断什么已经结束 关键条件开始出现可利用的现实回应，是接下来值得核对的信号。完成“带着一个具体问题向可信的人求证”后再看反馈；同时留意重复追问却不消化已有答案。","classic":"擊蒙，不利為寇，利禦寇。","source":"《周易》爻辞","modern":{"image":"“擊蒙，不利為寇，利禦寇。”是蒙在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而求知欲与急于证明自己之间互相拉扯也会在这一爻变得具体。","warning":"重复追问却不消化已有答案。","advice":["带着一个具体问题向可信的人求证。","列出应当停止、保留和移交的事项。"],"signal":{"label":"有利","meaning":"在蒙第6爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“你缺的是答案，还是分辨答案的方法”核对判断"},"tone":"收束","extended":{"trigger":{"label":"有利","observe":"完成“带着一个具体问题向可信的人求证”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“带着一个具体问题向可信的人求证”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“带着一个具体问题向可信的人求证”，可以保持小步推进。","pause_if":"若出现“重复追问却不消化已有答案”，先暂停扩大投入。"},"action":{"do":"带着一个具体问题向可信的人求证","review":"完成后记录蒙上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"不知道并不可耻，真正重要的是建立有效的学习关系","strengths":["仍有提问、试错和获得指导的空间","不必急着证明自己全懂"],"tensions":["求知欲与急于证明自己之间互相拉扯"],"risks":["重复追问却不消化已有答案"],"actions":["带着一个具体问题向可信的人求证"],"avoid":["把模糊包装成已经理解"],"questions":["你缺的是答案，还是分辨答案的方法？"],"extended":{"situation":{"direct":"眼下的重点是不知道并不可耻，真正重要的是建立有效的学习关系。","support":"已经可以利用的是：仍有提问、试错和获得指导的空间。","constraint":"仍需核实的是：求知欲与急于证明自己之间互相拉扯。"},"relationship":{"inner":"下卦坎，内部动力偏向风险、试探与信息缺口。","outer":"上卦艮，外部处境更受边界、停止与重新定位影响。","interaction":"内部想以“风险、试探与信息缺口”回应外部的“边界、停止与重新定位”；两边能否对接，要看“求知欲与急于证明自己之间互相拉扯”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“仍有提问、试错和获得指导的空间”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“带着一个具体问题向可信的人求证”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把模糊包装成已经理解”，风险会被放大。","effect":"最需要防止的是：重复追问却不消化已有答案。"},"paths":{"ready":"如果关键条件得到确认，可以继续“带着一个具体问题向可信的人求证”，但仍以小步反馈决定是否扩大。","not_ready":"如果“求知欲与急于证明自己之间互相拉扯”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"带着一个具体问题向可信的人求证","observe":"你缺的是答案，还是分辨答案的方法？","continue_if":"出现与“仍有提问、试错和获得指导的空间”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把模糊包装成已经理解”或“重复追问却不消化已有答案”的迹象。"}}}},{"id":5,"name":"需","pinyin":"xū","theme":"等待与准备","reflection":"等待不是停摆。先补足信息、资源和体力，时机成熟再行动。","source_note":"据《周易》需卦意象整理","upper_trigram":6,"lower_trigram":1,"lines":{"1":{"title":"初九","interpretation":"这一爻处在起步处，“等待的价值在于准备条件，而不是把决定无限推迟”仍需低成本试探 当前拉扯在于：若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大时机未明与内心急切同时存在 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“用忙碌代替真正的准备会在此时放大”，就暂停扩大动作。","classic":"需于郊，利用恒，无咎。","source":"《周易》爻辞","modern":{"image":"“需于郊，利用恒，无咎。”是需在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“等待的价值在于准备条件，而不是把决定无限推迟”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大时机未明与内心急切同时存在。","warning":"用忙碌代替真正的准备会在此时放大。","advice":["写下启动前必须满足的三个条件。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在需第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“什么信号出现时，你会知道可以行动”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“用忙碌代替真正的准备会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录需初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一爻把变化落在具体环节：局面正从内部准备转向真实互动，关系与条件逐渐可见 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“写下启动前必须满足的三个条件”后再看反馈；同时留意用忙碌代替真正的准备。","classic":"需于沙，小有言，終吉。","source":"《周易》爻辞","modern":{"image":"“需于沙，小有言，終吉。”是需在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是时机未明与内心急切同时存在，两者要放在同一次权衡里。","warning":"用忙碌代替真正的准备。","advice":["写下启动前必须满足的三个条件。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在需第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“什么信号出现时，你会知道可以行动”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“写下启动前必须满足的三个条件”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“写下启动前必须满足的三个条件”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“写下启动前必须满足的三个条件”，可以保持小步推进。","pause_if":"若出现“用忙碌代替真正的准备”，先暂停扩大投入。"},"action":{"do":"写下启动前必须满足的三个条件","review":"完成后记录需九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面正在显出边界：局面来到内外转换处，“等待与准备”开始承受压力测试 若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大时机未明与内心急切同时存在 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若用忙碌代替真正的准备，行动应当收束。","classic":"需于泥，致寇至。","source":"《周易》爻辞","modern":{"image":"“需于泥，致寇至。”是需在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“等待与准备”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大时机未明与内心急切同时存在。","warning":"用忙碌代替真正的准备。","advice":["写下启动前必须满足的三个条件。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在需第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么信号出现时，你会知道可以行动”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“用忙碌代替真正的准备”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录需九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"需来到四位，跨出原有边界之前要先说明责任 当前拉扯在于：此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是时机未明与内心急切同时存在，两者要放在同一次权衡里 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“写下启动前必须满足的三个条件”；若出现“用忙碌代替真正的准备，而不是把没有期限地观望当成解决办法，而需第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位”，就暂停扩大动作。","classic":"需于血，出自穴。","source":"《周易》爻辞","modern":{"image":"“需于血，出自穴。”是需在“越界”阶段留下的具体图景。","situation":"需来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是时机未明与内心急切同时存在，两者要放在同一次权衡里。","warning":"用忙碌代替真正的准备，而不是把没有期限地观望当成解决办法，而需第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位。","advice":["写下启动前必须满足的三个条件。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在需第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么信号出现时，你会知道可以行动”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“写下启动前必须满足的三个条件”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“写下启动前必须满足的三个条件”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“写下启动前必须满足的三个条件”，可以保持小步推进。","pause_if":"若出现“用忙碌代替真正的准备，而不是把没有期限地观望当成解决办法，而需第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位”，先暂停扩大投入。"},"action":{"do":"写下启动前必须满足的三个条件","review":"完成后记录需六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一爻把变化落在具体环节：这一阶段已进入主位，选择会放大为规则或示范 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意用忙碌代替真正的准备会在此时放大。","classic":"需于酒食，貞吉。","source":"《周易》爻辞","modern":{"image":"“需于酒食，貞吉。”是需在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大时机未明与内心急切同时存在。","warning":"用忙碌代替真正的准备会在此时放大。","advice":["写下启动前必须满足的三个条件。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在需第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“什么信号出现时，你会知道可以行动”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“用忙碌代替真正的准备会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录需九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"局面正在显出边界：局面走到极处，继续延长旧办法未必带来同等收益 此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是时机未明与内心急切同时存在，两者要放在同一次权衡里 可以用“写下启动前必须满足的三个条件”做一次验证；若用忙碌代替真正的准备，行动应当收束。","classic":"入于穴，有不速之客三人來，敬之，終吉。","source":"《周易》爻辞","modern":{"image":"“入于穴，有不速之客三人來，敬之，終吉。”是需在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是时机未明与内心急切同时存在，两者要放在同一次权衡里。","warning":"用忙碌代替真正的准备。","advice":["写下启动前必须满足的三个条件。","列出应当停止、保留和移交的事项。"],"signal":{"label":"可行","meaning":"在需第6爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“什么信号出现时，你会知道可以行动”核对判断"},"tone":"收束","extended":{"trigger":{"label":"可行","observe":"完成“写下启动前必须满足的三个条件”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“写下启动前必须满足的三个条件”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“写下启动前必须满足的三个条件”，可以保持小步推进。","pause_if":"若出现“用忙碌代替真正的准备”，先暂停扩大投入。"},"action":{"do":"写下启动前必须满足的三个条件","review":"完成后记录需上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"等待的价值在于准备条件，而不是把决定无限推迟","strengths":["目前仍有时间补足信息和资源","等待不是停摆。先补足信息、资源和体力，时机成熟再行动"],"tensions":["时机未明与内心急切同时存在"],"risks":["用忙碌代替真正的准备"],"actions":["写下启动前必须满足的三个条件"],"avoid":["没有期限地观望"],"questions":["什么信号出现时，你会知道可以行动？"],"extended":{"situation":{"direct":"眼下的重点是等待的价值在于准备条件，而不是把决定无限推迟。","support":"已经可以利用的是：目前仍有时间补足信息和资源。","constraint":"仍需核实的是：时机未明与内心急切同时存在。"},"relationship":{"inner":"下卦乾，内部动力偏向主动、原则与承担。","outer":"上卦坎，外部处境更受风险、试探与信息缺口影响。","interaction":"内部想以“主动、原则与承担”回应外部的“风险、试探与信息缺口”；两边能否对接，要看“时机未明与内心急切同时存在”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“目前仍有时间补足信息和资源”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“写下启动前必须满足的三个条件”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“没有期限地观望”，风险会被放大。","effect":"最需要防止的是：用忙碌代替真正的准备。"},"paths":{"ready":"如果关键条件得到确认，可以继续“写下启动前必须满足的三个条件”，但仍以小步反馈决定是否扩大。","not_ready":"如果“时机未明与内心急切同时存在”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"写下启动前必须满足的三个条件","observe":"什么信号出现时，你会知道可以行动？","continue_if":"出现与“目前仍有时间补足信息和资源”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“没有期限地观望”或“用忙碌代替真正的准备”的迹象。"}}}},{"id":6,"name":"讼","pinyin":"sòng","theme":"分歧与界限","reflection":"争论前先确认共同事实和底线；能协商就别把关系推向输赢。","source_note":"据《周易》讼卦意象整理","upper_trigram":1,"lower_trigram":6,"lines":{"1":{"title":"初六","interpretation":"这一爻把变化落在具体环节：变化尚在根部，先分清已经发生的事实和仍在期待的部分 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意把沟通变成输赢，而不是把在情绪最高处作不可撤回的表态当成解决办法，而讼第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","classic":"不永所事，小有言，終吉。","source":"《周易》爻辞","modern":{"image":"“不永所事，小有言，終吉。”是讼在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而维护立场与维持关系之间存在张力也会在这一爻变得具体。","warning":"把沟通变成输赢，而不是把在情绪最高处作不可撤回的表态当成解决办法，而讼第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["先确认双方承认的事实，再谈方案。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在讼第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你真正要维护的是原则、利益，还是面子”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把沟通变成输赢，而不是把在情绪最高处作不可撤回的表态当成解决办法，而讼第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录讼初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"局面正在显出边界：事情开始进入现实协作，“分歧与界限”要接受反馈检验 真正的拉扯来自维护立场与维持关系之间存在张力，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题 可以用“先确认双方承认的事实，再谈方案”做一次验证；若把沟通变成输赢会在此时放大，行动应当收束。","classic":"不克訟，歸而逋其邑，人三百戶，无眚。","source":"《周易》爻辞","modern":{"image":"“不克訟，歸而逋其邑，人三百戶，无眚。”是讼在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“分歧与界限”要接受反馈检验。","tension":"真正的拉扯来自维护立场与维持关系之间存在张力，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"把沟通变成输赢会在此时放大。","advice":["先确认双方承认的事实，再谈方案。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在讼第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“你真正要维护的是原则、利益，还是面子”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“先确认双方承认的事实，再谈方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认双方承认的事实，再谈方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认双方承认的事实，再谈方案”，可以保持小步推进。","pause_if":"若出现“把沟通变成输赢会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认双方承认的事实，再谈方案","review":"完成后记录讼九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"讼行至三位，旧方法的边界和新选择的代价同时出现 当前拉扯在于：继续原路与承认需要调整之间发生冲突，而维护立场与维持关系之间存在张力也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“把沟通变成输赢”，就暂停扩大动作。","classic":"食舊德，貞厲，終吉，或從王事，无成。","source":"《周易》爻辞","modern":{"image":"“食舊德，貞厲，終吉，或從王事，无成。”是讼在“转折”阶段留下的具体图景。","situation":"讼行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而维护立场与维持关系之间存在张力也会在这一爻变得具体。","warning":"把沟通变成输赢。","advice":["先确认双方承认的事实，再谈方案。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"可行","meaning":"在讼第3爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你真正要维护的是原则、利益，还是面子”核对判断"},"tone":"转折","extended":{"trigger":{"label":"可行","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把沟通变成输赢”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录讼六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"这一爻把变化落在具体环节：这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“先确认双方承认的事实，再谈方案”后再看反馈；同时留意把沟通变成输赢。","classic":"不克訟，復即命渝，安貞吉。","source":"《周易》爻辞","modern":{"image":"“不克訟，復即命渝，安貞吉。”是讼在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自维护立场与维持关系之间存在张力，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"把沟通变成输赢。","advice":["先确认双方承认的事实，再谈方案。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在讼第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你真正要维护的是原则、利益，还是面子”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“先确认双方承认的事实，再谈方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认双方承认的事实，再谈方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认双方承认的事实，再谈方案”，可以保持小步推进。","pause_if":"若出现“把沟通变成输赢”，先暂停扩大投入。"},"action":{"do":"先确认双方承认的事实，再谈方案","review":"完成后记录讼九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面正在显出边界：局面要求从个人得失转向整体结果和持续责任 扩大影响与照顾整体承接能力之间需要平衡，而维护立场与维持关系之间存在张力也会在这一爻变得具体 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若把沟通变成输赢，而不是把在情绪最高处作不可撤回的表态当成解决办法，而讼第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围，行动应当收束。","classic":"訟，元吉。","source":"《周易》爻辞","modern":{"image":"“訟，元吉。”是讼在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而维护立场与维持关系之间存在张力也会在这一爻变得具体。","warning":"把沟通变成输赢，而不是把在情绪最高处作不可撤回的表态当成解决办法，而讼第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["先确认双方承认的事实，再谈方案。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"顺势","meaning":"在讼第5爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“你真正要维护的是原则、利益，还是面子”核对判断"},"tone":"担当","extended":{"trigger":{"label":"顺势","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把沟通变成输赢，而不是把在情绪最高处作不可撤回的表态当成解决办法，而讼第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录讼九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"当前循环接近上限，“分歧与界限”需要从继续加力转向收束复盘 当前拉扯在于：真正的拉扯来自维护立场与维持关系之间存在张力，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“先确认双方承认的事实，再谈方案”；若出现“把沟通变成输赢会在此时放大”，就暂停扩大动作。","classic":"或錫之鞶帶，終朝三褫之。","source":"《周易》爻辞","modern":{"image":"“或錫之鞶帶，終朝三褫之。”是讼在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“分歧与界限”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自维护立场与维持关系之间存在张力，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"把沟通变成输赢会在此时放大。","advice":["先确认双方承认的事实，再谈方案。","列出应当停止、保留和移交的事项。"],"signal":{"label":"观察","meaning":"在讼第6爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“你真正要维护的是原则、利益，还是面子”核对判断"},"tone":"收束","extended":{"trigger":{"label":"观察","observe":"完成“先确认双方承认的事实，再谈方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认双方承认的事实，再谈方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认双方承认的事实，再谈方案”，可以保持小步推进。","pause_if":"若出现“把沟通变成输赢会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认双方承认的事实，再谈方案","review":"完成后记录讼上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"分歧需要回到事实、权限和底线，而非争一口气","strengths":["问题已经暴露，仍有澄清规则的机会","争论前先确认共同事实和底线"],"tensions":["维护立场与维持关系之间存在张力"],"risks":["把沟通变成输赢"],"actions":["先确认双方承认的事实，再谈方案"],"avoid":["在情绪最高处作不可撤回的表态"],"questions":["你真正要维护的是原则、利益，还是面子？"],"extended":{"situation":{"direct":"眼下的重点是分歧需要回到事实、权限和底线，而非争一口气。","support":"已经可以利用的是：问题已经暴露，仍有澄清规则的机会。","constraint":"仍需核实的是：维护立场与维持关系之间存在张力。"},"relationship":{"inner":"下卦坎，内部动力偏向风险、试探与信息缺口。","outer":"上卦乾，外部处境更受主动、原则与承担影响。","interaction":"内部想以“风险、试探与信息缺口”回应外部的“主动、原则与承担”；两边能否对接，要看“维护立场与维持关系之间存在张力”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“问题已经暴露，仍有澄清规则的机会”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“先确认双方承认的事实，再谈方案”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“在情绪最高处作不可撤回的表态”，风险会被放大。","effect":"最需要防止的是：把沟通变成输赢。"},"paths":{"ready":"如果关键条件得到确认，可以继续“先确认双方承认的事实，再谈方案”，但仍以小步反馈决定是否扩大。","not_ready":"如果“维护立场与维持关系之间存在张力”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"先确认双方承认的事实，再谈方案","observe":"你真正要维护的是原则、利益，还是面子？","continue_if":"出现与“问题已经暴露，仍有澄清规则的机会”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“在情绪最高处作不可撤回的表态”或“把沟通变成输赢”的迹象。"}}}},{"id":7,"name":"师","pinyin":"shī","theme":"组织与纪律","reflection":"复杂局面需要明确责任与节奏。先定原则，再带着团队行动。","source_note":"据《周易》师卦意象整理","upper_trigram":8,"lower_trigram":6,"lines":{"1":{"title":"初六","interpretation":"局面正在显出边界：事情刚在“组织与纪律”的起点露出端倪，可用条件还不多 此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是统一行动与个体差异需要协调，两者要放在同一次权衡里 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若责任模糊导致权力和后果错位，行动应当收束。","classic":"師出以律，否臧凶。","source":"《周易》爻辞","modern":{"image":"“師出以律，否臧凶。”是师在“潜藏”阶段留下的具体图景。","situation":"事情刚在“组织与纪律”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是统一行动与个体差异需要协调，两者要放在同一次权衡里。","warning":"责任模糊导致权力和后果错位。","advice":["明确目标、负责人和停止条件。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"止损","meaning":"在师第1爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“每个人是否都知道自己负责什么以及为何负责”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"止损","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“责任模糊导致权力和后果错位”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录师初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"师来到二位，个人判断正与资源、规则或他人发生接触 当前拉扯在于：若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大统一行动与个体差异需要协调 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“明确目标、负责人和停止条件”；若出现“责任模糊导致权力和后果错位，而不是把只下命令却不给判断依据当成解决办法，而师第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，就暂停扩大动作。","classic":"在師中吉，无咎，王三錫命。","source":"《周易》爻辞","modern":{"image":"“在師中吉，无咎，王三錫命。”是师在“接触”阶段留下的具体图景。","situation":"师来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大统一行动与个体差异需要协调。","warning":"责任模糊导致权力和后果错位，而不是把只下命令却不给判断依据当成解决办法，而师第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","advice":["明确目标、负责人和停止条件。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在师第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“每个人是否都知道自己负责什么以及为何负责”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“明确目标、负责人和停止条件”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“明确目标、负责人和停止条件”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“明确目标、负责人和停止条件”，可以保持小步推进。","pause_if":"若出现“责任模糊导致权力和后果错位，而不是把只下命令却不给判断依据当成解决办法，而师第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，先暂停扩大投入。"},"action":{"do":"明确目标、负责人和停止条件","review":"完成后记录师九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻把变化落在具体环节：这一爻处在容易用力过度的位置，调整比加码更重要 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意责任模糊导致权力和后果错位会在此时放大。","classic":"師或輿尸，凶。","source":"《周易》爻辞","modern":{"image":"“師或輿尸，凶。”是师在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是统一行动与个体差异需要协调，两者要放在同一次权衡里。","warning":"责任模糊导致权力和后果错位会在此时放大。","advice":["明确目标、负责人和停止条件。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"止损","meaning":"在师第3爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“每个人是否都知道自己负责什么以及为何负责”核对判断"},"tone":"转折","extended":{"trigger":{"label":"止损","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“责任模糊导致权力和后果错位会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录师六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"局面正在显出边界：局面已经接近新的层级，旧角色未必还能容纳当前变化 若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大统一行动与个体差异需要协调 可以用“明确目标、负责人和停止条件”做一次验证；若责任模糊导致权力和后果错位，行动应当收束。","classic":"師左次，无咎。","source":"《周易》爻辞","modern":{"image":"“師左次，无咎。”是师在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大统一行动与个体差异需要协调。","warning":"责任模糊导致权力和后果错位。","advice":["明确目标、负责人和停止条件。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在师第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“每个人是否都知道自己负责什么以及为何负责”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“明确目标、负责人和停止条件”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“明确目标、负责人和停止条件”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“明确目标、负责人和停止条件”，可以保持小步推进。","pause_if":"若出现“责任模糊导致权力和后果错位”，先暂停扩大投入。"},"action":{"do":"明确目标、负责人和停止条件","review":"完成后记录师六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"关键资源与决定权趋向集中，“组织与纪律”开始影响更多人 当前拉扯在于：此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是统一行动与个体差异需要协调，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“责任模糊导致权力和后果错位”，就暂停扩大动作。","classic":"田有禽，利執言，无咎。長子帥師，弟子輿尸，貞凶。","source":"《周易》爻辞","modern":{"image":"“田有禽，利執言，无咎。長子帥師，弟子輿尸，貞凶。”是师在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“组织与纪律”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是统一行动与个体差异需要协调，两者要放在同一次权衡里。","warning":"责任模糊导致权力和后果错位。","advice":["明确目标、负责人和停止条件。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"止损","meaning":"在师第5爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“每个人是否都知道自己负责什么以及为何负责”核对判断"},"tone":"担当","extended":{"trigger":{"label":"止损","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“责任模糊导致权力和后果错位”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录师六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻把变化落在具体环节：师来到上位，已有路径可能完成使命，也可能因过度而失衡 现实条件尚不足以支持扩大动作，是接下来值得核对的信号。完成“明确目标、负责人和停止条件”后再看反馈；同时留意责任模糊导致权力和后果错位，而不是把只下命令却不给判断依据当成解决办法，而师第6爻处在“收束”阶段。","classic":"大君有命，開國承家，小人勿用。","source":"《周易》爻辞","modern":{"image":"“大君有命，開國承家，小人勿用。”是师在“收束”阶段留下的具体图景。","situation":"师来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大统一行动与个体差异需要协调。","warning":"责任模糊导致权力和后果错位，而不是把只下命令却不给判断依据当成解决办法，而师第6爻处在“收束”阶段。","advice":["明确目标、负责人和停止条件。","列出应当停止、保留和移交的事项。"],"signal":{"label":"暂停","meaning":"在师第6爻里，爻辞给出明确的收势信号，眼下不宜把意愿直接变成大动作，可用“每个人是否都知道自己负责什么以及为何负责”核对判断"},"tone":"收束","extended":{"trigger":{"label":"暂停","observe":"完成“明确目标、负责人和停止条件”后，观察是否出现“现实条件尚不足以支持扩大动作”的现实反馈。","threshold":"只有当现实中出现与“明确目标、负责人和停止条件”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“明确目标、负责人和停止条件”，可以保持小步推进。","pause_if":"若出现“责任模糊导致权力和后果错位，而不是把只下命令却不给判断依据当成解决办法，而师第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"明确目标、负责人和停止条件","review":"完成后记录师上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"复杂任务要靠纪律与清晰分工，而非个人逞强","strengths":["已有组织资源或可调动的人手","复杂局面需要明确责任与节奏。先定原则，再带着团队行动"],"tensions":["统一行动与个体差异需要协调"],"risks":["责任模糊导致权力和后果错位"],"actions":["明确目标、负责人和停止条件"],"avoid":["只下命令却不给判断依据"],"questions":["每个人是否都知道自己负责什么以及为何负责？"],"extended":{"situation":{"direct":"眼下的重点是复杂任务要靠纪律与清晰分工，而非个人逞强。","support":"已经可以利用的是：已有组织资源或可调动的人手。","constraint":"仍需核实的是：统一行动与个体差异需要协调。"},"relationship":{"inner":"下卦坎，内部动力偏向风险、试探与信息缺口。","outer":"上卦坤，外部处境更受承载、配合与现实基础影响。","interaction":"内部想以“风险、试探与信息缺口”回应外部的“承载、配合与现实基础”；两边能否对接，要看“统一行动与个体差异需要协调”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“已有组织资源或可调动的人手”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“明确目标、负责人和停止条件”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“只下命令却不给判断依据”，风险会被放大。","effect":"最需要防止的是：责任模糊导致权力和后果错位。"},"paths":{"ready":"如果关键条件得到确认，可以继续“明确目标、负责人和停止条件”，但仍以小步反馈决定是否扩大。","not_ready":"如果“统一行动与个体差异需要协调”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"明确目标、负责人和停止条件","observe":"每个人是否都知道自己负责什么以及为何负责？","continue_if":"出现与“已有组织资源或可调动的人手”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“只下命令却不给判断依据”或“责任模糊导致权力和后果错位”的迹象。"}}}},{"id":8,"name":"比","pinyin":"bǐ","theme":"亲近与结伴","reflection":"选择价值观相近的人同行；真诚连接比讨好所有人更重要。","source_note":"据《周易》比卦意象整理","upper_trigram":6,"lower_trigram":8,"lines":{"1":{"title":"初六","interpretation":"比落在初位，眼下更像在辨认方向，而不是兑现结果 当前拉扯在于：真正的拉扯来自靠近他人与保持独立判断之间需要分寸，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“为了归属感忽略价值差异”，就暂停扩大动作。","classic":"有孚，比之无咎。有孚盈缶，終來，有它吉。","source":"《周易》爻辞","modern":{"image":"“有孚，比之无咎。有孚盈缶，終來，有它吉。”是比在“潜藏”阶段留下的具体图景。","situation":"比落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自靠近他人与保持独立判断之间需要分寸，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"为了归属感忽略价值差异。","advice":["用一件小事检验彼此是否可靠。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在比第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“这段连接建立在共同目标上，还是害怕独处上”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“为了归属感忽略价值差异”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录比初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"这一爻把变化落在具体环节：这一阶段不再只靠设想，回应和基本功开始决定走向 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“用一件小事检验彼此是否可靠”后再看反馈；同时留意为了归属感忽略价值差异。","classic":"比之自內，貞吉。","source":"《周易》爻辞","modern":{"image":"“比之自內，貞吉。”是比在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而靠近他人与保持独立判断之间需要分寸也会在这一爻变得具体。","warning":"为了归属感忽略价值差异。","advice":["用一件小事检验彼此是否可靠。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在比第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“这段连接建立在共同目标上，还是害怕独处上”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“用一件小事检验彼此是否可靠”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“用一件小事检验彼此是否可靠”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“用一件小事检验彼此是否可靠”，可以保持小步推进。","pause_if":"若出现“为了归属感忽略价值差异”，先暂停扩大投入。"},"action":{"do":"用一件小事检验彼此是否可靠","review":"完成后记录比六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面正在显出边界：事情跨入转折带，焦虑可能比事实更快推动决定 真正的拉扯来自靠近他人与保持独立判断之间需要分寸，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若为了归属感忽略价值差异，而不是把以讨好换取暂时接纳当成解决办法，而比第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码，行动应当收束。","classic":"比之匪人。","source":"《周易》爻辞","modern":{"image":"“比之匪人。”是比在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自靠近他人与保持独立判断之间需要分寸，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"为了归属感忽略价值差异，而不是把以讨好换取暂时接纳当成解决办法，而比第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","advice":["用一件小事检验彼此是否可靠。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在比第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“这段连接建立在共同目标上，还是害怕独处上”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“为了归属感忽略价值差异，而不是把以讨好换取暂时接纳当成解决办法，而比第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录比六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"事情正由内部走向外部，“亲近与结伴”需要重新确认位置和权限 当前拉扯在于：向外推进的需要与边界尚未说清之间互相牵制，而靠近他人与保持独立判断之间需要分寸也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“用一件小事检验彼此是否可靠”；若出现“为了归属感忽略价值差异会在此时放大”，就暂停扩大动作。","classic":"外比之，貞吉。","source":"《周易》爻辞","modern":{"image":"“外比之，貞吉。”是比在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“亲近与结伴”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而靠近他人与保持独立判断之间需要分寸也会在这一爻变得具体。","warning":"为了归属感忽略价值差异会在此时放大。","advice":["用一件小事检验彼此是否可靠。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在比第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“这段连接建立在共同目标上，还是害怕独处上”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“用一件小事检验彼此是否可靠”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“用一件小事检验彼此是否可靠”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“用一件小事检验彼此是否可靠”，可以保持小步推进。","pause_if":"若出现“为了归属感忽略价值差异会在此时放大”，先暂停扩大投入。"},"action":{"do":"用一件小事检验彼此是否可靠","review":"完成后记录比六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一爻把变化落在具体环节：比来到五位，能力之外还要衡量整体承接和长期后果 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意为了归属感忽略价值差异。","classic":"顯比，王用三驅，失前禽，邑人不誡，吉。","source":"《周易》爻辞","modern":{"image":"“顯比，王用三驅，失前禽，邑人不誡，吉。”是比在“担当”阶段留下的具体图景。","situation":"比来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自靠近他人与保持独立判断之间需要分寸，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"为了归属感忽略价值差异。","advice":["用一件小事检验彼此是否可靠。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在比第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“这段连接建立在共同目标上，还是害怕独处上”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“为了归属感忽略价值差异”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录比九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"局面正在显出边界：这一爻处在阶段末端，下一步先要判断什么已经结束 维持既有成果与允许阶段结束之间存在拉扯，而靠近他人与保持独立判断之间需要分寸也会在这一爻变得具体 可以用“用一件小事检验彼此是否可靠”做一次验证；若为了归属感忽略价值差异，行动应当收束。","classic":"比之无首，凶。","source":"《周易》爻辞","modern":{"image":"“比之无首，凶。”是比在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而靠近他人与保持独立判断之间需要分寸也会在这一爻变得具体。","warning":"为了归属感忽略价值差异。","advice":["用一件小事检验彼此是否可靠。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在比第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“这段连接建立在共同目标上，还是害怕独处上”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“用一件小事检验彼此是否可靠”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“用一件小事检验彼此是否可靠”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“用一件小事检验彼此是否可靠”，可以保持小步推进。","pause_if":"若出现“为了归属感忽略价值差异”，先暂停扩大投入。"},"action":{"do":"用一件小事检验彼此是否可靠","review":"完成后记录比上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"结伴的质量取决于共同原则，而非表面的热络","strengths":["有建立互信和互助关系的可能","选择价值观相近的人同行"],"tensions":["靠近他人与保持独立判断之间需要分寸"],"risks":["为了归属感忽略价值差异"],"actions":["用一件小事检验彼此是否可靠"],"avoid":["以讨好换取暂时接纳"],"questions":["这段连接建立在共同目标上，还是害怕独处上？"],"extended":{"situation":{"direct":"眼下的重点是结伴的质量取决于共同原则，而非表面的热络。","support":"已经可以利用的是：有建立互信和互助关系的可能。","constraint":"仍需核实的是：靠近他人与保持独立判断之间需要分寸。"},"relationship":{"inner":"下卦坤，内部动力偏向承载、配合与现实基础。","outer":"上卦坎，外部处境更受风险、试探与信息缺口影响。","interaction":"内部想以“承载、配合与现实基础”回应外部的“风险、试探与信息缺口”；两边能否对接，要看“靠近他人与保持独立判断之间需要分寸”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“有建立互信和互助关系的可能”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“用一件小事检验彼此是否可靠”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“以讨好换取暂时接纳”，风险会被放大。","effect":"最需要防止的是：为了归属感忽略价值差异。"},"paths":{"ready":"如果关键条件得到确认，可以继续“用一件小事检验彼此是否可靠”，但仍以小步反馈决定是否扩大。","not_ready":"如果“靠近他人与保持独立判断之间需要分寸”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"用一件小事检验彼此是否可靠","observe":"这段连接建立在共同目标上，还是害怕独处上？","continue_if":"出现与“有建立互信和互助关系的可能”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“以讨好换取暂时接纳”或“为了归属感忽略价值差异”的迹象。"}}}},{"id":9,"name":"小畜","pinyin":"xiǎo xù","theme":"小处蓄力","reflection":"进展虽小仍在累积。收拢精力，先把可控的细节做扎实。","source_note":"据《周易》小畜卦意象整理","upper_trigram":5,"lower_trigram":1,"lines":{"1":{"title":"初九","interpretation":"这一爻把变化落在具体环节：这一爻处在起步处，“小幅积累正在形成力量，眼下重在收拢而非扩张”仍需低成本试探 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意因为成果不显眼就频繁换方向会在此时放大。","classic":"復自道，何其咎，吉。","source":"《周易》爻辞","modern":{"image":"“復自道，何其咎，吉。”是小畜在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“小幅积累正在形成力量，眼下重在收拢而非扩张”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大进展缓慢容易诱发急于求成。","warning":"因为成果不显眼就频繁换方向会在此时放大。","advice":["选一个可控细节连续改进七天。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在小畜第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪项微小积累最可能在以后形成杠杆”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“因为成果不显眼就频繁换方向会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录小畜初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"局面正在显出边界：局面正从内部准备转向真实互动，关系与条件逐渐可见 此时一面是自己的节奏需要与现实反馈相互校准，另一面是进展缓慢容易诱发急于求成，两者要放在同一次权衡里 可以用“选一个可控细节连续改进七天”做一次验证；若因为成果不显眼就频繁换方向，行动应当收束。","classic":"牽復，吉。","source":"《周易》爻辞","modern":{"image":"“牽復，吉。”是小畜在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是进展缓慢容易诱发急于求成，两者要放在同一次权衡里。","warning":"因为成果不显眼就频繁换方向。","advice":["选一个可控细节连续改进七天。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在小畜第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪项微小积累最可能在以后形成杠杆”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“选一个可控细节连续改进七天”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“选一个可控细节连续改进七天”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选一个可控细节连续改进七天”，可以保持小步推进。","pause_if":"若出现“因为成果不显眼就频繁换方向”，先暂停扩大投入。"},"action":{"do":"选一个可控细节连续改进七天","review":"完成后记录小畜九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面来到内外转换处，“小处蓄力”开始承受压力测试 当前拉扯在于：若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大进展缓慢容易诱发急于求成 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“因为成果不显眼就频繁换方向”，就暂停扩大动作。","classic":"輿說輻，夫妻反目。","source":"《周易》爻辞","modern":{"image":"“輿說輻，夫妻反目。”是小畜在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“小处蓄力”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大进展缓慢容易诱发急于求成。","warning":"因为成果不显眼就频繁换方向。","advice":["选一个可控细节连续改进七天。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在小畜第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪项微小积累最可能在以后形成杠杆”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“因为成果不显眼就频繁换方向”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录小畜九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：小畜来到四位，跨出原有边界之前要先说明责任 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“选一个可控细节连续改进七天”后再看反馈；同时留意因为成果不显眼就频繁换方向，而不是把同时追逐多个大目标当成解决办法，而小畜第4爻处在“越界”阶段。","classic":"有孚，血去惕出，无咎。","source":"《周易》爻辞","modern":{"image":"“有孚，血去惕出，无咎。”是小畜在“越界”阶段留下的具体图景。","situation":"小畜来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是进展缓慢容易诱发急于求成，两者要放在同一次权衡里。","warning":"因为成果不显眼就频繁换方向，而不是把同时追逐多个大目标当成解决办法，而小畜第4爻处在“越界”阶段。","advice":["选一个可控细节连续改进七天。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在小畜第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“哪项微小积累最可能在以后形成杠杆”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“选一个可控细节连续改进七天”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“选一个可控细节连续改进七天”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选一个可控细节连续改进七天”，可以保持小步推进。","pause_if":"若出现“因为成果不显眼就频繁换方向，而不是把同时追逐多个大目标当成解决办法，而小畜第4爻处在“越界”阶段”，先暂停扩大投入。"},"action":{"do":"选一个可控细节连续改进七天","review":"完成后记录小畜六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面正在显出边界：这一阶段已进入主位，选择会放大为规则或示范 若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大进展缓慢容易诱发急于求成 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若因为成果不显眼就频繁换方向会在此时放大，行动应当收束。","classic":"有孚攣如，富以其鄰。","source":"《周易》爻辞","modern":{"image":"“有孚攣如，富以其鄰。”是小畜在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大进展缓慢容易诱发急于求成。","warning":"因为成果不显眼就频繁换方向会在此时放大。","advice":["选一个可控细节连续改进七天。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在小畜第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪项微小积累最可能在以后形成杠杆”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“因为成果不显眼就频繁换方向会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录小畜九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面走到极处，继续延长旧办法未必带来同等收益 当前拉扯在于：此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是进展缓慢容易诱发急于求成，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“选一个可控细节连续改进七天”；若出现“因为成果不显眼就频繁换方向”，就暂停扩大动作。","classic":"既雨既處，尚德載，婦貞厲。月幾望，君子征凶。","source":"《周易》爻辞","modern":{"image":"“既雨既處，尚德載，婦貞厲。月幾望，君子征凶。”是小畜在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是进展缓慢容易诱发急于求成，两者要放在同一次权衡里。","warning":"因为成果不显眼就频繁换方向。","advice":["选一个可控细节连续改进七天。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在小畜第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪项微小积累最可能在以后形成杠杆”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“选一个可控细节连续改进七天”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“选一个可控细节连续改进七天”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选一个可控细节连续改进七天”，可以保持小步推进。","pause_if":"若出现“因为成果不显眼就频繁换方向”，先暂停扩大投入。"},"action":{"do":"选一个可控细节连续改进七天","review":"完成后记录小畜上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"小幅积累正在形成力量，眼下重在收拢而非扩张","strengths":["细节和日常投入已经产生基础","进展虽小仍在累积。收拢精力，先把可控的细节做扎实"],"tensions":["进展缓慢容易诱发急于求成"],"risks":["因为成果不显眼就频繁换方向"],"actions":["选一个可控细节连续改进七天"],"avoid":["同时追逐多个大目标"],"questions":["哪项微小积累最可能在以后形成杠杆？"],"extended":{"situation":{"direct":"眼下的重点是小幅积累正在形成力量，眼下重在收拢而非扩张。","support":"已经可以利用的是：细节和日常投入已经产生基础。","constraint":"仍需核实的是：进展缓慢容易诱发急于求成。"},"relationship":{"inner":"下卦乾，内部动力偏向主动、原则与承担。","outer":"上卦巽，外部处境更受渗透、调整与持续影响影响。","interaction":"内部想以“主动、原则与承担”回应外部的“渗透、调整与持续影响”；两边能否对接，要看“进展缓慢容易诱发急于求成”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“细节和日常投入已经产生基础”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“选一个可控细节连续改进七天”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“同时追逐多个大目标”，风险会被放大。","effect":"最需要防止的是：因为成果不显眼就频繁换方向。"},"paths":{"ready":"如果关键条件得到确认，可以继续“选一个可控细节连续改进七天”，但仍以小步反馈决定是否扩大。","not_ready":"如果“进展缓慢容易诱发急于求成”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"选一个可控细节连续改进七天","observe":"哪项微小积累最可能在以后形成杠杆？","continue_if":"出现与“细节和日常投入已经产生基础”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“同时追逐多个大目标”或“因为成果不显眼就频繁换方向”的迹象。"}}}},{"id":10,"name":"履","pinyin":"lǚ","theme":"谨慎前行","reflection":"面对压力时，礼貌与清醒能保护你。一步一步走，不逞强。","source_note":"据《周易》履卦意象整理","upper_trigram":1,"lower_trigram":2,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：变化尚在根部，先分清已经发生的事实和仍在期待的部分 内在意愿已经出现，外部条件尚未完全成形，而前进意愿与现实风险贴得很近也会在这一爻变得具体 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若把谨慎误解为退缩，而不是把用侥幸测试不能承担的风险当成解决办法，而履第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论，行动应当收束。","classic":"素履，往无咎。","source":"《周易》爻辞","modern":{"image":"“素履，往无咎。”是履在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而前进意愿与现实风险贴得很近也会在这一爻变得具体。","warning":"把谨慎误解为退缩，而不是把用侥幸测试不能承担的风险当成解决办法，而履第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["在行动前写清红线和退出方式。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在履第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“哪一步可以前进，同时仍保留回头的空间”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把谨慎误解为退缩，而不是把用侥幸测试不能承担的风险当成解决办法，而履第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录履初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"事情开始进入现实协作，“谨慎前行”要接受反馈检验 当前拉扯在于：真正的拉扯来自前进意愿与现实风险贴得很近，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“在行动前写清红线和退出方式”；若出现“把谨慎误解为退缩会在此时放大”，就暂停扩大动作。","classic":"履道坦坦，幽人貞吉。","source":"《周易》爻辞","modern":{"image":"“履道坦坦，幽人貞吉。”是履在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“谨慎前行”要接受反馈检验。","tension":"真正的拉扯来自前进意愿与现实风险贴得很近，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"把谨慎误解为退缩会在此时放大。","advice":["在行动前写清红线和退出方式。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在履第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪一步可以前进，同时仍保留回头的空间”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“在行动前写清红线和退出方式”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“在行动前写清红线和退出方式”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“在行动前写清红线和退出方式”，可以保持小步推进。","pause_if":"若出现“把谨慎误解为退缩会在此时放大”，先暂停扩大投入。"},"action":{"do":"在行动前写清红线和退出方式","review":"完成后记录履九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻把变化落在具体环节：履行至三位，旧方法的边界和新选择的代价同时出现 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意把谨慎误解为退缩。","classic":"眇能視，跛能履，履虎尾，咥人凶。武人為于大君。","source":"《周易》爻辞","modern":{"image":"“眇能視，跛能履，履虎尾，咥人凶。武人為于大君。”是履在“转折”阶段留下的具体图景。","situation":"履行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而前进意愿与现实风险贴得很近也会在这一爻变得具体。","warning":"把谨慎误解为退缩。","advice":["在行动前写清红线和退出方式。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"止损","meaning":"在履第3爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪一步可以前进，同时仍保留回头的空间”核对判断"},"tone":"转折","extended":{"trigger":{"label":"止损","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把谨慎误解为退缩”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录履六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 真正的拉扯来自前进意愿与现实风险贴得很近，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题 可以用“在行动前写清红线和退出方式”做一次验证；若把谨慎误解为退缩，行动应当收束。","classic":"履虎尾，愬愬，終吉。","source":"《周易》爻辞","modern":{"image":"“履虎尾，愬愬，終吉。”是履在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自前进意愿与现实风险贴得很近，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"把谨慎误解为退缩。","advice":["在行动前写清红线和退出方式。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在履第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪一步可以前进，同时仍保留回头的空间”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“在行动前写清红线和退出方式”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“在行动前写清红线和退出方式”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“在行动前写清红线和退出方式”，可以保持小步推进。","pause_if":"若出现“把谨慎误解为退缩”，先暂停扩大投入。"},"action":{"do":"在行动前写清红线和退出方式","review":"完成后记录履九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面要求从个人得失转向整体结果和持续责任 当前拉扯在于：扩大影响与照顾整体承接能力之间需要平衡，而前进意愿与现实风险贴得很近也会在这一爻变得具体 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“把谨慎误解为退缩，而不是把用侥幸测试不能承担的风险当成解决办法，而履第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，就暂停扩大动作。","classic":"夬履，貞厲。","source":"《周易》爻辞","modern":{"image":"“夬履，貞厲。”是履在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而前进意愿与现实风险贴得很近也会在这一爻变得具体。","warning":"把谨慎误解为退缩，而不是把用侥幸测试不能承担的风险当成解决办法，而履第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["在行动前写清红线和退出方式。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在履第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪一步可以前进，同时仍保留回头的空间”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把谨慎误解为退缩，而不是把用侥幸测试不能承担的风险当成解决办法，而履第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录履九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"这一爻把变化落在具体环节：当前循环接近上限，“谨慎前行”需要从继续加力转向收束复盘 现实反馈与当前方向开始相互支持，是接下来值得核对的信号。完成“在行动前写清红线和退出方式”后再看反馈；同时留意把谨慎误解为退缩会在此时放大。","classic":"視履，考祥其旋，元吉。","source":"《周易》爻辞","modern":{"image":"“視履，考祥其旋，元吉。”是履在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“谨慎前行”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自前进意愿与现实风险贴得很近，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"把谨慎误解为退缩会在此时放大。","advice":["在行动前写清红线和退出方式。","列出应当停止、保留和移交的事项。"],"signal":{"label":"顺势","meaning":"在履第6爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“哪一步可以前进，同时仍保留回头的空间”核对判断"},"tone":"收束","extended":{"trigger":{"label":"顺势","observe":"完成“在行动前写清红线和退出方式”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“在行动前写清红线和退出方式”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“在行动前写清红线和退出方式”，可以保持小步推进。","pause_if":"若出现“把谨慎误解为退缩会在此时放大”，先暂停扩大投入。"},"action":{"do":"在行动前写清红线和退出方式","review":"完成后记录履上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"压力环境中，清醒的分寸比胆量更能保护行动","strengths":["具备继续前行所需的基本能力","面对压力时，礼貌与清醒能保护你。一步一步走，不逞强"],"tensions":["前进意愿与现实风险贴得很近"],"risks":["把谨慎误解为退缩"],"actions":["在行动前写清红线和退出方式"],"avoid":["用侥幸测试不能承担的风险"],"questions":["哪一步可以前进，同时仍保留回头的空间？"],"extended":{"situation":{"direct":"眼下的重点是压力环境中，清醒的分寸比胆量更能保护行动。","support":"已经可以利用的是：具备继续前行所需的基本能力。","constraint":"仍需核实的是：前进意愿与现实风险贴得很近。"},"relationship":{"inner":"下卦兑，内部动力偏向交流、回应与协商。","outer":"上卦乾，外部处境更受主动、原则与承担影响。","interaction":"内部想以“交流、回应与协商”回应外部的“主动、原则与承担”；两边能否对接，要看“前进意愿与现实风险贴得很近”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“具备继续前行所需的基本能力”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“在行动前写清红线和退出方式”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用侥幸测试不能承担的风险”，风险会被放大。","effect":"最需要防止的是：把谨慎误解为退缩。"},"paths":{"ready":"如果关键条件得到确认，可以继续“在行动前写清红线和退出方式”，但仍以小步反馈决定是否扩大。","not_ready":"如果“前进意愿与现实风险贴得很近”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"在行动前写清红线和退出方式","observe":"哪一步可以前进，同时仍保留回头的空间？","continue_if":"出现与“具备继续前行所需的基本能力”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用侥幸测试不能承担的风险”或“把谨慎误解为退缩”的迹象。"}}}},{"id":11,"name":"泰","pinyin":"tài","theme":"通达与交融","reflection":"当沟通顺畅时，适合推进合作；也别忽略为未来保留余地。","source_note":"据《周易》泰卦意象整理","upper_trigram":8,"lower_trigram":1,"lines":{"1":{"title":"初九","interpretation":"事情刚在“通达与交融”的起点露出端倪，可用条件还不多 当前拉扯在于：此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是眼前顺利可能削弱对长期风险的敏感，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“把暂时畅通当成永久状态”，就暂停扩大动作。","classic":"拔茅茹，以其彙，征吉。","source":"《周易》爻辞","modern":{"image":"“拔茅茹，以其彙，征吉。”是泰在“潜藏”阶段留下的具体图景。","situation":"事情刚在“通达与交融”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是眼前顺利可能削弱对长期风险的敏感，两者要放在同一次权衡里。","warning":"把暂时畅通当成永久状态。","advice":["推进合作的同时留下复盘节点。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在泰第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“如果顺风结束，什么仍能支撑这件事”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把暂时畅通当成永久状态”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录泰初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一爻把变化落在具体环节：泰来到二位，个人判断正与资源、规则或他人发生接触 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“推进合作的同时留下复盘节点”后再看反馈；同时留意把暂时畅通当成永久状态，而不是把把所有资源一次投入当成解决办法，而泰第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","classic":"包荒，用馮河，不遐遺，朋亡，得尚于中行。","source":"《周易》爻辞","modern":{"image":"“包荒，用馮河，不遐遺，朋亡，得尚于中行。”是泰在“接触”阶段留下的具体图景。","situation":"泰来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大眼前顺利可能削弱对长期风险的敏感。","warning":"把暂时畅通当成永久状态，而不是把把所有资源一次投入当成解决办法，而泰第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","advice":["推进合作的同时留下复盘节点。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在泰第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“如果顺风结束，什么仍能支撑这件事”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“推进合作的同时留下复盘节点”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“推进合作的同时留下复盘节点”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“推进合作的同时留下复盘节点”，可以保持小步推进。","pause_if":"若出现“把暂时畅通当成永久状态，而不是把把所有资源一次投入当成解决办法，而泰第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，先暂停扩大投入。"},"action":{"do":"推进合作的同时留下复盘节点","review":"完成后记录泰九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面正在显出边界：这一爻处在容易用力过度的位置，调整比加码更重要 此时一面是继续原路与承认需要调整之间发生冲突，另一面是眼前顺利可能削弱对长期风险的敏感，两者要放在同一次权衡里 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若把暂时畅通当成永久状态会在此时放大，行动应当收束。","classic":"无平不陂，无往不復。艱貞无咎。勿恤其孚，于食有福。","source":"《周易》爻辞","modern":{"image":"“无平不陂，无往不復。艱貞无咎。勿恤其孚，于食有福。”是泰在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是眼前顺利可能削弱对长期风险的敏感，两者要放在同一次权衡里。","warning":"把暂时畅通当成永久状态会在此时放大。","advice":["推进合作的同时留下复盘节点。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"守正","meaning":"在泰第3爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“如果顺风结束，什么仍能支撑这件事”核对判断"},"tone":"转折","extended":{"trigger":{"label":"守正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把暂时畅通当成永久状态会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录泰九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"局面已经接近新的层级，旧角色未必还能容纳当前变化 当前拉扯在于：若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大眼前顺利可能削弱对长期风险的敏感 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“推进合作的同时留下复盘节点”；若出现“把暂时畅通当成永久状态”，就暂停扩大动作。","classic":"翩翩，不富以其鄰，不戒以孚。","source":"《周易》爻辞","modern":{"image":"“翩翩，不富以其鄰，不戒以孚。”是泰在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大眼前顺利可能削弱对长期风险的敏感。","warning":"把暂时畅通当成永久状态。","advice":["推进合作的同时留下复盘节点。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在泰第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“如果顺风结束，什么仍能支撑这件事”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“推进合作的同时留下复盘节点”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“推进合作的同时留下复盘节点”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“推进合作的同时留下复盘节点”，可以保持小步推进。","pause_if":"若出现“把暂时畅通当成永久状态”，先暂停扩大投入。"},"action":{"do":"推进合作的同时留下复盘节点","review":"完成后记录泰六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"这一爻把变化落在具体环节：关键资源与决定权趋向集中，“通达与交融”开始影响更多人 现实反馈与当前方向开始相互支持，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意把暂时畅通当成永久状态。","classic":"帝乙歸妹，以祉元吉。","source":"《周易》爻辞","modern":{"image":"“帝乙歸妹，以祉元吉。”是泰在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“通达与交融”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是眼前顺利可能削弱对长期风险的敏感，两者要放在同一次权衡里。","warning":"把暂时畅通当成永久状态。","advice":["推进合作的同时留下复盘节点。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"顺势","meaning":"在泰第5爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“如果顺风结束，什么仍能支撑这件事”核对判断"},"tone":"担当","extended":{"trigger":{"label":"顺势","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把暂时畅通当成永久状态”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录泰六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"局面正在显出边界：泰来到上位，已有路径可能完成使命，也可能因过度而失衡 若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大眼前顺利可能削弱对长期风险的敏感 可以用“推进合作的同时留下复盘节点”做一次验证；若把暂时畅通当成永久状态，而不是把把所有资源一次投入当成解决办法，而泰第6爻处在“收束”阶段，还需防止执着延续已经完成或失效的阶段，行动应当收束。","classic":"城復于隍，勿用師。自邑告命，貞吝。","source":"《周易》爻辞","modern":{"image":"“城復于隍，勿用師。自邑告命，貞吝。”是泰在“收束”阶段留下的具体图景。","situation":"泰来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大眼前顺利可能削弱对长期风险的敏感。","warning":"把暂时畅通当成永久状态，而不是把把所有资源一次投入当成解决办法，而泰第6爻处在“收束”阶段，还需防止执着延续已经完成或失效的阶段。","advice":["推进合作的同时留下复盘节点。","列出应当停止、保留和移交的事项。"],"signal":{"label":"暂停","meaning":"在泰第6爻里，爻辞给出明确的收势信号，眼下不宜把意愿直接变成大动作，可用“如果顺风结束，什么仍能支撑这件事”核对判断"},"tone":"收束","extended":{"trigger":{"label":"暂停","observe":"完成“推进合作的同时留下复盘节点”后，观察是否出现“现实条件尚不足以支持扩大动作”的现实反馈。","threshold":"只有当现实中出现与“推进合作的同时留下复盘节点”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“推进合作的同时留下复盘节点”，可以保持小步推进。","pause_if":"若出现“把暂时畅通当成永久状态，而不是把把所有资源一次投入当成解决办法，而泰第6爻处在“收束”阶段，还需防止执着延续已经完成或失效的阶段”，先暂停扩大投入。"},"action":{"do":"推进合作的同时留下复盘节点","review":"完成后记录泰上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"通达时期适合协作，也要为变化预留余地","strengths":["沟通、资源或关系正形成顺畅循环","当沟通顺畅时，适合推进合作"],"tensions":["眼前顺利可能削弱对长期风险的敏感"],"risks":["把暂时畅通当成永久状态"],"actions":["推进合作的同时留下复盘节点"],"avoid":["把所有资源一次投入"],"questions":["如果顺风结束，什么仍能支撑这件事？"],"extended":{"situation":{"direct":"眼下的重点是通达时期适合协作，也要为变化预留余地。","support":"已经可以利用的是：沟通、资源或关系正形成顺畅循环。","constraint":"仍需核实的是：眼前顺利可能削弱对长期风险的敏感。"},"relationship":{"inner":"下卦乾，内部动力偏向主动、原则与承担。","outer":"上卦坤，外部处境更受承载、配合与现实基础影响。","interaction":"内部想以“主动、原则与承担”回应外部的“承载、配合与现实基础”；两边能否对接，要看“眼前顺利可能削弱对长期风险的敏感”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“沟通、资源或关系正形成顺畅循环”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“推进合作的同时留下复盘节点”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把所有资源一次投入”，风险会被放大。","effect":"最需要防止的是：把暂时畅通当成永久状态。"},"paths":{"ready":"如果关键条件得到确认，可以继续“推进合作的同时留下复盘节点”，但仍以小步反馈决定是否扩大。","not_ready":"如果“眼前顺利可能削弱对长期风险的敏感”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"推进合作的同时留下复盘节点","observe":"如果顺风结束，什么仍能支撑这件事？","continue_if":"出现与“沟通、资源或关系正形成顺畅循环”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把所有资源一次投入”或“把暂时畅通当成永久状态”的迹象。"}}}},{"id":12,"name":"否","pinyin":"pǐ","theme":"阻塞与收守","reflection":"暂时不通时，先收回消耗性的投入，整理内在与边界。","source_note":"据《周易》否卦意象整理","upper_trigram":1,"lower_trigram":8,"lines":{"1":{"title":"初六","interpretation":"这一爻把变化落在具体环节：否落在初位，眼下更像在辨认方向，而不是兑现结果 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意为了证明有效而持续加码。","classic":"拔茅茹，以其彙，貞吉，亨。","source":"《周易》爻辞","modern":{"image":"“拔茅茹，以其彙，貞吉，亨。”是否在“潜藏”阶段留下的具体图景。","situation":"否落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自外部不通与内在焦虑相互放大，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"为了证明有效而持续加码。","advice":["暂停一项高消耗低反馈的投入。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在否第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“现在最该保住的核心是什么”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“为了证明有效而持续加码”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录否初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：这一阶段不再只靠设想，回应和基本功开始决定走向 自己的节奏需要与现实反馈相互校准，而外部不通与内在焦虑相互放大也会在这一爻变得具体 可以用“暂停一项高消耗低反馈的投入”做一次验证；若为了证明有效而持续加码，行动应当收束。","classic":"包承，小人吉，大人否亨。","source":"《周易》爻辞","modern":{"image":"“包承，小人吉，大人否亨。”是否在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而外部不通与内在焦虑相互放大也会在这一爻变得具体。","warning":"为了证明有效而持续加码。","advice":["暂停一项高消耗低反馈的投入。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在否第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“现在最该保住的核心是什么”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“暂停一项高消耗低反馈的投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“暂停一项高消耗低反馈的投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“暂停一项高消耗低反馈的投入”，可以保持小步推进。","pause_if":"若出现“为了证明有效而持续加码”，先暂停扩大投入。"},"action":{"do":"暂停一项高消耗低反馈的投入","review":"完成后记录否六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"事情跨入转折带，焦虑可能比事实更快推动决定 当前拉扯在于：真正的拉扯来自外部不通与内在焦虑相互放大，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“为了证明有效而持续加码，而不是把在错误的通道里反复用力当成解决办法，而否第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，就暂停扩大动作。","classic":"包羞。","source":"《周易》爻辞","modern":{"image":"“包羞。”是否在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自外部不通与内在焦虑相互放大，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"为了证明有效而持续加码，而不是把在错误的通道里反复用力当成解决办法，而否第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","advice":["暂停一项高消耗低反馈的投入。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在否第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“现在最该保住的核心是什么”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“为了证明有效而持续加码，而不是把在错误的通道里反复用力当成解决办法，而否第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录否六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"这一爻把变化落在具体环节：事情正由内部走向外部，“阻塞与收守”需要重新确认位置和权限 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“暂停一项高消耗低反馈的投入”后再看反馈；同时留意为了证明有效而持续加码会在此时放大。","classic":"有命无咎，疇離祉。","source":"《周易》爻辞","modern":{"image":"“有命无咎，疇離祉。”是否在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“阻塞与收守”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而外部不通与内在焦虑相互放大也会在这一爻变得具体。","warning":"为了证明有效而持续加码会在此时放大。","advice":["暂停一项高消耗低反馈的投入。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在否第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“现在最该保住的核心是什么”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“暂停一项高消耗低反馈的投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“暂停一项高消耗低反馈的投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“暂停一项高消耗低反馈的投入”，可以保持小步推进。","pause_if":"若出现“为了证明有效而持续加码会在此时放大”，先暂停扩大投入。"},"action":{"do":"暂停一项高消耗低反馈的投入","review":"完成后记录否九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面正在显出边界：否来到五位，能力之外还要衡量整体承接和长期后果 真正的拉扯来自外部不通与内在焦虑相互放大，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若为了证明有效而持续加码，行动应当收束。","classic":"休否，大人吉。其亡其亡，繫于苞桑。","source":"《周易》爻辞","modern":{"image":"“休否，大人吉。其亡其亡，繫于苞桑。”是否在“担当”阶段留下的具体图景。","situation":"否来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自外部不通与内在焦虑相互放大，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"为了证明有效而持续加码。","advice":["暂停一项高消耗低反馈的投入。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在否第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“现在最该保住的核心是什么”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“为了证明有效而持续加码”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录否九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"这一爻处在阶段末端，下一步先要判断什么已经结束 当前拉扯在于：维持既有成果与允许阶段结束之间存在拉扯，而外部不通与内在焦虑相互放大也会在这一爻变得具体 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“暂停一项高消耗低反馈的投入”；若出现“为了证明有效而持续加码”，就暂停扩大动作。","classic":"傾否，先否後喜。","source":"《周易》爻辞","modern":{"image":"“傾否，先否後喜。”是否在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而外部不通与内在焦虑相互放大也会在这一爻变得具体。","warning":"为了证明有效而持续加码。","advice":["暂停一项高消耗低反馈的投入。","列出应当停止、保留和移交的事项。"],"signal":{"label":"观察","meaning":"在否第6爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“现在最该保住的核心是什么”核对判断"},"tone":"收束","extended":{"trigger":{"label":"观察","observe":"完成“暂停一项高消耗低反馈的投入”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“暂停一项高消耗低反馈的投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“暂停一项高消耗低反馈的投入”，可以保持小步推进。","pause_if":"若出现“为了证明有效而持续加码”，先暂停扩大投入。"},"action":{"do":"暂停一项高消耗低反馈的投入","review":"完成后记录否上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"阻塞时先保护核心，减少无效消耗","strengths":["仍能通过收守保存判断和资源","暂时不通时，先收回消耗性的投入，整理内在与边界"],"tensions":["外部不通与内在焦虑相互放大"],"risks":["为了证明有效而持续加码"],"actions":["暂停一项高消耗低反馈的投入"],"avoid":["在错误的通道里反复用力"],"questions":["现在最该保住的核心是什么？"],"extended":{"situation":{"direct":"眼下的重点是阻塞时先保护核心，减少无效消耗。","support":"已经可以利用的是：仍能通过收守保存判断和资源。","constraint":"仍需核实的是：外部不通与内在焦虑相互放大。"},"relationship":{"inner":"下卦坤，内部动力偏向承载、配合与现实基础。","outer":"上卦乾，外部处境更受主动、原则与承担影响。","interaction":"内部想以“承载、配合与现实基础”回应外部的“主动、原则与承担”；两边能否对接，要看“外部不通与内在焦虑相互放大”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“仍能通过收守保存判断和资源”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“暂停一项高消耗低反馈的投入”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“在错误的通道里反复用力”，风险会被放大。","effect":"最需要防止的是：为了证明有效而持续加码。"},"paths":{"ready":"如果关键条件得到确认，可以继续“暂停一项高消耗低反馈的投入”，但仍以小步反馈决定是否扩大。","not_ready":"如果“外部不通与内在焦虑相互放大”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"暂停一项高消耗低反馈的投入","observe":"现在最该保住的核心是什么？","continue_if":"出现与“仍能通过收守保存判断和资源”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“在错误的通道里反复用力”或“为了证明有效而持续加码”的迹象。"}}}},{"id":13,"name":"同人","pinyin":"tóng rén","theme":"同道与公开","reflection":"以清晰的共同目标凝聚人心，坦荡沟通比私下揣测更有力量。","source_note":"据《周易》同人卦意象整理","upper_trigram":1,"lower_trigram":3,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：这一爻处在起步处，“共同目标需要公开而清楚，信任来自可见的协作”仍需低成本试探 若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大群体目标与个人动机未必完全一致 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若依赖私下默契代替公开规则会在此时放大，行动应当收束。","classic":"同人于門，无咎。","source":"《周易》爻辞","modern":{"image":"“同人于門，无咎。”是同人在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“共同目标需要公开而清楚，信任来自可见的协作”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大群体目标与个人动机未必完全一致。","warning":"依赖私下默契代替公开规则会在此时放大。","advice":["把共同目标和分歧点写到同一页。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在同人第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“大家真正同意的是什么，而不是口头同意什么”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“依赖私下默契代替公开规则会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录同人初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正从内部准备转向真实互动，关系与条件逐渐可见 当前拉扯在于：此时一面是自己的节奏需要与现实反馈相互校准，另一面是群体目标与个人动机未必完全一致，两者要放在同一次权衡里 当原有做法显出明确代价，需要及时调整时，变化才有现实依据。先做“把共同目标和分歧点写到同一页”；若出现“依赖私下默契代替公开规则”，就暂停扩大动作。","classic":"同人于宗，吝。","source":"《周易》爻辞","modern":{"image":"“同人于宗，吝。”是同人在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是群体目标与个人动机未必完全一致，两者要放在同一次权衡里。","warning":"依赖私下默契代替公开规则。","advice":["把共同目标和分歧点写到同一页。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"修正","meaning":"在同人第2爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“大家真正同意的是什么，而不是口头同意什么”核对判断"},"tone":"接触","extended":{"trigger":{"label":"修正","observe":"完成“把共同目标和分歧点写到同一页”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把共同目标和分歧点写到同一页”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把共同目标和分歧点写到同一页”，可以保持小步推进。","pause_if":"若出现“依赖私下默契代替公开规则”，先暂停扩大投入。"},"action":{"do":"把共同目标和分歧点写到同一页","review":"完成后记录同人六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻把变化落在具体环节：局面来到内外转换处，“同道与公开”开始承受压力测试 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意依赖私下默契代替公开规则。","classic":"伏戎于莽，升其高陵，三歲不興。","source":"《周易》爻辞","modern":{"image":"“伏戎于莽，升其高陵，三歲不興。”是同人在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“同道与公开”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大群体目标与个人动机未必完全一致。","warning":"依赖私下默契代替公开规则。","advice":["把共同目标和分歧点写到同一页。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在同人第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“大家真正同意的是什么，而不是口头同意什么”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“依赖私下默契代替公开规则”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录同人九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：同人来到四位，跨出原有边界之前要先说明责任 此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是群体目标与个人动机未必完全一致，两者要放在同一次权衡里 可以用“把共同目标和分歧点写到同一页”做一次验证；若依赖私下默契代替公开规则，而不是把用阵营感掩盖实际问题当成解决办法，而同人第4爻处在“越界”阶段，行动应当收束。","classic":"乘其墉，弗克攻，吉。","source":"《周易》爻辞","modern":{"image":"“乘其墉，弗克攻，吉。”是同人在“越界”阶段留下的具体图景。","situation":"同人来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是群体目标与个人动机未必完全一致，两者要放在同一次权衡里。","warning":"依赖私下默契代替公开规则，而不是把用阵营感掩盖实际问题当成解决办法，而同人第4爻处在“越界”阶段。","advice":["把共同目标和分歧点写到同一页。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在同人第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“大家真正同意的是什么，而不是口头同意什么”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“把共同目标和分歧点写到同一页”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把共同目标和分歧点写到同一页”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把共同目标和分歧点写到同一页”，可以保持小步推进。","pause_if":"若出现“依赖私下默契代替公开规则，而不是把用阵营感掩盖实际问题当成解决办法，而同人第4爻处在“越界”阶段”，先暂停扩大投入。"},"action":{"do":"把共同目标和分歧点写到同一页","review":"完成后记录同人九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一阶段已进入主位，选择会放大为规则或示范 当前拉扯在于：若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大群体目标与个人动机未必完全一致 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“依赖私下默契代替公开规则会在此时放大”，就暂停扩大动作。","classic":"同人，先號咷而後笑，大師克相遇。","source":"《周易》爻辞","modern":{"image":"“同人，先號咷而後笑，大師克相遇。”是同人在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大群体目标与个人动机未必完全一致。","warning":"依赖私下默契代替公开规则会在此时放大。","advice":["把共同目标和分歧点写到同一页。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在同人第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“大家真正同意的是什么，而不是口头同意什么”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“依赖私下默契代替公开规则会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录同人九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"这一爻把变化落在具体环节：局面走到极处，继续延长旧办法未必带来同等收益 原有做法显出明确代价，需要及时调整，是接下来值得核对的信号。完成“把共同目标和分歧点写到同一页”后再看反馈；同时留意依赖私下默契代替公开规则。","classic":"同人于郊，无悔。","source":"《周易》爻辞","modern":{"image":"“同人于郊，无悔。”是同人在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是群体目标与个人动机未必完全一致，两者要放在同一次权衡里。","warning":"依赖私下默契代替公开规则。","advice":["把共同目标和分歧点写到同一页。","列出应当停止、保留和移交的事项。"],"signal":{"label":"修正","meaning":"在同人第6爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“大家真正同意的是什么，而不是口头同意什么”核对判断"},"tone":"收束","extended":{"trigger":{"label":"修正","observe":"完成“把共同目标和分歧点写到同一页”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把共同目标和分歧点写到同一页”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把共同目标和分歧点写到同一页”，可以保持小步推进。","pause_if":"若出现“依赖私下默契代替公开规则”，先暂停扩大投入。"},"action":{"do":"把共同目标和分歧点写到同一页","review":"完成后记录同人上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"共同目标需要公开而清楚，信任来自可见的协作","strengths":["有机会聚合同道并扩大合作","以清晰的共同目标凝聚人心，坦荡沟通比私下揣测更有力量"],"tensions":["群体目标与个人动机未必完全一致"],"risks":["依赖私下默契代替公开规则"],"actions":["把共同目标和分歧点写到同一页"],"avoid":["用阵营感掩盖实际问题"],"questions":["大家真正同意的是什么，而不是口头同意什么？"],"extended":{"situation":{"direct":"眼下的重点是共同目标需要公开而清楚，信任来自可见的协作。","support":"已经可以利用的是：有机会聚合同道并扩大合作。","constraint":"仍需核实的是：群体目标与个人动机未必完全一致。"},"relationship":{"inner":"下卦离，内部动力偏向辨识、表达与显明。","outer":"上卦乾，外部处境更受主动、原则与承担影响。","interaction":"内部想以“辨识、表达与显明”回应外部的“主动、原则与承担”；两边能否对接，要看“群体目标与个人动机未必完全一致”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“有机会聚合同道并扩大合作”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“把共同目标和分歧点写到同一页”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用阵营感掩盖实际问题”，风险会被放大。","effect":"最需要防止的是：依赖私下默契代替公开规则。"},"paths":{"ready":"如果关键条件得到确认，可以继续“把共同目标和分歧点写到同一页”，但仍以小步反馈决定是否扩大。","not_ready":"如果“群体目标与个人动机未必完全一致”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"把共同目标和分歧点写到同一页","observe":"大家真正同意的是什么，而不是口头同意什么？","continue_if":"出现与“有机会聚合同道并扩大合作”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用阵营感掩盖实际问题”或“依赖私下默契代替公开规则”的迹象。"}}}},{"id":14,"name":"大有","pinyin":"dà yǒu","theme":"丰盛与责任","reflection":"拥有资源时更要保持节制；分享与担当会让成果走得更远。","source_note":"据《周易》大有卦意象整理","upper_trigram":3,"lower_trigram":1,"lines":{"1":{"title":"初九","interpretation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分 当前拉扯在于：内在意愿已经出现，外部条件尚未完全成形，而扩大成果与公平承接之间需要平衡也会在这一爻变得具体 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“让丰盛转化为控制欲，而不是把把短期优势当成理所当然当成解决办法，而大有第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，就暂停扩大动作。","classic":"无交害，匪咎，艱則无咎。","source":"《周易》爻辞","modern":{"image":"“无交害，匪咎，艱則无咎。”是大有在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而扩大成果与公平承接之间需要平衡也会在这一爻变得具体。","warning":"让丰盛转化为控制欲，而不是把把短期优势当成理所当然当成解决办法，而大有第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["说明资源如何使用、由谁受益。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在大有第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“这些资源怎样使用才不会消耗未来的信任”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“让丰盛转化为控制欲，而不是把把短期优势当成理所当然当成解决办法，而大有第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录大有初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一爻把变化落在具体环节：事情开始进入现实协作，“丰盛与责任”要接受反馈检验 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“说明资源如何使用、由谁受益”后再看反馈；同时留意让丰盛转化为控制欲会在此时放大。","classic":"大車以載，有攸往，无咎。","source":"《周易》爻辞","modern":{"image":"“大車以載，有攸往，无咎。”是大有在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“丰盛与责任”要接受反馈检验。","tension":"真正的拉扯来自扩大成果与公平承接之间需要平衡，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"让丰盛转化为控制欲会在此时放大。","advice":["说明资源如何使用、由谁受益。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"守正","meaning":"在大有第2爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“这些资源怎样使用才不会消耗未来的信任”核对判断"},"tone":"接触","extended":{"trigger":{"label":"守正","observe":"完成“说明资源如何使用、由谁受益”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“说明资源如何使用、由谁受益”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“说明资源如何使用、由谁受益”，可以保持小步推进。","pause_if":"若出现“让丰盛转化为控制欲会在此时放大”，先暂停扩大投入。"},"action":{"do":"说明资源如何使用、由谁受益","review":"完成后记录大有九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面正在显出边界：大有行至三位，旧方法的边界和新选择的代价同时出现 继续原路与承认需要调整之间发生冲突，而扩大成果与公平承接之间需要平衡也会在这一爻变得具体 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若让丰盛转化为控制欲，行动应当收束。","classic":"公用亨于天子，小人弗克。","source":"《周易》爻辞","modern":{"image":"“公用亨于天子，小人弗克。”是大有在“转折”阶段留下的具体图景。","situation":"大有行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而扩大成果与公平承接之间需要平衡也会在这一爻变得具体。","warning":"让丰盛转化为控制欲。","advice":["说明资源如何使用、由谁受益。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在大有第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“这些资源怎样使用才不会消耗未来的信任”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“让丰盛转化为控制欲”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录大有九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 当前拉扯在于：真正的拉扯来自扩大成果与公平承接之间需要平衡，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“说明资源如何使用、由谁受益”；若出现“让丰盛转化为控制欲”，就暂停扩大动作。","classic":"匪其彭，无咎。","source":"《周易》爻辞","modern":{"image":"“匪其彭，无咎。”是大有在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自扩大成果与公平承接之间需要平衡，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"让丰盛转化为控制欲。","advice":["说明资源如何使用、由谁受益。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在大有第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“这些资源怎样使用才不会消耗未来的信任”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“说明资源如何使用、由谁受益”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“说明资源如何使用、由谁受益”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“说明资源如何使用、由谁受益”，可以保持小步推进。","pause_if":"若出现“让丰盛转化为控制欲”，先暂停扩大投入。"},"action":{"do":"说明资源如何使用、由谁受益","review":"完成后记录大有九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"这一爻把变化落在具体环节：局面要求从个人得失转向整体结果和持续责任 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意让丰盛转化为控制欲，而不是把把短期优势当成理所当然当成解决办法，而大有第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","classic":"厥孚交如，威如，吉。","source":"《周易》爻辞","modern":{"image":"“厥孚交如，威如，吉。”是大有在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而扩大成果与公平承接之间需要平衡也会在这一爻变得具体。","warning":"让丰盛转化为控制欲，而不是把把短期优势当成理所当然当成解决办法，而大有第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["说明资源如何使用、由谁受益。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在大有第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“这些资源怎样使用才不会消耗未来的信任”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“让丰盛转化为控制欲，而不是把把短期优势当成理所当然当成解决办法，而大有第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录大有六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面正在显出边界：当前循环接近上限，“丰盛与责任”需要从继续加力转向收束复盘 真正的拉扯来自扩大成果与公平承接之间需要平衡，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题 可以用“说明资源如何使用、由谁受益”做一次验证；若让丰盛转化为控制欲会在此时放大，行动应当收束。","classic":"自天祐之，吉无不利。","source":"《周易》爻辞","modern":{"image":"“自天祐之，吉无不利。”是大有在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“丰盛与责任”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自扩大成果与公平承接之间需要平衡，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"让丰盛转化为控制欲会在此时放大。","advice":["说明资源如何使用、由谁受益。","列出应当停止、保留和移交的事项。"],"signal":{"label":"通达","meaning":"在大有第6爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“这些资源怎样使用才不会消耗未来的信任”核对判断"},"tone":"收束","extended":{"trigger":{"label":"通达","observe":"完成“说明资源如何使用、由谁受益”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“说明资源如何使用、由谁受益”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“说明资源如何使用、由谁受益”，可以保持小步推进。","pause_if":"若出现“让丰盛转化为控制欲会在此时放大”，先暂停扩大投入。"},"action":{"do":"说明资源如何使用、由谁受益","review":"完成后记录大有上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"资源充足时，责任和分配方式比拥有本身更重要","strengths":["手中已有可调动的成果、影响或支持","拥有资源时更要保持节制"],"tensions":["扩大成果与公平承接之间需要平衡"],"risks":["让丰盛转化为控制欲"],"actions":["说明资源如何使用、由谁受益"],"avoid":["把短期优势当成理所当然"],"questions":["这些资源怎样使用才不会消耗未来的信任？"],"extended":{"situation":{"direct":"眼下的重点是资源充足时，责任和分配方式比拥有本身更重要。","support":"已经可以利用的是：手中已有可调动的成果、影响或支持。","constraint":"仍需核实的是：扩大成果与公平承接之间需要平衡。"},"relationship":{"inner":"下卦乾，内部动力偏向主动、原则与承担。","outer":"上卦离，外部处境更受辨识、表达与显明影响。","interaction":"内部想以“主动、原则与承担”回应外部的“辨识、表达与显明”；两边能否对接，要看“扩大成果与公平承接之间需要平衡”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“手中已有可调动的成果、影响或支持”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“说明资源如何使用、由谁受益”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把短期优势当成理所当然”，风险会被放大。","effect":"最需要防止的是：让丰盛转化为控制欲。"},"paths":{"ready":"如果关键条件得到确认，可以继续“说明资源如何使用、由谁受益”，但仍以小步反馈决定是否扩大。","not_ready":"如果“扩大成果与公平承接之间需要平衡”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"说明资源如何使用、由谁受益","observe":"这些资源怎样使用才不会消耗未来的信任？","continue_if":"出现与“手中已有可调动的成果、影响或支持”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把短期优势当成理所当然”或“让丰盛转化为控制欲”的迹象。"}}}},{"id":15,"name":"谦","pinyin":"qiān","theme":"谦逊与平衡","reflection":"让实力沉在行动里。适度退让能创造空间，但不必贬低自己。","source_note":"据《周易》谦卦意象整理","upper_trigram":8,"lower_trigram":7,"lines":{"1":{"title":"初六","interpretation":"这一爻把变化落在具体环节：事情刚在“谦逊与平衡”的起点露出端倪，可用条件还不多 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意用自我贬低逃避责任。","classic":"謙謙君子，用涉大川，吉。","source":"《周易》爻辞","modern":{"image":"“謙謙君子，用涉大川，吉。”是谦在“潜藏”阶段留下的具体图景。","situation":"事情刚在“谦逊与平衡”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是隐藏锋芒与承担应有位置之间需要拿捏，两者要放在同一次权衡里。","warning":"用自我贬低逃避责任。","advice":["用事实说明贡献，不夸大也不抹去。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在谦第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“如果不需要谦让给任何人看，你会怎样评价自己”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“用自我贬低逃避责任”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录谦初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：谦来到二位，个人判断正与资源、规则或他人发生接触 若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大隐藏锋芒与承担应有位置之间需要拿捏 可以用“用事实说明贡献，不夸大也不抹去”做一次验证；若用自我贬低逃避责任，而不是把为了不引人注意而放弃必要表达当成解决办法，而谦第2爻处在“接触”阶段，还需防止只听见符合期待的回应，行动应当收束。","classic":"鳴謙，貞吉。","source":"《周易》爻辞","modern":{"image":"“鳴謙，貞吉。”是谦在“接触”阶段留下的具体图景。","situation":"谦来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大隐藏锋芒与承担应有位置之间需要拿捏。","warning":"用自我贬低逃避责任，而不是把为了不引人注意而放弃必要表达当成解决办法，而谦第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","advice":["用事实说明贡献，不夸大也不抹去。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在谦第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“如果不需要谦让给任何人看，你会怎样评价自己”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“用事实说明贡献，不夸大也不抹去”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“用事实说明贡献，不夸大也不抹去”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“用事实说明贡献，不夸大也不抹去”，可以保持小步推进。","pause_if":"若出现“用自我贬低逃避责任，而不是把为了不引人注意而放弃必要表达当成解决办法，而谦第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，先暂停扩大投入。"},"action":{"do":"用事实说明贡献，不夸大也不抹去","review":"完成后记录谦六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻处在容易用力过度的位置，调整比加码更重要 当前拉扯在于：此时一面是继续原路与承认需要调整之间发生冲突，另一面是隐藏锋芒与承担应有位置之间需要拿捏，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“用自我贬低逃避责任会在此时放大”，就暂停扩大动作。","classic":"勞謙，君子有終，吉。","source":"《周易》爻辞","modern":{"image":"“勞謙，君子有終，吉。”是谦在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是隐藏锋芒与承担应有位置之间需要拿捏，两者要放在同一次权衡里。","warning":"用自我贬低逃避责任会在此时放大。","advice":["用事实说明贡献，不夸大也不抹去。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"可行","meaning":"在谦第3爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“如果不需要谦让给任何人看，你会怎样评价自己”核对判断"},"tone":"转折","extended":{"trigger":{"label":"可行","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“用自我贬低逃避责任会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录谦九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：局面已经接近新的层级，旧角色未必还能容纳当前变化 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“用事实说明贡献，不夸大也不抹去”后再看反馈；同时留意用自我贬低逃避责任。","classic":"无不利，撝謙。","source":"《周易》爻辞","modern":{"image":"“无不利，撝謙。”是谦在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大隐藏锋芒与承担应有位置之间需要拿捏。","warning":"用自我贬低逃避责任。","advice":["用事实说明贡献，不夸大也不抹去。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"通达","meaning":"在谦第4爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“如果不需要谦让给任何人看，你会怎样评价自己”核对判断"},"tone":"越界","extended":{"trigger":{"label":"通达","observe":"完成“用事实说明贡献，不夸大也不抹去”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“用事实说明贡献，不夸大也不抹去”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“用事实说明贡献，不夸大也不抹去”，可以保持小步推进。","pause_if":"若出现“用自我贬低逃避责任”，先暂停扩大投入。"},"action":{"do":"用事实说明贡献，不夸大也不抹去","review":"完成后记录谦六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"局面正在显出边界：关键资源与决定权趋向集中，“谦逊与平衡”开始影响更多人 此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是隐藏锋芒与承担应有位置之间需要拿捏，两者要放在同一次权衡里 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若用自我贬低逃避责任，行动应当收束。","classic":"不富以其鄰，利用侵伐，无不利。","source":"《周易》爻辞","modern":{"image":"“不富以其鄰，利用侵伐，无不利。”是谦在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“谦逊与平衡”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是隐藏锋芒与承担应有位置之间需要拿捏，两者要放在同一次权衡里。","warning":"用自我贬低逃避责任。","advice":["用事实说明贡献，不夸大也不抹去。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"通达","meaning":"在谦第5爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“如果不需要谦让给任何人看，你会怎样评价自己”核对判断"},"tone":"担当","extended":{"trigger":{"label":"通达","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“用自我贬低逃避责任”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录谦六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"谦来到上位，已有路径可能完成使命，也可能因过度而失衡 当前拉扯在于：若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大隐藏锋芒与承担应有位置之间需要拿捏 当关键条件开始出现可利用的现实回应时，变化才有现实依据。先做“用事实说明贡献，不夸大也不抹去”；若出现“用自我贬低逃避责任，而不是把为了不引人注意而放弃必要表达当成解决办法，而谦第6爻处在“收束”阶段”，就暂停扩大动作。","classic":"鳴謙，利用行師，征邑國。","source":"《周易》爻辞","modern":{"image":"“鳴謙，利用行師，征邑國。”是谦在“收束”阶段留下的具体图景。","situation":"谦来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大隐藏锋芒与承担应有位置之间需要拿捏。","warning":"用自我贬低逃避责任，而不是把为了不引人注意而放弃必要表达当成解决办法，而谦第6爻处在“收束”阶段。","advice":["用事实说明贡献，不夸大也不抹去。","列出应当停止、保留和移交的事项。"],"signal":{"label":"有利","meaning":"在谦第6爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“如果不需要谦让给任何人看，你会怎样评价自己”核对判断"},"tone":"收束","extended":{"trigger":{"label":"有利","observe":"完成“用事实说明贡献，不夸大也不抹去”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“用事实说明贡献，不夸大也不抹去”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“用事实说明贡献，不夸大也不抹去”，可以保持小步推进。","pause_if":"若出现“用自我贬低逃避责任，而不是把为了不引人注意而放弃必要表达当成解决办法，而谦第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"用事实说明贡献，不夸大也不抹去","review":"完成后记录谦上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"谦逊是准确看待自己，不是缩小自己","strengths":["有能力以低姿态持续做成事情","让实力沉在行动里。适度退让能创造空间，但不必贬低自己"],"tensions":["隐藏锋芒与承担应有位置之间需要拿捏"],"risks":["用自我贬低逃避责任"],"actions":["用事实说明贡献，不夸大也不抹去"],"avoid":["为了不引人注意而放弃必要表达"],"questions":["如果不需要谦让给任何人看，你会怎样评价自己？"],"extended":{"situation":{"direct":"眼下的重点是谦逊是准确看待自己，不是缩小自己。","support":"已经可以利用的是：有能力以低姿态持续做成事情。","constraint":"仍需核实的是：隐藏锋芒与承担应有位置之间需要拿捏。"},"relationship":{"inner":"下卦艮，内部动力偏向边界、停止与重新定位。","outer":"上卦坤，外部处境更受承载、配合与现实基础影响。","interaction":"内部想以“边界、停止与重新定位”回应外部的“承载、配合与现实基础”；两边能否对接，要看“隐藏锋芒与承担应有位置之间需要拿捏”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“有能力以低姿态持续做成事情”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“用事实说明贡献，不夸大也不抹去”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“为了不引人注意而放弃必要表达”，风险会被放大。","effect":"最需要防止的是：用自我贬低逃避责任。"},"paths":{"ready":"如果关键条件得到确认，可以继续“用事实说明贡献，不夸大也不抹去”，但仍以小步反馈决定是否扩大。","not_ready":"如果“隐藏锋芒与承担应有位置之间需要拿捏”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"用事实说明贡献，不夸大也不抹去","observe":"如果不需要谦让给任何人看，你会怎样评价自己？","continue_if":"出现与“有能力以低姿态持续做成事情”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“为了不引人注意而放弃必要表达”或“用自我贬低逃避责任”的迹象。"}}}},{"id":16,"name":"豫","pinyin":"yù","theme":"振作与预备","reflection":"情绪被点亮时，适合把愿景变成可执行计划；热情也需要节奏。","source_note":"据《周易》豫卦意象整理","upper_trigram":4,"lower_trigram":8,"lines":{"1":{"title":"初六","interpretation":"局面正在显出边界：豫落在初位，眼下更像在辨认方向，而不是兑现结果 真正的拉扯来自兴奋感可能快过计划与资源，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若把被鼓舞误当成已经准备好，行动应当收束。","classic":"鳴豫，凶。","source":"《周易》爻辞","modern":{"image":"“鳴豫，凶。”是豫在“潜藏”阶段留下的具体图景。","situation":"豫落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自兴奋感可能快过计划与资源，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"把被鼓舞误当成已经准备好。","advice":["把愿景拆成一周内能完成的动作。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"止损","meaning":"在豫第1爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“热情退去后，哪一步仍值得继续”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"止损","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把被鼓舞误当成已经准备好”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录豫初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"这一阶段不再只靠设想，回应和基本功开始决定走向 当前拉扯在于：自己的节奏需要与现实反馈相互校准，而兴奋感可能快过计划与资源也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“把愿景拆成一周内能完成的动作”；若出现“把被鼓舞误当成已经准备好”，就暂停扩大动作。","classic":"介于石，不終日，貞吉。","source":"《周易》爻辞","modern":{"image":"“介于石，不終日，貞吉。”是豫在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而兴奋感可能快过计划与资源也会在这一爻变得具体。","warning":"把被鼓舞误当成已经准备好。","advice":["把愿景拆成一周内能完成的动作。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在豫第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“热情退去后，哪一步仍值得继续”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“把愿景拆成一周内能完成的动作”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把愿景拆成一周内能完成的动作”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把愿景拆成一周内能完成的动作”，可以保持小步推进。","pause_if":"若出现“把被鼓舞误当成已经准备好”，先暂停扩大投入。"},"action":{"do":"把愿景拆成一周内能完成的动作","review":"完成后记录豫六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻把变化落在具体环节：事情跨入转折带，焦虑可能比事实更快推动决定 原有做法显出明确代价，需要及时调整，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意把被鼓舞误当成已经准备好，而不是把在高潮中作出过量承诺当成解决办法，而豫第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","classic":"盱豫，悔，遲有悔。","source":"《周易》爻辞","modern":{"image":"“盱豫，悔，遲有悔。”是豫在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自兴奋感可能快过计划与资源，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"把被鼓舞误当成已经准备好，而不是把在高潮中作出过量承诺当成解决办法，而豫第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","advice":["把愿景拆成一周内能完成的动作。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"修正","meaning":"在豫第3爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“热情退去后，哪一步仍值得继续”核对判断"},"tone":"转折","extended":{"trigger":{"label":"修正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把被鼓舞误当成已经准备好，而不是把在高潮中作出过量承诺当成解决办法，而豫第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录豫六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：事情正由内部走向外部，“振作与预备”需要重新确认位置和权限 向外推进的需要与边界尚未说清之间互相牵制，而兴奋感可能快过计划与资源也会在这一爻变得具体 可以用“把愿景拆成一周内能完成的动作”做一次验证；若把被鼓舞误当成已经准备好会在此时放大，行动应当收束。","classic":"由豫，大有得。勿疑，朋盍簪。","source":"《周易》爻辞","modern":{"image":"“由豫，大有得。勿疑，朋盍簪。”是豫在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“振作与预备”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而兴奋感可能快过计划与资源也会在这一爻变得具体。","warning":"把被鼓舞误当成已经准备好会在此时放大。","advice":["把愿景拆成一周内能完成的动作。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在豫第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“热情退去后，哪一步仍值得继续”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“把愿景拆成一周内能完成的动作”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把愿景拆成一周内能完成的动作”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把愿景拆成一周内能完成的动作”，可以保持小步推进。","pause_if":"若出现“把被鼓舞误当成已经准备好会在此时放大”，先暂停扩大投入。"},"action":{"do":"把愿景拆成一周内能完成的动作","review":"完成后记录豫九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"豫来到五位，能力之外还要衡量整体承接和长期后果 当前拉扯在于：真正的拉扯来自兴奋感可能快过计划与资源，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“把被鼓舞误当成已经准备好”，就暂停扩大动作。","classic":"貞疾，恒不死。","source":"《周易》爻辞","modern":{"image":"“貞疾，恒不死。”是豫在“担当”阶段留下的具体图景。","situation":"豫来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自兴奋感可能快过计划与资源，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"把被鼓舞误当成已经准备好。","advice":["把愿景拆成一周内能完成的动作。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在豫第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“热情退去后，哪一步仍值得继续”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把被鼓舞误当成已经准备好”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录豫六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻把变化落在具体环节：这一爻处在阶段末端，下一步先要判断什么已经结束 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“把愿景拆成一周内能完成的动作”后再看反馈；同时留意把被鼓舞误当成已经准备好。","classic":"冥豫，成有渝，无咎。","source":"《周易》爻辞","modern":{"image":"“冥豫，成有渝，无咎。”是豫在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而兴奋感可能快过计划与资源也会在这一爻变得具体。","warning":"把被鼓舞误当成已经准备好。","advice":["把愿景拆成一周内能完成的动作。","列出应当停止、保留和移交的事项。"],"signal":{"label":"守正","meaning":"在豫第6爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“热情退去后，哪一步仍值得继续”核对判断"},"tone":"收束","extended":{"trigger":{"label":"守正","observe":"完成“把愿景拆成一周内能完成的动作”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“把愿景拆成一周内能完成的动作”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把愿景拆成一周内能完成的动作”，可以保持小步推进。","pause_if":"若出现“把被鼓舞误当成已经准备好”，先暂停扩大投入。"},"action":{"do":"把愿景拆成一周内能完成的动作","review":"完成后记录豫上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"热情需要被安排进节奏，才能从愿景变成行动","strengths":["情绪和想象力正提供启动动力","情绪被点亮时，适合把愿景变成可执行计划"],"tensions":["兴奋感可能快过计划与资源"],"risks":["把被鼓舞误当成已经准备好"],"actions":["把愿景拆成一周内能完成的动作"],"avoid":["在高潮中作出过量承诺"],"questions":["热情退去后，哪一步仍值得继续？"],"extended":{"situation":{"direct":"眼下的重点是热情需要被安排进节奏，才能从愿景变成行动。","support":"已经可以利用的是：情绪和想象力正提供启动动力。","constraint":"仍需核实的是：兴奋感可能快过计划与资源。"},"relationship":{"inner":"下卦坤，内部动力偏向承载、配合与现实基础。","outer":"上卦震，外部处境更受启动、震动与迅速反应影响。","interaction":"内部想以“承载、配合与现实基础”回应外部的“启动、震动与迅速反应”；两边能否对接，要看“兴奋感可能快过计划与资源”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“情绪和想象力正提供启动动力”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“把愿景拆成一周内能完成的动作”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“在高潮中作出过量承诺”，风险会被放大。","effect":"最需要防止的是：把被鼓舞误当成已经准备好。"},"paths":{"ready":"如果关键条件得到确认，可以继续“把愿景拆成一周内能完成的动作”，但仍以小步反馈决定是否扩大。","not_ready":"如果“兴奋感可能快过计划与资源”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"把愿景拆成一周内能完成的动作","observe":"热情退去后，哪一步仍值得继续？","continue_if":"出现与“情绪和想象力正提供启动动力”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“在高潮中作出过量承诺”或“把被鼓舞误当成已经准备好”的迹象。"}}}},{"id":17,"name":"随","pinyin":"suí","theme":"顺势与选择","reflection":"顺势不是盲从。辨清自己认同的方向，再灵活调整方法。","source_note":"据《周易》随卦意象整理","upper_trigram":2,"lower_trigram":4,"lines":{"1":{"title":"初九","interpretation":"这一爻处在起步处，“顺势意味着辨认真实趋势，再主动选择如何跟随”仍需低成本试探 当前拉扯在于：若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大灵活适应与失去自身判断只差一线 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“把从众当成顺势会在此时放大”，就暂停扩大动作。","classic":"官有渝，貞吉。出門交有功。","source":"《周易》爻辞","modern":{"image":"“官有渝，貞吉。出門交有功。”是随在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“顺势意味着辨认真实趋势，再主动选择如何跟随”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大灵活适应与失去自身判断只差一线。","warning":"把从众当成顺势会在此时放大。","advice":["写下不可放弃的原则和可调整的方法。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在随第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你跟随的是事实、关系，还是群体情绪”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把从众当成顺势会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录随初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"这一爻把变化落在具体环节：局面正从内部准备转向真实互动，关系与条件逐渐可见 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“写下不可放弃的原则和可调整的方法”后再看反馈；同时留意把从众当成顺势。","classic":"係小子，失丈夫。","source":"《周易》爻辞","modern":{"image":"“係小子，失丈夫。”是随在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是灵活适应与失去自身判断只差一线，两者要放在同一次权衡里。","warning":"把从众当成顺势。","advice":["写下不可放弃的原则和可调整的方法。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在随第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“你跟随的是事实、关系，还是群体情绪”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“写下不可放弃的原则和可调整的方法”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“写下不可放弃的原则和可调整的方法”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“写下不可放弃的原则和可调整的方法”，可以保持小步推进。","pause_if":"若出现“把从众当成顺势”，先暂停扩大投入。"},"action":{"do":"写下不可放弃的原则和可调整的方法","review":"完成后记录随六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面正在显出边界：局面来到内外转换处，“顺势与选择”开始承受压力测试 若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大灵活适应与失去自身判断只差一线 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若把从众当成顺势，行动应当收束。","classic":"係丈夫，失小子。隨有求得，利居貞。","source":"《周易》爻辞","modern":{"image":"“係丈夫，失小子。隨有求得，利居貞。”是随在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“顺势与选择”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大灵活适应与失去自身判断只差一线。","warning":"把从众当成顺势。","advice":["写下不可放弃的原则和可调整的方法。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"有利","meaning":"在随第3爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“你跟随的是事实、关系，还是群体情绪”核对判断"},"tone":"转折","extended":{"trigger":{"label":"有利","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把从众当成顺势”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录随六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"随来到四位，跨出原有边界之前要先说明责任 当前拉扯在于：此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是灵活适应与失去自身判断只差一线，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“写下不可放弃的原则和可调整的方法”；若出现“把从众当成顺势，而不是把因为多数人的方向而跳过验证当成解决办法，而随第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位”，就暂停扩大动作。","classic":"隨有獲，貞凶。有孚，在道以明，何咎？","source":"《周易》爻辞","modern":{"image":"“隨有獲，貞凶。有孚，在道以明，何咎？”是随在“越界”阶段留下的具体图景。","situation":"随来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是灵活适应与失去自身判断只差一线，两者要放在同一次权衡里。","warning":"把从众当成顺势，而不是把因为多数人的方向而跳过验证当成解决办法，而随第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位。","advice":["写下不可放弃的原则和可调整的方法。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"止损","meaning":"在随第4爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“你跟随的是事实、关系，还是群体情绪”核对判断"},"tone":"越界","extended":{"trigger":{"label":"止损","observe":"完成“写下不可放弃的原则和可调整的方法”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“写下不可放弃的原则和可调整的方法”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“写下不可放弃的原则和可调整的方法”，可以保持小步推进。","pause_if":"若出现“把从众当成顺势，而不是把因为多数人的方向而跳过验证当成解决办法，而随第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位”，先暂停扩大投入。"},"action":{"do":"写下不可放弃的原则和可调整的方法","review":"完成后记录随九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一爻把变化落在具体环节：这一阶段已进入主位，选择会放大为规则或示范 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意把从众当成顺势会在此时放大。","classic":"孚于嘉，吉。","source":"《周易》爻辞","modern":{"image":"“孚于嘉，吉。”是随在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大灵活适应与失去自身判断只差一线。","warning":"把从众当成顺势会在此时放大。","advice":["写下不可放弃的原则和可调整的方法。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在随第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你跟随的是事实、关系，还是群体情绪”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把从众当成顺势会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录随九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"局面正在显出边界：局面走到极处，继续延长旧办法未必带来同等收益 此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是灵活适应与失去自身判断只差一线，两者要放在同一次权衡里 可以用“写下不可放弃的原则和可调整的方法”做一次验证；若把从众当成顺势，行动应当收束。","classic":"拘係之，乃從維之，王用亨于西山。","source":"《周易》爻辞","modern":{"image":"“拘係之，乃從維之，王用亨于西山。”是随在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是灵活适应与失去自身判断只差一线，两者要放在同一次权衡里。","warning":"把从众当成顺势。","advice":["写下不可放弃的原则和可调整的方法。","列出应当停止、保留和移交的事项。"],"signal":{"label":"观察","meaning":"在随第6爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“你跟随的是事实、关系，还是群体情绪”核对判断"},"tone":"收束","extended":{"trigger":{"label":"观察","observe":"完成“写下不可放弃的原则和可调整的方法”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“写下不可放弃的原则和可调整的方法”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“写下不可放弃的原则和可调整的方法”，可以保持小步推进。","pause_if":"若出现“把从众当成顺势”，先暂停扩大投入。"},"action":{"do":"写下不可放弃的原则和可调整的方法","review":"完成后记录随上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"顺势意味着辨认真实趋势，再主动选择如何跟随","strengths":["能够调整方法并响应外部变化","顺势不是盲从。辨清自己认同的方向，再灵活调整方法"],"tensions":["灵活适应与失去自身判断只差一线"],"risks":["把从众当成顺势"],"actions":["写下不可放弃的原则和可调整的方法"],"avoid":["因为多数人的方向而跳过验证"],"questions":["你跟随的是事实、关系，还是群体情绪？"],"extended":{"situation":{"direct":"眼下的重点是顺势意味着辨认真实趋势，再主动选择如何跟随。","support":"已经可以利用的是：能够调整方法并响应外部变化。","constraint":"仍需核实的是：灵活适应与失去自身判断只差一线。"},"relationship":{"inner":"下卦震，内部动力偏向启动、震动与迅速反应。","outer":"上卦兑，外部处境更受交流、回应与协商影响。","interaction":"内部想以“启动、震动与迅速反应”回应外部的“交流、回应与协商”；两边能否对接，要看“灵活适应与失去自身判断只差一线”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“能够调整方法并响应外部变化”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“写下不可放弃的原则和可调整的方法”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“因为多数人的方向而跳过验证”，风险会被放大。","effect":"最需要防止的是：把从众当成顺势。"},"paths":{"ready":"如果关键条件得到确认，可以继续“写下不可放弃的原则和可调整的方法”，但仍以小步反馈决定是否扩大。","not_ready":"如果“灵活适应与失去自身判断只差一线”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"写下不可放弃的原则和可调整的方法","observe":"你跟随的是事实、关系，还是群体情绪？","continue_if":"出现与“能够调整方法并响应外部变化”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“因为多数人的方向而跳过验证”或“把从众当成顺势”的迹象。"}}}},{"id":18,"name":"蛊","pinyin":"gǔ","theme":"整治与修复","reflection":"旧问题需要被认真看见。找出根源，逐项修复，不必一次解决所有事。","source_note":"据《周易》蛊卦意象整理","upper_trigram":7,"lower_trigram":5,"lines":{"1":{"title":"初六","interpretation":"这一爻把变化落在具体环节：变化尚在根部，先分清已经发生的事实和仍在期待的部分 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意沉迷责备却不处理机制，而不是把企图一次性清除所有历史负担当成解决办法，而蛊第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","classic":"幹父之蠱。有子，考无咎，厲，終吉。","source":"《周易》爻辞","modern":{"image":"“幹父之蠱。有子，考无咎，厲，終吉。”是蛊在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而追究责任与恢复功能可能互相牵制也会在这一爻变得具体。","warning":"沉迷责备却不处理机制，而不是把企图一次性清除所有历史负担当成解决办法，而蛊第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["选择一个反复出现的问题追到源头。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在蛊第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“什么机制一直在让同一个问题回来”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“沉迷责备却不处理机制，而不是把企图一次性清除所有历史负担当成解决办法，而蛊第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录蛊初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"局面正在显出边界：事情开始进入现实协作，“整治与修复”要接受反馈检验 真正的拉扯来自追究责任与恢复功能可能互相牵制，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题 可以用“选择一个反复出现的问题追到源头”做一次验证；若沉迷责备却不处理机制会在此时放大，行动应当收束。","classic":"幹母之蠱，不可貞。","source":"《周易》爻辞","modern":{"image":"“幹母之蠱，不可貞。”是蛊在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“整治与修复”要接受反馈检验。","tension":"真正的拉扯来自追究责任与恢复功能可能互相牵制，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"沉迷责备却不处理机制会在此时放大。","advice":["选择一个反复出现的问题追到源头。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"暂停","meaning":"在蛊第2爻里，爻辞给出明确的收势信号，眼下不宜把意愿直接变成大动作，可用“什么机制一直在让同一个问题回来”核对判断"},"tone":"接触","extended":{"trigger":{"label":"暂停","observe":"完成“选择一个反复出现的问题追到源头”后，观察是否出现“现实条件尚不足以支持扩大动作”的现实反馈。","threshold":"只有当现实中出现与“选择一个反复出现的问题追到源头”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选择一个反复出现的问题追到源头”，可以保持小步推进。","pause_if":"若出现“沉迷责备却不处理机制会在此时放大”，先暂停扩大投入。"},"action":{"do":"选择一个反复出现的问题追到源头","review":"完成后记录蛊九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"蛊行至三位，旧方法的边界和新选择的代价同时出现 当前拉扯在于：继续原路与承认需要调整之间发生冲突，而追究责任与恢复功能可能互相牵制也会在这一爻变得具体 当原有做法显出明确代价，需要及时调整时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“沉迷责备却不处理机制”，就暂停扩大动作。","classic":"幹父之蠱，小有悔，无大咎。","source":"《周易》爻辞","modern":{"image":"“幹父之蠱，小有悔，无大咎。”是蛊在“转折”阶段留下的具体图景。","situation":"蛊行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而追究责任与恢复功能可能互相牵制也会在这一爻变得具体。","warning":"沉迷责备却不处理机制。","advice":["选择一个反复出现的问题追到源头。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"修正","meaning":"在蛊第3爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“什么机制一直在让同一个问题回来”核对判断"},"tone":"转折","extended":{"trigger":{"label":"修正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“沉迷责备却不处理机制”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录蛊九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 原有做法显出明确代价，需要及时调整，是接下来值得核对的信号。完成“选择一个反复出现的问题追到源头”后再看反馈；同时留意沉迷责备却不处理机制。","classic":"裕父之蠱，往見吝。","source":"《周易》爻辞","modern":{"image":"“裕父之蠱，往見吝。”是蛊在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自追究责任与恢复功能可能互相牵制，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"沉迷责备却不处理机制。","advice":["选择一个反复出现的问题追到源头。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"修正","meaning":"在蛊第4爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“什么机制一直在让同一个问题回来”核对判断"},"tone":"越界","extended":{"trigger":{"label":"修正","observe":"完成“选择一个反复出现的问题追到源头”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“选择一个反复出现的问题追到源头”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选择一个反复出现的问题追到源头”，可以保持小步推进。","pause_if":"若出现“沉迷责备却不处理机制”，先暂停扩大投入。"},"action":{"do":"选择一个反复出现的问题追到源头","review":"完成后记录蛊六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"局面正在显出边界：局面要求从个人得失转向整体结果和持续责任 扩大影响与照顾整体承接能力之间需要平衡，而追究责任与恢复功能可能互相牵制也会在这一爻变得具体 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若沉迷责备却不处理机制，而不是把企图一次性清除所有历史负担当成解决办法，而蛊第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围，行动应当收束。","classic":"幹父之蠱，用譽。","source":"《周易》爻辞","modern":{"image":"“幹父之蠱，用譽。”是蛊在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而追究责任与恢复功能可能互相牵制也会在这一爻变得具体。","warning":"沉迷责备却不处理机制，而不是把企图一次性清除所有历史负担当成解决办法，而蛊第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["选择一个反复出现的问题追到源头。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在蛊第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么机制一直在让同一个问题回来”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“沉迷责备却不处理机制，而不是把企图一次性清除所有历史负担当成解决办法，而蛊第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录蛊六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"当前循环接近上限，“整治与修复”需要从继续加力转向收束复盘 当前拉扯在于：真正的拉扯来自追究责任与恢复功能可能互相牵制，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“选择一个反复出现的问题追到源头”；若出现“沉迷责备却不处理机制会在此时放大”，就暂停扩大动作。","classic":"不事王侯，高尚其事。","source":"《周易》爻辞","modern":{"image":"“不事王侯，高尚其事。”是蛊在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“整治与修复”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自追究责任与恢复功能可能互相牵制，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"沉迷责备却不处理机制会在此时放大。","advice":["选择一个反复出现的问题追到源头。","列出应当停止、保留和移交的事项。"],"signal":{"label":"观察","meaning":"在蛊第6爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么机制一直在让同一个问题回来”核对判断"},"tone":"收束","extended":{"trigger":{"label":"观察","observe":"完成“选择一个反复出现的问题追到源头”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“选择一个反复出现的问题追到源头”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选择一个反复出现的问题追到源头”，可以保持小步推进。","pause_if":"若出现“沉迷责备却不处理机制会在此时放大”，先暂停扩大投入。"},"action":{"do":"选择一个反复出现的问题追到源头","review":"完成后记录蛊上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"旧问题需要被看见、拆开并逐项修复","strengths":["根源已经露出，改变不必再停留在表面","旧问题需要被认真看见。找出根源，逐项修复，不必一次解决所有事"],"tensions":["追究责任与恢复功能可能互相牵制"],"risks":["沉迷责备却不处理机制"],"actions":["选择一个反复出现的问题追到源头"],"avoid":["企图一次性清除所有历史负担"],"questions":["什么机制一直在让同一个问题回来？"],"extended":{"situation":{"direct":"眼下的重点是旧问题需要被看见、拆开并逐项修复。","support":"已经可以利用的是：根源已经露出，改变不必再停留在表面。","constraint":"仍需核实的是：追究责任与恢复功能可能互相牵制。"},"relationship":{"inner":"下卦巽，内部动力偏向渗透、调整与持续影响。","outer":"上卦艮，外部处境更受边界、停止与重新定位影响。","interaction":"内部想以“渗透、调整与持续影响”回应外部的“边界、停止与重新定位”；两边能否对接，要看“追究责任与恢复功能可能互相牵制”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“根源已经露出，改变不必再停留在表面”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“选择一个反复出现的问题追到源头”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“企图一次性清除所有历史负担”，风险会被放大。","effect":"最需要防止的是：沉迷责备却不处理机制。"},"paths":{"ready":"如果关键条件得到确认，可以继续“选择一个反复出现的问题追到源头”，但仍以小步反馈决定是否扩大。","not_ready":"如果“追究责任与恢复功能可能互相牵制”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"选择一个反复出现的问题追到源头","observe":"什么机制一直在让同一个问题回来？","continue_if":"出现与“根源已经露出，改变不必再停留在表面”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“企图一次性清除所有历史负担”或“沉迷责备却不处理机制”的迹象。"}}}},{"id":19,"name":"临","pinyin":"lín","theme":"靠近与承担","reflection":"机会正在靠近。用真诚和准备回应它，同时保持长期视角。","source_note":"据《周易》临卦意象整理","upper_trigram":8,"lower_trigram":2,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：事情刚在“靠近与承担”的起点露出端倪，可用条件还不多 此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是主动靠近与长期责任需要同时考虑，两者要放在同一次权衡里 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若只看机会感而忽略后续维护，行动应当收束。","classic":"咸臨，貞吉。","source":"《周易》爻辞","modern":{"image":"“咸臨，貞吉。”是临在“潜藏”阶段留下的具体图景。","situation":"事情刚在“靠近与承担”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是主动靠近与长期责任需要同时考虑，两者要放在同一次权衡里。","warning":"只看机会感而忽略后续维护。","advice":["确认接近之后需要持续承担什么。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在临第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你准备迎接的是一次机会，还是它带来的长期责任”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“只看机会感而忽略后续维护”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录临初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"临来到二位，个人判断正与资源、规则或他人发生接触 当前拉扯在于：若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大主动靠近与长期责任需要同时考虑 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“确认接近之后需要持续承担什么”；若出现“只看机会感而忽略后续维护，而不是把用热情替代资源盘点当成解决办法，而临第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，就暂停扩大动作。","classic":"咸臨，吉，无不利。","source":"《周易》爻辞","modern":{"image":"“咸臨，吉，无不利。”是临在“接触”阶段留下的具体图景。","situation":"临来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大主动靠近与长期责任需要同时考虑。","warning":"只看机会感而忽略后续维护，而不是把用热情替代资源盘点当成解决办法，而临第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","advice":["确认接近之后需要持续承担什么。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"通达","meaning":"在临第2爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“你准备迎接的是一次机会，还是它带来的长期责任”核对判断"},"tone":"接触","extended":{"trigger":{"label":"通达","observe":"完成“确认接近之后需要持续承担什么”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“确认接近之后需要持续承担什么”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“确认接近之后需要持续承担什么”，可以保持小步推进。","pause_if":"若出现“只看机会感而忽略后续维护，而不是把用热情替代资源盘点当成解决办法，而临第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，先暂停扩大投入。"},"action":{"do":"确认接近之后需要持续承担什么","review":"完成后记录临九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻把变化落在具体环节：这一爻处在容易用力过度的位置，调整比加码更重要 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意只看机会感而忽略后续维护会在此时放大。","classic":"甘臨，无攸利，既憂之，无咎。","source":"《周易》爻辞","modern":{"image":"“甘臨，无攸利，既憂之，无咎。”是临在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是主动靠近与长期责任需要同时考虑，两者要放在同一次权衡里。","warning":"只看机会感而忽略后续维护会在此时放大。","advice":["确认接近之后需要持续承担什么。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"守正","meaning":"在临第3爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“你准备迎接的是一次机会，还是它带来的长期责任”核对判断"},"tone":"转折","extended":{"trigger":{"label":"守正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“只看机会感而忽略后续维护会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录临六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"局面正在显出边界：局面已经接近新的层级，旧角色未必还能容纳当前变化 若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大主动靠近与长期责任需要同时考虑 可以用“确认接近之后需要持续承担什么”做一次验证；若只看机会感而忽略后续维护，行动应当收束。","classic":"至臨，无咎。","source":"《周易》爻辞","modern":{"image":"“至臨，无咎。”是临在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大主动靠近与长期责任需要同时考虑。","warning":"只看机会感而忽略后续维护。","advice":["确认接近之后需要持续承担什么。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在临第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“你准备迎接的是一次机会，还是它带来的长期责任”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“确认接近之后需要持续承担什么”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“确认接近之后需要持续承担什么”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“确认接近之后需要持续承担什么”，可以保持小步推进。","pause_if":"若出现“只看机会感而忽略后续维护”，先暂停扩大投入。"},"action":{"do":"确认接近之后需要持续承担什么","review":"完成后记录临六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"关键资源与决定权趋向集中，“靠近与承担”开始影响更多人 当前拉扯在于：此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是主动靠近与长期责任需要同时考虑，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“只看机会感而忽略后续维护”，就暂停扩大动作。","classic":"知臨，大君之宜，吉。","source":"《周易》爻辞","modern":{"image":"“知臨，大君之宜，吉。”是临在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“靠近与承担”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是主动靠近与长期责任需要同时考虑，两者要放在同一次权衡里。","warning":"只看机会感而忽略后续维护。","advice":["确认接近之后需要持续承担什么。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在临第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你准备迎接的是一次机会，还是它带来的长期责任”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“只看机会感而忽略后续维护”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录临六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻把变化落在具体环节：临来到上位，已有路径可能完成使命，也可能因过度而失衡 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“确认接近之后需要持续承担什么”后再看反馈；同时留意只看机会感而忽略后续维护，而不是把用热情替代资源盘点当成解决办法，而临第6爻处在“收束”阶段。","classic":"敦臨，吉，无咎。","source":"《周易》爻辞","modern":{"image":"“敦臨，吉，无咎。”是临在“收束”阶段留下的具体图景。","situation":"临来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大主动靠近与长期责任需要同时考虑。","warning":"只看机会感而忽略后续维护，而不是把用热情替代资源盘点当成解决办法，而临第6爻处在“收束”阶段。","advice":["确认接近之后需要持续承担什么。","列出应当停止、保留和移交的事项。"],"signal":{"label":"可行","meaning":"在临第6爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你准备迎接的是一次机会，还是它带来的长期责任”核对判断"},"tone":"收束","extended":{"trigger":{"label":"可行","observe":"完成“确认接近之后需要持续承担什么”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“确认接近之后需要持续承担什么”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“确认接近之后需要持续承担什么”，可以保持小步推进。","pause_if":"若出现“只看机会感而忽略后续维护，而不是把用热情替代资源盘点当成解决办法，而临第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"确认接近之后需要持续承担什么","review":"完成后记录临上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"机会靠近时，准备程度决定能否承担它","strengths":["外部回应和可见机会正在增加","机会正在靠近。用真诚和准备回应它，同时保持长期视角"],"tensions":["主动靠近与长期责任需要同时考虑"],"risks":["只看机会感而忽略后续维护"],"actions":["确认接近之后需要持续承担什么"],"avoid":["用热情替代资源盘点"],"questions":["你准备迎接的是一次机会，还是它带来的长期责任？"],"extended":{"situation":{"direct":"眼下的重点是机会靠近时，准备程度决定能否承担它。","support":"已经可以利用的是：外部回应和可见机会正在增加。","constraint":"仍需核实的是：主动靠近与长期责任需要同时考虑。"},"relationship":{"inner":"下卦兑，内部动力偏向交流、回应与协商。","outer":"上卦坤，外部处境更受承载、配合与现实基础影响。","interaction":"内部想以“交流、回应与协商”回应外部的“承载、配合与现实基础”；两边能否对接，要看“主动靠近与长期责任需要同时考虑”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“外部回应和可见机会正在增加”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“确认接近之后需要持续承担什么”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用热情替代资源盘点”，风险会被放大。","effect":"最需要防止的是：只看机会感而忽略后续维护。"},"paths":{"ready":"如果关键条件得到确认，可以继续“确认接近之后需要持续承担什么”，但仍以小步反馈决定是否扩大。","not_ready":"如果“主动靠近与长期责任需要同时考虑”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"确认接近之后需要持续承担什么","observe":"你准备迎接的是一次机会，还是它带来的长期责任？","continue_if":"出现与“外部回应和可见机会正在增加”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用热情替代资源盘点”或“只看机会感而忽略后续维护”的迹象。"}}}},{"id":20,"name":"观","pinyin":"guān","theme":"观察与反省","reflection":"先暂停判断，看清全貌；也留意自己正在向外界传递什么。","source_note":"据《周易》观卦意象整理","upper_trigram":5,"lower_trigram":8,"lines":{"1":{"title":"初六","interpretation":"观落在初位，眼下更像在辨认方向，而不是兑现结果 当前拉扯在于：真正的拉扯来自旁观的清醒与逃避参与容易混淆，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“收集信息却一直不形成判断”，就暂停扩大动作。","classic":"童觀，小人无咎，君子吝。","source":"《周易》爻辞","modern":{"image":"“童觀，小人无咎，君子吝。”是观在“潜藏”阶段留下的具体图景。","situation":"观落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自旁观的清醒与逃避参与容易混淆，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"收集信息却一直不形成判断。","advice":["从三个不同立场描述同一件事。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在观第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“如果换一个位置看，哪项事实会变得突出”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“收集信息却一直不形成判断”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录观初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"这一爻把变化落在具体环节：这一阶段不再只靠设想，回应和基本功开始决定走向 关键条件开始出现可利用的现实回应，是接下来值得核对的信号。完成“从三个不同立场描述同一件事”后再看反馈；同时留意收集信息却一直不形成判断。","classic":"闚觀，利女貞。","source":"《周易》爻辞","modern":{"image":"“闚觀，利女貞。”是观在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而旁观的清醒与逃避参与容易混淆也会在这一爻变得具体。","warning":"收集信息却一直不形成判断。","advice":["从三个不同立场描述同一件事。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"有利","meaning":"在观第2爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“如果换一个位置看，哪项事实会变得突出”核对判断"},"tone":"接触","extended":{"trigger":{"label":"有利","observe":"完成“从三个不同立场描述同一件事”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“从三个不同立场描述同一件事”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“从三个不同立场描述同一件事”，可以保持小步推进。","pause_if":"若出现“收集信息却一直不形成判断”，先暂停扩大投入。"},"action":{"do":"从三个不同立场描述同一件事","review":"完成后记录观六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面正在显出边界：事情跨入转折带，焦虑可能比事实更快推动决定 真正的拉扯来自旁观的清醒与逃避参与容易混淆，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若收集信息却一直不形成判断，而不是把用观察拖延必要回应当成解决办法，而观第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码，行动应当收束。","classic":"觀我生，進退。","source":"《周易》爻辞","modern":{"image":"“觀我生，進退。”是观在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自旁观的清醒与逃避参与容易混淆，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"收集信息却一直不形成判断，而不是把用观察拖延必要回应当成解决办法，而观第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","advice":["从三个不同立场描述同一件事。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在观第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“如果换一个位置看，哪项事实会变得突出”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“收集信息却一直不形成判断，而不是把用观察拖延必要回应当成解决办法，而观第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录观六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"事情正由内部走向外部，“观察与反省”需要重新确认位置和权限 当前拉扯在于：向外推进的需要与边界尚未说清之间互相牵制，而旁观的清醒与逃避参与容易混淆也会在这一爻变得具体 当关键条件开始出现可利用的现实回应时，变化才有现实依据。先做“从三个不同立场描述同一件事”；若出现“收集信息却一直不形成判断会在此时放大”，就暂停扩大动作。","classic":"觀國之光，利用賓于王。","source":"《周易》爻辞","modern":{"image":"“觀國之光，利用賓于王。”是观在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“观察与反省”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而旁观的清醒与逃避参与容易混淆也会在这一爻变得具体。","warning":"收集信息却一直不形成判断会在此时放大。","advice":["从三个不同立场描述同一件事。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"有利","meaning":"在观第4爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“如果换一个位置看，哪项事实会变得突出”核对判断"},"tone":"越界","extended":{"trigger":{"label":"有利","observe":"完成“从三个不同立场描述同一件事”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“从三个不同立场描述同一件事”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“从三个不同立场描述同一件事”，可以保持小步推进。","pause_if":"若出现“收集信息却一直不形成判断会在此时放大”，先暂停扩大投入。"},"action":{"do":"从三个不同立场描述同一件事","review":"完成后记录观六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一爻把变化落在具体环节：观来到五位，能力之外还要衡量整体承接和长期后果 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意收集信息却一直不形成判断。","classic":"觀我生，君子无咎。","source":"《周易》爻辞","modern":{"image":"“觀我生，君子无咎。”是观在“担当”阶段留下的具体图景。","situation":"观来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自旁观的清醒与逃避参与容易混淆，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"收集信息却一直不形成判断。","advice":["从三个不同立场描述同一件事。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"守正","meaning":"在观第5爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“如果换一个位置看，哪项事实会变得突出”核对判断"},"tone":"担当","extended":{"trigger":{"label":"守正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“收集信息却一直不形成判断”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录观九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面正在显出边界：这一爻处在阶段末端，下一步先要判断什么已经结束 维持既有成果与允许阶段结束之间存在拉扯，而旁观的清醒与逃避参与容易混淆也会在这一爻变得具体 可以用“从三个不同立场描述同一件事”做一次验证；若收集信息却一直不形成判断，行动应当收束。","classic":"觀其生，君子无咎。","source":"《周易》爻辞","modern":{"image":"“觀其生，君子无咎。”是观在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而旁观的清醒与逃避参与容易混淆也会在这一爻变得具体。","warning":"收集信息却一直不形成判断。","advice":["从三个不同立场描述同一件事。","列出应当停止、保留和移交的事项。"],"signal":{"label":"守正","meaning":"在观第6爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“如果换一个位置看，哪项事实会变得突出”核对判断"},"tone":"收束","extended":{"trigger":{"label":"守正","observe":"完成“从三个不同立场描述同一件事”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“从三个不同立场描述同一件事”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“从三个不同立场描述同一件事”，可以保持小步推进。","pause_if":"若出现“收集信息却一直不形成判断”，先暂停扩大投入。"},"action":{"do":"从三个不同立场描述同一件事","review":"完成后记录观上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"观察既是看外部，也是在看自己如何参与局面","strengths":["暂缓行动可以换来更完整的视角","先暂停判断，看清全貌"],"tensions":["旁观的清醒与逃避参与容易混淆"],"risks":["收集信息却一直不形成判断"],"actions":["从三个不同立场描述同一件事"],"avoid":["用观察拖延必要回应"],"questions":["如果换一个位置看，哪项事实会变得突出？"],"extended":{"situation":{"direct":"眼下的重点是观察既是看外部，也是在看自己如何参与局面。","support":"已经可以利用的是：暂缓行动可以换来更完整的视角。","constraint":"仍需核实的是：旁观的清醒与逃避参与容易混淆。"},"relationship":{"inner":"下卦坤，内部动力偏向承载、配合与现实基础。","outer":"上卦巽，外部处境更受渗透、调整与持续影响影响。","interaction":"内部想以“承载、配合与现实基础”回应外部的“渗透、调整与持续影响”；两边能否对接，要看“旁观的清醒与逃避参与容易混淆”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“暂缓行动可以换来更完整的视角”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“从三个不同立场描述同一件事”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用观察拖延必要回应”，风险会被放大。","effect":"最需要防止的是：收集信息却一直不形成判断。"},"paths":{"ready":"如果关键条件得到确认，可以继续“从三个不同立场描述同一件事”，但仍以小步反馈决定是否扩大。","not_ready":"如果“旁观的清醒与逃避参与容易混淆”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"从三个不同立场描述同一件事","observe":"如果换一个位置看，哪项事实会变得突出？","continue_if":"出现与“暂缓行动可以换来更完整的视角”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用观察拖延必要回应”或“收集信息却一直不形成判断”的迹象。"}}}},{"id":21,"name":"噬嗑","pinyin":"shì kè","theme":"厘清与决断","reflection":"卡住你的往往是未处理的症结。正视规则与问题，果断但不过度。","source_note":"据《周易》噬嗑卦意象整理","upper_trigram":3,"lower_trigram":4,"lines":{"1":{"title":"初九","interpretation":"这一爻把变化落在具体环节：这一爻处在起步处，“真正卡住局面的症结需要被明确处理”仍需低成本试探 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意把解决问题变成惩罚某个人会在此时放大。","classic":"屨校滅趾，无咎。","source":"《周易》爻辞","modern":{"image":"“屨校滅趾，无咎。”是噬嗑在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“真正卡住局面的症结需要被明确处理”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大果断执行与保持比例原则之间有张力。","warning":"把解决问题变成惩罚某个人会在此时放大。","advice":["定义问题、规则和处理完成的标准。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在噬嗑第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“必须被处理的症结究竟是什么”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把解决问题变成惩罚某个人会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录噬嗑初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：局面正从内部准备转向真实互动，关系与条件逐渐可见 此时一面是自己的节奏需要与现实反馈相互校准，另一面是果断执行与保持比例原则之间有张力，两者要放在同一次权衡里 可以用“定义问题、规则和处理完成的标准”做一次验证；若把解决问题变成惩罚某个人，行动应当收束。","classic":"噬膚，滅鼻，无咎。","source":"《周易》爻辞","modern":{"image":"“噬膚，滅鼻，无咎。”是噬嗑在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是果断执行与保持比例原则之间有张力，两者要放在同一次权衡里。","warning":"把解决问题变成惩罚某个人。","advice":["定义问题、规则和处理完成的标准。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"守正","meaning":"在噬嗑第2爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“必须被处理的症结究竟是什么”核对判断"},"tone":"接触","extended":{"trigger":{"label":"守正","observe":"完成“定义问题、规则和处理完成的标准”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“定义问题、规则和处理完成的标准”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“定义问题、规则和处理完成的标准”，可以保持小步推进。","pause_if":"若出现“把解决问题变成惩罚某个人”，先暂停扩大投入。"},"action":{"do":"定义问题、规则和处理完成的标准","review":"完成后记录噬嗑六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面来到内外转换处，“厘清与决断”开始承受压力测试 当前拉扯在于：若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大果断执行与保持比例原则之间有张力 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“把解决问题变成惩罚某个人”，就暂停扩大动作。","classic":"噬腊肉，遇毒。小吝无咎。","source":"《周易》爻辞","modern":{"image":"“噬腊肉，遇毒。小吝无咎。”是噬嗑在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“厘清与决断”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大果断执行与保持比例原则之间有张力。","warning":"把解决问题变成惩罚某个人。","advice":["定义问题、规则和处理完成的标准。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"守正","meaning":"在噬嗑第3爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“必须被处理的症结究竟是什么”核对判断"},"tone":"转折","extended":{"trigger":{"label":"守正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把解决问题变成惩罚某个人”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录噬嗑六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"这一爻把变化落在具体环节：噬嗑来到四位，跨出原有边界之前要先说明责任 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“定义问题、规则和处理完成的标准”后再看反馈；同时留意把解决问题变成惩罚某个人，而不是把用模糊指责代替可核实事实当成解决办法，而噬嗑第4爻处在“越界”阶段。","classic":"噬乾胏，得金矢，利艱貞吉。","source":"《周易》爻辞","modern":{"image":"“噬乾胏，得金矢，利艱貞吉。”是噬嗑在“越界”阶段留下的具体图景。","situation":"噬嗑来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是果断执行与保持比例原则之间有张力，两者要放在同一次权衡里。","warning":"把解决问题变成惩罚某个人，而不是把用模糊指责代替可核实事实当成解决办法，而噬嗑第4爻处在“越界”阶段。","advice":["定义问题、规则和处理完成的标准。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在噬嗑第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“必须被处理的症结究竟是什么”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“定义问题、规则和处理完成的标准”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“定义问题、规则和处理完成的标准”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“定义问题、规则和处理完成的标准”，可以保持小步推进。","pause_if":"若出现“把解决问题变成惩罚某个人，而不是把用模糊指责代替可核实事实当成解决办法，而噬嗑第4爻处在“越界”阶段”，先暂停扩大投入。"},"action":{"do":"定义问题、规则和处理完成的标准","review":"完成后记录噬嗑九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"局面正在显出边界：这一阶段已进入主位，选择会放大为规则或示范 若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大果断执行与保持比例原则之间有张力 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若把解决问题变成惩罚某个人会在此时放大，行动应当收束。","classic":"噬乾肉，得黃金，貞厲无咎。","source":"《周易》爻辞","modern":{"image":"“噬乾肉，得黃金，貞厲无咎。”是噬嗑在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大果断执行与保持比例原则之间有张力。","warning":"把解决问题变成惩罚某个人会在此时放大。","advice":["定义问题、规则和处理完成的标准。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"守正","meaning":"在噬嗑第5爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“必须被处理的症结究竟是什么”核对判断"},"tone":"担当","extended":{"trigger":{"label":"守正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把解决问题变成惩罚某个人会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录噬嗑六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面走到极处，继续延长旧办法未必带来同等收益 当前拉扯在于：此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是果断执行与保持比例原则之间有张力，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“定义问题、规则和处理完成的标准”；若出现“把解决问题变成惩罚某个人”，就暂停扩大动作。","classic":"何校滅耳，凶。","source":"《周易》爻辞","modern":{"image":"“何校滅耳，凶。”是噬嗑在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是果断执行与保持比例原则之间有张力，两者要放在同一次权衡里。","warning":"把解决问题变成惩罚某个人。","advice":["定义问题、规则和处理完成的标准。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在噬嗑第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“必须被处理的症结究竟是什么”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“定义问题、规则和处理完成的标准”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“定义问题、规则和处理完成的标准”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“定义问题、规则和处理完成的标准”，可以保持小步推进。","pause_if":"若出现“把解决问题变成惩罚某个人”，先暂停扩大投入。"},"action":{"do":"定义问题、规则和处理完成的标准","review":"完成后记录噬嗑上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"真正卡住局面的症结需要被明确处理","strengths":["问题已有足够轮廓，可以进入决断","卡住你的往往是未处理的症结。正视规则与问题，果断但不过度"],"tensions":["果断执行与保持比例原则之间有张力"],"risks":["把解决问题变成惩罚某个人"],"actions":["定义问题、规则和处理完成的标准"],"avoid":["用模糊指责代替可核实事实"],"questions":["必须被处理的症结究竟是什么？"],"extended":{"situation":{"direct":"眼下的重点是真正卡住局面的症结需要被明确处理。","support":"已经可以利用的是：问题已有足够轮廓，可以进入决断。","constraint":"仍需核实的是：果断执行与保持比例原则之间有张力。"},"relationship":{"inner":"下卦震，内部动力偏向启动、震动与迅速反应。","outer":"上卦离，外部处境更受辨识、表达与显明影响。","interaction":"内部想以“启动、震动与迅速反应”回应外部的“辨识、表达与显明”；两边能否对接，要看“果断执行与保持比例原则之间有张力”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“问题已有足够轮廓，可以进入决断”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“定义问题、规则和处理完成的标准”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用模糊指责代替可核实事实”，风险会被放大。","effect":"最需要防止的是：把解决问题变成惩罚某个人。"},"paths":{"ready":"如果关键条件得到确认，可以继续“定义问题、规则和处理完成的标准”，但仍以小步反馈决定是否扩大。","not_ready":"如果“果断执行与保持比例原则之间有张力”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"定义问题、规则和处理完成的标准","observe":"必须被处理的症结究竟是什么？","continue_if":"出现与“问题已有足够轮廓，可以进入决断”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用模糊指责代替可核实事实”或“把解决问题变成惩罚某个人”的迹象。"}}}},{"id":22,"name":"贲","pinyin":"bì","theme":"修饰与本质","reflection":"美感能帮助表达，但别让形式盖过真实内容。回到最重要的价值。","source_note":"据《周易》贲卦意象整理","upper_trigram":7,"lower_trigram":3,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：变化尚在根部，先分清已经发生的事实和仍在期待的部分 内在意愿已经出现，外部条件尚未完全成形，而外在呈现可能遮住核心价值也会在这一爻变得具体 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若用包装弥补内容不足，而不是把把注意力都用在被看见上当成解决办法，而贲第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论，行动应当收束。","classic":"賁其趾，舍車而徒。","source":"《周易》爻辞","modern":{"image":"“賁其趾，舍車而徒。”是贲在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而外在呈现可能遮住核心价值也会在这一爻变得具体。","warning":"用包装弥补内容不足，而不是把把注意力都用在被看见上当成解决办法，而贲第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["先写出一句不靠修饰也成立的核心话。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"观察","meaning":"在贲第1爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“去掉形式之后，什么内容仍然站得住”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"观察","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“用包装弥补内容不足，而不是把把注意力都用在被看见上当成解决办法，而贲第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录贲初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"事情开始进入现实协作，“修饰与本质”要接受反馈检验 当前拉扯在于：真正的拉扯来自外在呈现可能遮住核心价值，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“先写出一句不靠修饰也成立的核心话”；若出现“用包装弥补内容不足会在此时放大”，就暂停扩大动作。","classic":"賁其須。","source":"《周易》爻辞","modern":{"image":"“賁其須。”是贲在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“修饰与本质”要接受反馈检验。","tension":"真正的拉扯来自外在呈现可能遮住核心价值，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"用包装弥补内容不足会在此时放大。","advice":["先写出一句不靠修饰也成立的核心话。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在贲第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“去掉形式之后，什么内容仍然站得住”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“先写出一句不靠修饰也成立的核心话”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先写出一句不靠修饰也成立的核心话”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先写出一句不靠修饰也成立的核心话”，可以保持小步推进。","pause_if":"若出现“用包装弥补内容不足会在此时放大”，先暂停扩大投入。"},"action":{"do":"先写出一句不靠修饰也成立的核心话","review":"完成后记录贲六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻把变化落在具体环节：贲行至三位，旧方法的边界和新选择的代价同时出现 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意用包装弥补内容不足。","classic":"賁如濡如，永貞吉。","source":"《周易》爻辞","modern":{"image":"“賁如濡如，永貞吉。”是贲在“转折”阶段留下的具体图景。","situation":"贲行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而外在呈现可能遮住核心价值也会在这一爻变得具体。","warning":"用包装弥补内容不足。","advice":["先写出一句不靠修饰也成立的核心话。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"可行","meaning":"在贲第3爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“去掉形式之后，什么内容仍然站得住”核对判断"},"tone":"转折","extended":{"trigger":{"label":"可行","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“用包装弥补内容不足”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录贲九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"局面正在显出边界：这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 真正的拉扯来自外在呈现可能遮住核心价值，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题 可以用“先写出一句不靠修饰也成立的核心话”做一次验证；若用包装弥补内容不足，行动应当收束。","classic":"賁如皤如，白馬翰如，匪寇婚媾。","source":"《周易》爻辞","modern":{"image":"“賁如皤如，白馬翰如，匪寇婚媾。”是贲在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自外在呈现可能遮住核心价值，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"用包装弥补内容不足。","advice":["先写出一句不靠修饰也成立的核心话。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在贲第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“去掉形式之后，什么内容仍然站得住”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“先写出一句不靠修饰也成立的核心话”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先写出一句不靠修饰也成立的核心话”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先写出一句不靠修饰也成立的核心话”，可以保持小步推进。","pause_if":"若出现“用包装弥补内容不足”，先暂停扩大投入。"},"action":{"do":"先写出一句不靠修饰也成立的核心话","review":"完成后记录贲六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"局面要求从个人得失转向整体结果和持续责任 当前拉扯在于：扩大影响与照顾整体承接能力之间需要平衡，而外在呈现可能遮住核心价值也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“用包装弥补内容不足，而不是把把注意力都用在被看见上当成解决办法，而贲第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，就暂停扩大动作。","classic":"賁于丘園，束帛戔戔。吝，終吉。","source":"《周易》爻辞","modern":{"image":"“賁于丘園，束帛戔戔。吝，終吉。”是贲在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而外在呈现可能遮住核心价值也会在这一爻变得具体。","warning":"用包装弥补内容不足，而不是把把注意力都用在被看见上当成解决办法，而贲第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["先写出一句不靠修饰也成立的核心话。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在贲第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“去掉形式之后，什么内容仍然站得住”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“用包装弥补内容不足，而不是把把注意力都用在被看见上当成解决办法，而贲第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录贲六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"这一爻把变化落在具体环节：当前循环接近上限，“修饰与本质”需要从继续加力转向收束复盘 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“先写出一句不靠修饰也成立的核心话”后再看反馈；同时留意用包装弥补内容不足会在此时放大。","classic":"白賁，无咎。","source":"《周易》爻辞","modern":{"image":"“白賁，无咎。”是贲在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“修饰与本质”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自外在呈现可能遮住核心价值，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"用包装弥补内容不足会在此时放大。","advice":["先写出一句不靠修饰也成立的核心话。","列出应当停止、保留和移交的事项。"],"signal":{"label":"守正","meaning":"在贲第6爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“去掉形式之后，什么内容仍然站得住”核对判断"},"tone":"收束","extended":{"trigger":{"label":"守正","observe":"完成“先写出一句不靠修饰也成立的核心话”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先写出一句不靠修饰也成立的核心话”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先写出一句不靠修饰也成立的核心话”，可以保持小步推进。","pause_if":"若出现“用包装弥补内容不足会在此时放大”，先暂停扩大投入。"},"action":{"do":"先写出一句不靠修饰也成立的核心话","review":"完成后记录贲上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"形式应帮助真实内容被看见，而不是代替内容","strengths":["表达、美感和礼仪能提高沟通质量","美感能帮助表达，但别让形式盖过真实内容。回到最重要的价值"],"tensions":["外在呈现可能遮住核心价值"],"risks":["用包装弥补内容不足"],"actions":["先写出一句不靠修饰也成立的核心话"],"avoid":["把注意力都用在被看见上"],"questions":["去掉形式之后，什么内容仍然站得住？"],"extended":{"situation":{"direct":"眼下的重点是形式应帮助真实内容被看见，而不是代替内容。","support":"已经可以利用的是：表达、美感和礼仪能提高沟通质量。","constraint":"仍需核实的是：外在呈现可能遮住核心价值。"},"relationship":{"inner":"下卦离，内部动力偏向辨识、表达与显明。","outer":"上卦艮，外部处境更受边界、停止与重新定位影响。","interaction":"内部想以“辨识、表达与显明”回应外部的“边界、停止与重新定位”；两边能否对接，要看“外在呈现可能遮住核心价值”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“表达、美感和礼仪能提高沟通质量”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“先写出一句不靠修饰也成立的核心话”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把注意力都用在被看见上”，风险会被放大。","effect":"最需要防止的是：用包装弥补内容不足。"},"paths":{"ready":"如果关键条件得到确认，可以继续“先写出一句不靠修饰也成立的核心话”，但仍以小步反馈决定是否扩大。","not_ready":"如果“外在呈现可能遮住核心价值”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"先写出一句不靠修饰也成立的核心话","observe":"去掉形式之后，什么内容仍然站得住？","continue_if":"出现与“表达、美感和礼仪能提高沟通质量”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把注意力都用在被看见上”或“用包装弥补内容不足”的迹象。"}}}},{"id":23,"name":"剥","pinyin":"bō","theme":"剥落与止损","reflection":"有些消耗该停下了。先保护核心，允许不必要的部分自然退出。","source_note":"据《周易》剥卦意象整理","upper_trigram":7,"lower_trigram":8,"lines":{"1":{"title":"初六","interpretation":"事情刚在“剥落与止损”的起点露出端倪，可用条件还不多 当前拉扯在于：此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是舍弃旧部分会带来失落和不安全感，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“因为不甘心而继续维持空壳”，就暂停扩大动作。","classic":"剝床以足，蔑貞凶。","source":"《周易》爻辞","modern":{"image":"“剝床以足，蔑貞凶。”是剥在“潜藏”阶段留下的具体图景。","situation":"事情刚在“剥落与止损”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是舍弃旧部分会带来失落和不安全感，两者要放在同一次权衡里。","warning":"因为不甘心而继续维持空壳。","advice":["列出必须保留与可以退出的部分。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"止损","meaning":"在剥第1爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪些东西已经结束，只是你还没允许它离开”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"止损","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“因为不甘心而继续维持空壳”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录剥初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"这一爻把变化落在具体环节：剥来到二位，个人判断正与资源、规则或他人发生接触 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“列出必须保留与可以退出的部分”后再看反馈；同时留意因为不甘心而继续维持空壳，而不是把在基础不稳时继续扩张当成解决办法，而剥第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","classic":"剝床以辨，蔑貞凶。","source":"《周易》爻辞","modern":{"image":"“剝床以辨，蔑貞凶。”是剥在“接触”阶段留下的具体图景。","situation":"剥来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大舍弃旧部分会带来失落和不安全感。","warning":"因为不甘心而继续维持空壳，而不是把在基础不稳时继续扩张当成解决办法，而剥第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","advice":["列出必须保留与可以退出的部分。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"止损","meaning":"在剥第2爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪些东西已经结束，只是你还没允许它离开”核对判断"},"tone":"接触","extended":{"trigger":{"label":"止损","observe":"完成“列出必须保留与可以退出的部分”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“列出必须保留与可以退出的部分”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“列出必须保留与可以退出的部分”，可以保持小步推进。","pause_if":"若出现“因为不甘心而继续维持空壳，而不是把在基础不稳时继续扩张当成解决办法，而剥第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，先暂停扩大投入。"},"action":{"do":"列出必须保留与可以退出的部分","review":"完成后记录剥六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面正在显出边界：这一爻处在容易用力过度的位置，调整比加码更重要 此时一面是继续原路与承认需要调整之间发生冲突，另一面是舍弃旧部分会带来失落和不安全感，两者要放在同一次权衡里 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若因为不甘心而继续维持空壳会在此时放大，行动应当收束。","classic":"剝之无咎。","source":"《周易》爻辞","modern":{"image":"“剝之无咎。”是剥在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是舍弃旧部分会带来失落和不安全感，两者要放在同一次权衡里。","warning":"因为不甘心而继续维持空壳会在此时放大。","advice":["列出必须保留与可以退出的部分。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"守正","meaning":"在剥第3爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“哪些东西已经结束，只是你还没允许它离开”核对判断"},"tone":"转折","extended":{"trigger":{"label":"守正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“因为不甘心而继续维持空壳会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录剥六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"局面已经接近新的层级，旧角色未必还能容纳当前变化 当前拉扯在于：若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大舍弃旧部分会带来失落和不安全感 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“列出必须保留与可以退出的部分”；若出现“因为不甘心而继续维持空壳”，就暂停扩大动作。","classic":"剝床以膚，凶。","source":"《周易》爻辞","modern":{"image":"“剝床以膚，凶。”是剥在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大舍弃旧部分会带来失落和不安全感。","warning":"因为不甘心而继续维持空壳。","advice":["列出必须保留与可以退出的部分。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"止损","meaning":"在剥第4爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪些东西已经结束，只是你还没允许它离开”核对判断"},"tone":"越界","extended":{"trigger":{"label":"止损","observe":"完成“列出必须保留与可以退出的部分”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“列出必须保留与可以退出的部分”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“列出必须保留与可以退出的部分”，可以保持小步推进。","pause_if":"若出现“因为不甘心而继续维持空壳”，先暂停扩大投入。"},"action":{"do":"列出必须保留与可以退出的部分","review":"完成后记录剥六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"这一爻把变化落在具体环节：关键资源与决定权趋向集中，“剥落与止损”开始影响更多人 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意因为不甘心而继续维持空壳。","classic":"貫魚以宮人寵，无不利。","source":"《周易》爻辞","modern":{"image":"“貫魚以宮人寵，无不利。”是剥在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“剥落与止损”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是舍弃旧部分会带来失落和不安全感，两者要放在同一次权衡里。","warning":"因为不甘心而继续维持空壳。","advice":["列出必须保留与可以退出的部分。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"通达","meaning":"在剥第5爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“哪些东西已经结束，只是你还没允许它离开”核对判断"},"tone":"担当","extended":{"trigger":{"label":"通达","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“因为不甘心而继续维持空壳”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录剥六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面正在显出边界：剥来到上位，已有路径可能完成使命，也可能因过度而失衡 若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大舍弃旧部分会带来失落和不安全感 可以用“列出必须保留与可以退出的部分”做一次验证；若因为不甘心而继续维持空壳，而不是把在基础不稳时继续扩张当成解决办法，而剥第6爻处在“收束”阶段，行动应当收束。","classic":"碩果不食，君子得輿，小人剝廬。","source":"《周易》爻辞","modern":{"image":"“碩果不食，君子得輿，小人剝廬。”是剥在“收束”阶段留下的具体图景。","situation":"剥来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大舍弃旧部分会带来失落和不安全感。","warning":"因为不甘心而继续维持空壳，而不是把在基础不稳时继续扩张当成解决办法，而剥第6爻处在“收束”阶段。","advice":["列出必须保留与可以退出的部分。","列出应当停止、保留和移交的事项。"],"signal":{"label":"观察","meaning":"在剥第6爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪些东西已经结束，只是你还没允许它离开”核对判断"},"tone":"收束","extended":{"trigger":{"label":"观察","observe":"完成“列出必须保留与可以退出的部分”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“列出必须保留与可以退出的部分”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“列出必须保留与可以退出的部分”，可以保持小步推进。","pause_if":"若出现“因为不甘心而继续维持空壳，而不是把在基础不稳时继续扩张当成解决办法，而剥第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"列出必须保留与可以退出的部分","review":"完成后记录剥上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"剥落阶段要先止损，保护仍有生命力的核心","strengths":["减少负担可以让真实结构显现","有些消耗该停下了。先保护核心，允许不必要的部分自然退出"],"tensions":["舍弃旧部分会带来失落和不安全感"],"risks":["因为不甘心而继续维持空壳"],"actions":["列出必须保留与可以退出的部分"],"avoid":["在基础不稳时继续扩张"],"questions":["哪些东西已经结束，只是你还没允许它离开？"],"extended":{"situation":{"direct":"眼下的重点是剥落阶段要先止损，保护仍有生命力的核心。","support":"已经可以利用的是：减少负担可以让真实结构显现。","constraint":"仍需核实的是：舍弃旧部分会带来失落和不安全感。"},"relationship":{"inner":"下卦坤，内部动力偏向承载、配合与现实基础。","outer":"上卦艮，外部处境更受边界、停止与重新定位影响。","interaction":"内部想以“承载、配合与现实基础”回应外部的“边界、停止与重新定位”；两边能否对接，要看“舍弃旧部分会带来失落和不安全感”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“减少负担可以让真实结构显现”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“列出必须保留与可以退出的部分”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“在基础不稳时继续扩张”，风险会被放大。","effect":"最需要防止的是：因为不甘心而继续维持空壳。"},"paths":{"ready":"如果关键条件得到确认，可以继续“列出必须保留与可以退出的部分”，但仍以小步反馈决定是否扩大。","not_ready":"如果“舍弃旧部分会带来失落和不安全感”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"列出必须保留与可以退出的部分","observe":"哪些东西已经结束，只是你还没允许它离开？","continue_if":"出现与“减少负担可以让真实结构显现”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“在基础不稳时继续扩张”或“因为不甘心而继续维持空壳”的迹象。"}}}},{"id":24,"name":"复","pinyin":"fù","theme":"回归与新生","reflection":"回到初心或规律中，微小的回转也值得珍惜。","source_note":"据《周易》复卦意象整理","upper_trigram":8,"lower_trigram":4,"lines":{"1":{"title":"初九","interpretation":"这一爻把变化落在具体环节：复落在初位，眼下更像在辨认方向，而不是兑现结果 现实反馈与当前方向开始相互支持，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意把一次回转夸大成彻底改变。","classic":"不遠復，无祇悔，元吉。","source":"《周易》爻辞","modern":{"image":"“不遠復，无祇悔，元吉。”是复在“潜藏”阶段留下的具体图景。","situation":"复落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自旧习惯仍可能把变化拉回原处，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"把一次回转夸大成彻底改变。","advice":["恢复一个曾经有效的基本习惯。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"顺势","meaning":"在复第1爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“什么最小变化说明你正在回到正轨”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"顺势","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把一次回转夸大成彻底改变”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录复初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：这一阶段不再只靠设想，回应和基本功开始决定走向 自己的节奏需要与现实反馈相互校准，而旧习惯仍可能把变化拉回原处也会在这一爻变得具体 可以用“恢复一个曾经有效的基本习惯”做一次验证；若把一次回转夸大成彻底改变，行动应当收束。","classic":"休復，吉。","source":"《周易》爻辞","modern":{"image":"“休復，吉。”是复在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而旧习惯仍可能把变化拉回原处也会在这一爻变得具体。","warning":"把一次回转夸大成彻底改变。","advice":["恢复一个曾经有效的基本习惯。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在复第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“什么最小变化说明你正在回到正轨”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“恢复一个曾经有效的基本习惯”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“恢复一个曾经有效的基本习惯”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“恢复一个曾经有效的基本习惯”，可以保持小步推进。","pause_if":"若出现“把一次回转夸大成彻底改变”，先暂停扩大投入。"},"action":{"do":"恢复一个曾经有效的基本习惯","review":"完成后记录复六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"事情跨入转折带，焦虑可能比事实更快推动决定 当前拉扯在于：真正的拉扯来自旧习惯仍可能把变化拉回原处，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“把一次回转夸大成彻底改变，而不是把用宏大计划压住微小但真实的进步当成解决办法，而复第3爻处在“转折”阶段”，就暂停扩大动作。","classic":"頻復，厲，无咎。","source":"《周易》爻辞","modern":{"image":"“頻復，厲，无咎。”是复在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自旧习惯仍可能把变化拉回原处，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"把一次回转夸大成彻底改变，而不是把用宏大计划压住微小但真实的进步当成解决办法，而复第3爻处在“转折”阶段。","advice":["恢复一个曾经有效的基本习惯。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"守正","meaning":"在复第3爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“什么最小变化说明你正在回到正轨”核对判断"},"tone":"转折","extended":{"trigger":{"label":"守正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把一次回转夸大成彻底改变，而不是把用宏大计划压住微小但真实的进步当成解决办法，而复第3爻处在“转折”阶段”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录复六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：事情正由内部走向外部，“回归与新生”需要重新确认位置和权限 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“恢复一个曾经有效的基本习惯”后再看反馈；同时留意把一次回转夸大成彻底改变会在此时放大。","classic":"中行獨復。","source":"《周易》爻辞","modern":{"image":"“中行獨復。”是复在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“回归与新生”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而旧习惯仍可能把变化拉回原处也会在这一爻变得具体。","warning":"把一次回转夸大成彻底改变会在此时放大。","advice":["恢复一个曾经有效的基本习惯。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在复第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么最小变化说明你正在回到正轨”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“恢复一个曾经有效的基本习惯”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“恢复一个曾经有效的基本习惯”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“恢复一个曾经有效的基本习惯”，可以保持小步推进。","pause_if":"若出现“把一次回转夸大成彻底改变会在此时放大”，先暂停扩大投入。"},"action":{"do":"恢复一个曾经有效的基本习惯","review":"完成后记录复六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"局面正在显出边界：复来到五位，能力之外还要衡量整体承接和长期后果 真正的拉扯来自旧习惯仍可能把变化拉回原处，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若把一次回转夸大成彻底改变，行动应当收束。","classic":"敦復，无悔。","source":"《周易》爻辞","modern":{"image":"“敦復，无悔。”是复在“担当”阶段留下的具体图景。","situation":"复来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自旧习惯仍可能把变化拉回原处，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"把一次回转夸大成彻底改变。","advice":["恢复一个曾经有效的基本习惯。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"修正","meaning":"在复第5爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“什么最小变化说明你正在回到正轨”核对判断"},"tone":"担当","extended":{"trigger":{"label":"修正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把一次回转夸大成彻底改变”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录复六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻处在阶段末端，下一步先要判断什么已经结束 当前拉扯在于：维持既有成果与允许阶段结束之间存在拉扯，而旧习惯仍可能把变化拉回原处也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“恢复一个曾经有效的基本习惯”；若出现“把一次回转夸大成彻底改变”，就暂停扩大动作。","classic":"迷復，凶，有災眚，用行師，終有大敗。以其國君，凶。至于十年不克征。","source":"《周易》爻辞","modern":{"image":"“迷復，凶，有災眚，用行師，終有大敗。以其國君，凶。至于十年不克征。”是复在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而旧习惯仍可能把变化拉回原处也会在这一爻变得具体。","warning":"把一次回转夸大成彻底改变。","advice":["恢复一个曾经有效的基本习惯。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在复第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“什么最小变化说明你正在回到正轨”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“恢复一个曾经有效的基本习惯”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“恢复一个曾经有效的基本习惯”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“恢复一个曾经有效的基本习惯”，可以保持小步推进。","pause_if":"若出现“把一次回转夸大成彻底改变”，先暂停扩大投入。"},"action":{"do":"恢复一个曾经有效的基本习惯","review":"完成后记录复上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"回归不是退回原点，而是重新接上有效的规律","strengths":["微小修正已经提供新的起点","回到初心或规律中，微小的回转也值得珍惜"],"tensions":["旧习惯仍可能把变化拉回原处"],"risks":["把一次回转夸大成彻底改变"],"actions":["恢复一个曾经有效的基本习惯"],"avoid":["用宏大计划压住微小但真实的进步"],"questions":["什么最小变化说明你正在回到正轨？"],"extended":{"situation":{"direct":"眼下的重点是回归不是退回原点，而是重新接上有效的规律。","support":"已经可以利用的是：微小修正已经提供新的起点。","constraint":"仍需核实的是：旧习惯仍可能把变化拉回原处。"},"relationship":{"inner":"下卦震，内部动力偏向启动、震动与迅速反应。","outer":"上卦坤，外部处境更受承载、配合与现实基础影响。","interaction":"内部想以“启动、震动与迅速反应”回应外部的“承载、配合与现实基础”；两边能否对接，要看“旧习惯仍可能把变化拉回原处”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“微小修正已经提供新的起点”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“恢复一个曾经有效的基本习惯”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用宏大计划压住微小但真实的进步”，风险会被放大。","effect":"最需要防止的是：把一次回转夸大成彻底改变。"},"paths":{"ready":"如果关键条件得到确认，可以继续“恢复一个曾经有效的基本习惯”，但仍以小步反馈决定是否扩大。","not_ready":"如果“旧习惯仍可能把变化拉回原处”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"恢复一个曾经有效的基本习惯","observe":"什么最小变化说明你正在回到正轨？","continue_if":"出现与“微小修正已经提供新的起点”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用宏大计划压住微小但真实的进步”或“把一次回转夸大成彻底改变”的迹象。"}}}},{"id":25,"name":"无妄","pinyin":"wú wàng","theme":"真诚与自然","reflection":"少一些预设与侥幸，按事实与良知行事，心会更安定。","source_note":"据《周易》无妄卦意象整理","upper_trigram":1,"lower_trigram":4,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：这一爻处在起步处，“行动要以事实和真实动机为依据，少靠预设与侥幸”仍需低成本试探 若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大自然推进与主观期待之间可能错位 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若把愿望当成已经发生的条件会在此时放大，行动应当收束。","classic":"无妄往，吉。","source":"《周易》爻辞","modern":{"image":"“无妄往，吉。”是无妄在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“行动要以事实和真实动机为依据，少靠预设与侥幸”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大自然推进与主观期待之间可能错位。","warning":"把愿望当成已经发生的条件会在此时放大。","advice":["核对一个决定所依赖的关键事实。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在无妄第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你现在依据的是事实，还是希望成真的期待”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把愿望当成已经发生的条件会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录无妄初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正从内部准备转向真实互动，关系与条件逐渐可见 当前拉扯在于：此时一面是自己的节奏需要与现实反馈相互校准，另一面是自然推进与主观期待之间可能错位，两者要放在同一次权衡里 当关键条件开始出现可利用的现实回应时，变化才有现实依据。先做“核对一个决定所依赖的关键事实”；若出现“把愿望当成已经发生的条件”，就暂停扩大动作。","classic":"不耕穫，不菑畬，則利有攸往。","source":"《周易》爻辞","modern":{"image":"“不耕穫，不菑畬，則利有攸往。”是无妄在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是自然推进与主观期待之间可能错位，两者要放在同一次权衡里。","warning":"把愿望当成已经发生的条件。","advice":["核对一个决定所依赖的关键事实。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"有利","meaning":"在无妄第2爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“你现在依据的是事实，还是希望成真的期待”核对判断"},"tone":"接触","extended":{"trigger":{"label":"有利","observe":"完成“核对一个决定所依赖的关键事实”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“核对一个决定所依赖的关键事实”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“核对一个决定所依赖的关键事实”，可以保持小步推进。","pause_if":"若出现“把愿望当成已经发生的条件”，先暂停扩大投入。"},"action":{"do":"核对一个决定所依赖的关键事实","review":"完成后记录无妄六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻把变化落在具体环节：局面来到内外转换处，“真诚与自然”开始承受压力测试 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意把愿望当成已经发生的条件。","classic":"无妄之災，或繫之牛，行人之得，邑人之災。","source":"《周易》爻辞","modern":{"image":"“无妄之災，或繫之牛，行人之得，邑人之災。”是无妄在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“真诚与自然”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大自然推进与主观期待之间可能错位。","warning":"把愿望当成已经发生的条件。","advice":["核对一个决定所依赖的关键事实。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在无妄第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“你现在依据的是事实，还是希望成真的期待”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把愿望当成已经发生的条件”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录无妄六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：无妄来到四位，跨出原有边界之前要先说明责任 此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是自然推进与主观期待之间可能错位，两者要放在同一次权衡里 可以用“核对一个决定所依赖的关键事实”做一次验证；若把愿望当成已经发生的条件，而不是把为了得到想要的结果而选择性看证据当成解决办法，而无妄第4爻处在“越界”阶段，行动应当收束。","classic":"可貞，无咎。","source":"《周易》爻辞","modern":{"image":"“可貞，无咎。”是无妄在“越界”阶段留下的具体图景。","situation":"无妄来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是自然推进与主观期待之间可能错位，两者要放在同一次权衡里。","warning":"把愿望当成已经发生的条件，而不是把为了得到想要的结果而选择性看证据当成解决办法，而无妄第4爻处在“越界”阶段。","advice":["核对一个决定所依赖的关键事实。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在无妄第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“你现在依据的是事实，还是希望成真的期待”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“核对一个决定所依赖的关键事实”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“核对一个决定所依赖的关键事实”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“核对一个决定所依赖的关键事实”，可以保持小步推进。","pause_if":"若出现“把愿望当成已经发生的条件，而不是把为了得到想要的结果而选择性看证据当成解决办法，而无妄第4爻处在“越界”阶段”，先暂停扩大投入。"},"action":{"do":"核对一个决定所依赖的关键事实","review":"完成后记录无妄九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一阶段已进入主位，选择会放大为规则或示范 当前拉扯在于：若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大自然推进与主观期待之间可能错位 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“把愿望当成已经发生的条件会在此时放大”，就暂停扩大动作。","classic":"无妄之疾，勿藥有喜。","source":"《周易》爻辞","modern":{"image":"“无妄之疾，勿藥有喜。”是无妄在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大自然推进与主观期待之间可能错位。","warning":"把愿望当成已经发生的条件会在此时放大。","advice":["核对一个决定所依赖的关键事实。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在无妄第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“你现在依据的是事实，还是希望成真的期待”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把愿望当成已经发生的条件会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录无妄九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"这一爻把变化落在具体环节：局面走到极处，继续延长旧办法未必带来同等收益 关键条件开始出现可利用的现实回应，是接下来值得核对的信号。完成“核对一个决定所依赖的关键事实”后再看反馈；同时留意把愿望当成已经发生的条件。","classic":"无妄行，有眚，无攸利。","source":"《周易》爻辞","modern":{"image":"“无妄行，有眚，无攸利。”是无妄在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是自然推进与主观期待之间可能错位，两者要放在同一次权衡里。","warning":"把愿望当成已经发生的条件。","advice":["核对一个决定所依赖的关键事实。","列出应当停止、保留和移交的事项。"],"signal":{"label":"有利","meaning":"在无妄第6爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“你现在依据的是事实，还是希望成真的期待”核对判断"},"tone":"收束","extended":{"trigger":{"label":"有利","observe":"完成“核对一个决定所依赖的关键事实”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“核对一个决定所依赖的关键事实”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“核对一个决定所依赖的关键事实”，可以保持小步推进。","pause_if":"若出现“把愿望当成已经发生的条件”，先暂停扩大投入。"},"action":{"do":"核对一个决定所依赖的关键事实","review":"完成后记录无妄上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"行动要以事实和真实动机为依据，少靠预设与侥幸","strengths":["坦诚能让判断减少额外负担","少一些预设与侥幸，按事实与良知行事，心会更安定"],"tensions":["自然推进与主观期待之间可能错位"],"risks":["把愿望当成已经发生的条件"],"actions":["核对一个决定所依赖的关键事实"],"avoid":["为了得到想要的结果而选择性看证据"],"questions":["你现在依据的是事实，还是希望成真的期待？"],"extended":{"situation":{"direct":"眼下的重点是行动要以事实和真实动机为依据，少靠预设与侥幸。","support":"已经可以利用的是：坦诚能让判断减少额外负担。","constraint":"仍需核实的是：自然推进与主观期待之间可能错位。"},"relationship":{"inner":"下卦震，内部动力偏向启动、震动与迅速反应。","outer":"上卦乾，外部处境更受主动、原则与承担影响。","interaction":"内部想以“启动、震动与迅速反应”回应外部的“主动、原则与承担”；两边能否对接，要看“自然推进与主观期待之间可能错位”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“坦诚能让判断减少额外负担”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“核对一个决定所依赖的关键事实”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“为了得到想要的结果而选择性看证据”，风险会被放大。","effect":"最需要防止的是：把愿望当成已经发生的条件。"},"paths":{"ready":"如果关键条件得到确认，可以继续“核对一个决定所依赖的关键事实”，但仍以小步反馈决定是否扩大。","not_ready":"如果“自然推进与主观期待之间可能错位”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"核对一个决定所依赖的关键事实","observe":"你现在依据的是事实，还是希望成真的期待？","continue_if":"出现与“坦诚能让判断减少额外负担”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“为了得到想要的结果而选择性看证据”或“把愿望当成已经发生的条件”的迹象。"}}}},{"id":26,"name":"大畜","pinyin":"dà xù","theme":"积累与克制","reflection":"现在适合沉淀能力与资源。克制冲动，是为更大的行动蓄力。","source_note":"据《周易》大畜卦意象整理","upper_trigram":7,"lower_trigram":1,"lines":{"1":{"title":"初九","interpretation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分 当前拉扯在于：内在意愿已经出现，外部条件尚未完全成形，而立即表现与继续蓄力之间需要判断也会在这一爻变得具体 当关键条件开始出现可利用的现实回应时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“把积累变成永远不出手，而不是把用准备之名逃避真实检验当成解决办法，而大畜第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，就暂停扩大动作。","classic":"有厲，利已。","source":"《周易》爻辞","modern":{"image":"“有厲，利已。”是大畜在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而立即表现与继续蓄力之间需要判断也会在这一爻变得具体。","warning":"把积累变成永远不出手，而不是把用准备之名逃避真实检验当成解决办法，而大畜第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["设定达到什么条件就开始行动。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"有利","meaning":"在大畜第1爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“还缺哪项关键能力，而不是泛泛地觉得没准备好”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"有利","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把积累变成永远不出手，而不是把用准备之名逃避真实检验当成解决办法，而大畜第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录大畜初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一爻把变化落在具体环节：事情开始进入现实协作，“积累与克制”要接受反馈检验 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“设定达到什么条件就开始行动”后再看反馈；同时留意把积累变成永远不出手会在此时放大。","classic":"輿說輹。","source":"《周易》爻辞","modern":{"image":"“輿說輹。”是大畜在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“积累与克制”要接受反馈检验。","tension":"真正的拉扯来自立即表现与继续蓄力之间需要判断，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"把积累变成永远不出手会在此时放大。","advice":["设定达到什么条件就开始行动。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在大畜第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“还缺哪项关键能力，而不是泛泛地觉得没准备好”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“设定达到什么条件就开始行动”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“设定达到什么条件就开始行动”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“设定达到什么条件就开始行动”，可以保持小步推进。","pause_if":"若出现“把积累变成永远不出手会在此时放大”，先暂停扩大投入。"},"action":{"do":"设定达到什么条件就开始行动","review":"完成后记录大畜九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面正在显出边界：大畜行至三位，旧方法的边界和新选择的代价同时出现 继续原路与承认需要调整之间发生冲突，而立即表现与继续蓄力之间需要判断也会在这一爻变得具体 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若把积累变成永远不出手，行动应当收束。","classic":"良馬逐，利艱貞。曰閑輿衛，利有攸往。","source":"《周易》爻辞","modern":{"image":"“良馬逐，利艱貞。曰閑輿衛，利有攸往。”是大畜在“转折”阶段留下的具体图景。","situation":"大畜行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而立即表现与继续蓄力之间需要判断也会在这一爻变得具体。","warning":"把积累变成永远不出手。","advice":["设定达到什么条件就开始行动。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"有利","meaning":"在大畜第3爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“还缺哪项关键能力，而不是泛泛地觉得没准备好”核对判断"},"tone":"转折","extended":{"trigger":{"label":"有利","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把积累变成永远不出手”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录大畜九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 当前拉扯在于：真正的拉扯来自立即表现与继续蓄力之间需要判断，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题 当现实反馈与当前方向开始相互支持时，变化才有现实依据。先做“设定达到什么条件就开始行动”；若出现“把积累变成永远不出手”，就暂停扩大动作。","classic":"童牛之牿，元吉。","source":"《周易》爻辞","modern":{"image":"“童牛之牿，元吉。”是大畜在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自立即表现与继续蓄力之间需要判断，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"把积累变成永远不出手。","advice":["设定达到什么条件就开始行动。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"顺势","meaning":"在大畜第4爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“还缺哪项关键能力，而不是泛泛地觉得没准备好”核对判断"},"tone":"越界","extended":{"trigger":{"label":"顺势","observe":"完成“设定达到什么条件就开始行动”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“设定达到什么条件就开始行动”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“设定达到什么条件就开始行动”，可以保持小步推进。","pause_if":"若出现“把积累变成永远不出手”，先暂停扩大投入。"},"action":{"do":"设定达到什么条件就开始行动","review":"完成后记录大畜六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"这一爻把变化落在具体环节：局面要求从个人得失转向整体结果和持续责任 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意把积累变成永远不出手，而不是把用准备之名逃避真实检验当成解决办法，而大畜第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","classic":"豶豕之牙，吉。","source":"《周易》爻辞","modern":{"image":"“豶豕之牙，吉。”是大畜在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而立即表现与继续蓄力之间需要判断也会在这一爻变得具体。","warning":"把积累变成永远不出手，而不是把用准备之名逃避真实检验当成解决办法，而大畜第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["设定达到什么条件就开始行动。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在大畜第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“还缺哪项关键能力，而不是泛泛地觉得没准备好”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把积累变成永远不出手，而不是把用准备之名逃避真实检验当成解决办法，而大畜第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录大畜六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面正在显出边界：当前循环接近上限，“积累与克制”需要从继续加力转向收束复盘 真正的拉扯来自立即表现与继续蓄力之间需要判断，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题 可以用“设定达到什么条件就开始行动”做一次验证；若把积累变成永远不出手会在此时放大，行动应当收束。","classic":"何天之衢，亨。","source":"《周易》爻辞","modern":{"image":"“何天之衢，亨。”是大畜在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“积累与克制”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自立即表现与继续蓄力之间需要判断，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"把积累变成永远不出手会在此时放大。","advice":["设定达到什么条件就开始行动。","列出应当停止、保留和移交的事项。"],"signal":{"label":"观察","meaning":"在大畜第6爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“还缺哪项关键能力，而不是泛泛地觉得没准备好”核对判断"},"tone":"收束","extended":{"trigger":{"label":"观察","observe":"完成“设定达到什么条件就开始行动”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“设定达到什么条件就开始行动”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“设定达到什么条件就开始行动”，可以保持小步推进。","pause_if":"若出现“把积累变成永远不出手会在此时放大”，先暂停扩大投入。"},"action":{"do":"设定达到什么条件就开始行动","review":"完成后记录大畜上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"克制是为更有分量的行动积累能力与资源","strengths":["已有耐心沉淀长期价值","现在适合沉淀能力与资源。克制冲动，是为更大的行动蓄力"],"tensions":["立即表现与继续蓄力之间需要判断"],"risks":["把积累变成永远不出手"],"actions":["设定达到什么条件就开始行动"],"avoid":["用准备之名逃避真实检验"],"questions":["还缺哪项关键能力，而不是泛泛地觉得没准备好？"],"extended":{"situation":{"direct":"眼下的重点是克制是为更有分量的行动积累能力与资源。","support":"已经可以利用的是：已有耐心沉淀长期价值。","constraint":"仍需核实的是：立即表现与继续蓄力之间需要判断。"},"relationship":{"inner":"下卦乾，内部动力偏向主动、原则与承担。","outer":"上卦艮，外部处境更受边界、停止与重新定位影响。","interaction":"内部想以“主动、原则与承担”回应外部的“边界、停止与重新定位”；两边能否对接，要看“立即表现与继续蓄力之间需要判断”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“已有耐心沉淀长期价值”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“设定达到什么条件就开始行动”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用准备之名逃避真实检验”，风险会被放大。","effect":"最需要防止的是：把积累变成永远不出手。"},"paths":{"ready":"如果关键条件得到确认，可以继续“设定达到什么条件就开始行动”，但仍以小步反馈决定是否扩大。","not_ready":"如果“立即表现与继续蓄力之间需要判断”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"设定达到什么条件就开始行动","observe":"还缺哪项关键能力，而不是泛泛地觉得没准备好？","continue_if":"出现与“已有耐心沉淀长期价值”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用准备之名逃避真实检验”或“把积累变成永远不出手”的迹象。"}}}},{"id":27,"name":"颐","pinyin":"yí","theme":"养护与言语","reflection":"照顾身体，也照顾输入与表达。你长期喂养什么，就会长成什么。","source_note":"据《周易》颐卦意象整理","upper_trigram":7,"lower_trigram":4,"lines":{"1":{"title":"初九","interpretation":"这一爻把变化落在具体环节：事情刚在“养护与言语”的起点露出端倪，可用条件还不多 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意忽略身体、信息或言语的持续影响。","classic":"舍爾靈龜，觀我朵頤，凶。","source":"《周易》爻辞","modern":{"image":"“舍爾靈龜，觀我朵頤，凶。”是颐在“潜藏”阶段留下的具体图景。","situation":"事情刚在“养护与言语”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是满足眼前需要与形成长期习惯之间有差距，两者要放在同一次权衡里。","warning":"忽略身体、信息或言语的持续影响。","advice":["减少一种消耗性输入，增加一种稳定补给。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"止损","meaning":"在颐第1爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“你每天在喂养什么，它正在把你带向哪里”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"止损","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“忽略身体、信息或言语的持续影响”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录颐初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：颐来到二位，个人判断正与资源、规则或他人发生接触 若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大满足眼前需要与形成长期习惯之间有差距 可以用“减少一种消耗性输入，增加一种稳定补给”做一次验证；若忽略身体、信息或言语的持续影响，而不是把把短期刺激当成真正滋养当成解决办法，而颐第2爻处在“接触”阶段，行动应当收束。","classic":"顛頤，拂經，于丘頤，征凶。","source":"《周易》爻辞","modern":{"image":"“顛頤，拂經，于丘頤，征凶。”是颐在“接触”阶段留下的具体图景。","situation":"颐来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大满足眼前需要与形成长期习惯之间有差距。","warning":"忽略身体、信息或言语的持续影响，而不是把把短期刺激当成真正滋养当成解决办法，而颐第2爻处在“接触”阶段。","advice":["减少一种消耗性输入，增加一种稳定补给。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"止损","meaning":"在颐第2爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“你每天在喂养什么，它正在把你带向哪里”核对判断"},"tone":"接触","extended":{"trigger":{"label":"止损","observe":"完成“减少一种消耗性输入，增加一种稳定补给”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“减少一种消耗性输入，增加一种稳定补给”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“减少一种消耗性输入，增加一种稳定补给”，可以保持小步推进。","pause_if":"若出现“忽略身体、信息或言语的持续影响，而不是把把短期刺激当成真正滋养当成解决办法，而颐第2爻处在“接触”阶段”，先暂停扩大投入。"},"action":{"do":"减少一种消耗性输入，增加一种稳定补给","review":"完成后记录颐六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻处在容易用力过度的位置，调整比加码更重要 当前拉扯在于：此时一面是继续原路与承认需要调整之间发生冲突，另一面是满足眼前需要与形成长期习惯之间有差距，两者要放在同一次权衡里 当现实条件尚不足以支持扩大动作时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“忽略身体、信息或言语的持续影响会在此时放大”，就暂停扩大动作。","classic":"拂頤，貞凶。十年勿用，无攸利。","source":"《周易》爻辞","modern":{"image":"“拂頤，貞凶。十年勿用，无攸利。”是颐在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是满足眼前需要与形成长期习惯之间有差距，两者要放在同一次权衡里。","warning":"忽略身体、信息或言语的持续影响会在此时放大。","advice":["减少一种消耗性输入，增加一种稳定补给。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"暂停","meaning":"在颐第3爻里，爻辞给出明确的收势信号，眼下不宜把意愿直接变成大动作，可用“你每天在喂养什么，它正在把你带向哪里”核对判断"},"tone":"转折","extended":{"trigger":{"label":"暂停","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实条件尚不足以支持扩大动作”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“忽略身体、信息或言语的持续影响会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录颐六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：局面已经接近新的层级，旧角色未必还能容纳当前变化 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“减少一种消耗性输入，增加一种稳定补给”后再看反馈；同时留意忽略身体、信息或言语的持续影响。","classic":"顛頤，吉，虎視眈眈，其欲逐逐，无咎。","source":"《周易》爻辞","modern":{"image":"“顛頤，吉，虎視眈眈，其欲逐逐，无咎。”是颐在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大满足眼前需要与形成长期习惯之间有差距。","warning":"忽略身体、信息或言语的持续影响。","advice":["减少一种消耗性输入，增加一种稳定补给。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在颐第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你每天在喂养什么，它正在把你带向哪里”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“减少一种消耗性输入，增加一种稳定补给”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“减少一种消耗性输入，增加一种稳定补给”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“减少一种消耗性输入，增加一种稳定补给”，可以保持小步推进。","pause_if":"若出现“忽略身体、信息或言语的持续影响”，先暂停扩大投入。"},"action":{"do":"减少一种消耗性输入，增加一种稳定补给","review":"完成后记录颐六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"局面正在显出边界：关键资源与决定权趋向集中，“养护与言语”开始影响更多人 此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是满足眼前需要与形成长期习惯之间有差距，两者要放在同一次权衡里 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若忽略身体、信息或言语的持续影响，行动应当收束。","classic":"拂經，居貞吉，不可涉大川。","source":"《周易》爻辞","modern":{"image":"“拂經，居貞吉，不可涉大川。”是颐在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“养护与言语”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是满足眼前需要与形成长期习惯之间有差距，两者要放在同一次权衡里。","warning":"忽略身体、信息或言语的持续影响。","advice":["减少一种消耗性输入，增加一种稳定补给。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"暂停","meaning":"在颐第5爻里，爻辞给出明确的收势信号，眼下不宜把意愿直接变成大动作，可用“你每天在喂养什么，它正在把你带向哪里”核对判断"},"tone":"担当","extended":{"trigger":{"label":"暂停","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实条件尚不足以支持扩大动作”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“忽略身体、信息或言语的持续影响”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录颐六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"颐来到上位，已有路径可能完成使命，也可能因过度而失衡 当前拉扯在于：若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大满足眼前需要与形成长期习惯之间有差距 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“减少一种消耗性输入，增加一种稳定补给”；若出现“忽略身体、信息或言语的持续影响，而不是把把短期刺激当成真正滋养当成解决办法，而颐第6爻处在“收束”阶段”，就暂停扩大动作。","classic":"由頤，厲吉，利涉大川。","source":"《周易》爻辞","modern":{"image":"“由頤，厲吉，利涉大川。”是颐在“收束”阶段留下的具体图景。","situation":"颐来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大满足眼前需要与形成长期习惯之间有差距。","warning":"忽略身体、信息或言语的持续影响，而不是把把短期刺激当成真正滋养当成解决办法，而颐第6爻处在“收束”阶段。","advice":["减少一种消耗性输入，增加一种稳定补给。","列出应当停止、保留和移交的事项。"],"signal":{"label":"可行","meaning":"在颐第6爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你每天在喂养什么，它正在把你带向哪里”核对判断"},"tone":"收束","extended":{"trigger":{"label":"可行","observe":"完成“减少一种消耗性输入，增加一种稳定补给”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“减少一种消耗性输入，增加一种稳定补给”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“减少一种消耗性输入，增加一种稳定补给”，可以保持小步推进。","pause_if":"若出现“忽略身体、信息或言语的持续影响，而不是把把短期刺激当成真正滋养当成解决办法，而颐第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"减少一种消耗性输入，增加一种稳定补给","review":"完成后记录颐上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"长期输入会塑造状态，表达也会反过来影响关系","strengths":["可以通过日常照料恢复稳定","照顾身体，也照顾输入与表达。你长期喂养什么，就会长成什么"],"tensions":["满足眼前需要与形成长期习惯之间有差距"],"risks":["忽略身体、信息或言语的持续影响"],"actions":["减少一种消耗性输入，增加一种稳定补给"],"avoid":["把短期刺激当成真正滋养"],"questions":["你每天在喂养什么，它正在把你带向哪里？"],"extended":{"situation":{"direct":"眼下的重点是长期输入会塑造状态，表达也会反过来影响关系。","support":"已经可以利用的是：可以通过日常照料恢复稳定。","constraint":"仍需核实的是：满足眼前需要与形成长期习惯之间有差距。"},"relationship":{"inner":"下卦震，内部动力偏向启动、震动与迅速反应。","outer":"上卦艮，外部处境更受边界、停止与重新定位影响。","interaction":"内部想以“启动、震动与迅速反应”回应外部的“边界、停止与重新定位”；两边能否对接，要看“满足眼前需要与形成长期习惯之间有差距”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“可以通过日常照料恢复稳定”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“减少一种消耗性输入，增加一种稳定补给”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把短期刺激当成真正滋养”，风险会被放大。","effect":"最需要防止的是：忽略身体、信息或言语的持续影响。"},"paths":{"ready":"如果关键条件得到确认，可以继续“减少一种消耗性输入，增加一种稳定补给”，但仍以小步反馈决定是否扩大。","not_ready":"如果“满足眼前需要与形成长期习惯之间有差距”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"减少一种消耗性输入，增加一种稳定补给","observe":"你每天在喂养什么，它正在把你带向哪里？","continue_if":"出现与“可以通过日常照料恢复稳定”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把短期刺激当成真正滋养”或“忽略身体、信息或言语的持续影响”的迹象。"}}}},{"id":28,"name":"大过","pinyin":"dà guò","theme":"压力与非常之举","reflection":"负担偏重时，先承认现实，再找到关键支点；不必独自硬撑。","source_note":"据《周易》大过卦意象整理","upper_trigram":2,"lower_trigram":5,"lines":{"1":{"title":"初六","interpretation":"局面正在显出边界：大过落在初位，眼下更像在辨认方向，而不是兑现结果 真正的拉扯来自承担责任与承认承载上限互相冲突，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若继续独撑直到结构失效，行动应当收束。","classic":"藉用白茅，无咎。","source":"《周易》爻辞","modern":{"image":"“藉用白茅，无咎。”是大过在“潜藏”阶段留下的具体图景。","situation":"大过落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自承担责任与承认承载上限互相冲突，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"继续独撑直到结构失效。","advice":["指出最重的负担并寻找可分担者。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在大过第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“如果不能继续硬撑，哪个支点最先需要改变”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“继续独撑直到结构失效”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录大过初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一阶段不再只靠设想，回应和基本功开始决定走向 当前拉扯在于：自己的节奏需要与现实反馈相互校准，而承担责任与承认承载上限互相冲突也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“指出最重的负担并寻找可分担者”；若出现“继续独撑直到结构失效”，就暂停扩大动作。","classic":"枯楊生稊，老夫得其女妻，无不利。","source":"《周易》爻辞","modern":{"image":"“枯楊生稊，老夫得其女妻，无不利。”是大过在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而承担责任与承认承载上限互相冲突也会在这一爻变得具体。","warning":"继续独撑直到结构失效。","advice":["指出最重的负担并寻找可分担者。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"通达","meaning":"在大过第2爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“如果不能继续硬撑，哪个支点最先需要改变”核对判断"},"tone":"接触","extended":{"trigger":{"label":"通达","observe":"完成“指出最重的负担并寻找可分担者”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“指出最重的负担并寻找可分担者”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“指出最重的负担并寻找可分担者”，可以保持小步推进。","pause_if":"若出现“继续独撑直到结构失效”，先暂停扩大投入。"},"action":{"do":"指出最重的负担并寻找可分担者","review":"完成后记录大过九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻把变化落在具体环节：事情跨入转折带，焦虑可能比事实更快推动决定 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意继续独撑直到结构失效，而不是把用意志力替代结构调整当成解决办法，而大过第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","classic":"棟橈，凶。","source":"《周易》爻辞","modern":{"image":"“棟橈，凶。”是大过在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自承担责任与承认承载上限互相冲突，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"继续独撑直到结构失效，而不是把用意志力替代结构调整当成解决办法，而大过第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","advice":["指出最重的负担并寻找可分担者。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"止损","meaning":"在大过第3爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“如果不能继续硬撑，哪个支点最先需要改变”核对判断"},"tone":"转折","extended":{"trigger":{"label":"止损","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“继续独撑直到结构失效，而不是把用意志力替代结构调整当成解决办法，而大过第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录大过九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：事情正由内部走向外部，“压力与非常之举”需要重新确认位置和权限 向外推进的需要与边界尚未说清之间互相牵制，而承担责任与承认承载上限互相冲突也会在这一爻变得具体 可以用“指出最重的负担并寻找可分担者”做一次验证；若继续独撑直到结构失效会在此时放大，行动应当收束。","classic":"棟隆，吉，有它吝。","source":"《周易》爻辞","modern":{"image":"“棟隆，吉，有它吝。”是大过在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“压力与非常之举”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而承担责任与承认承载上限互相冲突也会在这一爻变得具体。","warning":"继续独撑直到结构失效会在此时放大。","advice":["指出最重的负担并寻找可分担者。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在大过第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“如果不能继续硬撑，哪个支点最先需要改变”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“指出最重的负担并寻找可分担者”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“指出最重的负担并寻找可分担者”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“指出最重的负担并寻找可分担者”，可以保持小步推进。","pause_if":"若出现“继续独撑直到结构失效会在此时放大”，先暂停扩大投入。"},"action":{"do":"指出最重的负担并寻找可分担者","review":"完成后记录大过九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"大过来到五位，能力之外还要衡量整体承接和长期后果 当前拉扯在于：真正的拉扯来自承担责任与承认承载上限互相冲突，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“继续独撑直到结构失效”，就暂停扩大动作。","classic":"枯楊生華，老婦得其士夫，无咎无譽。","source":"《周易》爻辞","modern":{"image":"“枯楊生華，老婦得其士夫，无咎无譽。”是大过在“担当”阶段留下的具体图景。","situation":"大过来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自承担责任与承认承载上限互相冲突，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"继续独撑直到结构失效。","advice":["指出最重的负担并寻找可分担者。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"守正","meaning":"在大过第5爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“如果不能继续硬撑，哪个支点最先需要改变”核对判断"},"tone":"担当","extended":{"trigger":{"label":"守正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“继续独撑直到结构失效”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录大过九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻把变化落在具体环节：这一爻处在阶段末端，下一步先要判断什么已经结束 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“指出最重的负担并寻找可分担者”后再看反馈；同时留意继续独撑直到结构失效。","classic":"過涉滅頂，凶，无咎。","source":"《周易》爻辞","modern":{"image":"“過涉滅頂，凶，无咎。”是大过在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而承担责任与承认承载上限互相冲突也会在这一爻变得具体。","warning":"继续独撑直到结构失效。","advice":["指出最重的负担并寻找可分担者。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在大过第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“如果不能继续硬撑，哪个支点最先需要改变”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“指出最重的负担并寻找可分担者”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“指出最重的负担并寻找可分担者”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“指出最重的负担并寻找可分担者”，可以保持小步推进。","pause_if":"若出现“继续独撑直到结构失效”，先暂停扩大投入。"},"action":{"do":"指出最重的负担并寻找可分担者","review":"完成后记录大过上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"负担超过常态时，需要找到支点并作非常调整","strengths":["已经具备面对高压现实的勇气","负担偏重时，先承认现实，再找到关键支点"],"tensions":["承担责任与承认承载上限互相冲突"],"risks":["继续独撑直到结构失效"],"actions":["指出最重的负担并寻找可分担者"],"avoid":["用意志力替代结构调整"],"questions":["如果不能继续硬撑，哪个支点最先需要改变？"],"extended":{"situation":{"direct":"眼下的重点是负担超过常态时，需要找到支点并作非常调整。","support":"已经可以利用的是：已经具备面对高压现实的勇气。","constraint":"仍需核实的是：承担责任与承认承载上限互相冲突。"},"relationship":{"inner":"下卦巽，内部动力偏向渗透、调整与持续影响。","outer":"上卦兑，外部处境更受交流、回应与协商影响。","interaction":"内部想以“渗透、调整与持续影响”回应外部的“交流、回应与协商”；两边能否对接，要看“承担责任与承认承载上限互相冲突”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“已经具备面对高压现实的勇气”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“指出最重的负担并寻找可分担者”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用意志力替代结构调整”，风险会被放大。","effect":"最需要防止的是：继续独撑直到结构失效。"},"paths":{"ready":"如果关键条件得到确认，可以继续“指出最重的负担并寻找可分担者”，但仍以小步反馈决定是否扩大。","not_ready":"如果“承担责任与承认承载上限互相冲突”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"指出最重的负担并寻找可分担者","observe":"如果不能继续硬撑，哪个支点最先需要改变？","continue_if":"出现与“已经具备面对高压现实的勇气”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用意志力替代结构调整”或“继续独撑直到结构失效”的迹象。"}}}},{"id":29,"name":"坎","pinyin":"kǎn","theme":"险境与坚持","reflection":"身处反复的难处，守住基本安全与规律。先过这一段，再谈远方。","source_note":"据《周易》坎卦意象整理","upper_trigram":6,"lower_trigram":6,"lines":{"1":{"title":"初六","interpretation":"这一爻处在起步处，“反复险境中，先守住安全、规律和可信路径”仍需低成本试探 当前拉扯在于：若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大摆脱困境的急切可能带来新的风险 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“因为厌倦就选择未经验证的捷径会在此时放大”，就暂停扩大动作。","classic":"習坎，入于坎窞，凶。","source":"《周易》爻辞","modern":{"image":"“習坎，入于坎窞，凶。”是坎在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“反复险境中，先守住安全、规律和可信路径”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大摆脱困境的急切可能带来新的风险。","warning":"因为厌倦就选择未经验证的捷径会在此时放大。","advice":["确定今天必须守住的一条安全线。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"止损","meaning":"在坎第1爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“什么动作能让你先安全度过这一段”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"止损","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“因为厌倦就选择未经验证的捷径会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录坎初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一爻把变化落在具体环节：局面正从内部准备转向真实互动，关系与条件逐渐可见 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“确定今天必须守住的一条安全线”后再看反馈；同时留意因为厌倦就选择未经验证的捷径。","classic":"坎，有險，求小得。","source":"《周易》爻辞","modern":{"image":"“坎，有險，求小得。”是坎在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是摆脱困境的急切可能带来新的风险，两者要放在同一次权衡里。","warning":"因为厌倦就选择未经验证的捷径。","advice":["确定今天必须守住的一条安全线。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在坎第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么动作能让你先安全度过这一段”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“确定今天必须守住的一条安全线”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“确定今天必须守住的一条安全线”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“确定今天必须守住的一条安全线”，可以保持小步推进。","pause_if":"若出现“因为厌倦就选择未经验证的捷径”，先暂停扩大投入。"},"action":{"do":"确定今天必须守住的一条安全线","review":"完成后记录坎九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面正在显出边界：局面来到内外转换处，“险境与坚持”开始承受压力测试 若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大摆脱困境的急切可能带来新的风险 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若因为厌倦就选择未经验证的捷径，行动应当收束。","classic":"來之坎坎，險且枕，入于坎窞，勿用。","source":"《周易》爻辞","modern":{"image":"“來之坎坎，險且枕，入于坎窞，勿用。”是坎在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“险境与坚持”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大摆脱困境的急切可能带来新的风险。","warning":"因为厌倦就选择未经验证的捷径。","advice":["确定今天必须守住的一条安全线。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"暂停","meaning":"在坎第3爻里，爻辞给出明确的收势信号，眼下不宜把意愿直接变成大动作，可用“什么动作能让你先安全度过这一段”核对判断"},"tone":"转折","extended":{"trigger":{"label":"暂停","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实条件尚不足以支持扩大动作”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“因为厌倦就选择未经验证的捷径”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录坎六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"坎来到四位，跨出原有边界之前要先说明责任 当前拉扯在于：此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是摆脱困境的急切可能带来新的风险，两者要放在同一次权衡里 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“确定今天必须守住的一条安全线”；若出现“因为厌倦就选择未经验证的捷径，而不是把同时处理所有危险当成解决办法，而坎第4爻处在“越界”阶段”，就暂停扩大动作。","classic":"樽酒，簋貳，用缶，納約自牖，終无咎。","source":"《周易》爻辞","modern":{"image":"“樽酒，簋貳，用缶，納約自牖，終无咎。”是坎在“越界”阶段留下的具体图景。","situation":"坎来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是摆脱困境的急切可能带来新的风险，两者要放在同一次权衡里。","warning":"因为厌倦就选择未经验证的捷径，而不是把同时处理所有危险当成解决办法，而坎第4爻处在“越界”阶段。","advice":["确定今天必须守住的一条安全线。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在坎第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“什么动作能让你先安全度过这一段”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“确定今天必须守住的一条安全线”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“确定今天必须守住的一条安全线”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“确定今天必须守住的一条安全线”，可以保持小步推进。","pause_if":"若出现“因为厌倦就选择未经验证的捷径，而不是把同时处理所有危险当成解决办法，而坎第4爻处在“越界”阶段”，先暂停扩大投入。"},"action":{"do":"确定今天必须守住的一条安全线","review":"完成后记录坎六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一爻把变化落在具体环节：这一阶段已进入主位，选择会放大为规则或示范 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意因为厌倦就选择未经验证的捷径会在此时放大。","classic":"坎不盈，祗既平，无咎。","source":"《周易》爻辞","modern":{"image":"“坎不盈，祗既平，无咎。”是坎在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大摆脱困境的急切可能带来新的风险。","warning":"因为厌倦就选择未经验证的捷径会在此时放大。","advice":["确定今天必须守住的一条安全线。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"守正","meaning":"在坎第5爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“什么动作能让你先安全度过这一段”核对判断"},"tone":"担当","extended":{"trigger":{"label":"守正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“因为厌倦就选择未经验证的捷径会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录坎九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"局面正在显出边界：局面走到极处，继续延长旧办法未必带来同等收益 此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是摆脱困境的急切可能带来新的风险，两者要放在同一次权衡里 可以用“确定今天必须守住的一条安全线”做一次验证；若因为厌倦就选择未经验证的捷径，行动应当收束。","classic":"係用黴纆，寘于叢棘，三歲不得，凶。","source":"《周易》爻辞","modern":{"image":"“係用黴纆，寘于叢棘，三歲不得，凶。”是坎在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是摆脱困境的急切可能带来新的风险，两者要放在同一次权衡里。","warning":"因为厌倦就选择未经验证的捷径。","advice":["确定今天必须守住的一条安全线。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在坎第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“什么动作能让你先安全度过这一段”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“确定今天必须守住的一条安全线”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“确定今天必须守住的一条安全线”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“确定今天必须守住的一条安全线”，可以保持小步推进。","pause_if":"若出现“因为厌倦就选择未经验证的捷径”，先暂停扩大投入。"},"action":{"do":"确定今天必须守住的一条安全线","review":"完成后记录坎上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"反复险境中，先守住安全、规律和可信路径","strengths":["在困难中仍有保持节奏的能力","身处反复的难处，守住基本安全与规律。先过这一段，再谈远方"],"tensions":["摆脱困境的急切可能带来新的风险"],"risks":["因为厌倦就选择未经验证的捷径"],"actions":["确定今天必须守住的一条安全线"],"avoid":["同时处理所有危险"],"questions":["什么动作能让你先安全度过这一段？"],"extended":{"situation":{"direct":"眼下的重点是反复险境中，先守住安全、规律和可信路径。","support":"已经可以利用的是：在困难中仍有保持节奏的能力。","constraint":"仍需核实的是：摆脱困境的急切可能带来新的风险。"},"relationship":{"inner":"下卦坎，内部动力偏向风险、试探与信息缺口。","outer":"上卦坎，外部处境更受风险、试探与信息缺口影响。","interaction":"内部想以“风险、试探与信息缺口”回应外部的“风险、试探与信息缺口”；两边能否对接，要看“摆脱困境的急切可能带来新的风险”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“在困难中仍有保持节奏的能力”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“确定今天必须守住的一条安全线”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“同时处理所有危险”，风险会被放大。","effect":"最需要防止的是：因为厌倦就选择未经验证的捷径。"},"paths":{"ready":"如果关键条件得到确认，可以继续“确定今天必须守住的一条安全线”，但仍以小步反馈决定是否扩大。","not_ready":"如果“摆脱困境的急切可能带来新的风险”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"确定今天必须守住的一条安全线","observe":"什么动作能让你先安全度过这一段？","continue_if":"出现与“在困难中仍有保持节奏的能力”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“同时处理所有危险”或“因为厌倦就选择未经验证的捷径”的迹象。"}}}},{"id":30,"name":"离","pinyin":"lí","theme":"明辨与依附","reflection":"让事实照亮选择，也为自己寻找可靠的连接与支持。","source_note":"据《周易》离卦意象整理","upper_trigram":3,"lower_trigram":3,"lines":{"1":{"title":"初九","interpretation":"这一爻把变化落在具体环节：变化尚在根部，先分清已经发生的事实和仍在期待的部分 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意只选择能证明原有判断的信息，而不是把让强烈观点遮住相反证据当成解决办法，而离第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","classic":"履錯然，敬之，无咎。","source":"《周易》爻辞","modern":{"image":"“履錯然，敬之，无咎。”是离在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而追求明白与依赖外部认可之间会拉扯也会在这一爻变得具体。","warning":"只选择能证明原有判断的信息，而不是把让强烈观点遮住相反证据当成解决办法，而离第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["把证据、解释和感受分开记录。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在离第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“哪些是事实，哪些只是你对事实的解释”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“只选择能证明原有判断的信息，而不是把让强烈观点遮住相反证据当成解决办法，而离第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录离初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：事情开始进入现实协作，“明辨与依附”要接受反馈检验 真正的拉扯来自追求明白与依赖外部认可之间会拉扯，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题 可以用“把证据、解释和感受分开记录”做一次验证；若只选择能证明原有判断的信息会在此时放大，行动应当收束。","classic":"黃離，元吉。","source":"《周易》爻辞","modern":{"image":"“黃離，元吉。”是离在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“明辨与依附”要接受反馈检验。","tension":"真正的拉扯来自追求明白与依赖外部认可之间会拉扯，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"只选择能证明原有判断的信息会在此时放大。","advice":["把证据、解释和感受分开记录。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"顺势","meaning":"在离第2爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“哪些是事实，哪些只是你对事实的解释”核对判断"},"tone":"接触","extended":{"trigger":{"label":"顺势","observe":"完成“把证据、解释和感受分开记录”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“把证据、解释和感受分开记录”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把证据、解释和感受分开记录”，可以保持小步推进。","pause_if":"若出现“只选择能证明原有判断的信息会在此时放大”，先暂停扩大投入。"},"action":{"do":"把证据、解释和感受分开记录","review":"完成后记录离六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"离行至三位，旧方法的边界和新选择的代价同时出现 当前拉扯在于：继续原路与承认需要调整之间发生冲突，而追求明白与依赖外部认可之间会拉扯也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“只选择能证明原有判断的信息”，就暂停扩大动作。","classic":"日昃之離，不鼓缶而歌，則大耋之嗟，凶。","source":"《周易》爻辞","modern":{"image":"“日昃之離，不鼓缶而歌，則大耋之嗟，凶。”是离在“转折”阶段留下的具体图景。","situation":"离行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而追求明白与依赖外部认可之间会拉扯也会在这一爻变得具体。","warning":"只选择能证明原有判断的信息。","advice":["把证据、解释和感受分开记录。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"止损","meaning":"在离第3爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪些是事实，哪些只是你对事实的解释”核对判断"},"tone":"转折","extended":{"trigger":{"label":"止损","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“只选择能证明原有判断的信息”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录离九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"这一爻把变化落在具体环节：这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“把证据、解释和感受分开记录”后再看反馈；同时留意只选择能证明原有判断的信息。","classic":"突如其來如，焚如，死如，棄如。","source":"《周易》爻辞","modern":{"image":"“突如其來如，焚如，死如，棄如。”是离在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自追求明白与依赖外部认可之间会拉扯，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"只选择能证明原有判断的信息。","advice":["把证据、解释和感受分开记录。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在离第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪些是事实，哪些只是你对事实的解释”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“把证据、解释和感受分开记录”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把证据、解释和感受分开记录”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把证据、解释和感受分开记录”，可以保持小步推进。","pause_if":"若出现“只选择能证明原有判断的信息”，先暂停扩大投入。"},"action":{"do":"把证据、解释和感受分开记录","review":"完成后记录离九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"局面正在显出边界：局面要求从个人得失转向整体结果和持续责任 扩大影响与照顾整体承接能力之间需要平衡，而追求明白与依赖外部认可之间会拉扯也会在这一爻变得具体 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若只选择能证明原有判断的信息，而不是把让强烈观点遮住相反证据当成解决办法，而离第5爻处在“担当”阶段，行动应当收束。","classic":"出涕沱若，戚嗟若，吉。","source":"《周易》爻辞","modern":{"image":"“出涕沱若，戚嗟若，吉。”是离在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而追求明白与依赖外部认可之间会拉扯也会在这一爻变得具体。","warning":"只选择能证明原有判断的信息，而不是把让强烈观点遮住相反证据当成解决办法，而离第5爻处在“担当”阶段。","advice":["把证据、解释和感受分开记录。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在离第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪些是事实，哪些只是你对事实的解释”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“只选择能证明原有判断的信息，而不是把让强烈观点遮住相反证据当成解决办法，而离第5爻处在“担当”阶段”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录离六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"当前循环接近上限，“明辨与依附”需要从继续加力转向收束复盘 当前拉扯在于：真正的拉扯来自追求明白与依赖外部认可之间会拉扯，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“把证据、解释和感受分开记录”；若出现“只选择能证明原有判断的信息会在此时放大”，就暂停扩大动作。","classic":"王用出征，有嘉折首，獲匪其醜，无咎。","source":"《周易》爻辞","modern":{"image":"“王用出征，有嘉折首，獲匪其醜，无咎。”是离在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“明辨与依附”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自追求明白与依赖外部认可之间会拉扯，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"只选择能证明原有判断的信息会在此时放大。","advice":["把证据、解释和感受分开记录。","列出应当停止、保留和移交的事项。"],"signal":{"label":"守正","meaning":"在离第6爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“哪些是事实，哪些只是你对事实的解释”核对判断"},"tone":"收束","extended":{"trigger":{"label":"守正","observe":"完成“把证据、解释和感受分开记录”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“把证据、解释和感受分开记录”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把证据、解释和感受分开记录”，可以保持小步推进。","pause_if":"若出现“只选择能证明原有判断的信息会在此时放大”，先暂停扩大投入。"},"action":{"do":"把证据、解释和感受分开记录","review":"完成后记录离上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"清晰来自事实照见，也来自可靠关系的支撑","strengths":["有辨别信息和表达重点的能力","让事实照亮选择，也为自己寻找可靠的连接与支持"],"tensions":["追求明白与依赖外部认可之间会拉扯"],"risks":["只选择能证明原有判断的信息"],"actions":["把证据、解释和感受分开记录"],"avoid":["让强烈观点遮住相反证据"],"questions":["哪些是事实，哪些只是你对事实的解释？"],"extended":{"situation":{"direct":"眼下的重点是清晰来自事实照见，也来自可靠关系的支撑。","support":"已经可以利用的是：有辨别信息和表达重点的能力。","constraint":"仍需核实的是：追求明白与依赖外部认可之间会拉扯。"},"relationship":{"inner":"下卦离，内部动力偏向辨识、表达与显明。","outer":"上卦离，外部处境更受辨识、表达与显明影响。","interaction":"内部想以“辨识、表达与显明”回应外部的“辨识、表达与显明”；两边能否对接，要看“追求明白与依赖外部认可之间会拉扯”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“有辨别信息和表达重点的能力”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“把证据、解释和感受分开记录”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“让强烈观点遮住相反证据”，风险会被放大。","effect":"最需要防止的是：只选择能证明原有判断的信息。"},"paths":{"ready":"如果关键条件得到确认，可以继续“把证据、解释和感受分开记录”，但仍以小步反馈决定是否扩大。","not_ready":"如果“追求明白与依赖外部认可之间会拉扯”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"把证据、解释和感受分开记录","observe":"哪些是事实，哪些只是你对事实的解释？","continue_if":"出现与“有辨别信息和表达重点的能力”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“让强烈观点遮住相反证据”或“只选择能证明原有判断的信息”的迹象。"}}}},{"id":31,"name":"咸","pinyin":"xián","theme":"感应与互动","reflection":"关系里的回应值得被尊重。真诚表达感受，也听见对方的节奏。","source_note":"据《周易》咸卦意象整理","upper_trigram":2,"lower_trigram":7,"lines":{"1":{"title":"初六","interpretation":"局面正在显出边界：事情刚在“感应与互动”的起点露出端倪，可用条件还不多 此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是敏感回应与投射期待容易混在一起，两者要放在同一次权衡里 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若替对方解释没有说出口的想法，行动应当收束。","classic":"咸其拇。","source":"《周易》爻辞","modern":{"image":"“咸其拇。”是咸在“潜藏”阶段留下的具体图景。","situation":"事情刚在“感应与互动”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是敏感回应与投射期待容易混在一起，两者要放在同一次权衡里。","warning":"替对方解释没有说出口的想法。","advice":["用一次直接提问替代猜测。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"观察","meaning":"在咸第1爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪些回应是对方明确表达的，哪些是你的推测”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"观察","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“替对方解释没有说出口的想法”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录咸初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"咸来到二位，个人判断正与资源、规则或他人发生接触 当前拉扯在于：若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大敏感回应与投射期待容易混在一起 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“用一次直接提问替代猜测”；若出现“替对方解释没有说出口的想法，而不是把把短暂情绪当成稳定承诺当成解决办法，而咸第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，就暂停扩大动作。","classic":"咸其腓，凶，居吉。","source":"《周易》爻辞","modern":{"image":"“咸其腓，凶，居吉。”是咸在“接触”阶段留下的具体图景。","situation":"咸来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大敏感回应与投射期待容易混在一起。","warning":"替对方解释没有说出口的想法，而不是把把短暂情绪当成稳定承诺当成解决办法，而咸第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","advice":["用一次直接提问替代猜测。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"止损","meaning":"在咸第2爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪些回应是对方明确表达的，哪些是你的推测”核对判断"},"tone":"接触","extended":{"trigger":{"label":"止损","observe":"完成“用一次直接提问替代猜测”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“用一次直接提问替代猜测”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“用一次直接提问替代猜测”，可以保持小步推进。","pause_if":"若出现“替对方解释没有说出口的想法，而不是把把短暂情绪当成稳定承诺当成解决办法，而咸第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，先暂停扩大投入。"},"action":{"do":"用一次直接提问替代猜测","review":"完成后记录咸六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻把变化落在具体环节：这一爻处在容易用力过度的位置，调整比加码更重要 原有做法显出明确代价，需要及时调整，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意替对方解释没有说出口的想法会在此时放大。","classic":"咸其股，執其隨，往吝。","source":"《周易》爻辞","modern":{"image":"“咸其股，執其隨，往吝。”是咸在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是敏感回应与投射期待容易混在一起，两者要放在同一次权衡里。","warning":"替对方解释没有说出口的想法会在此时放大。","advice":["用一次直接提问替代猜测。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"修正","meaning":"在咸第3爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“哪些回应是对方明确表达的，哪些是你的推测”核对判断"},"tone":"转折","extended":{"trigger":{"label":"修正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“替对方解释没有说出口的想法会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录咸九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：局面已经接近新的层级，旧角色未必还能容纳当前变化 若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大敏感回应与投射期待容易混在一起 可以用“用一次直接提问替代猜测”做一次验证；若替对方解释没有说出口的想法，行动应当收束。","classic":"貞吉，悔亡，憧憧往來，朋從爾思。","source":"《周易》爻辞","modern":{"image":"“貞吉，悔亡，憧憧往來，朋從爾思。”是咸在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大敏感回应与投射期待容易混在一起。","warning":"替对方解释没有说出口的想法。","advice":["用一次直接提问替代猜测。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在咸第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪些回应是对方明确表达的，哪些是你的推测”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“用一次直接提问替代猜测”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“用一次直接提问替代猜测”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“用一次直接提问替代猜测”，可以保持小步推进。","pause_if":"若出现“替对方解释没有说出口的想法”，先暂停扩大投入。"},"action":{"do":"用一次直接提问替代猜测","review":"完成后记录咸九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"关键资源与决定权趋向集中，“感应与互动”开始影响更多人 当前拉扯在于：此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是敏感回应与投射期待容易混在一起，两者要放在同一次权衡里 当原有做法显出明确代价，需要及时调整时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“替对方解释没有说出口的想法”，就暂停扩大动作。","classic":"咸其脢，无悔。","source":"《周易》爻辞","modern":{"image":"“咸其脢，无悔。”是咸在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“感应与互动”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是敏感回应与投射期待容易混在一起，两者要放在同一次权衡里。","warning":"替对方解释没有说出口的想法。","advice":["用一次直接提问替代猜测。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"修正","meaning":"在咸第5爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“哪些回应是对方明确表达的，哪些是你的推测”核对判断"},"tone":"担当","extended":{"trigger":{"label":"修正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“替对方解释没有说出口的想法”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录咸九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻把变化落在具体环节：咸来到上位，已有路径可能完成使命，也可能因过度而失衡 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“用一次直接提问替代猜测”后再看反馈；同时留意替对方解释没有说出口的想法，而不是把把短暂情绪当成稳定承诺当成解决办法，而咸第6爻处在“收束”阶段。","classic":"咸其輔頰舌。","source":"《周易》爻辞","modern":{"image":"“咸其輔頰舌。”是咸在“收束”阶段留下的具体图景。","situation":"咸来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大敏感回应与投射期待容易混在一起。","warning":"替对方解释没有说出口的想法，而不是把把短暂情绪当成稳定承诺当成解决办法，而咸第6爻处在“收束”阶段。","advice":["用一次直接提问替代猜测。","列出应当停止、保留和移交的事项。"],"signal":{"label":"观察","meaning":"在咸第6爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪些回应是对方明确表达的，哪些是你的推测”核对判断"},"tone":"收束","extended":{"trigger":{"label":"观察","observe":"完成“用一次直接提问替代猜测”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“用一次直接提问替代猜测”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“用一次直接提问替代猜测”，可以保持小步推进。","pause_if":"若出现“替对方解释没有说出口的想法，而不是把把短暂情绪当成稳定承诺当成解决办法，而咸第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"用一次直接提问替代猜测","review":"完成后记录咸上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"互动中的真实回应需要被感受，也需要被核实","strengths":["关系里存在相互影响和靠近的可能","关系里的回应值得被尊重。真诚表达感受，也听见对方的节奏"],"tensions":["敏感回应与投射期待容易混在一起"],"risks":["替对方解释没有说出口的想法"],"actions":["用一次直接提问替代猜测"],"avoid":["把短暂情绪当成稳定承诺"],"questions":["哪些回应是对方明确表达的，哪些是你的推测？"],"extended":{"situation":{"direct":"眼下的重点是互动中的真实回应需要被感受，也需要被核实。","support":"已经可以利用的是：关系里存在相互影响和靠近的可能。","constraint":"仍需核实的是：敏感回应与投射期待容易混在一起。"},"relationship":{"inner":"下卦艮，内部动力偏向边界、停止与重新定位。","outer":"上卦兑，外部处境更受交流、回应与协商影响。","interaction":"内部想以“边界、停止与重新定位”回应外部的“交流、回应与协商”；两边能否对接，要看“敏感回应与投射期待容易混在一起”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“关系里存在相互影响和靠近的可能”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“用一次直接提问替代猜测”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把短暂情绪当成稳定承诺”，风险会被放大。","effect":"最需要防止的是：替对方解释没有说出口的想法。"},"paths":{"ready":"如果关键条件得到确认，可以继续“用一次直接提问替代猜测”，但仍以小步反馈决定是否扩大。","not_ready":"如果“敏感回应与投射期待容易混在一起”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"用一次直接提问替代猜测","observe":"哪些回应是对方明确表达的，哪些是你的推测？","continue_if":"出现与“关系里存在相互影响和靠近的可能”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把短暂情绪当成稳定承诺”或“替对方解释没有说出口的想法”的迹象。"}}}},{"id":32,"name":"恒","pinyin":"héng","theme":"持久与守常","reflection":"重要的事靠长期重复。设一个你做得到的节奏，而非追求一时完美。","source_note":"据《周易》恒卦意象整理","upper_trigram":4,"lower_trigram":5,"lines":{"1":{"title":"初六","interpretation":"恒落在初位，眼下更像在辨认方向，而不是兑现结果 当前拉扯在于：真正的拉扯来自稳定方法与环境变化之间需要调整，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“把坚持变成拒绝修正”，就暂停扩大动作。","classic":"浚恒，貞凶，无攸利。","source":"《周易》爻辞","modern":{"image":"“浚恒，貞凶，无攸利。”是恒在“潜藏”阶段留下的具体图景。","situation":"恒落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自稳定方法与环境变化之间需要调整，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"把坚持变成拒绝修正。","advice":["设一个低谷时也能完成的最低标准。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"止损","meaning":"在恒第1爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“什么节奏能让你坚持，同时仍能根据反馈改变”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"止损","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把坚持变成拒绝修正”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录恒初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一爻把变化落在具体环节：这一阶段不再只靠设想，回应和基本功开始决定走向 原有做法显出明确代价，需要及时调整，是接下来值得核对的信号。完成“设一个低谷时也能完成的最低标准”后再看反馈；同时留意把坚持变成拒绝修正。","classic":"悔亡。","source":"《周易》爻辞","modern":{"image":"“悔亡。”是恒在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而稳定方法与环境变化之间需要调整也会在这一爻变得具体。","warning":"把坚持变成拒绝修正。","advice":["设一个低谷时也能完成的最低标准。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"修正","meaning":"在恒第2爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“什么节奏能让你坚持，同时仍能根据反馈改变”核对判断"},"tone":"接触","extended":{"trigger":{"label":"修正","observe":"完成“设一个低谷时也能完成的最低标准”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“设一个低谷时也能完成的最低标准”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“设一个低谷时也能完成的最低标准”，可以保持小步推进。","pause_if":"若出现“把坚持变成拒绝修正”，先暂停扩大投入。"},"action":{"do":"设一个低谷时也能完成的最低标准","review":"完成后记录恒九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面正在显出边界：事情跨入转折带，焦虑可能比事实更快推动决定 真正的拉扯来自稳定方法与环境变化之间需要调整，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若把坚持变成拒绝修正，而不是把为了连续而重复无效方法当成解决办法，而恒第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码，行动应当收束。","classic":"不恒其德，或承之羞，貞吝。","source":"《周易》爻辞","modern":{"image":"“不恒其德，或承之羞，貞吝。”是恒在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自稳定方法与环境变化之间需要调整，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"把坚持变成拒绝修正，而不是把为了连续而重复无效方法当成解决办法，而恒第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","advice":["设一个低谷时也能完成的最低标准。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"修正","meaning":"在恒第3爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“什么节奏能让你坚持，同时仍能根据反馈改变”核对判断"},"tone":"转折","extended":{"trigger":{"label":"修正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把坚持变成拒绝修正，而不是把为了连续而重复无效方法当成解决办法，而恒第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录恒九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"事情正由内部走向外部，“持久与守常”需要重新确认位置和权限 当前拉扯在于：向外推进的需要与边界尚未说清之间互相牵制，而稳定方法与环境变化之间需要调整也会在这一爻变得具体 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“设一个低谷时也能完成的最低标准”；若出现“把坚持变成拒绝修正会在此时放大”，就暂停扩大动作。","classic":"田无禽。","source":"《周易》爻辞","modern":{"image":"“田无禽。”是恒在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“持久与守常”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而稳定方法与环境变化之间需要调整也会在这一爻变得具体。","warning":"把坚持变成拒绝修正会在此时放大。","advice":["设一个低谷时也能完成的最低标准。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在恒第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么节奏能让你坚持，同时仍能根据反馈改变”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“设一个低谷时也能完成的最低标准”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“设一个低谷时也能完成的最低标准”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“设一个低谷时也能完成的最低标准”，可以保持小步推进。","pause_if":"若出现“把坚持变成拒绝修正会在此时放大”，先暂停扩大投入。"},"action":{"do":"设一个低谷时也能完成的最低标准","review":"完成后记录恒九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"这一爻把变化落在具体环节：恒来到五位，能力之外还要衡量整体承接和长期后果 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意把坚持变成拒绝修正。","classic":"恒其德貞，婦人吉，夫子凶。","source":"《周易》爻辞","modern":{"image":"“恒其德貞，婦人吉，夫子凶。”是恒在“担当”阶段留下的具体图景。","situation":"恒来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自稳定方法与环境变化之间需要调整，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"把坚持变成拒绝修正。","advice":["设一个低谷时也能完成的最低标准。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"止损","meaning":"在恒第5爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“什么节奏能让你坚持，同时仍能根据反馈改变”核对判断"},"tone":"担当","extended":{"trigger":{"label":"止损","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把坚持变成拒绝修正”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录恒六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"局面正在显出边界：这一爻处在阶段末端，下一步先要判断什么已经结束 维持既有成果与允许阶段结束之间存在拉扯，而稳定方法与环境变化之间需要调整也会在这一爻变得具体 可以用“设一个低谷时也能完成的最低标准”做一次验证；若把坚持变成拒绝修正，行动应当收束。","classic":"振恒，凶。","source":"《周易》爻辞","modern":{"image":"“振恒，凶。”是恒在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而稳定方法与环境变化之间需要调整也会在这一爻变得具体。","warning":"把坚持变成拒绝修正。","advice":["设一个低谷时也能完成的最低标准。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在恒第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“什么节奏能让你坚持，同时仍能根据反馈改变”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“设一个低谷时也能完成的最低标准”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“设一个低谷时也能完成的最低标准”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“设一个低谷时也能完成的最低标准”，可以保持小步推进。","pause_if":"若出现“把坚持变成拒绝修正”，先暂停扩大投入。"},"action":{"do":"设一个低谷时也能完成的最低标准","review":"完成后记录恒上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"持久来自可重复的节奏，不来自一次用尽全力","strengths":["已有长期投入和保持承诺的能力","重要的事靠长期重复。设一个你做得到的节奏，而非追求一时完美"],"tensions":["稳定方法与环境变化之间需要调整"],"risks":["把坚持变成拒绝修正"],"actions":["设一个低谷时也能完成的最低标准"],"avoid":["为了连续而重复无效方法"],"questions":["什么节奏能让你坚持，同时仍能根据反馈改变？"],"extended":{"situation":{"direct":"眼下的重点是持久来自可重复的节奏，不来自一次用尽全力。","support":"已经可以利用的是：已有长期投入和保持承诺的能力。","constraint":"仍需核实的是：稳定方法与环境变化之间需要调整。"},"relationship":{"inner":"下卦巽，内部动力偏向渗透、调整与持续影响。","outer":"上卦震，外部处境更受启动、震动与迅速反应影响。","interaction":"内部想以“渗透、调整与持续影响”回应外部的“启动、震动与迅速反应”；两边能否对接，要看“稳定方法与环境变化之间需要调整”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“已有长期投入和保持承诺的能力”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“设一个低谷时也能完成的最低标准”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“为了连续而重复无效方法”，风险会被放大。","effect":"最需要防止的是：把坚持变成拒绝修正。"},"paths":{"ready":"如果关键条件得到确认，可以继续“设一个低谷时也能完成的最低标准”，但仍以小步反馈决定是否扩大。","not_ready":"如果“稳定方法与环境变化之间需要调整”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"设一个低谷时也能完成的最低标准","observe":"什么节奏能让你坚持，同时仍能根据反馈改变？","continue_if":"出现与“已有长期投入和保持承诺的能力”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“为了连续而重复无效方法”或“把坚持变成拒绝修正”的迹象。"}}}},{"id":33,"name":"遁","pinyin":"dùn","theme":"退避与保存","reflection":"及时后退是一种智慧。远离无谓的拉扯，把力量留给真正重要的事。","source_note":"据《周易》遁卦意象整理","upper_trigram":1,"lower_trigram":7,"lines":{"1":{"title":"初六","interpretation":"这一爻把变化落在具体环节：这一爻处在起步处，“及时后退能保存判断和力量，为以后留下空间”仍需低成本试探 现实条件尚不足以支持扩大动作，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意一遇压力就切断所有联系会在此时放大。","classic":"遯尾，厲。勿用有攸往。","source":"《周易》爻辞","modern":{"image":"“遯尾，厲。勿用有攸往。”是遁在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“及时后退能保存判断和力量，为以后留下空间”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大退出局面与逃避必要责任容易混淆。","warning":"一遇压力就切断所有联系会在此时放大。","advice":["说明后退的范围、期限和保留事项。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"暂停","meaning":"在遁第1爻里，爻辞给出明确的收势信号，眼下不宜把意愿直接变成大动作，可用“你要退出的是消耗，还是也退出了应承担的部分”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"暂停","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实条件尚不足以支持扩大动作”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“一遇压力就切断所有联系会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录遁初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：局面正从内部准备转向真实互动，关系与条件逐渐可见 此时一面是自己的节奏需要与现实反馈相互校准，另一面是退出局面与逃避必要责任容易混淆，两者要放在同一次权衡里 可以用“说明后退的范围、期限和保留事项”做一次验证；若一遇压力就切断所有联系，行动应当收束。","classic":"執之用黃牛之革，莫之勝說。","source":"《周易》爻辞","modern":{"image":"“執之用黃牛之革，莫之勝說。”是遁在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是退出局面与逃避必要责任容易混淆，两者要放在同一次权衡里。","warning":"一遇压力就切断所有联系。","advice":["说明后退的范围、期限和保留事项。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在遁第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“你要退出的是消耗，还是也退出了应承担的部分”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“说明后退的范围、期限和保留事项”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“说明后退的范围、期限和保留事项”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“说明后退的范围、期限和保留事项”，可以保持小步推进。","pause_if":"若出现“一遇压力就切断所有联系”，先暂停扩大投入。"},"action":{"do":"说明后退的范围、期限和保留事项","review":"完成后记录遁六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面来到内外转换处，“退避与保存”开始承受压力测试 当前拉扯在于：若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大退出局面与逃避必要责任容易混淆 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“一遇压力就切断所有联系”，就暂停扩大动作。","classic":"係遯，有疾厲，畜臣妾吉。","source":"《周易》爻辞","modern":{"image":"“係遯，有疾厲，畜臣妾吉。”是遁在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“退避与保存”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大退出局面与逃避必要责任容易混淆。","warning":"一遇压力就切断所有联系。","advice":["说明后退的范围、期限和保留事项。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"可行","meaning":"在遁第3爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你要退出的是消耗，还是也退出了应承担的部分”核对判断"},"tone":"转折","extended":{"trigger":{"label":"可行","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“一遇压力就切断所有联系”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录遁九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"这一爻把变化落在具体环节：遁来到四位，跨出原有边界之前要先说明责任 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“说明后退的范围、期限和保留事项”后再看反馈；同时留意一遇压力就切断所有联系，而不是把用消失代替清楚告别当成解决办法，而遁第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位。","classic":"好遯，君子吉，小人否。","source":"《周易》爻辞","modern":{"image":"“好遯，君子吉，小人否。”是遁在“越界”阶段留下的具体图景。","situation":"遁来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是退出局面与逃避必要责任容易混淆，两者要放在同一次权衡里。","warning":"一遇压力就切断所有联系，而不是把用消失代替清楚告别当成解决办法，而遁第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位。","advice":["说明后退的范围、期限和保留事项。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在遁第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你要退出的是消耗，还是也退出了应承担的部分”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“说明后退的范围、期限和保留事项”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“说明后退的范围、期限和保留事项”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“说明后退的范围、期限和保留事项”，可以保持小步推进。","pause_if":"若出现“一遇压力就切断所有联系，而不是把用消失代替清楚告别当成解决办法，而遁第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位”，先暂停扩大投入。"},"action":{"do":"说明后退的范围、期限和保留事项","review":"完成后记录遁九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面正在显出边界：这一阶段已进入主位，选择会放大为规则或示范 若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大退出局面与逃避必要责任容易混淆 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若一遇压力就切断所有联系会在此时放大，行动应当收束。","classic":"嘉遯，貞吉。","source":"《周易》爻辞","modern":{"image":"“嘉遯，貞吉。”是遁在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大退出局面与逃避必要责任容易混淆。","warning":"一遇压力就切断所有联系会在此时放大。","advice":["说明后退的范围、期限和保留事项。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在遁第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你要退出的是消耗，还是也退出了应承担的部分”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“一遇压力就切断所有联系会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录遁九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面走到极处，继续延长旧办法未必带来同等收益 当前拉扯在于：此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是退出局面与逃避必要责任容易混淆，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“说明后退的范围、期限和保留事项”；若出现“一遇压力就切断所有联系”，就暂停扩大动作。","classic":"肥遯，无不利。","source":"《周易》爻辞","modern":{"image":"“肥遯，无不利。”是遁在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是退出局面与逃避必要责任容易混淆，两者要放在同一次权衡里。","warning":"一遇压力就切断所有联系。","advice":["说明后退的范围、期限和保留事项。","列出应当停止、保留和移交的事项。"],"signal":{"label":"通达","meaning":"在遁第6爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“你要退出的是消耗，还是也退出了应承担的部分”核对判断"},"tone":"收束","extended":{"trigger":{"label":"通达","observe":"完成“说明后退的范围、期限和保留事项”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“说明后退的范围、期限和保留事项”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“说明后退的范围、期限和保留事项”，可以保持小步推进。","pause_if":"若出现“一遇压力就切断所有联系”，先暂停扩大投入。"},"action":{"do":"说明后退的范围、期限和保留事项","review":"完成后记录遁上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"及时后退能保存判断和力量，为以后留下空间","strengths":["能够识别无谓消耗并拉开距离","及时后退是一种智慧。远离无谓的拉扯，把力量留给真正重要的事"],"tensions":["退出局面与逃避必要责任容易混淆"],"risks":["一遇压力就切断所有联系"],"actions":["说明后退的范围、期限和保留事项"],"avoid":["用消失代替清楚告别"],"questions":["你要退出的是消耗，还是也退出了应承担的部分？"],"extended":{"situation":{"direct":"眼下的重点是及时后退能保存判断和力量，为以后留下空间。","support":"已经可以利用的是：能够识别无谓消耗并拉开距离。","constraint":"仍需核实的是：退出局面与逃避必要责任容易混淆。"},"relationship":{"inner":"下卦艮，内部动力偏向边界、停止与重新定位。","outer":"上卦乾，外部处境更受主动、原则与承担影响。","interaction":"内部想以“边界、停止与重新定位”回应外部的“主动、原则与承担”；两边能否对接，要看“退出局面与逃避必要责任容易混淆”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“能够识别无谓消耗并拉开距离”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“说明后退的范围、期限和保留事项”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用消失代替清楚告别”，风险会被放大。","effect":"最需要防止的是：一遇压力就切断所有联系。"},"paths":{"ready":"如果关键条件得到确认，可以继续“说明后退的范围、期限和保留事项”，但仍以小步反馈决定是否扩大。","not_ready":"如果“退出局面与逃避必要责任容易混淆”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"说明后退的范围、期限和保留事项","observe":"你要退出的是消耗，还是也退出了应承担的部分？","continue_if":"出现与“能够识别无谓消耗并拉开距离”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用消失代替清楚告别”或“一遇压力就切断所有联系”的迹象。"}}}},{"id":34,"name":"大壮","pinyin":"dà zhuàng","theme":"力量与节制","reflection":"力量上升时，更要问自己：此刻的强势是否合乎分寸与责任？","source_note":"据《周易》大壮卦意象整理","upper_trigram":4,"lower_trigram":1,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：变化尚在根部，先分清已经发生的事实和仍在期待的部分 内在意愿已经出现，外部条件尚未完全成形，而能做什么与该做什么并不相同也会在这一爻变得具体 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若把优势当成越过边界的许可，而不是把用胜负证明力量当成解决办法，而大壮第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论，行动应当收束。","classic":"壯于趾，征凶，有孚。","source":"《周易》爻辞","modern":{"image":"“壯于趾，征凶，有孚。”是大壮在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而能做什么与该做什么并不相同也会在这一爻变得具体。","warning":"把优势当成越过边界的许可，而不是把用胜负证明力量当成解决办法，而大壮第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["在行动前请受影响的人指出一个风险。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"止损","meaning":"在大壮第1爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“如果力量必须接受约束，最合理的约束是什么”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"止损","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把优势当成越过边界的许可，而不是把用胜负证明力量当成解决办法，而大壮第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录大壮初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"事情开始进入现实协作，“力量与节制”要接受反馈检验 当前拉扯在于：真正的拉扯来自能做什么与该做什么并不相同，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“在行动前请受影响的人指出一个风险”；若出现“把优势当成越过边界的许可会在此时放大”，就暂停扩大动作。","classic":"貞吉。","source":"《周易》爻辞","modern":{"image":"“貞吉。”是大壮在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“力量与节制”要接受反馈检验。","tension":"真正的拉扯来自能做什么与该做什么并不相同，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"把优势当成越过边界的许可会在此时放大。","advice":["在行动前请受影响的人指出一个风险。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在大壮第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“如果力量必须接受约束，最合理的约束是什么”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“在行动前请受影响的人指出一个风险”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“在行动前请受影响的人指出一个风险”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“在行动前请受影响的人指出一个风险”，可以保持小步推进。","pause_if":"若出现“把优势当成越过边界的许可会在此时放大”，先暂停扩大投入。"},"action":{"do":"在行动前请受影响的人指出一个风险","review":"完成后记录大壮九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻把变化落在具体环节：大壮行至三位，旧方法的边界和新选择的代价同时出现 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意把优势当成越过边界的许可。","classic":"小人用壯，君子用罔。貞厲，羝羊觸藩，羸其角。","source":"《周易》爻辞","modern":{"image":"“小人用壯，君子用罔。貞厲，羝羊觸藩，羸其角。”是大壮在“转折”阶段留下的具体图景。","situation":"大壮行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而能做什么与该做什么并不相同也会在这一爻变得具体。","warning":"把优势当成越过边界的许可。","advice":["在行动前请受影响的人指出一个风险。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在大壮第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“如果力量必须接受约束，最合理的约束是什么”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把优势当成越过边界的许可”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录大壮九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 真正的拉扯来自能做什么与该做什么并不相同，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题 可以用“在行动前请受影响的人指出一个风险”做一次验证；若把优势当成越过边界的许可，行动应当收束。","classic":"貞吉，悔亡，藩決不羸，壯于大輿之輹。","source":"《周易》爻辞","modern":{"image":"“貞吉，悔亡，藩決不羸，壯于大輿之輹。”是大壮在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自能做什么与该做什么并不相同，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"把优势当成越过边界的许可。","advice":["在行动前请受影响的人指出一个风险。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在大壮第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“如果力量必须接受约束，最合理的约束是什么”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“在行动前请受影响的人指出一个风险”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“在行动前请受影响的人指出一个风险”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“在行动前请受影响的人指出一个风险”，可以保持小步推进。","pause_if":"若出现“把优势当成越过边界的许可”，先暂停扩大投入。"},"action":{"do":"在行动前请受影响的人指出一个风险","review":"完成后记录大壮九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"局面要求从个人得失转向整体结果和持续责任 当前拉扯在于：扩大影响与照顾整体承接能力之间需要平衡，而能做什么与该做什么并不相同也会在这一爻变得具体 当原有做法显出明确代价，需要及时调整时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“把优势当成越过边界的许可，而不是把用胜负证明力量当成解决办法，而大壮第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，就暂停扩大动作。","classic":"喪羊于易，无悔。","source":"《周易》爻辞","modern":{"image":"“喪羊于易，无悔。”是大壮在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而能做什么与该做什么并不相同也会在这一爻变得具体。","warning":"把优势当成越过边界的许可，而不是把用胜负证明力量当成解决办法，而大壮第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["在行动前请受影响的人指出一个风险。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"修正","meaning":"在大壮第5爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“如果力量必须接受约束，最合理的约束是什么”核对判断"},"tone":"担当","extended":{"trigger":{"label":"修正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把优势当成越过边界的许可，而不是把用胜负证明力量当成解决办法，而大壮第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录大壮六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻把变化落在具体环节：当前循环接近上限，“力量与节制”需要从继续加力转向收束复盘 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“在行动前请受影响的人指出一个风险”后再看反馈；同时留意把优势当成越过边界的许可会在此时放大。","classic":"羝羊觸藩，不能退，不能遂，无攸利，艱則吉。","source":"《周易》爻辞","modern":{"image":"“羝羊觸藩，不能退，不能遂，无攸利，艱則吉。”是大壮在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“力量与节制”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自能做什么与该做什么并不相同，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"把优势当成越过边界的许可会在此时放大。","advice":["在行动前请受影响的人指出一个风险。","列出应当停止、保留和移交的事项。"],"signal":{"label":"可行","meaning":"在大壮第6爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“如果力量必须接受约束，最合理的约束是什么”核对判断"},"tone":"收束","extended":{"trigger":{"label":"可行","observe":"完成“在行动前请受影响的人指出一个风险”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“在行动前请受影响的人指出一个风险”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“在行动前请受影响的人指出一个风险”，可以保持小步推进。","pause_if":"若出现“把优势当成越过边界的许可会在此时放大”，先暂停扩大投入。"},"action":{"do":"在行动前请受影响的人指出一个风险","review":"完成后记录大壮上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"力量增长时，分寸和责任决定它会建设还是破坏","strengths":["拥有明显的行动能力或影响力","力量上升时，更要问自己：此刻的强势是否合乎分寸与责任？"],"tensions":["能做什么与该做什么并不相同"],"risks":["把优势当成越过边界的许可"],"actions":["在行动前请受影响的人指出一个风险"],"avoid":["用胜负证明力量"],"questions":["如果力量必须接受约束，最合理的约束是什么？"],"extended":{"situation":{"direct":"眼下的重点是力量增长时，分寸和责任决定它会建设还是破坏。","support":"已经可以利用的是：拥有明显的行动能力或影响力。","constraint":"仍需核实的是：能做什么与该做什么并不相同。"},"relationship":{"inner":"下卦乾，内部动力偏向主动、原则与承担。","outer":"上卦震，外部处境更受启动、震动与迅速反应影响。","interaction":"内部想以“主动、原则与承担”回应外部的“启动、震动与迅速反应”；两边能否对接，要看“能做什么与该做什么并不相同”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“拥有明显的行动能力或影响力”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“在行动前请受影响的人指出一个风险”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用胜负证明力量”，风险会被放大。","effect":"最需要防止的是：把优势当成越过边界的许可。"},"paths":{"ready":"如果关键条件得到确认，可以继续“在行动前请受影响的人指出一个风险”，但仍以小步反馈决定是否扩大。","not_ready":"如果“能做什么与该做什么并不相同”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"在行动前请受影响的人指出一个风险","observe":"如果力量必须接受约束，最合理的约束是什么？","continue_if":"出现与“拥有明显的行动能力或影响力”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用胜负证明力量”或“把优势当成越过边界的许可”的迹象。"}}}},{"id":35,"name":"晋","pinyin":"jìn","theme":"进展与显现","reflection":"努力被看见时，保持开放和稳健。让成果说话，而非急于证明。","source_note":"据《周易》晋卦意象整理","upper_trigram":3,"lower_trigram":8,"lines":{"1":{"title":"初六","interpretation":"事情刚在“进展与显现”的起点露出端倪，可用条件还不多 当前拉扯在于：此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是扩大影响与保持基础稳固之间需要平衡，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“急于证明导致承诺超过能力”，就暂停扩大动作。","classic":"晉如摧如，貞吉。罔孚裕，无咎。","source":"《周易》爻辞","modern":{"image":"“晉如摧如，貞吉。罔孚裕，无咎。”是晋在“潜藏”阶段留下的具体图景。","situation":"事情刚在“进展与显现”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是扩大影响与保持基础稳固之间需要平衡，两者要放在同一次权衡里。","warning":"急于证明导致承诺超过能力。","advice":["把当前成果整理成可复用的方法。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在晋第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“这次进展靠什么产生，能否被稳定复制”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“急于证明导致承诺超过能力”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录晋初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"这一爻把变化落在具体环节：晋来到二位，个人判断正与资源、规则或他人发生接触 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“把当前成果整理成可复用的方法”后再看反馈；同时留意急于证明导致承诺超过能力，而不是把只追逐可见度而忽略质量当成解决办法，而晋第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","classic":"晉如愁如，貞吉。受茲介福，于其王母。","source":"《周易》爻辞","modern":{"image":"“晉如愁如，貞吉。受茲介福，于其王母。”是晋在“接触”阶段留下的具体图景。","situation":"晋来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大扩大影响与保持基础稳固之间需要平衡。","warning":"急于证明导致承诺超过能力，而不是把只追逐可见度而忽略质量当成解决办法，而晋第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","advice":["把当前成果整理成可复用的方法。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在晋第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“这次进展靠什么产生，能否被稳定复制”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“把当前成果整理成可复用的方法”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把当前成果整理成可复用的方法”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把当前成果整理成可复用的方法”，可以保持小步推进。","pause_if":"若出现“急于证明导致承诺超过能力，而不是把只追逐可见度而忽略质量当成解决办法，而晋第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，先暂停扩大投入。"},"action":{"do":"把当前成果整理成可复用的方法","review":"完成后记录晋六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面正在显出边界：这一爻处在容易用力过度的位置，调整比加码更重要 此时一面是继续原路与承认需要调整之间发生冲突，另一面是扩大影响与保持基础稳固之间需要平衡，两者要放在同一次权衡里 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若急于证明导致承诺超过能力会在此时放大，行动应当收束。","classic":"眾允，悔亡。","source":"《周易》爻辞","modern":{"image":"“眾允，悔亡。”是晋在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是扩大影响与保持基础稳固之间需要平衡，两者要放在同一次权衡里。","warning":"急于证明导致承诺超过能力会在此时放大。","advice":["把当前成果整理成可复用的方法。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"修正","meaning":"在晋第3爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“这次进展靠什么产生，能否被稳定复制”核对判断"},"tone":"转折","extended":{"trigger":{"label":"修正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“急于证明导致承诺超过能力会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录晋六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面已经接近新的层级，旧角色未必还能容纳当前变化 当前拉扯在于：若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大扩大影响与保持基础稳固之间需要平衡 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“把当前成果整理成可复用的方法”；若出现“急于证明导致承诺超过能力”，就暂停扩大动作。","classic":"晉如鼫鼠，貞厲。","source":"《周易》爻辞","modern":{"image":"“晉如鼫鼠，貞厲。”是晋在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大扩大影响与保持基础稳固之间需要平衡。","warning":"急于证明导致承诺超过能力。","advice":["把当前成果整理成可复用的方法。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在晋第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“这次进展靠什么产生，能否被稳定复制”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“把当前成果整理成可复用的方法”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把当前成果整理成可复用的方法”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把当前成果整理成可复用的方法”，可以保持小步推进。","pause_if":"若出现“急于证明导致承诺超过能力”，先暂停扩大投入。"},"action":{"do":"把当前成果整理成可复用的方法","review":"完成后记录晋九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"这一爻把变化落在具体环节：关键资源与决定权趋向集中，“进展与显现”开始影响更多人 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意急于证明导致承诺超过能力。","classic":"悔亡，失得勿恤。往吉无不利。","source":"《周易》爻辞","modern":{"image":"“悔亡，失得勿恤。往吉无不利。”是晋在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“进展与显现”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是扩大影响与保持基础稳固之间需要平衡，两者要放在同一次权衡里。","warning":"急于证明导致承诺超过能力。","advice":["把当前成果整理成可复用的方法。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"通达","meaning":"在晋第5爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“这次进展靠什么产生，能否被稳定复制”核对判断"},"tone":"担当","extended":{"trigger":{"label":"通达","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“急于证明导致承诺超过能力”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录晋六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面正在显出边界：晋来到上位，已有路径可能完成使命，也可能因过度而失衡 若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大扩大影响与保持基础稳固之间需要平衡 可以用“把当前成果整理成可复用的方法”做一次验证；若急于证明导致承诺超过能力，而不是把只追逐可见度而忽略质量当成解决办法，而晋第6爻处在“收束”阶段，行动应当收束。","classic":"晉其角，維用伐邑。厲吉无咎，貞吝。","source":"《周易》爻辞","modern":{"image":"“晉其角，維用伐邑。厲吉无咎，貞吝。”是晋在“收束”阶段留下的具体图景。","situation":"晋来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大扩大影响与保持基础稳固之间需要平衡。","warning":"急于证明导致承诺超过能力，而不是把只追逐可见度而忽略质量当成解决办法，而晋第6爻处在“收束”阶段。","advice":["把当前成果整理成可复用的方法。","列出应当停止、保留和移交的事项。"],"signal":{"label":"可行","meaning":"在晋第6爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“这次进展靠什么产生，能否被稳定复制”核对判断"},"tone":"收束","extended":{"trigger":{"label":"可行","observe":"完成“把当前成果整理成可复用的方法”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把当前成果整理成可复用的方法”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把当前成果整理成可复用的方法”，可以保持小步推进。","pause_if":"若出现“急于证明导致承诺超过能力，而不是把只追逐可见度而忽略质量当成解决办法，而晋第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"把当前成果整理成可复用的方法","review":"完成后记录晋上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"进展被看见时，要让成果与位置相匹配","strengths":["已有成果、机会或认可正在显现","努力被看见时，保持开放和稳健。让成果说话，而非急于证明"],"tensions":["扩大影响与保持基础稳固之间需要平衡"],"risks":["急于证明导致承诺超过能力"],"actions":["把当前成果整理成可复用的方法"],"avoid":["只追逐可见度而忽略质量"],"questions":["这次进展靠什么产生，能否被稳定复制？"],"extended":{"situation":{"direct":"眼下的重点是进展被看见时，要让成果与位置相匹配。","support":"已经可以利用的是：已有成果、机会或认可正在显现。","constraint":"仍需核实的是：扩大影响与保持基础稳固之间需要平衡。"},"relationship":{"inner":"下卦坤，内部动力偏向承载、配合与现实基础。","outer":"上卦离，外部处境更受辨识、表达与显明影响。","interaction":"内部想以“承载、配合与现实基础”回应外部的“辨识、表达与显明”；两边能否对接，要看“扩大影响与保持基础稳固之间需要平衡”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“已有成果、机会或认可正在显现”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“把当前成果整理成可复用的方法”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“只追逐可见度而忽略质量”，风险会被放大。","effect":"最需要防止的是：急于证明导致承诺超过能力。"},"paths":{"ready":"如果关键条件得到确认，可以继续“把当前成果整理成可复用的方法”，但仍以小步反馈决定是否扩大。","not_ready":"如果“扩大影响与保持基础稳固之间需要平衡”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"把当前成果整理成可复用的方法","observe":"这次进展靠什么产生，能否被稳定复制？","continue_if":"出现与“已有成果、机会或认可正在显现”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“只追逐可见度而忽略质量”或“急于证明导致承诺超过能力”的迹象。"}}}},{"id":36,"name":"明夷","pinyin":"míng yí","theme":"藏明与自护","reflection":"环境不利时，先守护自己重要的判断与能量，不必强行发光。","source_note":"据《周易》明夷卦意象整理","upper_trigram":8,"lower_trigram":3,"lines":{"1":{"title":"初九","interpretation":"这一爻把变化落在具体环节：明夷落在初位，眼下更像在辨认方向，而不是兑现结果 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意为了被理解而暴露不必要的脆弱。","classic":"明夷于飛，垂其翼，君子于行，三日不食。有攸往，主人有言。","source":"《周易》爻辞","modern":{"image":"“明夷于飛，垂其翼，君子于行，三日不食。有攸往，主人有言。”是明夷在“潜藏”阶段留下的具体图景。","situation":"明夷落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自真实表达与现实安全之间存在冲突，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"为了被理解而暴露不必要的脆弱。","advice":["区分必须表达与暂时保留的内容。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"观察","meaning":"在明夷第1爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“怎样保护自己，同时不背离最重要的判断”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"观察","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“为了被理解而暴露不必要的脆弱”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录明夷初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：这一阶段不再只靠设想，回应和基本功开始决定走向 自己的节奏需要与现实反馈相互校准，而真实表达与现实安全之间存在冲突也会在这一爻变得具体 可以用“区分必须表达与暂时保留的内容”做一次验证；若为了被理解而暴露不必要的脆弱，行动应当收束。","classic":"明夷，夷于左股，用拯馬壯吉。","source":"《周易》爻辞","modern":{"image":"“明夷，夷于左股，用拯馬壯吉。”是明夷在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而真实表达与现实安全之间存在冲突也会在这一爻变得具体。","warning":"为了被理解而暴露不必要的脆弱。","advice":["区分必须表达与暂时保留的内容。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在明夷第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“怎样保护自己，同时不背离最重要的判断”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“区分必须表达与暂时保留的内容”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“区分必须表达与暂时保留的内容”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“区分必须表达与暂时保留的内容”，可以保持小步推进。","pause_if":"若出现“为了被理解而暴露不必要的脆弱”，先暂停扩大投入。"},"action":{"do":"区分必须表达与暂时保留的内容","review":"完成后记录明夷六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"事情跨入转折带，焦虑可能比事实更快推动决定 当前拉扯在于：真正的拉扯来自真实表达与现实安全之间存在冲突，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题 当现实条件尚不足以支持扩大动作时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“为了被理解而暴露不必要的脆弱，而不是把在不安全的环境里正面硬碰当成解决办法，而明夷第3爻处在“转折”阶段”，就暂停扩大动作。","classic":"明夷于南狩，得其大首，不可疾貞。","source":"《周易》爻辞","modern":{"image":"“明夷于南狩，得其大首，不可疾貞。”是明夷在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自真实表达与现实安全之间存在冲突，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"为了被理解而暴露不必要的脆弱，而不是把在不安全的环境里正面硬碰当成解决办法，而明夷第3爻处在“转折”阶段。","advice":["区分必须表达与暂时保留的内容。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"暂停","meaning":"在明夷第3爻里，爻辞给出明确的收势信号，眼下不宜把意愿直接变成大动作，可用“怎样保护自己，同时不背离最重要的判断”核对判断"},"tone":"转折","extended":{"trigger":{"label":"暂停","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实条件尚不足以支持扩大动作”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“为了被理解而暴露不必要的脆弱，而不是把在不安全的环境里正面硬碰当成解决办法，而明夷第3爻处在“转折”阶段”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录明夷九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：事情正由内部走向外部，“藏明与自护”需要重新确认位置和权限 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“区分必须表达与暂时保留的内容”后再看反馈；同时留意为了被理解而暴露不必要的脆弱会在此时放大。","classic":"入于左腹，獲明夷之心，于出門庭。","source":"《周易》爻辞","modern":{"image":"“入于左腹，獲明夷之心，于出門庭。”是明夷在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“藏明与自护”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而真实表达与现实安全之间存在冲突也会在这一爻变得具体。","warning":"为了被理解而暴露不必要的脆弱会在此时放大。","advice":["区分必须表达与暂时保留的内容。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在明夷第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“怎样保护自己，同时不背离最重要的判断”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“区分必须表达与暂时保留的内容”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“区分必须表达与暂时保留的内容”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“区分必须表达与暂时保留的内容”，可以保持小步推进。","pause_if":"若出现“为了被理解而暴露不必要的脆弱会在此时放大”，先暂停扩大投入。"},"action":{"do":"区分必须表达与暂时保留的内容","review":"完成后记录明夷六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"局面正在显出边界：明夷来到五位，能力之外还要衡量整体承接和长期后果 真正的拉扯来自真实表达与现实安全之间存在冲突，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若为了被理解而暴露不必要的脆弱，行动应当收束。","classic":"箕子之明夷，利貞。","source":"《周易》爻辞","modern":{"image":"“箕子之明夷，利貞。”是明夷在“担当”阶段留下的具体图景。","situation":"明夷来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自真实表达与现实安全之间存在冲突，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"为了被理解而暴露不必要的脆弱。","advice":["区分必须表达与暂时保留的内容。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"有利","meaning":"在明夷第5爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“怎样保护自己，同时不背离最重要的判断”核对判断"},"tone":"担当","extended":{"trigger":{"label":"有利","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“为了被理解而暴露不必要的脆弱”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录明夷六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻处在阶段末端，下一步先要判断什么已经结束 当前拉扯在于：维持既有成果与允许阶段结束之间存在拉扯，而真实表达与现实安全之间存在冲突也会在这一爻变得具体 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“区分必须表达与暂时保留的内容”；若出现“为了被理解而暴露不必要的脆弱”，就暂停扩大动作。","classic":"不明晦，初登于天，後入于地。","source":"《周易》爻辞","modern":{"image":"“不明晦，初登于天，後入于地。”是明夷在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而真实表达与现实安全之间存在冲突也会在这一爻变得具体。","warning":"为了被理解而暴露不必要的脆弱。","advice":["区分必须表达与暂时保留的内容。","列出应当停止、保留和移交的事项。"],"signal":{"label":"观察","meaning":"在明夷第6爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“怎样保护自己，同时不背离最重要的判断”核对判断"},"tone":"收束","extended":{"trigger":{"label":"观察","observe":"完成“区分必须表达与暂时保留的内容”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“区分必须表达与暂时保留的内容”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“区分必须表达与暂时保留的内容”，可以保持小步推进。","pause_if":"若出现“为了被理解而暴露不必要的脆弱”，先暂停扩大投入。"},"action":{"do":"区分必须表达与暂时保留的内容","review":"完成后记录明夷上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"环境不利时，保护清醒比公开证明更重要","strengths":["仍能保存核心判断和内在方向","环境不利时，先守护自己重要的判断与能量，不必强行发光"],"tensions":["真实表达与现实安全之间存在冲突"],"risks":["为了被理解而暴露不必要的脆弱"],"actions":["区分必须表达与暂时保留的内容"],"avoid":["在不安全的环境里正面硬碰"],"questions":["怎样保护自己，同时不背离最重要的判断？"],"extended":{"situation":{"direct":"眼下的重点是环境不利时，保护清醒比公开证明更重要。","support":"已经可以利用的是：仍能保存核心判断和内在方向。","constraint":"仍需核实的是：真实表达与现实安全之间存在冲突。"},"relationship":{"inner":"下卦离，内部动力偏向辨识、表达与显明。","outer":"上卦坤，外部处境更受承载、配合与现实基础影响。","interaction":"内部想以“辨识、表达与显明”回应外部的“承载、配合与现实基础”；两边能否对接，要看“真实表达与现实安全之间存在冲突”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“仍能保存核心判断和内在方向”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“区分必须表达与暂时保留的内容”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“在不安全的环境里正面硬碰”，风险会被放大。","effect":"最需要防止的是：为了被理解而暴露不必要的脆弱。"},"paths":{"ready":"如果关键条件得到确认，可以继续“区分必须表达与暂时保留的内容”，但仍以小步反馈决定是否扩大。","not_ready":"如果“真实表达与现实安全之间存在冲突”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"区分必须表达与暂时保留的内容","observe":"怎样保护自己，同时不背离最重要的判断？","continue_if":"出现与“仍能保存核心判断和内在方向”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“在不安全的环境里正面硬碰”或“为了被理解而暴露不必要的脆弱”的迹象。"}}}},{"id":37,"name":"家人","pinyin":"jiā rén","theme":"关系与分工","reflection":"亲密关系需要清晰责任与温柔表达。从可协商的小事开始调整。","source_note":"据《周易》家人卦意象整理","upper_trigram":5,"lower_trigram":3,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：这一爻处在起步处，“亲密关系需要清楚分工，也需要温和表达”仍需低成本试探 若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大情感期待与实际责任可能不对称 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若把熟悉当成不必说明会在此时放大，行动应当收束。","classic":"閑有家，悔亡。","source":"《周易》爻辞","modern":{"image":"“閑有家，悔亡。”是家人在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“亲密关系需要清楚分工，也需要温和表达”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大情感期待与实际责任可能不对称。","warning":"把熟悉当成不必说明会在此时放大。","advice":["选择一件具体家务或责任重新协商。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"修正","meaning":"在家人第1爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“哪项默认分工已经不再适合现在”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"修正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把熟悉当成不必说明会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录家人初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正从内部准备转向真实互动，关系与条件逐渐可见 当前拉扯在于：此时一面是自己的节奏需要与现实反馈相互校准，另一面是情感期待与实际责任可能不对称，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“选择一件具体家务或责任重新协商”；若出现“把熟悉当成不必说明”，就暂停扩大动作。","classic":"无攸遂，在中饋，貞吉。","source":"《周易》爻辞","modern":{"image":"“无攸遂，在中饋，貞吉。”是家人在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是情感期待与实际责任可能不对称，两者要放在同一次权衡里。","warning":"把熟悉当成不必说明。","advice":["选择一件具体家务或责任重新协商。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在家人第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪项默认分工已经不再适合现在”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“选择一件具体家务或责任重新协商”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“选择一件具体家务或责任重新协商”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选择一件具体家务或责任重新协商”，可以保持小步推进。","pause_if":"若出现“把熟悉当成不必说明”，先暂停扩大投入。"},"action":{"do":"选择一件具体家务或责任重新协商","review":"完成后记录家人六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻把变化落在具体环节：局面来到内外转换处，“关系与分工”开始承受压力测试 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意把熟悉当成不必说明。","classic":"家人嗃嗃，悔厲吉，婦子嘻嘻，終吝。","source":"《周易》爻辞","modern":{"image":"“家人嗃嗃，悔厲吉，婦子嘻嘻，終吝。”是家人在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“关系与分工”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大情感期待与实际责任可能不对称。","warning":"把熟悉当成不必说明。","advice":["选择一件具体家务或责任重新协商。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"可行","meaning":"在家人第3爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪项默认分工已经不再适合现在”核对判断"},"tone":"转折","extended":{"trigger":{"label":"可行","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把熟悉当成不必说明”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录家人九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"局面正在显出边界：家人来到四位，跨出原有边界之前要先说明责任 此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是情感期待与实际责任可能不对称，两者要放在同一次权衡里 可以用“选择一件具体家务或责任重新协商”做一次验证；若把熟悉当成不必说明，而不是把用旧角色限制彼此变化当成解决办法，而家人第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位，行动应当收束。","classic":"富家，大吉。","source":"《周易》爻辞","modern":{"image":"“富家，大吉。”是家人在“越界”阶段留下的具体图景。","situation":"家人来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是情感期待与实际责任可能不对称，两者要放在同一次权衡里。","warning":"把熟悉当成不必说明，而不是把用旧角色限制彼此变化当成解决办法，而家人第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位。","advice":["选择一件具体家务或责任重新协商。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"顺势","meaning":"在家人第4爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“哪项默认分工已经不再适合现在”核对判断"},"tone":"越界","extended":{"trigger":{"label":"顺势","observe":"完成“选择一件具体家务或责任重新协商”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“选择一件具体家务或责任重新协商”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选择一件具体家务或责任重新协商”，可以保持小步推进。","pause_if":"若出现“把熟悉当成不必说明，而不是把用旧角色限制彼此变化当成解决办法，而家人第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位”，先暂停扩大投入。"},"action":{"do":"选择一件具体家务或责任重新协商","review":"完成后记录家人六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一阶段已进入主位，选择会放大为规则或示范 当前拉扯在于：若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大情感期待与实际责任可能不对称 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“把熟悉当成不必说明会在此时放大”，就暂停扩大动作。","classic":"王假有家，勿恤，吉。","source":"《周易》爻辞","modern":{"image":"“王假有家，勿恤，吉。”是家人在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大情感期待与实际责任可能不对称。","warning":"把熟悉当成不必说明会在此时放大。","advice":["选择一件具体家务或责任重新协商。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在家人第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪项默认分工已经不再适合现在”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把熟悉当成不必说明会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录家人九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"这一爻把变化落在具体环节：局面走到极处，继续延长旧办法未必带来同等收益 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“选择一件具体家务或责任重新协商”后再看反馈；同时留意把熟悉当成不必说明。","classic":"有孚，威如，終吉。","source":"《周易》爻辞","modern":{"image":"“有孚，威如，終吉。”是家人在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是情感期待与实际责任可能不对称，两者要放在同一次权衡里。","warning":"把熟悉当成不必说明。","advice":["选择一件具体家务或责任重新协商。","列出应当停止、保留和移交的事项。"],"signal":{"label":"可行","meaning":"在家人第6爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪项默认分工已经不再适合现在”核对判断"},"tone":"收束","extended":{"trigger":{"label":"可行","observe":"完成“选择一件具体家务或责任重新协商”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“选择一件具体家务或责任重新协商”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选择一件具体家务或责任重新协商”，可以保持小步推进。","pause_if":"若出现“把熟悉当成不必说明”，先暂停扩大投入。"},"action":{"do":"选择一件具体家务或责任重新协商","review":"完成后记录家人上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"亲密关系需要清楚分工，也需要温和表达","strengths":["日常关系中仍有协商和修复空间","亲密关系需要清晰责任与温柔表达。从可协商的小事开始调整"],"tensions":["情感期待与实际责任可能不对称"],"risks":["把熟悉当成不必说明"],"actions":["选择一件具体家务或责任重新协商"],"avoid":["用旧角色限制彼此变化"],"questions":["哪项默认分工已经不再适合现在？"],"extended":{"situation":{"direct":"眼下的重点是亲密关系需要清楚分工，也需要温和表达。","support":"已经可以利用的是：日常关系中仍有协商和修复空间。","constraint":"仍需核实的是：情感期待与实际责任可能不对称。"},"relationship":{"inner":"下卦离，内部动力偏向辨识、表达与显明。","outer":"上卦巽，外部处境更受渗透、调整与持续影响影响。","interaction":"内部想以“辨识、表达与显明”回应外部的“渗透、调整与持续影响”；两边能否对接，要看“情感期待与实际责任可能不对称”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“日常关系中仍有协商和修复空间”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“选择一件具体家务或责任重新协商”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用旧角色限制彼此变化”，风险会被放大。","effect":"最需要防止的是：把熟悉当成不必说明。"},"paths":{"ready":"如果关键条件得到确认，可以继续“选择一件具体家务或责任重新协商”，但仍以小步反馈决定是否扩大。","not_ready":"如果“情感期待与实际责任可能不对称”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"选择一件具体家务或责任重新协商","observe":"哪项默认分工已经不再适合现在？","continue_if":"出现与“日常关系中仍有协商和修复空间”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用旧角色限制彼此变化”或“把熟悉当成不必说明”的迹象。"}}}},{"id":38,"name":"睽","pinyin":"kuí","theme":"差异与求同","reflection":"不同不等于敌对。保留差异，先寻找能够合作的最小共识。","source_note":"据《周易》睽卦意象整理","upper_trigram":3,"lower_trigram":2,"lines":{"1":{"title":"初九","interpretation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分 当前拉扯在于：内在意愿已经出现，外部条件尚未完全成形，而坚持不同立场与维持联系互相拉扯也会在这一爻变得具体 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“把不同意见升级为人格否定，而不是把逼迫对方证明站在同一边当成解决办法，而睽第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，就暂停扩大动作。","classic":"悔亡，喪馬勿逐，自復。見惡人，无咎。","source":"《周易》爻辞","modern":{"image":"“悔亡，喪馬勿逐，自復。見惡人，无咎。”是睽在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而坚持不同立场与维持联系互相拉扯也会在这一爻变得具体。","warning":"把不同意见升级为人格否定，而不是把逼迫对方证明站在同一边当成解决办法，而睽第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["确认一个不必一致也能合作的目标。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在睽第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“什么差异可以保留，什么底线必须说清”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把不同意见升级为人格否定，而不是把逼迫对方证明站在同一边当成解决办法，而睽第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录睽初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一爻把变化落在具体环节：事情开始进入现实协作，“差异与求同”要接受反馈检验 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“确认一个不必一致也能合作的目标”后再看反馈；同时留意把不同意见升级为人格否定会在此时放大。","classic":"遇主于巷，无咎。","source":"《周易》爻辞","modern":{"image":"“遇主于巷，无咎。”是睽在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“差异与求同”要接受反馈检验。","tension":"真正的拉扯来自坚持不同立场与维持联系互相拉扯，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"把不同意见升级为人格否定会在此时放大。","advice":["确认一个不必一致也能合作的目标。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"守正","meaning":"在睽第2爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“什么差异可以保留，什么底线必须说清”核对判断"},"tone":"接触","extended":{"trigger":{"label":"守正","observe":"完成“确认一个不必一致也能合作的目标”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“确认一个不必一致也能合作的目标”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“确认一个不必一致也能合作的目标”，可以保持小步推进。","pause_if":"若出现“把不同意见升级为人格否定会在此时放大”，先暂停扩大投入。"},"action":{"do":"确认一个不必一致也能合作的目标","review":"完成后记录睽九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面正在显出边界：睽行至三位，旧方法的边界和新选择的代价同时出现 继续原路与承认需要调整之间发生冲突，而坚持不同立场与维持联系互相拉扯也会在这一爻变得具体 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若把不同意见升级为人格否定，行动应当收束。","classic":"見輿曳，其牛掣，其人天且劓，无初有終。","source":"《周易》爻辞","modern":{"image":"“見輿曳，其牛掣，其人天且劓，无初有終。”是睽在“转折”阶段留下的具体图景。","situation":"睽行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而坚持不同立场与维持联系互相拉扯也会在这一爻变得具体。","warning":"把不同意见升级为人格否定。","advice":["确认一个不必一致也能合作的目标。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在睽第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么差异可以保留，什么底线必须说清”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把不同意见升级为人格否定”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录睽六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 当前拉扯在于：真正的拉扯来自坚持不同立场与维持联系互相拉扯，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“确认一个不必一致也能合作的目标”；若出现“把不同意见升级为人格否定”，就暂停扩大动作。","classic":"睽孤，遇元夫。交孚，厲无咎。","source":"《周易》爻辞","modern":{"image":"“睽孤，遇元夫。交孚，厲无咎。”是睽在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自坚持不同立场与维持联系互相拉扯，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"把不同意见升级为人格否定。","advice":["确认一个不必一致也能合作的目标。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在睽第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“什么差异可以保留，什么底线必须说清”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“确认一个不必一致也能合作的目标”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“确认一个不必一致也能合作的目标”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“确认一个不必一致也能合作的目标”，可以保持小步推进。","pause_if":"若出现“把不同意见升级为人格否定”，先暂停扩大投入。"},"action":{"do":"确认一个不必一致也能合作的目标","review":"完成后记录睽九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"这一爻把变化落在具体环节：局面要求从个人得失转向整体结果和持续责任 原有做法显出明确代价，需要及时调整，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意把不同意见升级为人格否定，而不是把逼迫对方证明站在同一边当成解决办法，而睽第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","classic":"悔亡。厥宗噬膚，往何咎。","source":"《周易》爻辞","modern":{"image":"“悔亡。厥宗噬膚，往何咎。”是睽在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而坚持不同立场与维持联系互相拉扯也会在这一爻变得具体。","warning":"把不同意见升级为人格否定，而不是把逼迫对方证明站在同一边当成解决办法，而睽第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["确认一个不必一致也能合作的目标。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"修正","meaning":"在睽第5爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“什么差异可以保留，什么底线必须说清”核对判断"},"tone":"担当","extended":{"trigger":{"label":"修正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把不同意见升级为人格否定，而不是把逼迫对方证明站在同一边当成解决办法，而睽第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录睽六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面正在显出边界：当前循环接近上限，“差异与求同”需要从继续加力转向收束复盘 真正的拉扯来自坚持不同立场与维持联系互相拉扯，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题 可以用“确认一个不必一致也能合作的目标”做一次验证；若把不同意见升级为人格否定会在此时放大，行动应当收束。","classic":"睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧，匪寇婚媾。往，遇雨則吉。","source":"《周易》爻辞","modern":{"image":"“睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧，匪寇婚媾。往，遇雨則吉。”是睽在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“差异与求同”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自坚持不同立场与维持联系互相拉扯，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"把不同意见升级为人格否定会在此时放大。","advice":["确认一个不必一致也能合作的目标。","列出应当停止、保留和移交的事项。"],"signal":{"label":"可行","meaning":"在睽第6爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“什么差异可以保留，什么底线必须说清”核对判断"},"tone":"收束","extended":{"trigger":{"label":"可行","observe":"完成“确认一个不必一致也能合作的目标”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“确认一个不必一致也能合作的目标”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“确认一个不必一致也能合作的目标”，可以保持小步推进。","pause_if":"若出现“把不同意见升级为人格否定会在此时放大”，先暂停扩大投入。"},"action":{"do":"确认一个不必一致也能合作的目标","review":"完成后记录睽上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"差异不必被消灭，先找到可以共同完成的小事","strengths":["双方仍可能在局部建立合作","不同不等于敌对。保留差异，先寻找能够合作的最小共识"],"tensions":["坚持不同立场与维持联系互相拉扯"],"risks":["把不同意见升级为人格否定"],"actions":["确认一个不必一致也能合作的目标"],"avoid":["逼迫对方证明站在同一边"],"questions":["什么差异可以保留，什么底线必须说清？"],"extended":{"situation":{"direct":"眼下的重点是差异不必被消灭，先找到可以共同完成的小事。","support":"已经可以利用的是：双方仍可能在局部建立合作。","constraint":"仍需核实的是：坚持不同立场与维持联系互相拉扯。"},"relationship":{"inner":"下卦兑，内部动力偏向交流、回应与协商。","outer":"上卦离，外部处境更受辨识、表达与显明影响。","interaction":"内部想以“交流、回应与协商”回应外部的“辨识、表达与显明”；两边能否对接，要看“坚持不同立场与维持联系互相拉扯”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“双方仍可能在局部建立合作”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“确认一个不必一致也能合作的目标”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“逼迫对方证明站在同一边”，风险会被放大。","effect":"最需要防止的是：把不同意见升级为人格否定。"},"paths":{"ready":"如果关键条件得到确认，可以继续“确认一个不必一致也能合作的目标”，但仍以小步反馈决定是否扩大。","not_ready":"如果“坚持不同立场与维持联系互相拉扯”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"确认一个不必一致也能合作的目标","observe":"什么差异可以保留，什么底线必须说清？","continue_if":"出现与“双方仍可能在局部建立合作”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“逼迫对方证明站在同一边”或“把不同意见升级为人格否定”的迹象。"}}}},{"id":39,"name":"蹇","pinyin":"jiǎn","theme":"困难与求助","reflection":"路难走时，别只靠蛮力。绕路、暂停或求助，都是向前的一部分。","source_note":"据《周易》蹇卦意象整理","upper_trigram":6,"lower_trigram":7,"lines":{"1":{"title":"初六","interpretation":"这一爻把变化落在具体环节：事情刚在“困难与求助”的起点露出端倪，可用条件还不多 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意把求助理解为能力不足。","classic":"往蹇來譽。","source":"《周易》爻辞","modern":{"image":"“往蹇來譽。”是蹇在“潜藏”阶段留下的具体图景。","situation":"事情刚在“困难与求助”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是坚持原路与承认需要换法之间有冲突，两者要放在同一次权衡里。","warning":"把求助理解为能力不足。","advice":["找一个能提供具体信息或资源的人。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"观察","meaning":"在蹇第1爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“这道困难需要更多力气，还是需要另一条路”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"观察","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把求助理解为能力不足”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录蹇初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：蹇来到二位，个人判断正与资源、规则或他人发生接触 若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大坚持原路与承认需要换法之间有冲突 可以用“找一个能提供具体信息或资源的人”做一次验证；若把求助理解为能力不足，而不是把继续用同一种方式撞同一堵墙当成解决办法，而蹇第2爻处在“接触”阶段，还需防止只听见符合期待的回应，行动应当收束。","classic":"王臣蹇蹇，匪躬之故。","source":"《周易》爻辞","modern":{"image":"“王臣蹇蹇，匪躬之故。”是蹇在“接触”阶段留下的具体图景。","situation":"蹇来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大坚持原路与承认需要换法之间有冲突。","warning":"把求助理解为能力不足，而不是把继续用同一种方式撞同一堵墙当成解决办法，而蹇第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","advice":["找一个能提供具体信息或资源的人。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在蹇第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“这道困难需要更多力气，还是需要另一条路”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“找一个能提供具体信息或资源的人”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“找一个能提供具体信息或资源的人”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“找一个能提供具体信息或资源的人”，可以保持小步推进。","pause_if":"若出现“把求助理解为能力不足，而不是把继续用同一种方式撞同一堵墙当成解决办法，而蹇第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，先暂停扩大投入。"},"action":{"do":"找一个能提供具体信息或资源的人","review":"完成后记录蹇六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻处在容易用力过度的位置，调整比加码更重要 当前拉扯在于：此时一面是继续原路与承认需要调整之间发生冲突，另一面是坚持原路与承认需要换法之间有冲突，两者要放在同一次权衡里 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“把求助理解为能力不足会在此时放大”，就暂停扩大动作。","classic":"往蹇來反。","source":"《周易》爻辞","modern":{"image":"“往蹇來反。”是蹇在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是坚持原路与承认需要换法之间有冲突，两者要放在同一次权衡里。","warning":"把求助理解为能力不足会在此时放大。","advice":["找一个能提供具体信息或资源的人。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在蹇第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“这道困难需要更多力气，还是需要另一条路”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把求助理解为能力不足会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录蹇九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：局面已经接近新的层级，旧角色未必还能容纳当前变化 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“找一个能提供具体信息或资源的人”后再看反馈；同时留意把求助理解为能力不足。","classic":"往蹇來連。","source":"《周易》爻辞","modern":{"image":"“往蹇來連。”是蹇在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大坚持原路与承认需要换法之间有冲突。","warning":"把求助理解为能力不足。","advice":["找一个能提供具体信息或资源的人。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在蹇第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“这道困难需要更多力气，还是需要另一条路”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“找一个能提供具体信息或资源的人”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“找一个能提供具体信息或资源的人”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“找一个能提供具体信息或资源的人”，可以保持小步推进。","pause_if":"若出现“把求助理解为能力不足”，先暂停扩大投入。"},"action":{"do":"找一个能提供具体信息或资源的人","review":"完成后记录蹇六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面正在显出边界：关键资源与决定权趋向集中，“困难与求助”开始影响更多人 此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是坚持原路与承认需要换法之间有冲突，两者要放在同一次权衡里 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若把求助理解为能力不足，行动应当收束。","classic":"大蹇朋來。","source":"《周易》爻辞","modern":{"image":"“大蹇朋來。”是蹇在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“困难与求助”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是坚持原路与承认需要换法之间有冲突，两者要放在同一次权衡里。","warning":"把求助理解为能力不足。","advice":["找一个能提供具体信息或资源的人。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在蹇第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“这道困难需要更多力气，还是需要另一条路”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把求助理解为能力不足”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录蹇九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"蹇来到上位，已有路径可能完成使命，也可能因过度而失衡 当前拉扯在于：若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大坚持原路与承认需要换法之间有冲突 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“找一个能提供具体信息或资源的人”；若出现“把求助理解为能力不足，而不是把继续用同一种方式撞同一堵墙当成解决办法，而蹇第6爻处在“收束”阶段”，就暂停扩大动作。","classic":"往蹇來碩，吉，利見大人。","source":"《周易》爻辞","modern":{"image":"“往蹇來碩，吉，利見大人。”是蹇在“收束”阶段留下的具体图景。","situation":"蹇来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大坚持原路与承认需要换法之间有冲突。","warning":"把求助理解为能力不足，而不是把继续用同一种方式撞同一堵墙当成解决办法，而蹇第6爻处在“收束”阶段。","advice":["找一个能提供具体信息或资源的人。","列出应当停止、保留和移交的事项。"],"signal":{"label":"可行","meaning":"在蹇第6爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“这道困难需要更多力气，还是需要另一条路”核对判断"},"tone":"收束","extended":{"trigger":{"label":"可行","observe":"完成“找一个能提供具体信息或资源的人”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“找一个能提供具体信息或资源的人”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“找一个能提供具体信息或资源的人”，可以保持小步推进。","pause_if":"若出现“把求助理解为能力不足，而不是把继续用同一种方式撞同一堵墙当成解决办法，而蹇第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"找一个能提供具体信息或资源的人","review":"完成后记录蹇上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"路难走时，绕行、暂停和求助都是有效行动","strengths":["已经看见阻力，不必再假装畅通","路难走时，别只靠蛮力。绕路、暂停或求助，都是向前的一部分"],"tensions":["坚持原路与承认需要换法之间有冲突"],"risks":["把求助理解为能力不足"],"actions":["找一个能提供具体信息或资源的人"],"avoid":["继续用同一种方式撞同一堵墙"],"questions":["这道困难需要更多力气，还是需要另一条路？"],"extended":{"situation":{"direct":"眼下的重点是路难走时，绕行、暂停和求助都是有效行动。","support":"已经可以利用的是：已经看见阻力，不必再假装畅通。","constraint":"仍需核实的是：坚持原路与承认需要换法之间有冲突。"},"relationship":{"inner":"下卦艮，内部动力偏向边界、停止与重新定位。","outer":"上卦坎，外部处境更受风险、试探与信息缺口影响。","interaction":"内部想以“边界、停止与重新定位”回应外部的“风险、试探与信息缺口”；两边能否对接，要看“坚持原路与承认需要换法之间有冲突”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“已经看见阻力，不必再假装畅通”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“找一个能提供具体信息或资源的人”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“继续用同一种方式撞同一堵墙”，风险会被放大。","effect":"最需要防止的是：把求助理解为能力不足。"},"paths":{"ready":"如果关键条件得到确认，可以继续“找一个能提供具体信息或资源的人”，但仍以小步反馈决定是否扩大。","not_ready":"如果“坚持原路与承认需要换法之间有冲突”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"找一个能提供具体信息或资源的人","observe":"这道困难需要更多力气，还是需要另一条路？","continue_if":"出现与“已经看见阻力，不必再假装畅通”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“继续用同一种方式撞同一堵墙”或“把求助理解为能力不足”的迹象。"}}}},{"id":40,"name":"解","pinyin":"xiè","theme":"松绑与释放","reflection":"紧张有机会缓解。先放下最不必要的压力，再处理遗留的问题。","source_note":"据《周易》解卦意象整理","upper_trigram":4,"lower_trigram":6,"lines":{"1":{"title":"初六","interpretation":"局面正在显出边界：解落在初位，眼下更像在辨认方向，而不是兑现结果 真正的拉扯来自释放压力与逃避后续责任容易混淆，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若一放松就恢复旧模式，行动应当收束。","classic":"无咎。","source":"《周易》爻辞","modern":{"image":"“无咎。”是解在“潜藏”阶段留下的具体图景。","situation":"解落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自释放压力与逃避后续责任容易混淆，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"一放松就恢复旧模式。","advice":["先处理一项最影响后续的遗留事项。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在解第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“压力减轻后，哪件事终于可以被认真处理”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“一放松就恢复旧模式”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录解初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一阶段不再只靠设想，回应和基本功开始决定走向 当前拉扯在于：自己的节奏需要与现实反馈相互校准，而释放压力与逃避后续责任容易混淆也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“先处理一项最影响后续的遗留事项”；若出现“一放松就恢复旧模式”，就暂停扩大动作。","classic":"田獲三狐，得黃矢，貞吉。","source":"《周易》爻辞","modern":{"image":"“田獲三狐，得黃矢，貞吉。”是解在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而释放压力与逃避后续责任容易混淆也会在这一爻变得具体。","warning":"一放松就恢复旧模式。","advice":["先处理一项最影响后续的遗留事项。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在解第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“压力减轻后，哪件事终于可以被认真处理”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“先处理一项最影响后续的遗留事项”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先处理一项最影响后续的遗留事项”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先处理一项最影响后续的遗留事项”，可以保持小步推进。","pause_if":"若出现“一放松就恢复旧模式”，先暂停扩大投入。"},"action":{"do":"先处理一项最影响后续的遗留事项","review":"完成后记录解九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻把变化落在具体环节：事情跨入转折带，焦虑可能比事实更快推动决定 原有做法显出明确代价，需要及时调整，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意一放松就恢复旧模式，而不是把把暂时缓解当成彻底解决当成解决办法，而解第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","classic":"負且乘，致寇至，貞吝。","source":"《周易》爻辞","modern":{"image":"“負且乘，致寇至，貞吝。”是解在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自释放压力与逃避后续责任容易混淆，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"一放松就恢复旧模式，而不是把把暂时缓解当成彻底解决当成解决办法，而解第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","advice":["先处理一项最影响后续的遗留事项。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"修正","meaning":"在解第3爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“压力减轻后，哪件事终于可以被认真处理”核对判断"},"tone":"转折","extended":{"trigger":{"label":"修正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“一放松就恢复旧模式，而不是把把暂时缓解当成彻底解决当成解决办法，而解第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录解六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：事情正由内部走向外部，“松绑与释放”需要重新确认位置和权限 向外推进的需要与边界尚未说清之间互相牵制，而释放压力与逃避后续责任容易混淆也会在这一爻变得具体 可以用“先处理一项最影响后续的遗留事项”做一次验证；若一放松就恢复旧模式会在此时放大，行动应当收束。","classic":"解而拇，朋至斯孚。","source":"《周易》爻辞","modern":{"image":"“解而拇，朋至斯孚。”是解在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“松绑与释放”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而释放压力与逃避后续责任容易混淆也会在这一爻变得具体。","warning":"一放松就恢复旧模式会在此时放大。","advice":["先处理一项最影响后续的遗留事项。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在解第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“压力减轻后，哪件事终于可以被认真处理”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“先处理一项最影响后续的遗留事项”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先处理一项最影响后续的遗留事项”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先处理一项最影响后续的遗留事项”，可以保持小步推进。","pause_if":"若出现“一放松就恢复旧模式会在此时放大”，先暂停扩大投入。"},"action":{"do":"先处理一项最影响后续的遗留事项","review":"完成后记录解九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"解来到五位，能力之外还要衡量整体承接和长期后果 当前拉扯在于：真正的拉扯来自释放压力与逃避后续责任容易混淆，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“一放松就恢复旧模式”，就暂停扩大动作。","classic":"君子維有解，吉，有孚于小人。","source":"《周易》爻辞","modern":{"image":"“君子維有解，吉，有孚于小人。”是解在“担当”阶段留下的具体图景。","situation":"解来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自释放压力与逃避后续责任容易混淆，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"一放松就恢复旧模式。","advice":["先处理一项最影响后续的遗留事项。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在解第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“压力减轻后，哪件事终于可以被认真处理”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“一放松就恢复旧模式”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录解六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻把变化落在具体环节：这一爻处在阶段末端，下一步先要判断什么已经结束 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“先处理一项最影响后续的遗留事项”后再看反馈；同时留意一放松就恢复旧模式。","classic":"公用射隼于高墉之上，獲之，无不利。","source":"《周易》爻辞","modern":{"image":"“公用射隼于高墉之上，獲之，无不利。”是解在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而释放压力与逃避后续责任容易混淆也会在这一爻变得具体。","warning":"一放松就恢复旧模式。","advice":["先处理一项最影响后续的遗留事项。","列出应当停止、保留和移交的事项。"],"signal":{"label":"通达","meaning":"在解第6爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“压力减轻后，哪件事终于可以被认真处理”核对判断"},"tone":"收束","extended":{"trigger":{"label":"通达","observe":"完成“先处理一项最影响后续的遗留事项”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先处理一项最影响后续的遗留事项”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先处理一项最影响后续的遗留事项”，可以保持小步推进。","pause_if":"若出现“一放松就恢复旧模式”，先暂停扩大投入。"},"action":{"do":"先处理一项最影响后续的遗留事项","review":"完成后记录解上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"松绑之后仍要处理遗留问题，轻松不是结束","strengths":["紧张局面出现缓解和重新安排的空间","紧张有机会缓解。先放下最不必要的压力，再处理遗留的问题"],"tensions":["释放压力与逃避后续责任容易混淆"],"risks":["一放松就恢复旧模式"],"actions":["先处理一项最影响后续的遗留事项"],"avoid":["把暂时缓解当成彻底解决"],"questions":["压力减轻后，哪件事终于可以被认真处理？"],"extended":{"situation":{"direct":"眼下的重点是松绑之后仍要处理遗留问题，轻松不是结束。","support":"已经可以利用的是：紧张局面出现缓解和重新安排的空间。","constraint":"仍需核实的是：释放压力与逃避后续责任容易混淆。"},"relationship":{"inner":"下卦坎，内部动力偏向风险、试探与信息缺口。","outer":"上卦震，外部处境更受启动、震动与迅速反应影响。","interaction":"内部想以“风险、试探与信息缺口”回应外部的“启动、震动与迅速反应”；两边能否对接，要看“释放压力与逃避后续责任容易混淆”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“紧张局面出现缓解和重新安排的空间”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“先处理一项最影响后续的遗留事项”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把暂时缓解当成彻底解决”，风险会被放大。","effect":"最需要防止的是：一放松就恢复旧模式。"},"paths":{"ready":"如果关键条件得到确认，可以继续“先处理一项最影响后续的遗留事项”，但仍以小步反馈决定是否扩大。","not_ready":"如果“释放压力与逃避后续责任容易混淆”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"先处理一项最影响后续的遗留事项","observe":"压力减轻后，哪件事终于可以被认真处理？","continue_if":"出现与“紧张局面出现缓解和重新安排的空间”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把暂时缓解当成彻底解决”或“一放松就恢复旧模式”的迹象。"}}}},{"id":41,"name":"损","pinyin":"sǔn","theme":"减法与取舍","reflection":"适当减少承诺和杂讯，为真正珍视的事留出空间。","source_note":"据《周易》损卦意象整理","upper_trigram":7,"lower_trigram":2,"lines":{"1":{"title":"初九","interpretation":"这一爻处在起步处，“有意识的减少，是把资源归还给真正重要的事”仍需低成本试探 当前拉扯在于：若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大失去感可能阻碍必要的减法 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“只削减容易削减的，却保留核心消耗会在此时放大”，就暂停扩大动作。","classic":"已事遄往，无咎，酌損之。","source":"《周易》爻辞","modern":{"image":"“已事遄往，无咎，酌損之。”是损在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“有意识的减少，是把资源归还给真正重要的事”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大失去感可能阻碍必要的减法。","warning":"只削减容易削减的，却保留核心消耗会在此时放大。","advice":["停止一项回报最低的承诺。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在损第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“减少什么会让最重要的部分反而更完整”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“只削减容易削减的，却保留核心消耗会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录损初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一爻把变化落在具体环节：局面正从内部准备转向真实互动，关系与条件逐渐可见 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“停止一项回报最低的承诺”后再看反馈；同时留意只削减容易削减的，却保留核心消耗。","classic":"利貞，征凶。弗損，益之。","source":"《周易》爻辞","modern":{"image":"“利貞，征凶。弗損，益之。”是损在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是失去感可能阻碍必要的减法，两者要放在同一次权衡里。","warning":"只削减容易削减的，却保留核心消耗。","advice":["停止一项回报最低的承诺。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"止损","meaning":"在损第2爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“减少什么会让最重要的部分反而更完整”核对判断"},"tone":"接触","extended":{"trigger":{"label":"止损","observe":"完成“停止一项回报最低的承诺”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“停止一项回报最低的承诺”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“停止一项回报最低的承诺”，可以保持小步推进。","pause_if":"若出现“只削减容易削减的，却保留核心消耗”，先暂停扩大投入。"},"action":{"do":"停止一项回报最低的承诺","review":"完成后记录损九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面正在显出边界：局面来到内外转换处，“减法与取舍”开始承受压力测试 若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大失去感可能阻碍必要的减法 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若只削减容易削减的，却保留核心消耗，行动应当收束。","classic":"三人行，則損一人，一人行，則得其友。","source":"《周易》爻辞","modern":{"image":"“三人行，則損一人，一人行，則得其友。”是损在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“减法与取舍”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大失去感可能阻碍必要的减法。","warning":"只削减容易削减的，却保留核心消耗。","advice":["停止一项回报最低的承诺。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在损第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“减少什么会让最重要的部分反而更完整”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“只削减容易削减的，却保留核心消耗”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录损六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"损来到四位，跨出原有边界之前要先说明责任 当前拉扯在于：此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是失去感可能阻碍必要的减法，两者要放在同一次权衡里 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“停止一项回报最低的承诺”；若出现“只削减容易削减的，却保留核心消耗，而不是把把节省变成对基本需要的苛刻当成解决办法，而损第4爻处在“越界”阶段”，就暂停扩大动作。","classic":"損其疾，使遄有喜，无咎。","source":"《周易》爻辞","modern":{"image":"“損其疾，使遄有喜，无咎。”是损在“越界”阶段留下的具体图景。","situation":"损来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是失去感可能阻碍必要的减法，两者要放在同一次权衡里。","warning":"只削减容易削减的，却保留核心消耗，而不是把把节省变成对基本需要的苛刻当成解决办法，而损第4爻处在“越界”阶段。","advice":["停止一项回报最低的承诺。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在损第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“减少什么会让最重要的部分反而更完整”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“停止一项回报最低的承诺”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“停止一项回报最低的承诺”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“停止一项回报最低的承诺”，可以保持小步推进。","pause_if":"若出现“只削减容易削减的，却保留核心消耗，而不是把把节省变成对基本需要的苛刻当成解决办法，而损第4爻处在“越界”阶段”，先暂停扩大投入。"},"action":{"do":"停止一项回报最低的承诺","review":"完成后记录损六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"这一爻把变化落在具体环节：这一阶段已进入主位，选择会放大为规则或示范 现实反馈与当前方向开始相互支持，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意只削减容易削减的，却保留核心消耗会在此时放大。","classic":"或益之十朋之龜，弗克違，元吉。","source":"《周易》爻辞","modern":{"image":"“或益之十朋之龜，弗克違，元吉。”是损在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大失去感可能阻碍必要的减法。","warning":"只削减容易削减的，却保留核心消耗会在此时放大。","advice":["停止一项回报最低的承诺。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"顺势","meaning":"在损第5爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“减少什么会让最重要的部分反而更完整”核对判断"},"tone":"担当","extended":{"trigger":{"label":"顺势","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“只削减容易削减的，却保留核心消耗会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录损六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面正在显出边界：局面走到极处，继续延长旧办法未必带来同等收益 此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是失去感可能阻碍必要的减法，两者要放在同一次权衡里 可以用“停止一项回报最低的承诺”做一次验证；若只削减容易削减的，却保留核心消耗，行动应当收束。","classic":"弗損，益之，无咎，貞吉，利有攸往，得臣无家。","source":"《周易》爻辞","modern":{"image":"“弗損，益之，无咎，貞吉，利有攸往，得臣无家。”是损在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是失去感可能阻碍必要的减法，两者要放在同一次权衡里。","warning":"只削减容易削减的，却保留核心消耗。","advice":["停止一项回报最低的承诺。","列出应当停止、保留和移交的事项。"],"signal":{"label":"可行","meaning":"在损第6爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“减少什么会让最重要的部分反而更完整”核对判断"},"tone":"收束","extended":{"trigger":{"label":"可行","observe":"完成“停止一项回报最低的承诺”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“停止一项回报最低的承诺”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“停止一项回报最低的承诺”，可以保持小步推进。","pause_if":"若出现“只削减容易削减的，却保留核心消耗”，先暂停扩大投入。"},"action":{"do":"停止一项回报最低的承诺","review":"完成后记录损上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"有意识的减少，是把资源归还给真正重要的事","strengths":["能够通过取舍恢复清晰和余量","适当减少承诺和杂讯，为真正珍视的事留出空间"],"tensions":["失去感可能阻碍必要的减法"],"risks":["只削减容易削减的，却保留核心消耗"],"actions":["停止一项回报最低的承诺"],"avoid":["把节省变成对基本需要的苛刻"],"questions":["减少什么会让最重要的部分反而更完整？"],"extended":{"situation":{"direct":"眼下的重点是有意识的减少，是把资源归还给真正重要的事。","support":"已经可以利用的是：能够通过取舍恢复清晰和余量。","constraint":"仍需核实的是：失去感可能阻碍必要的减法。"},"relationship":{"inner":"下卦兑，内部动力偏向交流、回应与协商。","outer":"上卦艮，外部处境更受边界、停止与重新定位影响。","interaction":"内部想以“交流、回应与协商”回应外部的“边界、停止与重新定位”；两边能否对接，要看“失去感可能阻碍必要的减法”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“能够通过取舍恢复清晰和余量”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“停止一项回报最低的承诺”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把节省变成对基本需要的苛刻”，风险会被放大。","effect":"最需要防止的是：只削减容易削减的，却保留核心消耗。"},"paths":{"ready":"如果关键条件得到确认，可以继续“停止一项回报最低的承诺”，但仍以小步反馈决定是否扩大。","not_ready":"如果“失去感可能阻碍必要的减法”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"停止一项回报最低的承诺","observe":"减少什么会让最重要的部分反而更完整？","continue_if":"出现与“能够通过取舍恢复清晰和余量”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把节省变成对基本需要的苛刻”或“只削减容易削减的，却保留核心消耗”的迹象。"}}}},{"id":42,"name":"益","pinyin":"yì","theme":"增益与互助","reflection":"把资源投入有成长性的地方；帮助他人时，也让关系形成良性循环。","source_note":"据《周易》益卦意象整理","upper_trigram":5,"lower_trigram":4,"lines":{"1":{"title":"初九","interpretation":"这一爻把变化落在具体环节：变化尚在根部，先分清已经发生的事实和仍在期待的部分 现实反馈与当前方向开始相互支持，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意把帮助变成单向耗损，而不是把因为短期回报而忽略长期价值当成解决办法，而益第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","classic":"利用為大作，元吉，无咎。","source":"《周易》爻辞","modern":{"image":"“利用為大作，元吉，无咎。”是益在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而扩大投入与维持可持续性之间有张力也会在这一爻变得具体。","warning":"把帮助变成单向耗损，而不是把因为短期回报而忽略长期价值当成解决办法，而益第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["把新增资源投向一个可观察的成长点。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"顺势","meaning":"在益第1爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“这份增加会形成循环，还是只产生一次消耗”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"顺势","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把帮助变成单向耗损，而不是把因为短期回报而忽略长期价值当成解决办法，而益第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录益初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：事情开始进入现实协作，“增益与互助”要接受反馈检验 真正的拉扯来自扩大投入与维持可持续性之间有张力，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题 可以用“把新增资源投向一个可观察的成长点”做一次验证；若把帮助变成单向耗损会在此时放大，行动应当收束。","classic":"或益之十朋之龜，弗克違，永貞吉。王用享于帝，吉。","source":"《周易》爻辞","modern":{"image":"“或益之十朋之龜，弗克違，永貞吉。王用享于帝，吉。”是益在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“增益与互助”要接受反馈检验。","tension":"真正的拉扯来自扩大投入与维持可持续性之间有张力，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"把帮助变成单向耗损会在此时放大。","advice":["把新增资源投向一个可观察的成长点。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在益第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“这份增加会形成循环，还是只产生一次消耗”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“把新增资源投向一个可观察的成长点”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把新增资源投向一个可观察的成长点”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把新增资源投向一个可观察的成长点”，可以保持小步推进。","pause_if":"若出现“把帮助变成单向耗损会在此时放大”，先暂停扩大投入。"},"action":{"do":"把新增资源投向一个可观察的成长点","review":"完成后记录益六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"益行至三位，旧方法的边界和新选择的代价同时出现 当前拉扯在于：继续原路与承认需要调整之间发生冲突，而扩大投入与维持可持续性之间有张力也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“把帮助变成单向耗损”，就暂停扩大动作。","classic":"益之用凶事，无咎。有孚中行，告公用圭。","source":"《周易》爻辞","modern":{"image":"“益之用凶事，无咎。有孚中行，告公用圭。”是益在“转折”阶段留下的具体图景。","situation":"益行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而扩大投入与维持可持续性之间有张力也会在这一爻变得具体。","warning":"把帮助变成单向耗损。","advice":["把新增资源投向一个可观察的成长点。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"止损","meaning":"在益第3爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“这份增加会形成循环，还是只产生一次消耗”核对判断"},"tone":"转折","extended":{"trigger":{"label":"止损","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把帮助变成单向耗损”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录益六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 关键条件开始出现可利用的现实回应，是接下来值得核对的信号。完成“把新增资源投向一个可观察的成长点”后再看反馈；同时留意把帮助变成单向耗损。","classic":"中行，告公從，利用為依遷國。","source":"《周易》爻辞","modern":{"image":"“中行，告公從，利用為依遷國。”是益在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自扩大投入与维持可持续性之间有张力，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"把帮助变成单向耗损。","advice":["把新增资源投向一个可观察的成长点。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"有利","meaning":"在益第4爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“这份增加会形成循环，还是只产生一次消耗”核对判断"},"tone":"越界","extended":{"trigger":{"label":"有利","observe":"完成“把新增资源投向一个可观察的成长点”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“把新增资源投向一个可观察的成长点”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把新增资源投向一个可观察的成长点”，可以保持小步推进。","pause_if":"若出现“把帮助变成单向耗损”，先暂停扩大投入。"},"action":{"do":"把新增资源投向一个可观察的成长点","review":"完成后记录益六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面正在显出边界：局面要求从个人得失转向整体结果和持续责任 扩大影响与照顾整体承接能力之间需要平衡，而扩大投入与维持可持续性之间有张力也会在这一爻变得具体 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若把帮助变成单向耗损，而不是把因为短期回报而忽略长期价值当成解决办法，而益第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围，行动应当收束。","classic":"有孚惠心，勿問元吉。有孚惠我德。","source":"《周易》爻辞","modern":{"image":"“有孚惠心，勿問元吉。有孚惠我德。”是益在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而扩大投入与维持可持续性之间有张力也会在这一爻变得具体。","warning":"把帮助变成单向耗损，而不是把因为短期回报而忽略长期价值当成解决办法，而益第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["把新增资源投向一个可观察的成长点。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"顺势","meaning":"在益第5爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“这份增加会形成循环，还是只产生一次消耗”核对判断"},"tone":"担当","extended":{"trigger":{"label":"顺势","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把帮助变成单向耗损，而不是把因为短期回报而忽略长期价值当成解决办法，而益第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录益九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"当前循环接近上限，“增益与互助”需要从继续加力转向收束复盘 当前拉扯在于：真正的拉扯来自扩大投入与维持可持续性之间有张力，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“把新增资源投向一个可观察的成长点”；若出现“把帮助变成单向耗损会在此时放大”，就暂停扩大动作。","classic":"莫益之，或擊之，立心勿恒，凶。","source":"《周易》爻辞","modern":{"image":"“莫益之，或擊之，立心勿恒，凶。”是益在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“增益与互助”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自扩大投入与维持可持续性之间有张力，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"把帮助变成单向耗损会在此时放大。","advice":["把新增资源投向一个可观察的成长点。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在益第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“这份增加会形成循环，还是只产生一次消耗”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“把新增资源投向一个可观察的成长点”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把新增资源投向一个可观察的成长点”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把新增资源投向一个可观察的成长点”，可以保持小步推进。","pause_if":"若出现“把帮助变成单向耗损会在此时放大”，先暂停扩大投入。"},"action":{"do":"把新增资源投向一个可观察的成长点","review":"完成后记录益上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"增益要流向能持续生长并形成互惠的地方","strengths":["资源、帮助或学习机会正在增加","把资源投入有成长性的地方"],"tensions":["扩大投入与维持可持续性之间有张力"],"risks":["把帮助变成单向耗损"],"actions":["把新增资源投向一个可观察的成长点"],"avoid":["因为短期回报而忽略长期价值"],"questions":["这份增加会形成循环，还是只产生一次消耗？"],"extended":{"situation":{"direct":"眼下的重点是增益要流向能持续生长并形成互惠的地方。","support":"已经可以利用的是：资源、帮助或学习机会正在增加。","constraint":"仍需核实的是：扩大投入与维持可持续性之间有张力。"},"relationship":{"inner":"下卦震，内部动力偏向启动、震动与迅速反应。","outer":"上卦巽，外部处境更受渗透、调整与持续影响影响。","interaction":"内部想以“启动、震动与迅速反应”回应外部的“渗透、调整与持续影响”；两边能否对接，要看“扩大投入与维持可持续性之间有张力”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“资源、帮助或学习机会正在增加”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“把新增资源投向一个可观察的成长点”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“因为短期回报而忽略长期价值”，风险会被放大。","effect":"最需要防止的是：把帮助变成单向耗损。"},"paths":{"ready":"如果关键条件得到确认，可以继续“把新增资源投向一个可观察的成长点”，但仍以小步反馈决定是否扩大。","not_ready":"如果“扩大投入与维持可持续性之间有张力”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"把新增资源投向一个可观察的成长点","observe":"这份增加会形成循环，还是只产生一次消耗？","continue_if":"出现与“资源、帮助或学习机会正在增加”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“因为短期回报而忽略长期价值”或“把帮助变成单向耗损”的迹象。"}}}},{"id":43,"name":"夬","pinyin":"guài","theme":"表明与突破","reflection":"该说清楚的事可以坦荡说明。果断不等于攻击，保持尊重与边界。","source_note":"据《周易》夬卦意象整理","upper_trigram":2,"lower_trigram":1,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：事情刚在“表明与突破”的起点露出端倪，可用条件还不多 此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是果断表态与保护关系之间需要分寸，两者要放在同一次权衡里 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若用正义感放大敌意，行动应当收束。","classic":"壯于前趾，往不勝為咎。","source":"《周易》爻辞","modern":{"image":"“壯于前趾，往不勝為咎。”是夬在“潜藏”阶段留下的具体图景。","situation":"事情刚在“表明与突破”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是果断表态与保护关系之间需要分寸，两者要放在同一次权衡里。","warning":"用正义感放大敌意。","advice":["用事实、影响和请求表达立场。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"观察","meaning":"在夬第1爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“怎样说清底线，同时仍给问题留下解决空间”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"观察","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“用正义感放大敌意”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录夬初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"夬来到二位，个人判断正与资源、规则或他人发生接触 当前拉扯在于：若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大果断表态与保护关系之间需要分寸 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“用事实、影响和请求表达立场”；若出现“用正义感放大敌意，而不是把在没有退路时逼对方立即回应当成解决办法，而夬第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，就暂停扩大动作。","classic":"惕號，莫夜有戎，勿恤。","source":"《周易》爻辞","modern":{"image":"“惕號，莫夜有戎，勿恤。”是夬在“接触”阶段留下的具体图景。","situation":"夬来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大果断表态与保护关系之间需要分寸。","warning":"用正义感放大敌意，而不是把在没有退路时逼对方立即回应当成解决办法，而夬第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","advice":["用事实、影响和请求表达立场。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在夬第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“怎样说清底线，同时仍给问题留下解决空间”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“用事实、影响和请求表达立场”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“用事实、影响和请求表达立场”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“用事实、影响和请求表达立场”，可以保持小步推进。","pause_if":"若出现“用正义感放大敌意，而不是把在没有退路时逼对方立即回应当成解决办法，而夬第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，先暂停扩大投入。"},"action":{"do":"用事实、影响和请求表达立场","review":"完成后记录夬九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻把变化落在具体环节：这一爻处在容易用力过度的位置，调整比加码更重要 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意用正义感放大敌意会在此时放大。","classic":"壯于頄，有凶。君子夬夬，獨行，遇雨若濡。有慍无咎。","source":"《周易》爻辞","modern":{"image":"“壯于頄，有凶。君子夬夬，獨行，遇雨若濡。有慍无咎。”是夬在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是果断表态与保护关系之间需要分寸，两者要放在同一次权衡里。","warning":"用正义感放大敌意会在此时放大。","advice":["用事实、影响和请求表达立场。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"止损","meaning":"在夬第3爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“怎样说清底线，同时仍给问题留下解决空间”核对判断"},"tone":"转折","extended":{"trigger":{"label":"止损","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“用正义感放大敌意会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录夬九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：局面已经接近新的层级，旧角色未必还能容纳当前变化 若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大果断表态与保护关系之间需要分寸 可以用“用事实、影响和请求表达立场”做一次验证；若用正义感放大敌意，行动应当收束。","classic":"臀无膚，其行次且，牽羊悔亡，聞言不信。","source":"《周易》爻辞","modern":{"image":"“臀无膚，其行次且，牽羊悔亡，聞言不信。”是夬在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大果断表态与保护关系之间需要分寸。","warning":"用正义感放大敌意。","advice":["用事实、影响和请求表达立场。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"修正","meaning":"在夬第4爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“怎样说清底线，同时仍给问题留下解决空间”核对判断"},"tone":"越界","extended":{"trigger":{"label":"修正","observe":"完成“用事实、影响和请求表达立场”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“用事实、影响和请求表达立场”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“用事实、影响和请求表达立场”，可以保持小步推进。","pause_if":"若出现“用正义感放大敌意”，先暂停扩大投入。"},"action":{"do":"用事实、影响和请求表达立场","review":"完成后记录夬九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"关键资源与决定权趋向集中，“表明与突破”开始影响更多人 当前拉扯在于：此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是果断表态与保护关系之间需要分寸，两者要放在同一次权衡里 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“用正义感放大敌意”，就暂停扩大动作。","classic":"莧陸夬夬，中行无咎。","source":"《周易》爻辞","modern":{"image":"“莧陸夬夬，中行无咎。”是夬在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“表明与突破”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是果断表态与保护关系之间需要分寸，两者要放在同一次权衡里。","warning":"用正义感放大敌意。","advice":["用事实、影响和请求表达立场。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"守正","meaning":"在夬第5爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“怎样说清底线，同时仍给问题留下解决空间”核对判断"},"tone":"担当","extended":{"trigger":{"label":"守正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“用正义感放大敌意”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录夬九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻把变化落在具体环节：夬来到上位，已有路径可能完成使命，也可能因过度而失衡 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“用事实、影响和请求表达立场”后再看反馈；同时留意用正义感放大敌意，而不是把在没有退路时逼对方立即回应当成解决办法，而夬第6爻处在“收束”阶段。","classic":"无號，終有凶。","source":"《周易》爻辞","modern":{"image":"“无號，終有凶。”是夬在“收束”阶段留下的具体图景。","situation":"夬来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大果断表态与保护关系之间需要分寸。","warning":"用正义感放大敌意，而不是把在没有退路时逼对方立即回应当成解决办法，而夬第6爻处在“收束”阶段。","advice":["用事实、影响和请求表达立场。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在夬第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“怎样说清底线，同时仍给问题留下解决空间”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“用事实、影响和请求表达立场”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“用事实、影响和请求表达立场”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“用事实、影响和请求表达立场”，可以保持小步推进。","pause_if":"若出现“用正义感放大敌意，而不是把在没有退路时逼对方立即回应当成解决办法，而夬第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"用事实、影响和请求表达立场","review":"完成后记录夬上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"该说清楚的事要明确，但表达不能变成攻击","strengths":["已经具备突破含混局面的条件","该说清楚的事可以坦荡说明。果断不等于攻击，保持尊重与边界"],"tensions":["果断表态与保护关系之间需要分寸"],"risks":["用正义感放大敌意"],"actions":["用事实、影响和请求表达立场"],"avoid":["在没有退路时逼对方立即回应"],"questions":["怎样说清底线，同时仍给问题留下解决空间？"],"extended":{"situation":{"direct":"眼下的重点是该说清楚的事要明确，但表达不能变成攻击。","support":"已经可以利用的是：已经具备突破含混局面的条件。","constraint":"仍需核实的是：果断表态与保护关系之间需要分寸。"},"relationship":{"inner":"下卦乾，内部动力偏向主动、原则与承担。","outer":"上卦兑，外部处境更受交流、回应与协商影响。","interaction":"内部想以“主动、原则与承担”回应外部的“交流、回应与协商”；两边能否对接，要看“果断表态与保护关系之间需要分寸”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“已经具备突破含混局面的条件”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“用事实、影响和请求表达立场”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“在没有退路时逼对方立即回应”，风险会被放大。","effect":"最需要防止的是：用正义感放大敌意。"},"paths":{"ready":"如果关键条件得到确认，可以继续“用事实、影响和请求表达立场”，但仍以小步反馈决定是否扩大。","not_ready":"如果“果断表态与保护关系之间需要分寸”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"用事实、影响和请求表达立场","observe":"怎样说清底线，同时仍给问题留下解决空间？","continue_if":"出现与“已经具备突破含混局面的条件”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“在没有退路时逼对方立即回应”或“用正义感放大敌意”的迹象。"}}}},{"id":44,"name":"姤","pinyin":"gòu","theme":"相遇与辨别","reflection":"突如其来的机会或关系，先观察是否真正契合，不急于投入。","source_note":"据《周易》姤卦意象整理","upper_trigram":1,"lower_trigram":5,"lines":{"1":{"title":"初六","interpretation":"姤落在初位，眼下更像在辨认方向，而不是兑现结果 当前拉扯在于：真正的拉扯来自吸引力和长期契合度尚未得到验证，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“因为新鲜感迅速投入过深”，就暂停扩大动作。","classic":"繫于金柅，貞吉。有攸往，見凶。羸豕孚蹢躅。","source":"《周易》爻辞","modern":{"image":"“繫于金柅，貞吉。有攸往，見凶。羸豕孚蹢躅。”是姤在“潜藏”阶段留下的具体图景。","situation":"姤落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自吸引力和长期契合度尚未得到验证，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"因为新鲜感迅速投入过深。","advice":["给新机会设置一个观察期。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"止损","meaning":"在姤第1爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“吸引你的究竟是它的价值，还是它出现得突然”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"止损","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“因为新鲜感迅速投入过深”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录姤初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一爻把变化落在具体环节：这一阶段不再只靠设想，回应和基本功开始决定走向 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“给新机会设置一个观察期”后再看反馈；同时留意因为新鲜感迅速投入过深。","classic":"包有魚，无咎，不利賓。","source":"《周易》爻辞","modern":{"image":"“包有魚，无咎，不利賓。”是姤在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而吸引力和长期契合度尚未得到验证也会在这一爻变得具体。","warning":"因为新鲜感迅速投入过深。","advice":["给新机会设置一个观察期。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"守正","meaning":"在姤第2爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“吸引你的究竟是它的价值，还是它出现得突然”核对判断"},"tone":"接触","extended":{"trigger":{"label":"守正","observe":"完成“给新机会设置一个观察期”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“给新机会设置一个观察期”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“给新机会设置一个观察期”，可以保持小步推进。","pause_if":"若出现“因为新鲜感迅速投入过深”，先暂停扩大投入。"},"action":{"do":"给新机会设置一个观察期","review":"完成后记录姤九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面正在显出边界：事情跨入转折带，焦虑可能比事实更快推动决定 真正的拉扯来自吸引力和长期契合度尚未得到验证，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若因为新鲜感迅速投入过深，而不是把忽略早期的不一致信号当成解决办法，而姤第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码，行动应当收束。","classic":"臀无膚，其行次且，厲，无大咎。","source":"《周易》爻辞","modern":{"image":"“臀无膚，其行次且，厲，无大咎。”是姤在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自吸引力和长期契合度尚未得到验证，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"因为新鲜感迅速投入过深，而不是把忽略早期的不一致信号当成解决办法，而姤第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","advice":["给新机会设置一个观察期。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在姤第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“吸引你的究竟是它的价值，还是它出现得突然”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“因为新鲜感迅速投入过深，而不是把忽略早期的不一致信号当成解决办法，而姤第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录姤九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"事情正由内部走向外部，“相遇与辨别”需要重新确认位置和权限 当前拉扯在于：向外推进的需要与边界尚未说清之间互相牵制，而吸引力和长期契合度尚未得到验证也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“给新机会设置一个观察期”；若出现“因为新鲜感迅速投入过深会在此时放大”，就暂停扩大动作。","classic":"包无魚，起凶。","source":"《周易》爻辞","modern":{"image":"“包无魚，起凶。”是姤在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“相遇与辨别”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而吸引力和长期契合度尚未得到验证也会在这一爻变得具体。","warning":"因为新鲜感迅速投入过深会在此时放大。","advice":["给新机会设置一个观察期。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"止损","meaning":"在姤第4爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“吸引你的究竟是它的价值，还是它出现得突然”核对判断"},"tone":"越界","extended":{"trigger":{"label":"止损","observe":"完成“给新机会设置一个观察期”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“给新机会设置一个观察期”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“给新机会设置一个观察期”，可以保持小步推进。","pause_if":"若出现“因为新鲜感迅速投入过深会在此时放大”，先暂停扩大投入。"},"action":{"do":"给新机会设置一个观察期","review":"完成后记录姤九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一爻把变化落在具体环节：姤来到五位，能力之外还要衡量整体承接和长期后果 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意因为新鲜感迅速投入过深。","classic":"以杞包瓜，含章，有隕自天。","source":"《周易》爻辞","modern":{"image":"“以杞包瓜，含章，有隕自天。”是姤在“担当”阶段留下的具体图景。","situation":"姤来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自吸引力和长期契合度尚未得到验证，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"因为新鲜感迅速投入过深。","advice":["给新机会设置一个观察期。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在姤第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“吸引你的究竟是它的价值，还是它出现得突然”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“因为新鲜感迅速投入过深”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录姤九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面正在显出边界：这一爻处在阶段末端，下一步先要判断什么已经结束 维持既有成果与允许阶段结束之间存在拉扯，而吸引力和长期契合度尚未得到验证也会在这一爻变得具体 可以用“给新机会设置一个观察期”做一次验证；若因为新鲜感迅速投入过深，行动应当收束。","classic":"姤其角，吝，无咎。","source":"《周易》爻辞","modern":{"image":"“姤其角，吝，无咎。”是姤在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而吸引力和长期契合度尚未得到验证也会在这一爻变得具体。","warning":"因为新鲜感迅速投入过深。","advice":["给新机会设置一个观察期。","列出应当停止、保留和移交的事项。"],"signal":{"label":"守正","meaning":"在姤第6爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“吸引你的究竟是它的价值，还是它出现得突然”核对判断"},"tone":"收束","extended":{"trigger":{"label":"守正","observe":"完成“给新机会设置一个观察期”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“给新机会设置一个观察期”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“给新机会设置一个观察期”，可以保持小步推进。","pause_if":"若出现“因为新鲜感迅速投入过深”，先暂停扩大投入。"},"action":{"do":"给新机会设置一个观察期","review":"完成后记录姤上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"突然出现的机会或关系，需要先辨别再靠近","strengths":["新刺激可能带来真实的变化窗口","突如其来的机会或关系，先观察是否真正契合，不急于投入"],"tensions":["吸引力和长期契合度尚未得到验证"],"risks":["因为新鲜感迅速投入过深"],"actions":["给新机会设置一个观察期"],"avoid":["忽略早期的不一致信号"],"questions":["吸引你的究竟是它的价值，还是它出现得突然？"],"extended":{"situation":{"direct":"眼下的重点是突然出现的机会或关系，需要先辨别再靠近。","support":"已经可以利用的是：新刺激可能带来真实的变化窗口。","constraint":"仍需核实的是：吸引力和长期契合度尚未得到验证。"},"relationship":{"inner":"下卦巽，内部动力偏向渗透、调整与持续影响。","outer":"上卦乾，外部处境更受主动、原则与承担影响。","interaction":"内部想以“渗透、调整与持续影响”回应外部的“主动、原则与承担”；两边能否对接，要看“吸引力和长期契合度尚未得到验证”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“新刺激可能带来真实的变化窗口”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“给新机会设置一个观察期”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“忽略早期的不一致信号”，风险会被放大。","effect":"最需要防止的是：因为新鲜感迅速投入过深。"},"paths":{"ready":"如果关键条件得到确认，可以继续“给新机会设置一个观察期”，但仍以小步反馈决定是否扩大。","not_ready":"如果“吸引力和长期契合度尚未得到验证”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"给新机会设置一个观察期","observe":"吸引你的究竟是它的价值，还是它出现得突然？","continue_if":"出现与“新刺激可能带来真实的变化窗口”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“忽略早期的不一致信号”或“因为新鲜感迅速投入过深”的迹象。"}}}},{"id":45,"name":"萃","pinyin":"cuì","theme":"汇聚与共识","reflection":"人和资源正在聚拢。明确目的和规则，才能让集体力量真正发挥。","source_note":"据《周易》萃卦意象整理","upper_trigram":2,"lower_trigram":8,"lines":{"1":{"title":"初六","interpretation":"这一爻把变化落在具体环节：这一爻处在起步处，“聚集只有在目标和规则清楚时才会形成合力”仍需低成本试探 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意把人数当成真正认同会在此时放大。","classic":"有孚不終，乃亂乃萃，若號。一握為笑，勿恤，往无咎。","source":"《周易》爻辞","modern":{"image":"“有孚不終，乃亂乃萃，若號。一握為笑，勿恤，往无咎。”是萃在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“聚集只有在目标和规则清楚时才会形成合力”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大规模扩大与共识质量之间可能脱节。","warning":"把人数当成真正认同会在此时放大。","advice":["在集合行动前确认共同目的和决策方式。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在萃第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“聚在一起之后，大家准备共同完成什么”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把人数当成真正认同会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录萃初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：局面正从内部准备转向真实互动，关系与条件逐渐可见 此时一面是自己的节奏需要与现实反馈相互校准，另一面是规模扩大与共识质量之间可能脱节，两者要放在同一次权衡里 可以用“在集合行动前确认共同目的和决策方式”做一次验证；若把人数当成真正认同，行动应当收束。","classic":"引吉，无咎，孚乃利用禴。","source":"《周易》爻辞","modern":{"image":"“引吉，无咎，孚乃利用禴。”是萃在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是规模扩大与共识质量之间可能脱节，两者要放在同一次权衡里。","warning":"把人数当成真正认同。","advice":["在集合行动前确认共同目的和决策方式。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在萃第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“聚在一起之后，大家准备共同完成什么”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“在集合行动前确认共同目的和决策方式”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“在集合行动前确认共同目的和决策方式”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“在集合行动前确认共同目的和决策方式”，可以保持小步推进。","pause_if":"若出现“把人数当成真正认同”，先暂停扩大投入。"},"action":{"do":"在集合行动前确认共同目的和决策方式","review":"完成后记录萃六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面来到内外转换处，“汇聚与共识”开始承受压力测试 当前拉扯在于：若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大规模扩大与共识质量之间可能脱节 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“把人数当成真正认同”，就暂停扩大动作。","classic":"萃如嗟如，无攸利。往无咎，小吝。","source":"《周易》爻辞","modern":{"image":"“萃如嗟如，无攸利。往无咎，小吝。”是萃在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“汇聚与共识”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大规模扩大与共识质量之间可能脱节。","warning":"把人数当成真正认同。","advice":["在集合行动前确认共同目的和决策方式。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"守正","meaning":"在萃第3爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“聚在一起之后，大家准备共同完成什么”核对判断"},"tone":"转折","extended":{"trigger":{"label":"守正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把人数当成真正认同”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录萃六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"这一爻把变化落在具体环节：萃来到四位，跨出原有边界之前要先说明责任 现实反馈与当前方向开始相互支持，是接下来值得核对的信号。完成“在集合行动前确认共同目的和决策方式”后再看反馈；同时留意把人数当成真正认同，而不是把让少数声音被热闹淹没当成解决办法，而萃第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位。","classic":"大吉，无咎。","source":"《周易》爻辞","modern":{"image":"“大吉，无咎。”是萃在“越界”阶段留下的具体图景。","situation":"萃来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是规模扩大与共识质量之间可能脱节，两者要放在同一次权衡里。","warning":"把人数当成真正认同，而不是把让少数声音被热闹淹没当成解决办法，而萃第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位。","advice":["在集合行动前确认共同目的和决策方式。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"顺势","meaning":"在萃第4爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“聚在一起之后，大家准备共同完成什么”核对判断"},"tone":"越界","extended":{"trigger":{"label":"顺势","observe":"完成“在集合行动前确认共同目的和决策方式”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“在集合行动前确认共同目的和决策方式”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“在集合行动前确认共同目的和决策方式”，可以保持小步推进。","pause_if":"若出现“把人数当成真正认同，而不是把让少数声音被热闹淹没当成解决办法，而萃第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位”，先暂停扩大投入。"},"action":{"do":"在集合行动前确认共同目的和决策方式","review":"完成后记录萃九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面正在显出边界：这一阶段已进入主位，选择会放大为规则或示范 若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大规模扩大与共识质量之间可能脱节 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若把人数当成真正认同会在此时放大，行动应当收束。","classic":"萃有位，无咎，匪孚。元永貞，悔亡。","source":"《周易》爻辞","modern":{"image":"“萃有位，无咎，匪孚。元永貞，悔亡。”是萃在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大规模扩大与共识质量之间可能脱节。","warning":"把人数当成真正认同会在此时放大。","advice":["在集合行动前确认共同目的和决策方式。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"守正","meaning":"在萃第5爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“聚在一起之后，大家准备共同完成什么”核对判断"},"tone":"担当","extended":{"trigger":{"label":"守正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把人数当成真正认同会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录萃九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"局面走到极处，继续延长旧办法未必带来同等收益 当前拉扯在于：此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是规模扩大与共识质量之间可能脱节，两者要放在同一次权衡里 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“在集合行动前确认共同目的和决策方式”；若出现“把人数当成真正认同”，就暂停扩大动作。","classic":"齎咨涕洟，无咎。","source":"《周易》爻辞","modern":{"image":"“齎咨涕洟，无咎。”是萃在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是规模扩大与共识质量之间可能脱节，两者要放在同一次权衡里。","warning":"把人数当成真正认同。","advice":["在集合行动前确认共同目的和决策方式。","列出应当停止、保留和移交的事项。"],"signal":{"label":"守正","meaning":"在萃第6爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“聚在一起之后，大家准备共同完成什么”核对判断"},"tone":"收束","extended":{"trigger":{"label":"守正","observe":"完成“在集合行动前确认共同目的和决策方式”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“在集合行动前确认共同目的和决策方式”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“在集合行动前确认共同目的和决策方式”，可以保持小步推进。","pause_if":"若出现“把人数当成真正认同”，先暂停扩大投入。"},"action":{"do":"在集合行动前确认共同目的和决策方式","review":"完成后记录萃上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"聚集只有在目标和规则清楚时才会形成合力","strengths":["人、信息或资源正在向同一处靠拢","人和资源正在聚拢。明确目的和规则，才能让集体力量真正发挥"],"tensions":["规模扩大与共识质量之间可能脱节"],"risks":["把人数当成真正认同"],"actions":["在集合行动前确认共同目的和决策方式"],"avoid":["让少数声音被热闹淹没"],"questions":["聚在一起之后，大家准备共同完成什么？"],"extended":{"situation":{"direct":"眼下的重点是聚集只有在目标和规则清楚时才会形成合力。","support":"已经可以利用的是：人、信息或资源正在向同一处靠拢。","constraint":"仍需核实的是：规模扩大与共识质量之间可能脱节。"},"relationship":{"inner":"下卦坤，内部动力偏向承载、配合与现实基础。","outer":"上卦兑，外部处境更受交流、回应与协商影响。","interaction":"内部想以“承载、配合与现实基础”回应外部的“交流、回应与协商”；两边能否对接，要看“规模扩大与共识质量之间可能脱节”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“人、信息或资源正在向同一处靠拢”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“在集合行动前确认共同目的和决策方式”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“让少数声音被热闹淹没”，风险会被放大。","effect":"最需要防止的是：把人数当成真正认同。"},"paths":{"ready":"如果关键条件得到确认，可以继续“在集合行动前确认共同目的和决策方式”，但仍以小步反馈决定是否扩大。","not_ready":"如果“规模扩大与共识质量之间可能脱节”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"在集合行动前确认共同目的和决策方式","observe":"聚在一起之后，大家准备共同完成什么？","continue_if":"出现与“人、信息或资源正在向同一处靠拢”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“让少数声音被热闹淹没”或“把人数当成真正认同”的迹象。"}}}},{"id":46,"name":"升","pinyin":"shēng","theme":"渐进与成长","reflection":"向上不必跳跃。持续投入、接受指导，稳步累积会带来变化。","source_note":"据《周易》升卦意象整理","upper_trigram":8,"lower_trigram":5,"lines":{"1":{"title":"初六","interpretation":"局面正在显出边界：变化尚在根部，先分清已经发生的事实和仍在期待的部分 内在意愿已经出现，外部条件尚未完全成形，而渴望跃迁与实际积累速度不一致也会在这一爻变得具体 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若只盯结果而跳过基础练习，而不是把频繁比较导致节奏失真当成解决办法，而升第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论，行动应当收束。","classic":"允升，大吉。","source":"《周易》爻辞","modern":{"image":"“允升，大吉。”是升在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而渴望跃迁与实际积累速度不一致也会在这一爻变得具体。","warning":"只盯结果而跳过基础练习，而不是把频繁比较导致节奏失真当成解决办法，而升第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["确认下一阶需要的具体能力并练习。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"顺势","meaning":"在升第1爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“下一阶真正要求你会什么，而不只是拥有什么”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"顺势","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“只盯结果而跳过基础练习，而不是把频繁比较导致节奏失真当成解决办法，而升第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录升初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"事情开始进入现实协作，“渐进与成长”要接受反馈检验 当前拉扯在于：真正的拉扯来自渴望跃迁与实际积累速度不一致，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“确认下一阶需要的具体能力并练习”；若出现“只盯结果而跳过基础练习会在此时放大”，就暂停扩大动作。","classic":"孚乃利用禴，无咎。","source":"《周易》爻辞","modern":{"image":"“孚乃利用禴，无咎。”是升在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“渐进与成长”要接受反馈检验。","tension":"真正的拉扯来自渴望跃迁与实际积累速度不一致，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"只盯结果而跳过基础练习会在此时放大。","advice":["确认下一阶需要的具体能力并练习。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"守正","meaning":"在升第2爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“下一阶真正要求你会什么，而不只是拥有什么”核对判断"},"tone":"接触","extended":{"trigger":{"label":"守正","observe":"完成“确认下一阶需要的具体能力并练习”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“确认下一阶需要的具体能力并练习”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“确认下一阶需要的具体能力并练习”，可以保持小步推进。","pause_if":"若出现“只盯结果而跳过基础练习会在此时放大”，先暂停扩大投入。"},"action":{"do":"确认下一阶需要的具体能力并练习","review":"完成后记录升九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻把变化落在具体环节：升行至三位，旧方法的边界和新选择的代价同时出现 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意只盯结果而跳过基础练习。","classic":"升虛邑。","source":"《周易》爻辞","modern":{"image":"“升虛邑。”是升在“转折”阶段留下的具体图景。","situation":"升行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而渴望跃迁与实际积累速度不一致也会在这一爻变得具体。","warning":"只盯结果而跳过基础练习。","advice":["确认下一阶需要的具体能力并练习。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在升第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“下一阶真正要求你会什么，而不只是拥有什么”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“只盯结果而跳过基础练习”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录升九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"局面正在显出边界：这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 真正的拉扯来自渴望跃迁与实际积累速度不一致，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题 可以用“确认下一阶需要的具体能力并练习”做一次验证；若只盯结果而跳过基础练习，行动应当收束。","classic":"王用亨于岐山，吉，无咎。","source":"《周易》爻辞","modern":{"image":"“王用亨于岐山，吉，无咎。”是升在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自渴望跃迁与实际积累速度不一致，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"只盯结果而跳过基础练习。","advice":["确认下一阶需要的具体能力并练习。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在升第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“下一阶真正要求你会什么，而不只是拥有什么”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“确认下一阶需要的具体能力并练习”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“确认下一阶需要的具体能力并练习”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“确认下一阶需要的具体能力并练习”，可以保持小步推进。","pause_if":"若出现“只盯结果而跳过基础练习”，先暂停扩大投入。"},"action":{"do":"确认下一阶需要的具体能力并练习","review":"完成后记录升六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"局面要求从个人得失转向整体结果和持续责任 当前拉扯在于：扩大影响与照顾整体承接能力之间需要平衡，而渴望跃迁与实际积累速度不一致也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“只盯结果而跳过基础练习，而不是把频繁比较导致节奏失真当成解决办法，而升第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，就暂停扩大动作。","classic":"貞吉，升階。","source":"《周易》爻辞","modern":{"image":"“貞吉，升階。”是升在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而渴望跃迁与实际积累速度不一致也会在这一爻变得具体。","warning":"只盯结果而跳过基础练习，而不是把频繁比较导致节奏失真当成解决办法，而升第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["确认下一阶需要的具体能力并练习。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在升第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“下一阶真正要求你会什么，而不只是拥有什么”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“只盯结果而跳过基础练习，而不是把频繁比较导致节奏失真当成解决办法，而升第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录升六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻把变化落在具体环节：当前循环接近上限，“渐进与成长”需要从继续加力转向收束复盘 关键条件开始出现可利用的现实回应，是接下来值得核对的信号。完成“确认下一阶需要的具体能力并练习”后再看反馈；同时留意只盯结果而跳过基础练习会在此时放大。","classic":"冥升，利于不息之貞。","source":"《周易》爻辞","modern":{"image":"“冥升，利于不息之貞。”是升在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“渐进与成长”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自渴望跃迁与实际积累速度不一致，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"只盯结果而跳过基础练习会在此时放大。","advice":["确认下一阶需要的具体能力并练习。","列出应当停止、保留和移交的事项。"],"signal":{"label":"有利","meaning":"在升第6爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“下一阶真正要求你会什么，而不只是拥有什么”核对判断"},"tone":"收束","extended":{"trigger":{"label":"有利","observe":"完成“确认下一阶需要的具体能力并练习”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“确认下一阶需要的具体能力并练习”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“确认下一阶需要的具体能力并练习”，可以保持小步推进。","pause_if":"若出现“只盯结果而跳过基础练习会在此时放大”，先暂停扩大投入。"},"action":{"do":"确认下一阶需要的具体能力并练习","review":"完成后记录升上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"向上成长依赖持续投入、指导和可见台阶","strengths":["当前存在逐步提升的路径","向上不必跳跃。持续投入、接受指导，稳步累积会带来变化"],"tensions":["渴望跃迁与实际积累速度不一致"],"risks":["只盯结果而跳过基础练习"],"actions":["确认下一阶需要的具体能力并练习"],"avoid":["频繁比较导致节奏失真"],"questions":["下一阶真正要求你会什么，而不只是拥有什么？"],"extended":{"situation":{"direct":"眼下的重点是向上成长依赖持续投入、指导和可见台阶。","support":"已经可以利用的是：当前存在逐步提升的路径。","constraint":"仍需核实的是：渴望跃迁与实际积累速度不一致。"},"relationship":{"inner":"下卦巽，内部动力偏向渗透、调整与持续影响。","outer":"上卦坤，外部处境更受承载、配合与现实基础影响。","interaction":"内部想以“渗透、调整与持续影响”回应外部的“承载、配合与现实基础”；两边能否对接，要看“渴望跃迁与实际积累速度不一致”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“当前存在逐步提升的路径”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“确认下一阶需要的具体能力并练习”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“频繁比较导致节奏失真”，风险会被放大。","effect":"最需要防止的是：只盯结果而跳过基础练习。"},"paths":{"ready":"如果关键条件得到确认，可以继续“确认下一阶需要的具体能力并练习”，但仍以小步反馈决定是否扩大。","not_ready":"如果“渴望跃迁与实际积累速度不一致”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"确认下一阶需要的具体能力并练习","observe":"下一阶真正要求你会什么，而不只是拥有什么？","continue_if":"出现与“当前存在逐步提升的路径”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“频繁比较导致节奏失真”或“只盯结果而跳过基础练习”的迹象。"}}}},{"id":47,"name":"困","pinyin":"kùn","theme":"受限与守心","reflection":"资源有限时，先守住核心需求。说出困难，接受可信赖的支持。","source_note":"据《周易》困卦意象整理","upper_trigram":2,"lower_trigram":6,"lines":{"1":{"title":"初六","interpretation":"事情刚在“受限与守心”的起点露出端倪，可用条件还不多 当前拉扯在于：此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是独自承受与寻求支持之间存在阻力，两者要放在同一次权衡里 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“因羞耻而隐藏已经影响功能的困难”，就暂停扩大动作。","classic":"臀困于株木，入于幽谷，三歲不覿。","source":"《周易》爻辞","modern":{"image":"“臀困于株木，入于幽谷，三歲不覿。”是困在“潜藏”阶段留下的具体图景。","situation":"事情刚在“受限与守心”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是独自承受与寻求支持之间存在阻力，两者要放在同一次权衡里。","warning":"因羞耻而隐藏已经影响功能的困难。","advice":["向可信的人说明一个具体限制和需要。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"观察","meaning":"在困第1爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“在资源有限时，什么必须优先被照顾”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"观察","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“因羞耻而隐藏已经影响功能的困难”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录困初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一爻把变化落在具体环节：困来到二位，个人判断正与资源、规则或他人发生接触 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“向可信的人说明一个具体限制和需要”后再看反馈；同时留意因羞耻而隐藏已经影响功能的困难，而不是把把所有问题归咎于自身意志当成解决办法，而困第2爻处在“接触”阶段。","classic":"困于酒食，朱紱方來，利用享祀，征凶，无咎。","source":"《周易》爻辞","modern":{"image":"“困于酒食，朱紱方來，利用享祀，征凶，无咎。”是困在“接触”阶段留下的具体图景。","situation":"困来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大独自承受与寻求支持之间存在阻力。","warning":"因羞耻而隐藏已经影响功能的困难，而不是把把所有问题归咎于自身意志当成解决办法，而困第2爻处在“接触”阶段。","advice":["向可信的人说明一个具体限制和需要。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"止损","meaning":"在困第2爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“在资源有限时，什么必须优先被照顾”核对判断"},"tone":"接触","extended":{"trigger":{"label":"止损","observe":"完成“向可信的人说明一个具体限制和需要”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“向可信的人说明一个具体限制和需要”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“向可信的人说明一个具体限制和需要”，可以保持小步推进。","pause_if":"若出现“因羞耻而隐藏已经影响功能的困难，而不是把把所有问题归咎于自身意志当成解决办法，而困第2爻处在“接触”阶段”，先暂停扩大投入。"},"action":{"do":"向可信的人说明一个具体限制和需要","review":"完成后记录困九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面正在显出边界：这一爻处在容易用力过度的位置，调整比加码更重要 此时一面是继续原路与承认需要调整之间发生冲突，另一面是独自承受与寻求支持之间存在阻力，两者要放在同一次权衡里 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若因羞耻而隐藏已经影响功能的困难会在此时放大，行动应当收束。","classic":"困于石，據于蒺蔾，入于其宮，不見其妻，凶。","source":"《周易》爻辞","modern":{"image":"“困于石，據于蒺蔾，入于其宮，不見其妻，凶。”是困在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是独自承受与寻求支持之间存在阻力，两者要放在同一次权衡里。","warning":"因羞耻而隐藏已经影响功能的困难会在此时放大。","advice":["向可信的人说明一个具体限制和需要。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"止损","meaning":"在困第3爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“在资源有限时，什么必须优先被照顾”核对判断"},"tone":"转折","extended":{"trigger":{"label":"止损","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“因羞耻而隐藏已经影响功能的困难会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录困六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面已经接近新的层级，旧角色未必还能容纳当前变化 当前拉扯在于：若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大独自承受与寻求支持之间存在阻力 当原有做法显出明确代价，需要及时调整时，变化才有现实依据。先做“向可信的人说明一个具体限制和需要”；若出现“因羞耻而隐藏已经影响功能的困难”，就暂停扩大动作。","classic":"來徐徐，困于金車。吝，有終。","source":"《周易》爻辞","modern":{"image":"“來徐徐，困于金車。吝，有終。”是困在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大独自承受与寻求支持之间存在阻力。","warning":"因羞耻而隐藏已经影响功能的困难。","advice":["向可信的人说明一个具体限制和需要。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"修正","meaning":"在困第4爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“在资源有限时，什么必须优先被照顾”核对判断"},"tone":"越界","extended":{"trigger":{"label":"修正","observe":"完成“向可信的人说明一个具体限制和需要”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“向可信的人说明一个具体限制和需要”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“向可信的人说明一个具体限制和需要”，可以保持小步推进。","pause_if":"若出现“因羞耻而隐藏已经影响功能的困难”，先暂停扩大投入。"},"action":{"do":"向可信的人说明一个具体限制和需要","review":"完成后记录困九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一爻把变化落在具体环节：关键资源与决定权趋向集中，“受限与守心”开始影响更多人 关键条件开始出现可利用的现实回应，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意因羞耻而隐藏已经影响功能的困难。","classic":"劓刖，困于赤紱，乃徐有說。利用祭祀。","source":"《周易》爻辞","modern":{"image":"“劓刖，困于赤紱，乃徐有說。利用祭祀。”是困在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“受限与守心”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是独自承受与寻求支持之间存在阻力，两者要放在同一次权衡里。","warning":"因羞耻而隐藏已经影响功能的困难。","advice":["向可信的人说明一个具体限制和需要。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"有利","meaning":"在困第5爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“在资源有限时，什么必须优先被照顾”核对判断"},"tone":"担当","extended":{"trigger":{"label":"有利","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“因羞耻而隐藏已经影响功能的困难”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录困九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"局面正在显出边界：困来到上位，已有路径可能完成使命，也可能因过度而失衡 若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大独自承受与寻求支持之间存在阻力 可以用“向可信的人说明一个具体限制和需要”做一次验证；若因羞耻而隐藏已经影响功能的困难，而不是把把所有问题归咎于自身意志当成解决办法，而困第6爻处在“收束”阶段，行动应当收束。","classic":"困于葛藟，于臲卼，曰動悔有悔，征吉。","source":"《周易》爻辞","modern":{"image":"“困于葛藟，于臲卼，曰動悔有悔，征吉。”是困在“收束”阶段留下的具体图景。","situation":"困来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大独自承受与寻求支持之间存在阻力。","warning":"因羞耻而隐藏已经影响功能的困难，而不是把把所有问题归咎于自身意志当成解决办法，而困第6爻处在“收束”阶段。","advice":["向可信的人说明一个具体限制和需要。","列出应当停止、保留和移交的事项。"],"signal":{"label":"可行","meaning":"在困第6爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“在资源有限时，什么必须优先被照顾”核对判断"},"tone":"收束","extended":{"trigger":{"label":"可行","observe":"完成“向可信的人说明一个具体限制和需要”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“向可信的人说明一个具体限制和需要”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“向可信的人说明一个具体限制和需要”，可以保持小步推进。","pause_if":"若出现“因羞耻而隐藏已经影响功能的困难，而不是把把所有问题归咎于自身意志当成解决办法，而困第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"向可信的人说明一个具体限制和需要","review":"完成后记录困上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"受限时期先守住核心需求，也要让困难被看见","strengths":["即使资源有限，仍能保留价值和判断","资源有限时，先守住核心需求。说出困难，接受可信赖的支持"],"tensions":["独自承受与寻求支持之间存在阻力"],"risks":["因羞耻而隐藏已经影响功能的困难"],"actions":["向可信的人说明一个具体限制和需要"],"avoid":["把所有问题归咎于自身意志"],"questions":["在资源有限时，什么必须优先被照顾？"],"extended":{"situation":{"direct":"眼下的重点是受限时期先守住核心需求，也要让困难被看见。","support":"已经可以利用的是：即使资源有限，仍能保留价值和判断。","constraint":"仍需核实的是：独自承受与寻求支持之间存在阻力。"},"relationship":{"inner":"下卦坎，内部动力偏向风险、试探与信息缺口。","outer":"上卦兑，外部处境更受交流、回应与协商影响。","interaction":"内部想以“风险、试探与信息缺口”回应外部的“交流、回应与协商”；两边能否对接，要看“独自承受与寻求支持之间存在阻力”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“即使资源有限，仍能保留价值和判断”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“向可信的人说明一个具体限制和需要”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把所有问题归咎于自身意志”，风险会被放大。","effect":"最需要防止的是：因羞耻而隐藏已经影响功能的困难。"},"paths":{"ready":"如果关键条件得到确认，可以继续“向可信的人说明一个具体限制和需要”，但仍以小步反馈决定是否扩大。","not_ready":"如果“独自承受与寻求支持之间存在阻力”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"向可信的人说明一个具体限制和需要","observe":"在资源有限时，什么必须优先被照顾？","continue_if":"出现与“即使资源有限，仍能保留价值和判断”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把所有问题归咎于自身意志”或“因羞耻而隐藏已经影响功能的困难”的迹象。"}}}},{"id":48,"name":"井","pinyin":"jǐng","theme":"根基与共享","reflection":"回到长期可用的资源和能力。修好基础设施，再谈更大的扩张。","source_note":"据《周易》井卦意象整理","upper_trigram":6,"lower_trigram":5,"lines":{"1":{"title":"初六","interpretation":"这一爻把变化落在具体环节：井落在初位，眼下更像在辨认方向，而不是兑现结果 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意只取用却不维护。","classic":"井泥不食，舊井无禽。","source":"《周易》爻辞","modern":{"image":"“井泥不食，舊井无禽。”是井在“潜藏”阶段留下的具体图景。","situation":"井落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自使用现成资源与更新基础设施之间需要平衡，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"只取用却不维护。","advice":["修复一个反复影响效率的基础环节。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"观察","meaning":"在井第1爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么基础一旦修好，会长期帮助许多人”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"观察","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“只取用却不维护”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录井初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"局面正在显出边界：这一阶段不再只靠设想，回应和基本功开始决定走向 自己的节奏需要与现实反馈相互校准，而使用现成资源与更新基础设施之间需要平衡也会在这一爻变得具体 可以用“修复一个反复影响效率的基础环节”做一次验证；若只取用却不维护，行动应当收束。","classic":"井谷射鮒，甕敝漏。","source":"《周易》爻辞","modern":{"image":"“井谷射鮒，甕敝漏。”是井在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而使用现成资源与更新基础设施之间需要平衡也会在这一爻变得具体。","warning":"只取用却不维护。","advice":["修复一个反复影响效率的基础环节。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在井第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么基础一旦修好，会长期帮助许多人”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“修复一个反复影响效率的基础环节”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“修复一个反复影响效率的基础环节”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“修复一个反复影响效率的基础环节”，可以保持小步推进。","pause_if":"若出现“只取用却不维护”，先暂停扩大投入。"},"action":{"do":"修复一个反复影响效率的基础环节","review":"完成后记录井九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"事情跨入转折带，焦虑可能比事实更快推动决定 当前拉扯在于：真正的拉扯来自使用现成资源与更新基础设施之间需要平衡，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“只取用却不维护，而不是把在根基失修时追求表面扩张当成解决办法，而井第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，就暂停扩大动作。","classic":"井渫不食，為我心惻，可用汲。王明，並受其福。","source":"《周易》爻辞","modern":{"image":"“井渫不食，為我心惻，可用汲。王明，並受其福。”是井在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自使用现成资源与更新基础设施之间需要平衡，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"只取用却不维护，而不是把在根基失修时追求表面扩张当成解决办法，而井第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","advice":["修复一个反复影响效率的基础环节。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在井第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么基础一旦修好，会长期帮助许多人”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“只取用却不维护，而不是把在根基失修时追求表面扩张当成解决办法，而井第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录井九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：事情正由内部走向外部，“根基与共享”需要重新确认位置和权限 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“修复一个反复影响效率的基础环节”后再看反馈；同时留意只取用却不维护会在此时放大。","classic":"井甃无咎。","source":"《周易》爻辞","modern":{"image":"“井甃无咎。”是井在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“根基与共享”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而使用现成资源与更新基础设施之间需要平衡也会在这一爻变得具体。","warning":"只取用却不维护会在此时放大。","advice":["修复一个反复影响效率的基础环节。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在井第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“什么基础一旦修好，会长期帮助许多人”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“修复一个反复影响效率的基础环节”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“修复一个反复影响效率的基础环节”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“修复一个反复影响效率的基础环节”，可以保持小步推进。","pause_if":"若出现“只取用却不维护会在此时放大”，先暂停扩大投入。"},"action":{"do":"修复一个反复影响效率的基础环节","review":"完成后记录井六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面正在显出边界：井来到五位，能力之外还要衡量整体承接和长期后果 真正的拉扯来自使用现成资源与更新基础设施之间需要平衡，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若只取用却不维护，行动应当收束。","classic":"井洌，寒泉食。","source":"《周易》爻辞","modern":{"image":"“井洌，寒泉食。”是井在“担当”阶段留下的具体图景。","situation":"井来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自使用现成资源与更新基础设施之间需要平衡，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"只取用却不维护。","advice":["修复一个反复影响效率的基础环节。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在井第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么基础一旦修好，会长期帮助许多人”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“只取用却不维护”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录井九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻处在阶段末端，下一步先要判断什么已经结束 当前拉扯在于：维持既有成果与允许阶段结束之间存在拉扯，而使用现成资源与更新基础设施之间需要平衡也会在这一爻变得具体 当现实反馈与当前方向开始相互支持时，变化才有现实依据。先做“修复一个反复影响效率的基础环节”；若出现“只取用却不维护”，就暂停扩大动作。","classic":"井收勿幕，有孚元吉。","source":"《周易》爻辞","modern":{"image":"“井收勿幕，有孚元吉。”是井在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而使用现成资源与更新基础设施之间需要平衡也会在这一爻变得具体。","warning":"只取用却不维护。","advice":["修复一个反复影响效率的基础环节。","列出应当停止、保留和移交的事项。"],"signal":{"label":"顺势","meaning":"在井第6爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“什么基础一旦修好，会长期帮助许多人”核对判断"},"tone":"收束","extended":{"trigger":{"label":"顺势","observe":"完成“修复一个反复影响效率的基础环节”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“修复一个反复影响效率的基础环节”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“修复一个反复影响效率的基础环节”，可以保持小步推进。","pause_if":"若出现“只取用却不维护”，先暂停扩大投入。"},"action":{"do":"修复一个反复影响效率的基础环节","review":"完成后记录井上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"长期可用的基础资源需要维护并公平共享","strengths":["已有经验、系统或关系可以持续供给","回到长期可用的资源和能力。修好基础设施，再谈更大的扩张"],"tensions":["使用现成资源与更新基础设施之间需要平衡"],"risks":["只取用却不维护"],"actions":["修复一个反复影响效率的基础环节"],"avoid":["在根基失修时追求表面扩张"],"questions":["什么基础一旦修好，会长期帮助许多人？"],"extended":{"situation":{"direct":"眼下的重点是长期可用的基础资源需要维护并公平共享。","support":"已经可以利用的是：已有经验、系统或关系可以持续供给。","constraint":"仍需核实的是：使用现成资源与更新基础设施之间需要平衡。"},"relationship":{"inner":"下卦巽，内部动力偏向渗透、调整与持续影响。","outer":"上卦坎，外部处境更受风险、试探与信息缺口影响。","interaction":"内部想以“渗透、调整与持续影响”回应外部的“风险、试探与信息缺口”；两边能否对接，要看“使用现成资源与更新基础设施之间需要平衡”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“已有经验、系统或关系可以持续供给”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“修复一个反复影响效率的基础环节”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“在根基失修时追求表面扩张”，风险会被放大。","effect":"最需要防止的是：只取用却不维护。"},"paths":{"ready":"如果关键条件得到确认，可以继续“修复一个反复影响效率的基础环节”，但仍以小步反馈决定是否扩大。","not_ready":"如果“使用现成资源与更新基础设施之间需要平衡”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"修复一个反复影响效率的基础环节","observe":"什么基础一旦修好，会长期帮助许多人？","continue_if":"出现与“已有经验、系统或关系可以持续供给”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“在根基失修时追求表面扩张”或“只取用却不维护”的迹象。"}}}},{"id":49,"name":"革","pinyin":"gé","theme":"变革与时机","reflection":"改变需要理由、共识与时机。先沟通必要性，再坚定执行。","source_note":"据《周易》革卦意象整理","upper_trigram":2,"lower_trigram":3,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：这一爻处在起步处，“改变需要真实理由、适当时机和可承接的共识”仍需低成本试探 若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大变革速度与相关者适应能力不一致 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若把不满直接等同于必须推翻会在此时放大，行动应当收束。","classic":"鞏用黃牛之革。","source":"《周易》爻辞","modern":{"image":"“鞏用黃牛之革。”是革在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“改变需要真实理由、适当时机和可承接的共识”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大变革速度与相关者适应能力不一致。","warning":"把不满直接等同于必须推翻会在此时放大。","advice":["说明不改变的代价和改变的过渡方案。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"观察","meaning":"在革第1爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么证据说明现在确实到了改变的时候”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"观察","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把不满直接等同于必须推翻会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录革初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正从内部准备转向真实互动，关系与条件逐渐可见 当前拉扯在于：此时一面是自己的节奏需要与现实反馈相互校准，另一面是变革速度与相关者适应能力不一致，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“说明不改变的代价和改变的过渡方案”；若出现“把不满直接等同于必须推翻”，就暂停扩大动作。","classic":"已日乃革之，征吉，无咎。","source":"《周易》爻辞","modern":{"image":"“已日乃革之，征吉，无咎。”是革在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是变革速度与相关者适应能力不一致，两者要放在同一次权衡里。","warning":"把不满直接等同于必须推翻。","advice":["说明不改变的代价和改变的过渡方案。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在革第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“什么证据说明现在确实到了改变的时候”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“说明不改变的代价和改变的过渡方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“说明不改变的代价和改变的过渡方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“说明不改变的代价和改变的过渡方案”，可以保持小步推进。","pause_if":"若出现“把不满直接等同于必须推翻”，先暂停扩大投入。"},"action":{"do":"说明不改变的代价和改变的过渡方案","review":"完成后记录革六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻把变化落在具体环节：局面来到内外转换处，“变革与时机”开始承受压力测试 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意把不满直接等同于必须推翻。","classic":"征凶，貞厲，革言三就，有孚。","source":"《周易》爻辞","modern":{"image":"“征凶，貞厲，革言三就，有孚。”是革在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“变革与时机”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大变革速度与相关者适应能力不一致。","warning":"把不满直接等同于必须推翻。","advice":["说明不改变的代价和改变的过渡方案。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"止损","meaning":"在革第3爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“什么证据说明现在确实到了改变的时候”核对判断"},"tone":"转折","extended":{"trigger":{"label":"止损","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把不满直接等同于必须推翻”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录革九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：革来到四位，跨出原有边界之前要先说明责任 此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是变革速度与相关者适应能力不一致，两者要放在同一次权衡里 可以用“说明不改变的代价和改变的过渡方案”做一次验证；若把不满直接等同于必须推翻，而不是把只宣布新方向却不处理旧结构当成解决办法，而革第4爻处在“越界”阶段，行动应当收束。","classic":"悔亡，有孚，改命吉。","source":"《周易》爻辞","modern":{"image":"“悔亡，有孚，改命吉。”是革在“越界”阶段留下的具体图景。","situation":"革来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是变革速度与相关者适应能力不一致，两者要放在同一次权衡里。","warning":"把不满直接等同于必须推翻，而不是把只宣布新方向却不处理旧结构当成解决办法，而革第4爻处在“越界”阶段。","advice":["说明不改变的代价和改变的过渡方案。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在革第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“什么证据说明现在确实到了改变的时候”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“说明不改变的代价和改变的过渡方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“说明不改变的代价和改变的过渡方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“说明不改变的代价和改变的过渡方案”，可以保持小步推进。","pause_if":"若出现“把不满直接等同于必须推翻，而不是把只宣布新方向却不处理旧结构当成解决办法，而革第4爻处在“越界”阶段”，先暂停扩大投入。"},"action":{"do":"说明不改变的代价和改变的过渡方案","review":"完成后记录革九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一阶段已进入主位，选择会放大为规则或示范 当前拉扯在于：若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大变革速度与相关者适应能力不一致 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“把不满直接等同于必须推翻会在此时放大”，就暂停扩大动作。","classic":"大人虎變，未占有孚。","source":"《周易》爻辞","modern":{"image":"“大人虎變，未占有孚。”是革在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大变革速度与相关者适应能力不一致。","warning":"把不满直接等同于必须推翻会在此时放大。","advice":["说明不改变的代价和改变的过渡方案。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在革第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么证据说明现在确实到了改变的时候”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把不满直接等同于必须推翻会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录革九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻把变化落在具体环节：局面走到极处，继续延长旧办法未必带来同等收益 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“说明不改变的代价和改变的过渡方案”后再看反馈；同时留意把不满直接等同于必须推翻。","classic":"君子豹變，小人革面，征凶，居貞吉。","source":"《周易》爻辞","modern":{"image":"“君子豹變，小人革面，征凶，居貞吉。”是革在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是变革速度与相关者适应能力不一致，两者要放在同一次权衡里。","warning":"把不满直接等同于必须推翻。","advice":["说明不改变的代价和改变的过渡方案。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在革第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“什么证据说明现在确实到了改变的时候”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“说明不改变的代价和改变的过渡方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“说明不改变的代价和改变的过渡方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“说明不改变的代价和改变的过渡方案”，可以保持小步推进。","pause_if":"若出现“把不满直接等同于必须推翻”，先暂停扩大投入。"},"action":{"do":"说明不改变的代价和改变的过渡方案","review":"完成后记录革上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"改变需要真实理由、适当时机和可承接的共识","strengths":["旧方式已经出现需要更新的证据","改变需要理由、共识与时机。先沟通必要性，再坚定执行"],"tensions":["变革速度与相关者适应能力不一致"],"risks":["把不满直接等同于必须推翻"],"actions":["说明不改变的代价和改变的过渡方案"],"avoid":["只宣布新方向却不处理旧结构"],"questions":["什么证据说明现在确实到了改变的时候？"],"extended":{"situation":{"direct":"眼下的重点是改变需要真实理由、适当时机和可承接的共识。","support":"已经可以利用的是：旧方式已经出现需要更新的证据。","constraint":"仍需核实的是：变革速度与相关者适应能力不一致。"},"relationship":{"inner":"下卦离，内部动力偏向辨识、表达与显明。","outer":"上卦兑，外部处境更受交流、回应与协商影响。","interaction":"内部想以“辨识、表达与显明”回应外部的“交流、回应与协商”；两边能否对接，要看“变革速度与相关者适应能力不一致”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“旧方式已经出现需要更新的证据”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“说明不改变的代价和改变的过渡方案”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“只宣布新方向却不处理旧结构”，风险会被放大。","effect":"最需要防止的是：把不满直接等同于必须推翻。"},"paths":{"ready":"如果关键条件得到确认，可以继续“说明不改变的代价和改变的过渡方案”，但仍以小步反馈决定是否扩大。","not_ready":"如果“变革速度与相关者适应能力不一致”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"说明不改变的代价和改变的过渡方案","observe":"什么证据说明现在确实到了改变的时候？","continue_if":"出现与“旧方式已经出现需要更新的证据”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“只宣布新方向却不处理旧结构”或“把不满直接等同于必须推翻”的迹象。"}}}},{"id":50,"name":"鼎","pinyin":"dǐng","theme":"转化与成器","reflection":"把经验慢慢熬成能力。重视过程中的协作与品质，成果会更有价值。","source_note":"据《周易》鼎卦意象整理","upper_trigram":3,"lower_trigram":5,"lines":{"1":{"title":"初六","interpretation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分 当前拉扯在于：内在意愿已经出现，外部条件尚未完全成形，而追求成果与打磨过程之间需要耐心也会在这一爻变得具体 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“把形式上的完成当成真正成熟，而不是把频繁换方法打断积累当成解决办法，而鼎第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，就暂停扩大动作。","classic":"鼎顛趾，利出否，得妾以其子，无咎。","source":"《周易》爻辞","modern":{"image":"“鼎顛趾，利出否，得妾以其子，无咎。”是鼎在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而追求成果与打磨过程之间需要耐心也会在这一爻变得具体。","warning":"把形式上的完成当成真正成熟，而不是把频繁换方法打断积累当成解决办法，而鼎第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["选择一个关键过程建立质量标准。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在鼎第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“哪些经验已经可以被整理成稳定的方法”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“把形式上的完成当成真正成熟，而不是把频繁换方法打断积累当成解决办法，而鼎第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录鼎初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一爻把变化落在具体环节：事情开始进入现实协作，“转化与成器”要接受反馈检验 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“选择一个关键过程建立质量标准”后再看反馈；同时留意把形式上的完成当成真正成熟会在此时放大。","classic":"鼎有實，我仇有疾，不我能即，吉。","source":"《周易》爻辞","modern":{"image":"“鼎有實，我仇有疾，不我能即，吉。”是鼎在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“转化与成器”要接受反馈检验。","tension":"真正的拉扯来自追求成果与打磨过程之间需要耐心，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"把形式上的完成当成真正成熟会在此时放大。","advice":["选择一个关键过程建立质量标准。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在鼎第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪些经验已经可以被整理成稳定的方法”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“选择一个关键过程建立质量标准”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“选择一个关键过程建立质量标准”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选择一个关键过程建立质量标准”，可以保持小步推进。","pause_if":"若出现“把形式上的完成当成真正成熟会在此时放大”，先暂停扩大投入。"},"action":{"do":"选择一个关键过程建立质量标准","review":"完成后记录鼎九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面正在显出边界：鼎行至三位，旧方法的边界和新选择的代价同时出现 继续原路与承认需要调整之间发生冲突，而追求成果与打磨过程之间需要耐心也会在这一爻变得具体 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若把形式上的完成当成真正成熟，行动应当收束。","classic":"鼎耳革，其行塞，雉膏不食。方雨虧悔，終吉。","source":"《周易》爻辞","modern":{"image":"“鼎耳革，其行塞，雉膏不食。方雨虧悔，終吉。”是鼎在“转折”阶段留下的具体图景。","situation":"鼎行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而追求成果与打磨过程之间需要耐心也会在这一爻变得具体。","warning":"把形式上的完成当成真正成熟。","advice":["选择一个关键过程建立质量标准。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"可行","meaning":"在鼎第3爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪些经验已经可以被整理成稳定的方法”核对判断"},"tone":"转折","extended":{"trigger":{"label":"可行","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“把形式上的完成当成真正成熟”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录鼎九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 当前拉扯在于：真正的拉扯来自追求成果与打磨过程之间需要耐心，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“选择一个关键过程建立质量标准”；若出现“把形式上的完成当成真正成熟”，就暂停扩大动作。","classic":"鼎折足，覆公餗，其形渥，凶。","source":"《周易》爻辞","modern":{"image":"“鼎折足，覆公餗，其形渥，凶。”是鼎在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自追求成果与打磨过程之间需要耐心，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"把形式上的完成当成真正成熟。","advice":["选择一个关键过程建立质量标准。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"止损","meaning":"在鼎第4爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪些经验已经可以被整理成稳定的方法”核对判断"},"tone":"越界","extended":{"trigger":{"label":"止损","observe":"完成“选择一个关键过程建立质量标准”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“选择一个关键过程建立质量标准”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选择一个关键过程建立质量标准”，可以保持小步推进。","pause_if":"若出现“把形式上的完成当成真正成熟”，先暂停扩大投入。"},"action":{"do":"选择一个关键过程建立质量标准","review":"完成后记录鼎九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"这一爻把变化落在具体环节：局面要求从个人得失转向整体结果和持续责任 关键条件开始出现可利用的现实回应，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意把形式上的完成当成真正成熟，而不是把频繁换方法打断积累当成解决办法，而鼎第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","classic":"鼎黃耳金鉉，利貞。","source":"《周易》爻辞","modern":{"image":"“鼎黃耳金鉉，利貞。”是鼎在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而追求成果与打磨过程之间需要耐心也会在这一爻变得具体。","warning":"把形式上的完成当成真正成熟，而不是把频繁换方法打断积累当成解决办法，而鼎第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["选择一个关键过程建立质量标准。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"有利","meaning":"在鼎第5爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“哪些经验已经可以被整理成稳定的方法”核对判断"},"tone":"担当","extended":{"trigger":{"label":"有利","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“把形式上的完成当成真正成熟，而不是把频繁换方法打断积累当成解决办法，而鼎第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录鼎六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面正在显出边界：当前循环接近上限，“转化与成器”需要从继续加力转向收束复盘 真正的拉扯来自追求成果与打磨过程之间需要耐心，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题 可以用“选择一个关键过程建立质量标准”做一次验证；若把形式上的完成当成真正成熟会在此时放大，行动应当收束。","classic":"鼎玉鉉，大吉，无不利。","source":"《周易》爻辞","modern":{"image":"“鼎玉鉉，大吉，无不利。”是鼎在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“转化与成器”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自追求成果与打磨过程之间需要耐心，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"把形式上的完成当成真正成熟会在此时放大。","advice":["选择一个关键过程建立质量标准。","列出应当停止、保留和移交的事项。"],"signal":{"label":"通达","meaning":"在鼎第6爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“哪些经验已经可以被整理成稳定的方法”核对判断"},"tone":"收束","extended":{"trigger":{"label":"通达","observe":"完成“选择一个关键过程建立质量标准”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“选择一个关键过程建立质量标准”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选择一个关键过程建立质量标准”，可以保持小步推进。","pause_if":"若出现“把形式上的完成当成真正成熟会在此时放大”，先暂停扩大投入。"},"action":{"do":"选择一个关键过程建立质量标准","review":"完成后记录鼎上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"经验要经过时间、协作和品质要求才能转化成能力","strengths":["现有材料具备被整合和提升的潜力","把经验慢慢熬成能力。重视过程中的协作与品质，成果会更有价值"],"tensions":["追求成果与打磨过程之间需要耐心"],"risks":["把形式上的完成当成真正成熟"],"actions":["选择一个关键过程建立质量标准"],"avoid":["频繁换方法打断积累"],"questions":["哪些经验已经可以被整理成稳定的方法？"],"extended":{"situation":{"direct":"眼下的重点是经验要经过时间、协作和品质要求才能转化成能力。","support":"已经可以利用的是：现有材料具备被整合和提升的潜力。","constraint":"仍需核实的是：追求成果与打磨过程之间需要耐心。"},"relationship":{"inner":"下卦巽，内部动力偏向渗透、调整与持续影响。","outer":"上卦离，外部处境更受辨识、表达与显明影响。","interaction":"内部想以“渗透、调整与持续影响”回应外部的“辨识、表达与显明”；两边能否对接，要看“追求成果与打磨过程之间需要耐心”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“现有材料具备被整合和提升的潜力”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“选择一个关键过程建立质量标准”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“频繁换方法打断积累”，风险会被放大。","effect":"最需要防止的是：把形式上的完成当成真正成熟。"},"paths":{"ready":"如果关键条件得到确认，可以继续“选择一个关键过程建立质量标准”，但仍以小步反馈决定是否扩大。","not_ready":"如果“追求成果与打磨过程之间需要耐心”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"选择一个关键过程建立质量标准","observe":"哪些经验已经可以被整理成稳定的方法？","continue_if":"出现与“现有材料具备被整合和提升的潜力”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“频繁换方法打断积累”或“把形式上的完成当成真正成熟”的迹象。"}}}},{"id":51,"name":"震","pinyin":"zhèn","theme":"惊动与觉醒","reflection":"突发变化先让人慌乱。稳住呼吸，辨别真正需要回应的部分。","source_note":"据《周易》震卦意象整理","upper_trigram":4,"lower_trigram":4,"lines":{"1":{"title":"初九","interpretation":"这一爻把变化落在具体环节：事情刚在“惊动与觉醒”的起点露出端倪，可用条件还不多 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意在惊吓中扩大问题或仓促承诺。","classic":"震來虩虩，後笑言啞啞，吉。","source":"《周易》爻辞","modern":{"image":"“震來虩虩，後笑言啞啞，吉。”是震在“潜藏”阶段留下的具体图景。","situation":"事情刚在“惊动与觉醒”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是即时反应与冷静判断之间存在时间差，两者要放在同一次权衡里。","warning":"在惊吓中扩大问题或仓促承诺。","advice":["先恢复基本节奏，再确认需要回应的事实。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在震第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“震动过去后，真正需要处理的是什么”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“在惊吓中扩大问题或仓促承诺”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录震初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：震来到二位，个人判断正与资源、规则或他人发生接触 若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大即时反应与冷静判断之间存在时间差 可以用“先恢复基本节奏，再确认需要回应的事实”做一次验证；若在惊吓中扩大问题或仓促承诺，而不是把把所有变化都当成危险当成解决办法，而震第2爻处在“接触”阶段，还需防止只听见符合期待的回应，行动应当收束。","classic":"震來厲，億喪貝，躋于九陵。勿逐，七日得。","source":"《周易》爻辞","modern":{"image":"“震來厲，億喪貝，躋于九陵。勿逐，七日得。”是震在“接触”阶段留下的具体图景。","situation":"震来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大即时反应与冷静判断之间存在时间差。","warning":"在惊吓中扩大问题或仓促承诺，而不是把把所有变化都当成危险当成解决办法，而震第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","advice":["先恢复基本节奏，再确认需要回应的事实。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在震第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“震动过去后，真正需要处理的是什么”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“先恢复基本节奏，再确认需要回应的事实”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先恢复基本节奏，再确认需要回应的事实”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先恢复基本节奏，再确认需要回应的事实”，可以保持小步推进。","pause_if":"若出现“在惊吓中扩大问题或仓促承诺，而不是把把所有变化都当成危险当成解决办法，而震第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，先暂停扩大投入。"},"action":{"do":"先恢复基本节奏，再确认需要回应的事实","review":"完成后记录震六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻处在容易用力过度的位置，调整比加码更重要 当前拉扯在于：此时一面是继续原路与承认需要调整之间发生冲突，另一面是即时反应与冷静判断之间存在时间差，两者要放在同一次权衡里 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“在惊吓中扩大问题或仓促承诺会在此时放大”，就暂停扩大动作。","classic":"震蘇蘇，震行无眚。","source":"《周易》爻辞","modern":{"image":"“震蘇蘇，震行无眚。”是震在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是即时反应与冷静判断之间存在时间差，两者要放在同一次权衡里。","warning":"在惊吓中扩大问题或仓促承诺会在此时放大。","advice":["先恢复基本节奏，再确认需要回应的事实。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在震第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“震动过去后，真正需要处理的是什么”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“在惊吓中扩大问题或仓促承诺会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录震六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"这一爻把变化落在具体环节：局面已经接近新的层级，旧角色未必还能容纳当前变化 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“先恢复基本节奏，再确认需要回应的事实”后再看反馈；同时留意在惊吓中扩大问题或仓促承诺。","classic":"震遂泥。","source":"《周易》爻辞","modern":{"image":"“震遂泥。”是震在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大即时反应与冷静判断之间存在时间差。","warning":"在惊吓中扩大问题或仓促承诺。","advice":["先恢复基本节奏，再确认需要回应的事实。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在震第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“震动过去后，真正需要处理的是什么”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“先恢复基本节奏，再确认需要回应的事实”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先恢复基本节奏，再确认需要回应的事实”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先恢复基本节奏，再确认需要回应的事实”，可以保持小步推进。","pause_if":"若出现“在惊吓中扩大问题或仓促承诺”，先暂停扩大投入。"},"action":{"do":"先恢复基本节奏，再确认需要回应的事实","review":"完成后记录震九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"局面正在显出边界：关键资源与决定权趋向集中，“惊动与觉醒”开始影响更多人 此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是即时反应与冷静判断之间存在时间差，两者要放在同一次权衡里 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若在惊吓中扩大问题或仓促承诺，行动应当收束。","classic":"震往來厲，億无喪，有事。","source":"《周易》爻辞","modern":{"image":"“震往來厲，億无喪，有事。”是震在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“惊动与觉醒”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是即时反应与冷静判断之间存在时间差，两者要放在同一次权衡里。","warning":"在惊吓中扩大问题或仓促承诺。","advice":["先恢复基本节奏，再确认需要回应的事实。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在震第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“震动过去后，真正需要处理的是什么”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“在惊吓中扩大问题或仓促承诺”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录震六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"震来到上位，已有路径可能完成使命，也可能因过度而失衡 当前拉扯在于：若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大即时反应与冷静判断之间存在时间差 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“先恢复基本节奏，再确认需要回应的事实”；若出现“在惊吓中扩大问题或仓促承诺，而不是把把所有变化都当成危险当成解决办法，而震第6爻处在“收束”阶段”，就暂停扩大动作。","classic":"震索索，視矍矍，征凶。震不于其躬于其鄰，无咎。婚媾有言。","source":"《周易》爻辞","modern":{"image":"“震索索，視矍矍，征凶。震不于其躬于其鄰，无咎。婚媾有言。”是震在“收束”阶段留下的具体图景。","situation":"震来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大即时反应与冷静判断之间存在时间差。","warning":"在惊吓中扩大问题或仓促承诺，而不是把把所有变化都当成危险当成解决办法，而震第6爻处在“收束”阶段。","advice":["先恢复基本节奏，再确认需要回应的事实。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在震第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“震动过去后，真正需要处理的是什么”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“先恢复基本节奏，再确认需要回应的事实”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先恢复基本节奏，再确认需要回应的事实”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先恢复基本节奏，再确认需要回应的事实”，可以保持小步推进。","pause_if":"若出现“在惊吓中扩大问题或仓促承诺，而不是把把所有变化都当成危险当成解决办法，而震第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"先恢复基本节奏，再确认需要回应的事实","review":"完成后记录震上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"突发变化先带来惊动，随后才有可能看清真正重点","strengths":["警觉能够帮助你快速识别重要信号","突发变化先让人慌乱。稳住呼吸，辨别真正需要回应的部分"],"tensions":["即时反应与冷静判断之间存在时间差"],"risks":["在惊吓中扩大问题或仓促承诺"],"actions":["先恢复基本节奏，再确认需要回应的事实"],"avoid":["把所有变化都当成危险"],"questions":["震动过去后，真正需要处理的是什么？"],"extended":{"situation":{"direct":"眼下的重点是突发变化先带来惊动，随后才有可能看清真正重点。","support":"已经可以利用的是：警觉能够帮助你快速识别重要信号。","constraint":"仍需核实的是：即时反应与冷静判断之间存在时间差。"},"relationship":{"inner":"下卦震，内部动力偏向启动、震动与迅速反应。","outer":"上卦震，外部处境更受启动、震动与迅速反应影响。","interaction":"内部想以“启动、震动与迅速反应”回应外部的“启动、震动与迅速反应”；两边能否对接，要看“即时反应与冷静判断之间存在时间差”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“警觉能够帮助你快速识别重要信号”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“先恢复基本节奏，再确认需要回应的事实”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把所有变化都当成危险”，风险会被放大。","effect":"最需要防止的是：在惊吓中扩大问题或仓促承诺。"},"paths":{"ready":"如果关键条件得到确认，可以继续“先恢复基本节奏，再确认需要回应的事实”，但仍以小步反馈决定是否扩大。","not_ready":"如果“即时反应与冷静判断之间存在时间差”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"先恢复基本节奏，再确认需要回应的事实","observe":"震动过去后，真正需要处理的是什么？","continue_if":"出现与“警觉能够帮助你快速识别重要信号”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把所有变化都当成危险”或“在惊吓中扩大问题或仓促承诺”的迹象。"}}}},{"id":52,"name":"艮","pinyin":"gèn","theme":"止与安定","reflection":"此刻适合停下来。停止并非放弃，而是让心和行动重新对齐。","source_note":"据《周易》艮卦意象整理","upper_trigram":7,"lower_trigram":7,"lines":{"1":{"title":"初六","interpretation":"局面正在显出边界：艮落在初位，眼下更像在辨认方向，而不是兑现结果 真正的拉扯来自暂停行动与逃避面对容易混淆，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若身体停下但思绪继续反复消耗，行动应当收束。","classic":"艮其趾，无咎，利永貞。","source":"《周易》爻辞","modern":{"image":"“艮其趾，无咎，利永貞。”是艮在“潜藏”阶段留下的具体图景。","situation":"艮落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自暂停行动与逃避面对容易混淆，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"身体停下但思绪继续反复消耗。","advice":["为一件事设定明确的暂停边界。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在艮第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“停下来之后，你终于能看见什么”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“身体停下但思绪继续反复消耗”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录艮初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"这一阶段不再只靠设想，回应和基本功开始决定走向 当前拉扯在于：自己的节奏需要与现实反馈相互校准，而暂停行动与逃避面对容易混淆也会在这一爻变得具体 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“为一件事设定明确的暂停边界”；若出现“身体停下但思绪继续反复消耗”，就暂停扩大动作。","classic":"艮其腓，不拯其隨，其心不快。","source":"《周易》爻辞","modern":{"image":"“艮其腓，不拯其隨，其心不快。”是艮在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而暂停行动与逃避面对容易混淆也会在这一爻变得具体。","warning":"身体停下但思绪继续反复消耗。","advice":["为一件事设定明确的暂停边界。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在艮第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“停下来之后，你终于能看见什么”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“为一件事设定明确的暂停边界”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“为一件事设定明确的暂停边界”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“为一件事设定明确的暂停边界”，可以保持小步推进。","pause_if":"若出现“身体停下但思绪继续反复消耗”，先暂停扩大投入。"},"action":{"do":"为一件事设定明确的暂停边界","review":"完成后记录艮六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻把变化落在具体环节：事情跨入转折带，焦虑可能比事实更快推动决定 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意身体停下但思绪继续反复消耗，而不是把在没有澄清目的时重新启动当成解决办法，而艮第3爻处在“转折”阶段。","classic":"艮其限，列其夤，厲薰心。","source":"《周易》爻辞","modern":{"image":"“艮其限，列其夤，厲薰心。”是艮在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自暂停行动与逃避面对容易混淆，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"身体停下但思绪继续反复消耗，而不是把在没有澄清目的时重新启动当成解决办法，而艮第3爻处在“转折”阶段。","advice":["为一件事设定明确的暂停边界。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在艮第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“停下来之后，你终于能看见什么”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“身体停下但思绪继续反复消耗，而不是把在没有澄清目的时重新启动当成解决办法，而艮第3爻处在“转折”阶段”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录艮九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"局面正在显出边界：事情正由内部走向外部，“止与安定”需要重新确认位置和权限 向外推进的需要与边界尚未说清之间互相牵制，而暂停行动与逃避面对容易混淆也会在这一爻变得具体 可以用“为一件事设定明确的暂停边界”做一次验证；若身体停下但思绪继续反复消耗会在此时放大，行动应当收束。","classic":"艮其身，无咎。","source":"《周易》爻辞","modern":{"image":"“艮其身，无咎。”是艮在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“止与安定”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而暂停行动与逃避面对容易混淆也会在这一爻变得具体。","warning":"身体停下但思绪继续反复消耗会在此时放大。","advice":["为一件事设定明确的暂停边界。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在艮第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“停下来之后，你终于能看见什么”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“为一件事设定明确的暂停边界”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“为一件事设定明确的暂停边界”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“为一件事设定明确的暂停边界”，可以保持小步推进。","pause_if":"若出现“身体停下但思绪继续反复消耗会在此时放大”，先暂停扩大投入。"},"action":{"do":"为一件事设定明确的暂停边界","review":"完成后记录艮六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"艮来到五位，能力之外还要衡量整体承接和长期后果 当前拉扯在于：真正的拉扯来自暂停行动与逃避面对容易混淆，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题 当原有做法显出明确代价，需要及时调整时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“身体停下但思绪继续反复消耗”，就暂停扩大动作。","classic":"艮其輔，言有序，悔亡。","source":"《周易》爻辞","modern":{"image":"“艮其輔，言有序，悔亡。”是艮在“担当”阶段留下的具体图景。","situation":"艮来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自暂停行动与逃避面对容易混淆，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"身体停下但思绪继续反复消耗。","advice":["为一件事设定明确的暂停边界。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"修正","meaning":"在艮第5爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“停下来之后，你终于能看见什么”核对判断"},"tone":"担当","extended":{"trigger":{"label":"修正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“身体停下但思绪继续反复消耗”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录艮六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"这一爻把变化落在具体环节：这一爻处在阶段末端，下一步先要判断什么已经结束 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“为一件事设定明确的暂停边界”后再看反馈；同时留意身体停下但思绪继续反复消耗。","classic":"敦艮，吉。","source":"《周易》爻辞","modern":{"image":"“敦艮，吉。”是艮在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而暂停行动与逃避面对容易混淆也会在这一爻变得具体。","warning":"身体停下但思绪继续反复消耗。","advice":["为一件事设定明确的暂停边界。","列出应当停止、保留和移交的事项。"],"signal":{"label":"可行","meaning":"在艮第6爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“停下来之后，你终于能看见什么”核对判断"},"tone":"收束","extended":{"trigger":{"label":"可行","observe":"完成“为一件事设定明确的暂停边界”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“为一件事设定明确的暂停边界”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“为一件事设定明确的暂停边界”，可以保持小步推进。","pause_if":"若出现“身体停下但思绪继续反复消耗”，先暂停扩大投入。"},"action":{"do":"为一件事设定明确的暂停边界","review":"完成后记录艮上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"停止是为了让心、边界和行动重新对齐","strengths":["有机会中断无效惯性并恢复安定","此刻适合停下来。停止并非放弃，而是让心和行动重新对齐"],"tensions":["暂停行动与逃避面对容易混淆"],"risks":["身体停下但思绪继续反复消耗"],"actions":["为一件事设定明确的暂停边界"],"avoid":["在没有澄清目的时重新启动"],"questions":["停下来之后，你终于能看见什么？"],"extended":{"situation":{"direct":"眼下的重点是停止是为了让心、边界和行动重新对齐。","support":"已经可以利用的是：有机会中断无效惯性并恢复安定。","constraint":"仍需核实的是：暂停行动与逃避面对容易混淆。"},"relationship":{"inner":"下卦艮，内部动力偏向边界、停止与重新定位。","outer":"上卦艮，外部处境更受边界、停止与重新定位影响。","interaction":"内部想以“边界、停止与重新定位”回应外部的“边界、停止与重新定位”；两边能否对接，要看“暂停行动与逃避面对容易混淆”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“有机会中断无效惯性并恢复安定”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“为一件事设定明确的暂停边界”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“在没有澄清目的时重新启动”，风险会被放大。","effect":"最需要防止的是：身体停下但思绪继续反复消耗。"},"paths":{"ready":"如果关键条件得到确认，可以继续“为一件事设定明确的暂停边界”，但仍以小步反馈决定是否扩大。","not_ready":"如果“暂停行动与逃避面对容易混淆”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"为一件事设定明确的暂停边界","observe":"停下来之后，你终于能看见什么？","continue_if":"出现与“有机会中断无效惯性并恢复安定”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“在没有澄清目的时重新启动”或“身体停下但思绪继续反复消耗”的迹象。"}}}},{"id":53,"name":"渐","pinyin":"jiàn","theme":"循序与成熟","reflection":"好的变化需要时间。尊重过程，不因缓慢就怀疑自己的方向。","source_note":"据《周易》渐卦意象整理","upper_trigram":5,"lower_trigram":7,"lines":{"1":{"title":"初六","interpretation":"这一爻处在起步处，“成熟变化依赖次序和时间，不必用速度证明方向”仍需低成本试探 当前拉扯在于：若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大长期过程与即时回报期待之间有落差 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“因为缓慢就否定真实进展会在此时放大”，就暂停扩大动作。","classic":"鴻漸于干，小子厲，有言，无咎。","source":"《周易》爻辞","modern":{"image":"“鴻漸于干，小子厲，有言，无咎。”是渐在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“成熟变化依赖次序和时间，不必用速度证明方向”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大长期过程与即时回报期待之间有落差。","warning":"因为缓慢就否定真实进展会在此时放大。","advice":["记录一个月前做不到而现在能做到的事。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在渐第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“什么证据说明缓慢仍然是在向前”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“因为缓慢就否定真实进展会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录渐初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"这一爻把变化落在具体环节：局面正从内部准备转向真实互动，关系与条件逐渐可见 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“记录一个月前做不到而现在能做到的事”后再看反馈；同时留意因为缓慢就否定真实进展。","classic":"鴻漸于磐，飲食衎衎，吉。","source":"《周易》爻辞","modern":{"image":"“鴻漸于磐，飲食衎衎，吉。”是渐在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是长期过程与即时回报期待之间有落差，两者要放在同一次权衡里。","warning":"因为缓慢就否定真实进展。","advice":["记录一个月前做不到而现在能做到的事。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在渐第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“什么证据说明缓慢仍然是在向前”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“记录一个月前做不到而现在能做到的事”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“记录一个月前做不到而现在能做到的事”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“记录一个月前做不到而现在能做到的事”，可以保持小步推进。","pause_if":"若出现“因为缓慢就否定真实进展”，先暂停扩大投入。"},"action":{"do":"记录一个月前做不到而现在能做到的事","review":"完成后记录渐六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面正在显出边界：局面来到内外转换处，“循序与成熟”开始承受压力测试 若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大长期过程与即时回报期待之间有落差 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若因为缓慢就否定真实进展，行动应当收束。","classic":"鴻漸于陸，夫征不復，婦孕不育，凶，利禦寇。","source":"《周易》爻辞","modern":{"image":"“鴻漸于陸，夫征不復，婦孕不育，凶，利禦寇。”是渐在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“循序与成熟”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大长期过程与即时回报期待之间有落差。","warning":"因为缓慢就否定真实进展。","advice":["记录一个月前做不到而现在能做到的事。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"止损","meaning":"在渐第3爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“什么证据说明缓慢仍然是在向前”核对判断"},"tone":"转折","extended":{"trigger":{"label":"止损","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“因为缓慢就否定真实进展”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录渐九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"渐来到四位，跨出原有边界之前要先说明责任 当前拉扯在于：此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是长期过程与即时回报期待之间有落差，两者要放在同一次权衡里 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“记录一个月前做不到而现在能做到的事”；若出现“因为缓慢就否定真实进展，而不是把频繁更换衡量标准当成解决办法，而渐第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位”，就暂停扩大动作。","classic":"鴻漸于木，或得其桷，无咎。","source":"《周易》爻辞","modern":{"image":"“鴻漸于木，或得其桷，无咎。”是渐在“越界”阶段留下的具体图景。","situation":"渐来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是长期过程与即时回报期待之间有落差，两者要放在同一次权衡里。","warning":"因为缓慢就否定真实进展，而不是把频繁更换衡量标准当成解决办法，而渐第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位。","advice":["记录一个月前做不到而现在能做到的事。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在渐第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“什么证据说明缓慢仍然是在向前”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“记录一个月前做不到而现在能做到的事”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“记录一个月前做不到而现在能做到的事”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“记录一个月前做不到而现在能做到的事”，可以保持小步推进。","pause_if":"若出现“因为缓慢就否定真实进展，而不是把频繁更换衡量标准当成解决办法，而渐第4爻处在“越界”阶段，还需防止因位置错判造成责任和期待错位”，先暂停扩大投入。"},"action":{"do":"记录一个月前做不到而现在能做到的事","review":"完成后记录渐六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一爻把变化落在具体环节：这一阶段已进入主位，选择会放大为规则或示范 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意因为缓慢就否定真实进展会在此时放大。","classic":"鴻漸于陵，婦三歲不孕，終莫之勝，吉。","source":"《周易》爻辞","modern":{"image":"“鴻漸于陵，婦三歲不孕，終莫之勝，吉。”是渐在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大长期过程与即时回报期待之间有落差。","warning":"因为缓慢就否定真实进展会在此时放大。","advice":["记录一个月前做不到而现在能做到的事。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在渐第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“什么证据说明缓慢仍然是在向前”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“因为缓慢就否定真实进展会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录渐九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面正在显出边界：局面走到极处，继续延长旧办法未必带来同等收益 此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是长期过程与即时回报期待之间有落差，两者要放在同一次权衡里 可以用“记录一个月前做不到而现在能做到的事”做一次验证；若因为缓慢就否定真实进展，行动应当收束。","classic":"鴻漸于陸，其羽可用為儀，吉。","source":"《周易》爻辞","modern":{"image":"“鴻漸于陸，其羽可用為儀，吉。”是渐在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是长期过程与即时回报期待之间有落差，两者要放在同一次权衡里。","warning":"因为缓慢就否定真实进展。","advice":["记录一个月前做不到而现在能做到的事。","列出应当停止、保留和移交的事项。"],"signal":{"label":"可行","meaning":"在渐第6爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“什么证据说明缓慢仍然是在向前”核对判断"},"tone":"收束","extended":{"trigger":{"label":"可行","observe":"完成“记录一个月前做不到而现在能做到的事”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“记录一个月前做不到而现在能做到的事”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“记录一个月前做不到而现在能做到的事”，可以保持小步推进。","pause_if":"若出现“因为缓慢就否定真实进展”，先暂停扩大投入。"},"action":{"do":"记录一个月前做不到而现在能做到的事","review":"完成后记录渐上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"成熟变化依赖次序和时间，不必用速度证明方向","strengths":["已有稳定成长的轨迹","好的变化需要时间。尊重过程，不因缓慢就怀疑自己的方向"],"tensions":["长期过程与即时回报期待之间有落差"],"risks":["因为缓慢就否定真实进展"],"actions":["记录一个月前做不到而现在能做到的事"],"avoid":["频繁更换衡量标准"],"questions":["什么证据说明缓慢仍然是在向前？"],"extended":{"situation":{"direct":"眼下的重点是成熟变化依赖次序和时间，不必用速度证明方向。","support":"已经可以利用的是：已有稳定成长的轨迹。","constraint":"仍需核实的是：长期过程与即时回报期待之间有落差。"},"relationship":{"inner":"下卦艮，内部动力偏向边界、停止与重新定位。","outer":"上卦巽，外部处境更受渗透、调整与持续影响影响。","interaction":"内部想以“边界、停止与重新定位”回应外部的“渗透、调整与持续影响”；两边能否对接，要看“长期过程与即时回报期待之间有落差”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“已有稳定成长的轨迹”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“记录一个月前做不到而现在能做到的事”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“频繁更换衡量标准”，风险会被放大。","effect":"最需要防止的是：因为缓慢就否定真实进展。"},"paths":{"ready":"如果关键条件得到确认，可以继续“记录一个月前做不到而现在能做到的事”，但仍以小步反馈决定是否扩大。","not_ready":"如果“长期过程与即时回报期待之间有落差”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"记录一个月前做不到而现在能做到的事","observe":"什么证据说明缓慢仍然是在向前？","continue_if":"出现与“已有稳定成长的轨迹”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“频繁更换衡量标准”或“因为缓慢就否定真实进展”的迹象。"}}}},{"id":54,"name":"归妹","pinyin":"guī mèi","theme":"关系与位置","reflection":"投入关系前，先确认彼此期待与位置。尊重自己，也尊重现实条件。","source_note":"据《周易》归妹卦意象整理","upper_trigram":4,"lower_trigram":2,"lines":{"1":{"title":"初九","interpretation":"这一爻把变化落在具体环节：变化尚在根部，先分清已经发生的事实和仍在期待的部分 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意在关系未明确时承担过多，而不是把用想象补齐没有说清的部分当成解决办法，而归妹第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","classic":"歸妹以娣，跛能履，征吉。","source":"《周易》爻辞","modern":{"image":"“歸妹以娣，跛能履，征吉。”是归妹在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而情感投入与实际位置可能不匹配也会在这一爻变得具体。","warning":"在关系未明确时承担过多，而不是把用想象补齐没有说清的部分当成解决办法，而归妹第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["直接确认彼此期待和可承诺范围。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在归妹第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你被邀请进入的，究竟是什么位置”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“在关系未明确时承担过多，而不是把用想象补齐没有说清的部分当成解决办法，而归妹第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录归妹初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"局面正在显出边界：事情开始进入现实协作，“关系与位置”要接受反馈检验 真正的拉扯来自情感投入与实际位置可能不匹配，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题 可以用“直接确认彼此期待和可承诺范围”做一次验证；若在关系未明确时承担过多会在此时放大，行动应当收束。","classic":"眇能視，利幽人之貞。","source":"《周易》爻辞","modern":{"image":"“眇能視，利幽人之貞。”是归妹在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“关系与位置”要接受反馈检验。","tension":"真正的拉扯来自情感投入与实际位置可能不匹配，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"在关系未明确时承担过多会在此时放大。","advice":["直接确认彼此期待和可承诺范围。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"有利","meaning":"在归妹第2爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“你被邀请进入的，究竟是什么位置”核对判断"},"tone":"接触","extended":{"trigger":{"label":"有利","observe":"完成“直接确认彼此期待和可承诺范围”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“直接确认彼此期待和可承诺范围”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“直接确认彼此期待和可承诺范围”，可以保持小步推进。","pause_if":"若出现“在关系未明确时承担过多会在此时放大”，先暂停扩大投入。"},"action":{"do":"直接确认彼此期待和可承诺范围","review":"完成后记录归妹九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"归妹行至三位，旧方法的边界和新选择的代价同时出现 当前拉扯在于：继续原路与承认需要调整之间发生冲突，而情感投入与实际位置可能不匹配也会在这一爻变得具体 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“在关系未明确时承担过多”，就暂停扩大动作。","classic":"歸妹以須，反歸以娣。","source":"《周易》爻辞","modern":{"image":"“歸妹以須，反歸以娣。”是归妹在“转折”阶段留下的具体图景。","situation":"归妹行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而情感投入与实际位置可能不匹配也会在这一爻变得具体。","warning":"在关系未明确时承担过多。","advice":["直接确认彼此期待和可承诺范围。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在归妹第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“你被邀请进入的，究竟是什么位置”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“在关系未明确时承担过多”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录归妹六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"这一爻把变化落在具体环节：这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“直接确认彼此期待和可承诺范围”后再看反馈；同时留意在关系未明确时承担过多。","classic":"歸妹愆期，遲歸有時。","source":"《周易》爻辞","modern":{"image":"“歸妹愆期，遲歸有時。”是归妹在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自情感投入与实际位置可能不匹配，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"在关系未明确时承担过多。","advice":["直接确认彼此期待和可承诺范围。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在归妹第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“你被邀请进入的，究竟是什么位置”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“直接确认彼此期待和可承诺范围”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“直接确认彼此期待和可承诺范围”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“直接确认彼此期待和可承诺范围”，可以保持小步推进。","pause_if":"若出现“在关系未明确时承担过多”，先暂停扩大投入。"},"action":{"do":"直接确认彼此期待和可承诺范围","review":"完成后记录归妹九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"局面正在显出边界：局面要求从个人得失转向整体结果和持续责任 扩大影响与照顾整体承接能力之间需要平衡，而情感投入与实际位置可能不匹配也会在这一爻变得具体 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若在关系未明确时承担过多，而不是把用想象补齐没有说清的部分当成解决办法，而归妹第5爻处在“担当”阶段，行动应当收束。","classic":"帝乙歸妹，其君之袂，不如其娣之袂良。月幾望，吉。","source":"《周易》爻辞","modern":{"image":"“帝乙歸妹，其君之袂，不如其娣之袂良。月幾望，吉。”是归妹在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而情感投入与实际位置可能不匹配也会在这一爻变得具体。","warning":"在关系未明确时承担过多，而不是把用想象补齐没有说清的部分当成解决办法，而归妹第5爻处在“担当”阶段。","advice":["直接确认彼此期待和可承诺范围。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在归妹第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你被邀请进入的，究竟是什么位置”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“在关系未明确时承担过多，而不是把用想象补齐没有说清的部分当成解决办法，而归妹第5爻处在“担当”阶段”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录归妹六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"当前循环接近上限，“关系与位置”需要从继续加力转向收束复盘 当前拉扯在于：真正的拉扯来自情感投入与实际位置可能不匹配，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题 当关键条件开始出现可利用的现实回应时，变化才有现实依据。先做“直接确认彼此期待和可承诺范围”；若出现“在关系未明确时承担过多会在此时放大”，就暂停扩大动作。","classic":"女承筐无實，士刲羊无血，无攸利。","source":"《周易》爻辞","modern":{"image":"“女承筐无實，士刲羊无血，无攸利。”是归妹在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“关系与位置”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自情感投入与实际位置可能不匹配，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"在关系未明确时承担过多会在此时放大。","advice":["直接确认彼此期待和可承诺范围。","列出应当停止、保留和移交的事项。"],"signal":{"label":"有利","meaning":"在归妹第6爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“你被邀请进入的，究竟是什么位置”核对判断"},"tone":"收束","extended":{"trigger":{"label":"有利","observe":"完成“直接确认彼此期待和可承诺范围”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“直接确认彼此期待和可承诺范围”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“直接确认彼此期待和可承诺范围”，可以保持小步推进。","pause_if":"若出现“在关系未明确时承担过多会在此时放大”，先暂停扩大投入。"},"action":{"do":"直接确认彼此期待和可承诺范围","review":"完成后记录归妹上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"进入关系或新位置前，要确认角色、期待和现实条件","strengths":["存在靠近和建立连接的机会","投入关系前，先确认彼此期待与位置。尊重自己，也尊重现实条件"],"tensions":["情感投入与实际位置可能不匹配"],"risks":["在关系未明确时承担过多"],"actions":["直接确认彼此期待和可承诺范围"],"avoid":["用想象补齐没有说清的部分"],"questions":["你被邀请进入的，究竟是什么位置？"],"extended":{"situation":{"direct":"眼下的重点是进入关系或新位置前，要确认角色、期待和现实条件。","support":"已经可以利用的是：存在靠近和建立连接的机会。","constraint":"仍需核实的是：情感投入与实际位置可能不匹配。"},"relationship":{"inner":"下卦兑，内部动力偏向交流、回应与协商。","outer":"上卦震，外部处境更受启动、震动与迅速反应影响。","interaction":"内部想以“交流、回应与协商”回应外部的“启动、震动与迅速反应”；两边能否对接，要看“情感投入与实际位置可能不匹配”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“存在靠近和建立连接的机会”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“直接确认彼此期待和可承诺范围”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用想象补齐没有说清的部分”，风险会被放大。","effect":"最需要防止的是：在关系未明确时承担过多。"},"paths":{"ready":"如果关键条件得到确认，可以继续“直接确认彼此期待和可承诺范围”，但仍以小步反馈决定是否扩大。","not_ready":"如果“情感投入与实际位置可能不匹配”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"直接确认彼此期待和可承诺范围","observe":"你被邀请进入的，究竟是什么位置？","continue_if":"出现与“存在靠近和建立连接的机会”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用想象补齐没有说清的部分”或“在关系未明确时承担过多”的迹象。"}}}},{"id":55,"name":"丰","pinyin":"fēng","theme":"丰盛与清醒","reflection":"事情正处高点，适合把握机会；同时整理重点，别被繁多选择淹没。","source_note":"据《周易》丰卦意象整理","upper_trigram":4,"lower_trigram":3,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：事情刚在“丰盛与清醒”的起点露出端倪，可用条件还不多 此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是把握机会与防止过载之间需要取舍，两者要放在同一次权衡里 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若每个机会都想抓住，行动应当收束。","classic":"遇其配主，雖旬无咎，往有尚。","source":"《周易》爻辞","modern":{"image":"“遇其配主，雖旬无咎，往有尚。”是丰在“潜藏”阶段留下的具体图景。","situation":"事情刚在“丰盛与清醒”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是把握机会与防止过载之间需要取舍，两者要放在同一次权衡里。","warning":"每个机会都想抓住。","advice":["选出最能代表当前方向的一项成果。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在丰第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“如果只能保留一项，什么最值得带到下一阶段”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“每个机会都想抓住”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录丰初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"丰来到二位，个人判断正与资源、规则或他人发生接触 当前拉扯在于：若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大把握机会与防止过载之间需要取舍 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“选出最能代表当前方向的一项成果”；若出现“每个机会都想抓住，而不是把在高峰期增加无法维护的承诺当成解决办法，而丰第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，就暂停扩大动作。","classic":"豐其蔀，日中見斗。往得疑疾，有孚發若，吉。","source":"《周易》爻辞","modern":{"image":"“豐其蔀，日中見斗。往得疑疾，有孚發若，吉。”是丰在“接触”阶段留下的具体图景。","situation":"丰来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大把握机会与防止过载之间需要取舍。","warning":"每个机会都想抓住，而不是把在高峰期增加无法维护的承诺当成解决办法，而丰第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","advice":["选出最能代表当前方向的一项成果。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在丰第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“如果只能保留一项，什么最值得带到下一阶段”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“选出最能代表当前方向的一项成果”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“选出最能代表当前方向的一项成果”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选出最能代表当前方向的一项成果”，可以保持小步推进。","pause_if":"若出现“每个机会都想抓住，而不是把在高峰期增加无法维护的承诺当成解决办法，而丰第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，先暂停扩大投入。"},"action":{"do":"选出最能代表当前方向的一项成果","review":"完成后记录丰六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻把变化落在具体环节：这一爻处在容易用力过度的位置，调整比加码更重要 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意每个机会都想抓住会在此时放大。","classic":"豐其沛，日中見沬。折其右肱，无咎。","source":"《周易》爻辞","modern":{"image":"“豐其沛，日中見沬。折其右肱，无咎。”是丰在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是把握机会与防止过载之间需要取舍，两者要放在同一次权衡里。","warning":"每个机会都想抓住会在此时放大。","advice":["选出最能代表当前方向的一项成果。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"守正","meaning":"在丰第3爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“如果只能保留一项，什么最值得带到下一阶段”核对判断"},"tone":"转折","extended":{"trigger":{"label":"守正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“每个机会都想抓住会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录丰九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：局面已经接近新的层级，旧角色未必还能容纳当前变化 若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大把握机会与防止过载之间需要取舍 可以用“选出最能代表当前方向的一项成果”做一次验证；若每个机会都想抓住，行动应当收束。","classic":"豐其蔀，日中見斗，遇其夷主，吉。","source":"《周易》爻辞","modern":{"image":"“豐其蔀，日中見斗，遇其夷主，吉。”是丰在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大把握机会与防止过载之间需要取舍。","warning":"每个机会都想抓住。","advice":["选出最能代表当前方向的一项成果。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在丰第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“如果只能保留一项，什么最值得带到下一阶段”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“选出最能代表当前方向的一项成果”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“选出最能代表当前方向的一项成果”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选出最能代表当前方向的一项成果”，可以保持小步推进。","pause_if":"若出现“每个机会都想抓住”，先暂停扩大投入。"},"action":{"do":"选出最能代表当前方向的一项成果","review":"完成后记录丰九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"关键资源与决定权趋向集中，“丰盛与清醒”开始影响更多人 当前拉扯在于：此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是把握机会与防止过载之间需要取舍，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“每个机会都想抓住”，就暂停扩大动作。","classic":"來章，有慶譽，吉。","source":"《周易》爻辞","modern":{"image":"“來章，有慶譽，吉。”是丰在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“丰盛与清醒”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是把握机会与防止过载之间需要取舍，两者要放在同一次权衡里。","warning":"每个机会都想抓住。","advice":["选出最能代表当前方向的一项成果。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在丰第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“如果只能保留一项，什么最值得带到下一阶段”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“每个机会都想抓住”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录丰六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻把变化落在具体环节：丰来到上位，已有路径可能完成使命，也可能因过度而失衡 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“选出最能代表当前方向的一项成果”后再看反馈；同时留意每个机会都想抓住，而不是把在高峰期增加无法维护的承诺当成解决办法，而丰第6爻处在“收束”阶段。","classic":"豐其屋，蔀其家，闚其戶，闃其无人，三歲不覿，凶。","source":"《周易》爻辞","modern":{"image":"“豐其屋，蔀其家，闚其戶，闃其无人，三歲不覿，凶。”是丰在“收束”阶段留下的具体图景。","situation":"丰来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大把握机会与防止过载之间需要取舍。","warning":"每个机会都想抓住，而不是把在高峰期增加无法维护的承诺当成解决办法，而丰第6爻处在“收束”阶段。","advice":["选出最能代表当前方向的一项成果。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在丰第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“如果只能保留一项，什么最值得带到下一阶段”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“选出最能代表当前方向的一项成果”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“选出最能代表当前方向的一项成果”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“选出最能代表当前方向的一项成果”，可以保持小步推进。","pause_if":"若出现“每个机会都想抓住，而不是把在高峰期增加无法维护的承诺当成解决办法，而丰第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"选出最能代表当前方向的一项成果","review":"完成后记录丰上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"高点带来机会，也要求从繁多中辨出重点","strengths":["资源、关注或选择正处于丰富阶段","事情正处高点，适合把握机会"],"tensions":["把握机会与防止过载之间需要取舍"],"risks":["每个机会都想抓住"],"actions":["选出最能代表当前方向的一项成果"],"avoid":["在高峰期增加无法维护的承诺"],"questions":["如果只能保留一项，什么最值得带到下一阶段？"],"extended":{"situation":{"direct":"眼下的重点是高点带来机会，也要求从繁多中辨出重点。","support":"已经可以利用的是：资源、关注或选择正处于丰富阶段。","constraint":"仍需核实的是：把握机会与防止过载之间需要取舍。"},"relationship":{"inner":"下卦离，内部动力偏向辨识、表达与显明。","outer":"上卦震，外部处境更受启动、震动与迅速反应影响。","interaction":"内部想以“辨识、表达与显明”回应外部的“启动、震动与迅速反应”；两边能否对接，要看“把握机会与防止过载之间需要取舍”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“资源、关注或选择正处于丰富阶段”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“选出最能代表当前方向的一项成果”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“在高峰期增加无法维护的承诺”，风险会被放大。","effect":"最需要防止的是：每个机会都想抓住。"},"paths":{"ready":"如果关键条件得到确认，可以继续“选出最能代表当前方向的一项成果”，但仍以小步反馈决定是否扩大。","not_ready":"如果“把握机会与防止过载之间需要取舍”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"选出最能代表当前方向的一项成果","observe":"如果只能保留一项，什么最值得带到下一阶段？","continue_if":"出现与“资源、关注或选择正处于丰富阶段”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“在高峰期增加无法维护的承诺”或“每个机会都想抓住”的迹象。"}}}},{"id":56,"name":"旅","pinyin":"lǚ","theme":"行旅与适应","reflection":"在不熟悉的环境里，轻装、守礼、随机应变。先安顿好自己。","source_note":"据《周易》旅卦意象整理","upper_trigram":3,"lower_trigram":7,"lines":{"1":{"title":"初六","interpretation":"旅落在初位，眼下更像在辨认方向，而不是兑现结果 当前拉扯在于：真正的拉扯来自灵活融入与失去自身节奏之间有张力，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“急于证明归属而过度暴露或承诺”，就暂停扩大动作。","classic":"旅瑣瑣，斯其所取災。","source":"《周易》爻辞","modern":{"image":"“旅瑣瑣，斯其所取災。”是旅在“潜藏”阶段留下的具体图景。","situation":"旅落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自灵活融入与失去自身节奏之间有张力，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"急于证明归属而过度暴露或承诺。","advice":["先确认当地规则和一个可靠联系人。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"观察","meaning":"在旅第1爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“在这个阶段，什么能让你既适应又不失去自己”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"观察","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“急于证明归属而过度暴露或承诺”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录旅初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"这一爻把变化落在具体环节：这一阶段不再只靠设想，回应和基本功开始决定走向 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“先确认当地规则和一个可靠联系人”后再看反馈；同时留意急于证明归属而过度暴露或承诺。","classic":"旅即次，懷其資，得童僕貞。","source":"《周易》爻辞","modern":{"image":"“旅即次，懷其資，得童僕貞。”是旅在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而灵活融入与失去自身节奏之间有张力也会在这一爻变得具体。","warning":"急于证明归属而过度暴露或承诺。","advice":["先确认当地规则和一个可靠联系人。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在旅第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“在这个阶段，什么能让你既适应又不失去自己”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“先确认当地规则和一个可靠联系人”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认当地规则和一个可靠联系人”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认当地规则和一个可靠联系人”，可以保持小步推进。","pause_if":"若出现“急于证明归属而过度暴露或承诺”，先暂停扩大投入。"},"action":{"do":"先确认当地规则和一个可靠联系人","review":"完成后记录旅六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面正在显出边界：事情跨入转折带，焦虑可能比事实更快推动决定 真正的拉扯来自灵活融入与失去自身节奏之间有张力，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若急于证明归属而过度暴露或承诺，而不是把把暂时状态当成永久身份当成解决办法，而旅第3爻处在“转折”阶段，行动应当收束。","classic":"旅焚其次，喪其童僕，貞厲。","source":"《周易》爻辞","modern":{"image":"“旅焚其次，喪其童僕，貞厲。”是旅在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自灵活融入与失去自身节奏之间有张力，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"急于证明归属而过度暴露或承诺，而不是把把暂时状态当成永久身份当成解决办法，而旅第3爻处在“转折”阶段。","advice":["先确认当地规则和一个可靠联系人。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在旅第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“在这个阶段，什么能让你既适应又不失去自己”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“急于证明归属而过度暴露或承诺，而不是把把暂时状态当成永久身份当成解决办法，而旅第3爻处在“转折”阶段”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录旅九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"事情正由内部走向外部，“行旅与适应”需要重新确认位置和权限 当前拉扯在于：向外推进的需要与边界尚未说清之间互相牵制，而灵活融入与失去自身节奏之间有张力也会在这一爻变得具体 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“先确认当地规则和一个可靠联系人”；若出现“急于证明归属而过度暴露或承诺会在此时放大”，就暂停扩大动作。","classic":"旅于處，得其資斧，我心不快。","source":"《周易》爻辞","modern":{"image":"“旅于處，得其資斧，我心不快。”是旅在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“行旅与适应”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而灵活融入与失去自身节奏之间有张力也会在这一爻变得具体。","warning":"急于证明归属而过度暴露或承诺会在此时放大。","advice":["先确认当地规则和一个可靠联系人。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在旅第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“在这个阶段，什么能让你既适应又不失去自己”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“先确认当地规则和一个可靠联系人”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先确认当地规则和一个可靠联系人”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认当地规则和一个可靠联系人”，可以保持小步推进。","pause_if":"若出现“急于证明归属而过度暴露或承诺会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认当地规则和一个可靠联系人","review":"完成后记录旅九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"这一爻把变化落在具体环节：旅来到五位，能力之外还要衡量整体承接和长期后果 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意急于证明归属而过度暴露或承诺。","classic":"射雉，一矢亡，終以譽命。","source":"《周易》爻辞","modern":{"image":"“射雉，一矢亡，終以譽命。”是旅在“担当”阶段留下的具体图景。","situation":"旅来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自灵活融入与失去自身节奏之间有张力，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"急于证明归属而过度暴露或承诺。","advice":["先确认当地规则和一个可靠联系人。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在旅第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“在这个阶段，什么能让你既适应又不失去自己”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“急于证明归属而过度暴露或承诺”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录旅六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面正在显出边界：这一爻处在阶段末端，下一步先要判断什么已经结束 维持既有成果与允许阶段结束之间存在拉扯，而灵活融入与失去自身节奏之间有张力也会在这一爻变得具体 可以用“先确认当地规则和一个可靠联系人”做一次验证；若急于证明归属而过度暴露或承诺，行动应当收束。","classic":"鳥焚其巢，旅人先笑後號咷，喪牛于易，凶。","source":"《周易》爻辞","modern":{"image":"“鳥焚其巢，旅人先笑後號咷，喪牛于易，凶。”是旅在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而灵活融入与失去自身节奏之间有张力也会在这一爻变得具体。","warning":"急于证明归属而过度暴露或承诺。","advice":["先确认当地规则和一个可靠联系人。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在旅第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“在这个阶段，什么能让你既适应又不失去自己”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“先确认当地规则和一个可靠联系人”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认当地规则和一个可靠联系人”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认当地规则和一个可靠联系人”，可以保持小步推进。","pause_if":"若出现“急于证明归属而过度暴露或承诺”，先暂停扩大投入。"},"action":{"do":"先确认当地规则和一个可靠联系人","review":"完成后记录旅上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"陌生环境里先安顿自己，再逐步建立连接和判断","strengths":["具备适应变化与轻装行动的能力","在不熟悉的环境里，轻装、守礼、随机应变。先安顿好自己"],"tensions":["灵活融入与失去自身节奏之间有张力"],"risks":["急于证明归属而过度暴露或承诺"],"actions":["先确认当地规则和一个可靠联系人"],"avoid":["把暂时状态当成永久身份"],"questions":["在这个阶段，什么能让你既适应又不失去自己？"],"extended":{"situation":{"direct":"眼下的重点是陌生环境里先安顿自己，再逐步建立连接和判断。","support":"已经可以利用的是：具备适应变化与轻装行动的能力。","constraint":"仍需核实的是：灵活融入与失去自身节奏之间有张力。"},"relationship":{"inner":"下卦艮，内部动力偏向边界、停止与重新定位。","outer":"上卦离，外部处境更受辨识、表达与显明影响。","interaction":"内部想以“边界、停止与重新定位”回应外部的“辨识、表达与显明”；两边能否对接，要看“灵活融入与失去自身节奏之间有张力”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“具备适应变化与轻装行动的能力”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“先确认当地规则和一个可靠联系人”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把暂时状态当成永久身份”，风险会被放大。","effect":"最需要防止的是：急于证明归属而过度暴露或承诺。"},"paths":{"ready":"如果关键条件得到确认，可以继续“先确认当地规则和一个可靠联系人”，但仍以小步反馈决定是否扩大。","not_ready":"如果“灵活融入与失去自身节奏之间有张力”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"先确认当地规则和一个可靠联系人","observe":"在这个阶段，什么能让你既适应又不失去自己？","continue_if":"出现与“具备适应变化与轻装行动的能力”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把暂时状态当成永久身份”或“急于证明归属而过度暴露或承诺”的迹象。"}}}},{"id":57,"name":"巽","pinyin":"xùn","theme":"渗透与谦顺","reflection":"温和而持续的沟通，比一次强力推动更容易深入人心。","source_note":"据《周易》巽卦意象整理","upper_trigram":5,"lower_trigram":5,"lines":{"1":{"title":"初六","interpretation":"这一爻把变化落在具体环节：这一爻处在起步处，“温和而持续的影响，往往比一次强推更深入”仍需低成本试探 关键条件开始出现可利用的现实回应，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意为了维持柔和而不说关键问题会在此时放大。","classic":"進退，利武人之貞。","source":"《周易》爻辞","modern":{"image":"“進退，利武人之貞。”是巽在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“温和而持续的影响，往往比一次强推更深入”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大柔顺表达与回避明确立场可能混淆。","warning":"为了维持柔和而不说关键问题会在此时放大。","advice":["把核心诉求缩成一句可重复表达的话。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"有利","meaning":"在巽第1爻里，爻辞指出可利用的方向，同时也要求分清适用范围，可用“哪句话需要被持续、清楚地说出来”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"有利","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“关键条件开始出现可利用的现实回应”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“为了维持柔和而不说关键问题会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录巽初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"局面正在显出边界：局面正从内部准备转向真实互动，关系与条件逐渐可见 此时一面是自己的节奏需要与现实反馈相互校准，另一面是柔顺表达与回避明确立场可能混淆，两者要放在同一次权衡里 可以用“把核心诉求缩成一句可重复表达的话”做一次验证；若为了维持柔和而不说关键问题，行动应当收束。","classic":"巽在床下，用史巫紛若，吉无咎。","source":"《周易》爻辞","modern":{"image":"“巽在床下，用史巫紛若，吉无咎。”是巽在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是柔顺表达与回避明确立场可能混淆，两者要放在同一次权衡里。","warning":"为了维持柔和而不说关键问题。","advice":["把核心诉求缩成一句可重复表达的话。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在巽第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪句话需要被持续、清楚地说出来”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“把核心诉求缩成一句可重复表达的话”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把核心诉求缩成一句可重复表达的话”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把核心诉求缩成一句可重复表达的话”，可以保持小步推进。","pause_if":"若出现“为了维持柔和而不说关键问题”，先暂停扩大投入。"},"action":{"do":"把核心诉求缩成一句可重复表达的话","review":"完成后记录巽九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面来到内外转换处，“渗透与谦顺”开始承受压力测试 当前拉扯在于：若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大柔顺表达与回避明确立场可能混淆 当原有做法显出明确代价，需要及时调整时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“为了维持柔和而不说关键问题”，就暂停扩大动作。","classic":"頻巽，吝。","source":"《周易》爻辞","modern":{"image":"“頻巽，吝。”是巽在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“渗透与谦顺”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大柔顺表达与回避明确立场可能混淆。","warning":"为了维持柔和而不说关键问题。","advice":["把核心诉求缩成一句可重复表达的话。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"修正","meaning":"在巽第3爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“哪句话需要被持续、清楚地说出来”核对判断"},"tone":"转折","extended":{"trigger":{"label":"修正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“为了维持柔和而不说关键问题”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录巽九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：巽来到四位，跨出原有边界之前要先说明责任 原有做法显出明确代价，需要及时调整，是接下来值得核对的信号。完成“把核心诉求缩成一句可重复表达的话”后再看反馈；同时留意为了维持柔和而不说关键问题，而不是把一次说太多却没有后续当成解决办法，而巽第4爻处在“越界”阶段。","classic":"悔亡，田獲三品。","source":"《周易》爻辞","modern":{"image":"“悔亡，田獲三品。”是巽在“越界”阶段留下的具体图景。","situation":"巽来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是柔顺表达与回避明确立场可能混淆，两者要放在同一次权衡里。","warning":"为了维持柔和而不说关键问题，而不是把一次说太多却没有后续当成解决办法，而巽第4爻处在“越界”阶段。","advice":["把核心诉求缩成一句可重复表达的话。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"修正","meaning":"在巽第4爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“哪句话需要被持续、清楚地说出来”核对判断"},"tone":"越界","extended":{"trigger":{"label":"修正","observe":"完成“把核心诉求缩成一句可重复表达的话”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把核心诉求缩成一句可重复表达的话”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把核心诉求缩成一句可重复表达的话”，可以保持小步推进。","pause_if":"若出现“为了维持柔和而不说关键问题，而不是把一次说太多却没有后续当成解决办法，而巽第4爻处在“越界”阶段”，先暂停扩大投入。"},"action":{"do":"把核心诉求缩成一句可重复表达的话","review":"完成后记录巽六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面正在显出边界：这一阶段已进入主位，选择会放大为规则或示范 若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大柔顺表达与回避明确立场可能混淆 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若为了维持柔和而不说关键问题会在此时放大，行动应当收束。","classic":"貞吉，悔亡，无不利。无初有終，先庚三日，後庚三日，吉。","source":"《周易》爻辞","modern":{"image":"“貞吉，悔亡，无不利。无初有終，先庚三日，後庚三日，吉。”是巽在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大柔顺表达与回避明确立场可能混淆。","warning":"为了维持柔和而不说关键问题会在此时放大。","advice":["把核心诉求缩成一句可重复表达的话。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"通达","meaning":"在巽第5爻里，爻辞显示阻力较少，但仍要让行动与实际承载力相称，可用“哪句话需要被持续、清楚地说出来”核对判断"},"tone":"担当","extended":{"trigger":{"label":"通达","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“为了维持柔和而不说关键问题会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录巽九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面走到极处，继续延长旧办法未必带来同等收益 当前拉扯在于：此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是柔顺表达与回避明确立场可能混淆，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“把核心诉求缩成一句可重复表达的话”；若出现“为了维持柔和而不说关键问题”，就暂停扩大动作。","classic":"巽在床下，喪其資斧，貞凶。","source":"《周易》爻辞","modern":{"image":"“巽在床下，喪其資斧，貞凶。”是巽在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是柔顺表达与回避明确立场可能混淆，两者要放在同一次权衡里。","warning":"为了维持柔和而不说关键问题。","advice":["把核心诉求缩成一句可重复表达的话。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在巽第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪句话需要被持续、清楚地说出来”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“把核心诉求缩成一句可重复表达的话”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把核心诉求缩成一句可重复表达的话”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把核心诉求缩成一句可重复表达的话”，可以保持小步推进。","pause_if":"若出现“为了维持柔和而不说关键问题”，先暂停扩大投入。"},"action":{"do":"把核心诉求缩成一句可重复表达的话","review":"完成后记录巽上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"温和而持续的影响，往往比一次强推更深入","strengths":["具备通过沟通和重复积累改变的空间","温和而持续的沟通，比一次强力推动更容易深入人心"],"tensions":["柔顺表达与回避明确立场可能混淆"],"risks":["为了维持柔和而不说关键问题"],"actions":["把核心诉求缩成一句可重复表达的话"],"avoid":["一次说太多却没有后续"],"questions":["哪句话需要被持续、清楚地说出来？"],"extended":{"situation":{"direct":"眼下的重点是温和而持续的影响，往往比一次强推更深入。","support":"已经可以利用的是：具备通过沟通和重复积累改变的空间。","constraint":"仍需核实的是：柔顺表达与回避明确立场可能混淆。"},"relationship":{"inner":"下卦巽，内部动力偏向渗透、调整与持续影响。","outer":"上卦巽，外部处境更受渗透、调整与持续影响影响。","interaction":"内部想以“渗透、调整与持续影响”回应外部的“渗透、调整与持续影响”；两边能否对接，要看“柔顺表达与回避明确立场可能混淆”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“具备通过沟通和重复积累改变的空间”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“把核心诉求缩成一句可重复表达的话”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“一次说太多却没有后续”，风险会被放大。","effect":"最需要防止的是：为了维持柔和而不说关键问题。"},"paths":{"ready":"如果关键条件得到确认，可以继续“把核心诉求缩成一句可重复表达的话”，但仍以小步反馈决定是否扩大。","not_ready":"如果“柔顺表达与回避明确立场可能混淆”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"把核心诉求缩成一句可重复表达的话","observe":"哪句话需要被持续、清楚地说出来？","continue_if":"出现与“具备通过沟通和重复积累改变的空间”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“一次说太多却没有后续”或“为了维持柔和而不说关键问题”的迹象。"}}}},{"id":58,"name":"兑","pinyin":"duì","theme":"喜悦与交流","reflection":"让真诚的交流带来轻松感，也留意别为取悦他人而忽略原则。","source_note":"据《周易》兑卦意象整理","upper_trigram":2,"lower_trigram":2,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：变化尚在根部，先分清已经发生的事实和仍在期待的部分 内在意愿已经出现，外部条件尚未完全成形，而愉快氛围与必要分歧可能互相遮挡也会在这一爻变得具体 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若为了讨好而答应并不认同的事，而不是把用玩笑避开需要承担的对话当成解决办法，而兑第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论，行动应当收束。","classic":"和兌吉。","source":"《周易》爻辞","modern":{"image":"“和兌吉。”是兑在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而愉快氛围与必要分歧可能互相遮挡也会在这一爻变得具体。","warning":"为了讨好而答应并不认同的事，而不是把用玩笑避开需要承担的对话当成解决办法，而兑第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["在友好语气里清楚说出一个真实意见。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在兑第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪些愉快来自真实连接，哪些来自暂时迎合”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“为了讨好而答应并不认同的事，而不是把用玩笑避开需要承担的对话当成解决办法，而兑第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录兑初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"事情开始进入现实协作，“喜悦与交流”要接受反馈检验 当前拉扯在于：真正的拉扯来自愉快氛围与必要分歧可能互相遮挡，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“在友好语气里清楚说出一个真实意见”；若出现“为了讨好而答应并不认同的事会在此时放大”，就暂停扩大动作。","classic":"孚兌，吉，悔亡。","source":"《周易》爻辞","modern":{"image":"“孚兌，吉，悔亡。”是兑在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“喜悦与交流”要接受反馈检验。","tension":"真正的拉扯来自愉快氛围与必要分歧可能互相遮挡，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"为了讨好而答应并不认同的事会在此时放大。","advice":["在友好语气里清楚说出一个真实意见。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在兑第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“哪些愉快来自真实连接，哪些来自暂时迎合”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“在友好语气里清楚说出一个真实意见”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“在友好语气里清楚说出一个真实意见”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“在友好语气里清楚说出一个真实意见”，可以保持小步推进。","pause_if":"若出现“为了讨好而答应并不认同的事会在此时放大”，先暂停扩大投入。"},"action":{"do":"在友好语气里清楚说出一个真实意见","review":"完成后记录兑九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻把变化落在具体环节：兑行至三位，旧方法的边界和新选择的代价同时出现 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意为了讨好而答应并不认同的事。","classic":"來兌，凶。","source":"《周易》爻辞","modern":{"image":"“來兌，凶。”是兑在“转折”阶段留下的具体图景。","situation":"兑行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而愉快氛围与必要分歧可能互相遮挡也会在这一爻变得具体。","warning":"为了讨好而答应并不认同的事。","advice":["在友好语气里清楚说出一个真实意见。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"止损","meaning":"在兑第3爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪些愉快来自真实连接，哪些来自暂时迎合”核对判断"},"tone":"转折","extended":{"trigger":{"label":"止损","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“为了讨好而答应并不认同的事”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录兑六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 真正的拉扯来自愉快氛围与必要分歧可能互相遮挡，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题 可以用“在友好语气里清楚说出一个真实意见”做一次验证；若为了讨好而答应并不认同的事，行动应当收束。","classic":"商兌未寧，介疾有喜。","source":"《周易》爻辞","modern":{"image":"“商兌未寧，介疾有喜。”是兑在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自愉快氛围与必要分歧可能互相遮挡，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"为了讨好而答应并不认同的事。","advice":["在友好语气里清楚说出一个真实意见。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在兑第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪些愉快来自真实连接，哪些来自暂时迎合”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“在友好语气里清楚说出一个真实意见”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“在友好语气里清楚说出一个真实意见”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“在友好语气里清楚说出一个真实意见”，可以保持小步推进。","pause_if":"若出现“为了讨好而答应并不认同的事”，先暂停扩大投入。"},"action":{"do":"在友好语气里清楚说出一个真实意见","review":"完成后记录兑九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面要求从个人得失转向整体结果和持续责任 当前拉扯在于：扩大影响与照顾整体承接能力之间需要平衡，而愉快氛围与必要分歧可能互相遮挡也会在这一爻变得具体 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“为了讨好而答应并不认同的事，而不是把用玩笑避开需要承担的对话当成解决办法，而兑第5爻处在“担当”阶段”，就暂停扩大动作。","classic":"孚于剝，有厲。","source":"《周易》爻辞","modern":{"image":"“孚于剝，有厲。”是兑在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而愉快氛围与必要分歧可能互相遮挡也会在这一爻变得具体。","warning":"为了讨好而答应并不认同的事，而不是把用玩笑避开需要承担的对话当成解决办法，而兑第5爻处在“担当”阶段。","advice":["在友好语气里清楚说出一个真实意见。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在兑第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪些愉快来自真实连接，哪些来自暂时迎合”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“为了讨好而答应并不认同的事，而不是把用玩笑避开需要承担的对话当成解决办法，而兑第5爻处在“担当”阶段”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录兑九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻把变化落在具体环节：当前循环接近上限，“喜悦与交流”需要从继续加力转向收束复盘 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“在友好语气里清楚说出一个真实意见”后再看反馈；同时留意为了讨好而答应并不认同的事会在此时放大。","classic":"引兌。","source":"《周易》爻辞","modern":{"image":"“引兌。”是兑在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“喜悦与交流”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自愉快氛围与必要分歧可能互相遮挡，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"为了讨好而答应并不认同的事会在此时放大。","advice":["在友好语气里清楚说出一个真实意见。","列出应当停止、保留和移交的事项。"],"signal":{"label":"观察","meaning":"在兑第6爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪些愉快来自真实连接，哪些来自暂时迎合”核对判断"},"tone":"收束","extended":{"trigger":{"label":"观察","observe":"完成“在友好语气里清楚说出一个真实意见”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“在友好语气里清楚说出一个真实意见”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“在友好语气里清楚说出一个真实意见”，可以保持小步推进。","pause_if":"若出现“为了讨好而答应并不认同的事会在此时放大”，先暂停扩大投入。"},"action":{"do":"在友好语气里清楚说出一个真实意见","review":"完成后记录兑上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"交流带来的轻松应建立在真实和原则之上","strengths":["有开放表达、互相回应和恢复活力的可能","让真诚的交流带来轻松感，也留意别为取悦他人而忽略原则"],"tensions":["愉快氛围与必要分歧可能互相遮挡"],"risks":["为了讨好而答应并不认同的事"],"actions":["在友好语气里清楚说出一个真实意见"],"avoid":["用玩笑避开需要承担的对话"],"questions":["哪些愉快来自真实连接，哪些来自暂时迎合？"],"extended":{"situation":{"direct":"眼下的重点是交流带来的轻松应建立在真实和原则之上。","support":"已经可以利用的是：有开放表达、互相回应和恢复活力的可能。","constraint":"仍需核实的是：愉快氛围与必要分歧可能互相遮挡。"},"relationship":{"inner":"下卦兑，内部动力偏向交流、回应与协商。","outer":"上卦兑，外部处境更受交流、回应与协商影响。","interaction":"内部想以“交流、回应与协商”回应外部的“交流、回应与协商”；两边能否对接，要看“愉快氛围与必要分歧可能互相遮挡”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“有开放表达、互相回应和恢复活力的可能”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“在友好语气里清楚说出一个真实意见”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用玩笑避开需要承担的对话”，风险会被放大。","effect":"最需要防止的是：为了讨好而答应并不认同的事。"},"paths":{"ready":"如果关键条件得到确认，可以继续“在友好语气里清楚说出一个真实意见”，但仍以小步反馈决定是否扩大。","not_ready":"如果“愉快氛围与必要分歧可能互相遮挡”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"在友好语气里清楚说出一个真实意见","observe":"哪些愉快来自真实连接，哪些来自暂时迎合？","continue_if":"出现与“有开放表达、互相回应和恢复活力的可能”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用玩笑避开需要承担的对话”或“为了讨好而答应并不认同的事”的迹象。"}}}},{"id":59,"name":"涣","pinyin":"huàn","theme":"疏解与凝聚","reflection":"当人心散乱，先疏通情绪与误解，再回到共同目标。","source_note":"据《周易》涣卦意象整理","upper_trigram":5,"lower_trigram":6,"lines":{"1":{"title":"初六","interpretation":"事情刚在“疏解与凝聚”的起点露出端倪，可用条件还不多 当前拉扯在于：此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是释放个人情绪与重建共同方向不是同一件事，两者要放在同一次权衡里 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“只宣泄却不回到事实和目标”，就暂停扩大动作。","classic":"用拯馬壯，吉。","source":"《周易》爻辞","modern":{"image":"“用拯馬壯，吉。”是涣在“潜藏”阶段留下的具体图景。","situation":"事情刚在“疏解与凝聚”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是释放个人情绪与重建共同方向不是同一件事，两者要放在同一次权衡里。","warning":"只宣泄却不回到事实和目标。","advice":["让各方先说出最担心失去的东西。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在涣第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“阻隔被说开以后，大家还能共同守住什么”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“只宣泄却不回到事实和目标”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录涣初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一爻把变化落在具体环节：涣来到二位，个人判断正与资源、规则或他人发生接触 原有做法显出明确代价，需要及时调整，是接下来值得核对的信号。完成“让各方先说出最担心失去的东西”后再看反馈；同时留意只宣泄却不回到事实和目标，而不是把在误解未清时强求一致当成解决办法，而涣第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","classic":"渙奔其机，悔亡。","source":"《周易》爻辞","modern":{"image":"“渙奔其机，悔亡。”是涣在“接触”阶段留下的具体图景。","situation":"涣来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大释放个人情绪与重建共同方向不是同一件事。","warning":"只宣泄却不回到事实和目标，而不是把在误解未清时强求一致当成解决办法，而涣第2爻处在“接触”阶段，还需防止只听见符合期待的回应。","advice":["让各方先说出最担心失去的东西。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"修正","meaning":"在涣第2爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“阻隔被说开以后，大家还能共同守住什么”核对判断"},"tone":"接触","extended":{"trigger":{"label":"修正","observe":"完成“让各方先说出最担心失去的东西”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“让各方先说出最担心失去的东西”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“让各方先说出最担心失去的东西”，可以保持小步推进。","pause_if":"若出现“只宣泄却不回到事实和目标，而不是把在误解未清时强求一致当成解决办法，而涣第2爻处在“接触”阶段，还需防止只听见符合期待的回应”，先暂停扩大投入。"},"action":{"do":"让各方先说出最担心失去的东西","review":"完成后记录涣九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"局面正在显出边界：这一爻处在容易用力过度的位置，调整比加码更重要 此时一面是继续原路与承认需要调整之间发生冲突，另一面是释放个人情绪与重建共同方向不是同一件事，两者要放在同一次权衡里 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若只宣泄却不回到事实和目标会在此时放大，行动应当收束。","classic":"渙其躬，无悔。","source":"《周易》爻辞","modern":{"image":"“渙其躬，无悔。”是涣在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是释放个人情绪与重建共同方向不是同一件事，两者要放在同一次权衡里。","warning":"只宣泄却不回到事实和目标会在此时放大。","advice":["让各方先说出最担心失去的东西。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"修正","meaning":"在涣第3爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“阻隔被说开以后，大家还能共同守住什么”核对判断"},"tone":"转折","extended":{"trigger":{"label":"修正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“只宣泄却不回到事实和目标会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录涣六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"局面已经接近新的层级，旧角色未必还能容纳当前变化 当前拉扯在于：若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大释放个人情绪与重建共同方向不是同一件事 当现实反馈与当前方向开始相互支持时，变化才有现实依据。先做“让各方先说出最担心失去的东西”；若出现“只宣泄却不回到事实和目标”，就暂停扩大动作。","classic":"渙其群，元吉。渙有丘，匪夷所思。","source":"《周易》爻辞","modern":{"image":"“渙其群，元吉。渙有丘，匪夷所思。”是涣在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大释放个人情绪与重建共同方向不是同一件事。","warning":"只宣泄却不回到事实和目标。","advice":["让各方先说出最担心失去的东西。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"顺势","meaning":"在涣第4爻里，爻辞给出较强的正向信号，重点是守住使局面成立的条件，可用“阻隔被说开以后，大家还能共同守住什么”核对判断"},"tone":"越界","extended":{"trigger":{"label":"顺势","observe":"完成“让各方先说出最担心失去的东西”后，观察是否出现“现实反馈与当前方向开始相互支持”的现实反馈。","threshold":"只有当现实中出现与“让各方先说出最担心失去的东西”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“让各方先说出最担心失去的东西”，可以保持小步推进。","pause_if":"若出现“只宣泄却不回到事实和目标”，先暂停扩大投入。"},"action":{"do":"让各方先说出最担心失去的东西","review":"完成后记录涣六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一爻把变化落在具体环节：关键资源与决定权趋向集中，“疏解与凝聚”开始影响更多人 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意只宣泄却不回到事实和目标。","classic":"渙汗其大號，渙王居，无咎。","source":"《周易》爻辞","modern":{"image":"“渙汗其大號，渙王居，无咎。”是涣在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“疏解与凝聚”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是释放个人情绪与重建共同方向不是同一件事，两者要放在同一次权衡里。","warning":"只宣泄却不回到事实和目标。","advice":["让各方先说出最担心失去的东西。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"守正","meaning":"在涣第5爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“阻隔被说开以后，大家还能共同守住什么”核对判断"},"tone":"担当","extended":{"trigger":{"label":"守正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“只宣泄却不回到事实和目标”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录涣九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"局面正在显出边界：涣来到上位，已有路径可能完成使命，也可能因过度而失衡 若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大释放个人情绪与重建共同方向不是同一件事 可以用“让各方先说出最担心失去的东西”做一次验证；若只宣泄却不回到事实和目标，而不是把在误解未清时强求一致当成解决办法，而涣第6爻处在“收束”阶段，行动应当收束。","classic":"渙其血，去逖出，无咎。","source":"《周易》爻辞","modern":{"image":"“渙其血，去逖出，无咎。”是涣在“收束”阶段留下的具体图景。","situation":"涣来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大释放个人情绪与重建共同方向不是同一件事。","warning":"只宣泄却不回到事实和目标，而不是把在误解未清时强求一致当成解决办法，而涣第6爻处在“收束”阶段。","advice":["让各方先说出最担心失去的东西。","列出应当停止、保留和移交的事项。"],"signal":{"label":"守正","meaning":"在涣第6爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“阻隔被说开以后，大家还能共同守住什么”核对判断"},"tone":"收束","extended":{"trigger":{"label":"守正","observe":"完成“让各方先说出最担心失去的东西”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“让各方先说出最担心失去的东西”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“让各方先说出最担心失去的东西”，可以保持小步推进。","pause_if":"若出现“只宣泄却不回到事实和目标，而不是把在误解未清时强求一致当成解决办法，而涣第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"让各方先说出最担心失去的东西","review":"完成后记录涣上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"先疏通隔阂和情绪，分散的人心才可能重新聚拢","strengths":["旧的僵结有机会被松开","当人心散乱，先疏通情绪与误解，再回到共同目标"],"tensions":["释放个人情绪与重建共同方向不是同一件事"],"risks":["只宣泄却不回到事实和目标"],"actions":["让各方先说出最担心失去的东西"],"avoid":["在误解未清时强求一致"],"questions":["阻隔被说开以后，大家还能共同守住什么？"],"extended":{"situation":{"direct":"眼下的重点是先疏通隔阂和情绪，分散的人心才可能重新聚拢。","support":"已经可以利用的是：旧的僵结有机会被松开。","constraint":"仍需核实的是：释放个人情绪与重建共同方向不是同一件事。"},"relationship":{"inner":"下卦坎，内部动力偏向风险、试探与信息缺口。","outer":"上卦巽，外部处境更受渗透、调整与持续影响影响。","interaction":"内部想以“风险、试探与信息缺口”回应外部的“渗透、调整与持续影响”；两边能否对接，要看“释放个人情绪与重建共同方向不是同一件事”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“旧的僵结有机会被松开”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“让各方先说出最担心失去的东西”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“在误解未清时强求一致”，风险会被放大。","effect":"最需要防止的是：只宣泄却不回到事实和目标。"},"paths":{"ready":"如果关键条件得到确认，可以继续“让各方先说出最担心失去的东西”，但仍以小步反馈决定是否扩大。","not_ready":"如果“释放个人情绪与重建共同方向不是同一件事”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"让各方先说出最担心失去的东西","observe":"阻隔被说开以后，大家还能共同守住什么？","continue_if":"出现与“旧的僵结有机会被松开”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“在误解未清时强求一致”或“只宣泄却不回到事实和目标”的迹象。"}}}},{"id":60,"name":"节","pinyin":"jié","theme":"节制与规则","reflection":"清晰的限制能带来自由。为时间、金钱与情绪设一条可执行的线。","source_note":"据《周易》节卦意象整理","upper_trigram":6,"lower_trigram":2,"lines":{"1":{"title":"初九","interpretation":"这一爻把变化落在具体环节：节落在初位，眼下更像在辨认方向，而不是兑现结果 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意制定无法长期遵守的严格标准。","classic":"不出戶庭，无咎。","source":"《周易》爻辞","modern":{"image":"“不出戶庭，无咎。”是节在“潜藏”阶段留下的具体图景。","situation":"节落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自合理边界与过度控制之间需要调整，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"制定无法长期遵守的严格标准。","advice":["为时间或资源设一条可检验的上限。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在节第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“这条限制是在保护价值，还是只在缓解焦虑”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“制定无法长期遵守的严格标准”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录节初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"局面正在显出边界：这一阶段不再只靠设想，回应和基本功开始决定走向 自己的节奏需要与现实反馈相互校准，而合理边界与过度控制之间需要调整也会在这一爻变得具体 可以用“为时间或资源设一条可检验的上限”做一次验证；若制定无法长期遵守的严格标准，行动应当收束。","classic":"不出門庭，凶。","source":"《周易》爻辞","modern":{"image":"“不出門庭，凶。”是节在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而合理边界与过度控制之间需要调整也会在这一爻变得具体。","warning":"制定无法长期遵守的严格标准。","advice":["为时间或资源设一条可检验的上限。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"止损","meaning":"在节第2爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“这条限制是在保护价值，还是只在缓解焦虑”核对判断"},"tone":"接触","extended":{"trigger":{"label":"止损","observe":"完成“为时间或资源设一条可检验的上限”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“为时间或资源设一条可检验的上限”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“为时间或资源设一条可检验的上限”，可以保持小步推进。","pause_if":"若出现“制定无法长期遵守的严格标准”，先暂停扩大投入。"},"action":{"do":"为时间或资源设一条可检验的上限","review":"完成后记录节九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"事情跨入转折带，焦虑可能比事实更快推动决定 当前拉扯在于：真正的拉扯来自合理边界与过度控制之间需要调整，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“制定无法长期遵守的严格标准，而不是把用规则惩罚正常需要当成解决办法，而节第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，就暂停扩大动作。","classic":"不節若，則嗟若，无咎。","source":"《周易》爻辞","modern":{"image":"“不節若，則嗟若，无咎。”是节在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自合理边界与过度控制之间需要调整，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"制定无法长期遵守的严格标准，而不是把用规则惩罚正常需要当成解决办法，而节第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码。","advice":["为时间或资源设一条可检验的上限。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"守正","meaning":"在节第3爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“这条限制是在保护价值，还是只在缓解焦虑”核对判断"},"tone":"转折","extended":{"trigger":{"label":"守正","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“制定无法长期遵守的严格标准，而不是把用规则惩罚正常需要当成解决办法，而节第3爻处在“转折”阶段，还需防止在压力中逞强或仓促加码”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录节六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：事情正由内部走向外部，“节制与规则”需要重新确认位置和权限 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“为时间或资源设一条可检验的上限”后再看反馈；同时留意制定无法长期遵守的严格标准会在此时放大。","classic":"安節，亨。","source":"《周易》爻辞","modern":{"image":"“安節，亨。”是节在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“节制与规则”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而合理边界与过度控制之间需要调整也会在这一爻变得具体。","warning":"制定无法长期遵守的严格标准会在此时放大。","advice":["为时间或资源设一条可检验的上限。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在节第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“这条限制是在保护价值，还是只在缓解焦虑”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“为时间或资源设一条可检验的上限”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“为时间或资源设一条可检验的上限”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“为时间或资源设一条可检验的上限”，可以保持小步推进。","pause_if":"若出现“制定无法长期遵守的严格标准会在此时放大”，先暂停扩大投入。"},"action":{"do":"为时间或资源设一条可检验的上限","review":"完成后记录节六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面正在显出边界：节来到五位，能力之外还要衡量整体承接和长期后果 真正的拉扯来自合理边界与过度控制之间需要调整，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若制定无法长期遵守的严格标准，行动应当收束。","classic":"甘節，吉，往有尚。","source":"《周易》爻辞","modern":{"image":"“甘節，吉，往有尚。”是节在“担当”阶段留下的具体图景。","situation":"节来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自合理边界与过度控制之间需要调整，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"制定无法长期遵守的严格标准。","advice":["为时间或资源设一条可检验的上限。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在节第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“这条限制是在保护价值，还是只在缓解焦虑”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“制定无法长期遵守的严格标准”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录节九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"这一爻处在阶段末端，下一步先要判断什么已经结束 当前拉扯在于：维持既有成果与允许阶段结束之间存在拉扯，而合理边界与过度控制之间需要调整也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“为时间或资源设一条可检验的上限”；若出现“制定无法长期遵守的严格标准”，就暂停扩大动作。","classic":"苦節，貞凶，悔亡。","source":"《周易》爻辞","modern":{"image":"“苦節，貞凶，悔亡。”是节在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而合理边界与过度控制之间需要调整也会在这一爻变得具体。","warning":"制定无法长期遵守的严格标准。","advice":["为时间或资源设一条可检验的上限。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在节第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“这条限制是在保护价值，还是只在缓解焦虑”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“为时间或资源设一条可检验的上限”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“为时间或资源设一条可检验的上限”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“为时间或资源设一条可检验的上限”，可以保持小步推进。","pause_if":"若出现“制定无法长期遵守的严格标准”，先暂停扩大投入。"},"action":{"do":"为时间或资源设一条可检验的上限","review":"完成后记录节上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"清楚而可执行的限制，能够保护真正重要的自由","strengths":["有机会通过规则恢复秩序和余量","清晰的限制能带来自由。为时间、金钱与情绪设一条可执行的线"],"tensions":["合理边界与过度控制之间需要调整"],"risks":["制定无法长期遵守的严格标准"],"actions":["为时间或资源设一条可检验的上限"],"avoid":["用规则惩罚正常需要"],"questions":["这条限制是在保护价值，还是只在缓解焦虑？"],"extended":{"situation":{"direct":"眼下的重点是清楚而可执行的限制，能够保护真正重要的自由。","support":"已经可以利用的是：有机会通过规则恢复秩序和余量。","constraint":"仍需核实的是：合理边界与过度控制之间需要调整。"},"relationship":{"inner":"下卦兑，内部动力偏向交流、回应与协商。","outer":"上卦坎，外部处境更受风险、试探与信息缺口影响。","interaction":"内部想以“交流、回应与协商”回应外部的“风险、试探与信息缺口”；两边能否对接，要看“合理边界与过度控制之间需要调整”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“有机会通过规则恢复秩序和余量”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“为时间或资源设一条可检验的上限”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“用规则惩罚正常需要”，风险会被放大。","effect":"最需要防止的是：制定无法长期遵守的严格标准。"},"paths":{"ready":"如果关键条件得到确认，可以继续“为时间或资源设一条可检验的上限”，但仍以小步反馈决定是否扩大。","not_ready":"如果“合理边界与过度控制之间需要调整”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"为时间或资源设一条可检验的上限","observe":"这条限制是在保护价值，还是只在缓解焦虑？","continue_if":"出现与“有机会通过规则恢复秩序和余量”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“用规则惩罚正常需要”或“制定无法长期遵守的严格标准”的迹象。"}}}},{"id":61,"name":"中孚","pinyin":"zhōng fú","theme":"诚信与内在","reflection":"内心与言行一致时，信任会慢慢生长。先做到对自己诚实。","source_note":"据《周易》中孚卦意象整理","upper_trigram":5,"lower_trigram":2,"lines":{"1":{"title":"初九","interpretation":"局面正在显出边界：这一爻处在起步处，“内在诚实和外在一致，是信任能够生长的基础”仍需低成本试探 若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大坦诚与期待对方立即回应之间有距离 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若用“真诚”要求别人接受自己的全部判断会在此时放大，行动应当收束。","classic":"虞吉，有它不燕。","source":"《周易》爻辞","modern":{"image":"“虞吉，有它不燕。”是中孚在“潜藏”阶段留下的具体图景。","situation":"这一爻处在起步处，“内在诚实和外在一致，是信任能够生长的基础”仍需低成本试探。","tension":"若只顾推进，容易忽略内在意愿已经出现，外部条件尚未完全成形，若只顾防守，又会放大坦诚与期待对方立即回应之间有距离。","warning":"用“真诚”要求别人接受自己的全部判断会在此时放大。","advice":["先承认一个自己也不愿面对的事实。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"可行","meaning":"在中孚第1爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“你的言行在哪一处还没有真正对齐”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"可行","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“用“真诚”要求别人接受自己的全部判断会在此时放大”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录中孚初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"局面正从内部准备转向真实互动，关系与条件逐渐可见 当前拉扯在于：此时一面是自己的节奏需要与现实反馈相互校准，另一面是坦诚与期待对方立即回应之间有距离，两者要放在同一次权衡里 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“先承认一个自己也不愿面对的事实”；若出现“用“真诚”要求别人接受自己的全部判断”，就暂停扩大动作。","classic":"鳴鶴在陰，其子和之；我有好爵，吾與爾靡之。","source":"《周易》爻辞","modern":{"image":"“鳴鶴在陰，其子和之；我有好爵，吾與爾靡之。”是中孚在“接触”阶段留下的具体图景。","situation":"局面正从内部准备转向真实互动，关系与条件逐渐可见。","tension":"此时一面是自己的节奏需要与现实反馈相互校准，另一面是坦诚与期待对方立即回应之间有距离，两者要放在同一次权衡里。","warning":"用“真诚”要求别人接受自己的全部判断。","advice":["先承认一个自己也不愿面对的事实。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在中孚第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“你的言行在哪一处还没有真正对齐”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“先承认一个自己也不愿面对的事实”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“先承认一个自己也不愿面对的事实”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先承认一个自己也不愿面对的事实”，可以保持小步推进。","pause_if":"若出现“用“真诚”要求别人接受自己的全部判断”，先暂停扩大投入。"},"action":{"do":"先承认一个自己也不愿面对的事实","review":"完成后记录中孚九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻把变化落在具体环节：局面来到内外转换处，“诚信与内在”开始承受压力测试 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意用“真诚”要求别人接受自己的全部判断。","classic":"得敵，或鼓或罷，或泣或歌。","source":"《周易》爻辞","modern":{"image":"“得敵，或鼓或罷，或泣或歌。”是中孚在“转折”阶段留下的具体图景。","situation":"局面来到内外转换处，“诚信与内在”开始承受压力测试。","tension":"若只顾推进，容易忽略继续原路与承认需要调整之间发生冲突，若只顾防守，又会放大坦诚与期待对方立即回应之间有距离。","warning":"用“真诚”要求别人接受自己的全部判断。","advice":["先承认一个自己也不愿面对的事实。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"观察","meaning":"在中孚第3爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“你的言行在哪一处还没有真正对齐”核对判断"},"tone":"转折","extended":{"trigger":{"label":"观察","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“用“真诚”要求别人接受自己的全部判断”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录中孚六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"局面正在显出边界：中孚来到四位，跨出原有边界之前要先说明责任 此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是坦诚与期待对方立即回应之间有距离，两者要放在同一次权衡里 可以用“先承认一个自己也不愿面对的事实”做一次验证；若用“真诚”要求别人接受自己的全部判断，而不是把以漂亮表达代替实际兑现当成解决办法，而中孚第4爻处在“越界”阶段，行动应当收束。","classic":"月幾望，馬匹亡，无咎。","source":"《周易》爻辞","modern":{"image":"“月幾望，馬匹亡，无咎。”是中孚在“越界”阶段留下的具体图景。","situation":"中孚来到四位，跨出原有边界之前要先说明责任。","tension":"此时一面是向外推进的需要与边界尚未说清之间互相牵制，另一面是坦诚与期待对方立即回应之间有距离，两者要放在同一次权衡里。","warning":"用“真诚”要求别人接受自己的全部判断，而不是把以漂亮表达代替实际兑现当成解决办法，而中孚第4爻处在“越界”阶段。","advice":["先承认一个自己也不愿面对的事实。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"守正","meaning":"在中孚第4爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“你的言行在哪一处还没有真正对齐”核对判断"},"tone":"越界","extended":{"trigger":{"label":"守正","observe":"完成“先承认一个自己也不愿面对的事实”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先承认一个自己也不愿面对的事实”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先承认一个自己也不愿面对的事实”，可以保持小步推进。","pause_if":"若出现“用“真诚”要求别人接受自己的全部判断，而不是把以漂亮表达代替实际兑现当成解决办法，而中孚第4爻处在“越界”阶段”，先暂停扩大投入。"},"action":{"do":"先承认一个自己也不愿面对的事实","review":"完成后记录中孚六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"这一阶段已进入主位，选择会放大为规则或示范 当前拉扯在于：若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大坦诚与期待对方立即回应之间有距离 当做法、位置与责任边界能够保持一致时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“用“真诚”要求别人接受自己的全部判断会在此时放大”，就暂停扩大动作。","classic":"有孚攣如，无咎。","source":"《周易》爻辞","modern":{"image":"“有孚攣如，无咎。”是中孚在“担当”阶段留下的具体图景。","situation":"这一阶段已进入主位，选择会放大为规则或示范。","tension":"若只顾推进，容易忽略扩大影响与照顾整体承接能力之间需要平衡，若只顾防守，又会放大坦诚与期待对方立即回应之间有距离。","warning":"用“真诚”要求别人接受自己的全部判断会在此时放大。","advice":["先承认一个自己也不愿面对的事实。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"守正","meaning":"在中孚第5爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“你的言行在哪一处还没有真正对齐”核对判断"},"tone":"担当","extended":{"trigger":{"label":"守正","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“用“真诚”要求别人接受自己的全部判断会在此时放大”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录中孚九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"这一爻把变化落在具体环节：局面走到极处，继续延长旧办法未必带来同等收益 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“先承认一个自己也不愿面对的事实”后再看反馈；同时留意用“真诚”要求别人接受自己的全部判断。","classic":"翰音登于天，貞凶。","source":"《周易》爻辞","modern":{"image":"“翰音登于天，貞凶。”是中孚在“收束”阶段留下的具体图景。","situation":"局面走到极处，继续延长旧办法未必带来同等收益。","tension":"此时一面是维持既有成果与允许阶段结束之间存在拉扯，另一面是坦诚与期待对方立即回应之间有距离，两者要放在同一次权衡里。","warning":"用“真诚”要求别人接受自己的全部判断。","advice":["先承认一个自己也不愿面对的事实。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在中孚第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“你的言行在哪一处还没有真正对齐”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“先承认一个自己也不愿面对的事实”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先承认一个自己也不愿面对的事实”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先承认一个自己也不愿面对的事实”，可以保持小步推进。","pause_if":"若出现“用“真诚”要求别人接受自己的全部判断”，先暂停扩大投入。"},"action":{"do":"先承认一个自己也不愿面对的事实","review":"完成后记录中孚上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"内在诚实和外在一致，是信任能够生长的基础","strengths":["有机会通过真实表达建立深层互信","内心与言行一致时，信任会慢慢生长。先做到对自己诚实"],"tensions":["坦诚与期待对方立即回应之间有距离"],"risks":["用“真诚”要求别人接受自己的全部判断"],"actions":["先承认一个自己也不愿面对的事实"],"avoid":["以漂亮表达代替实际兑现"],"questions":["你的言行在哪一处还没有真正对齐？"],"extended":{"situation":{"direct":"眼下的重点是内在诚实和外在一致，是信任能够生长的基础。","support":"已经可以利用的是：有机会通过真实表达建立深层互信。","constraint":"仍需核实的是：坦诚与期待对方立即回应之间有距离。"},"relationship":{"inner":"下卦兑，内部动力偏向交流、回应与协商。","outer":"上卦巽，外部处境更受渗透、调整与持续影响影响。","interaction":"内部想以“交流、回应与协商”回应外部的“渗透、调整与持续影响”；两边能否对接，要看“坦诚与期待对方立即回应之间有距离”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“有机会通过真实表达建立深层互信”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“先承认一个自己也不愿面对的事实”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“以漂亮表达代替实际兑现”，风险会被放大。","effect":"最需要防止的是：用“真诚”要求别人接受自己的全部判断。"},"paths":{"ready":"如果关键条件得到确认，可以继续“先承认一个自己也不愿面对的事实”，但仍以小步反馈决定是否扩大。","not_ready":"如果“坦诚与期待对方立即回应之间有距离”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"先承认一个自己也不愿面对的事实","observe":"你的言行在哪一处还没有真正对齐？","continue_if":"出现与“有机会通过真实表达建立深层互信”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“以漂亮表达代替实际兑现”或“用“真诚”要求别人接受自己的全部判断”的迹象。"}}}},{"id":62,"name":"小过","pinyin":"xiǎo guò","theme":"小心与细节","reflection":"不宜冒进。把注意力放在细节、日常和眼前可完成的事上。","source_note":"据《周易》小过卦意象整理","upper_trigram":4,"lower_trigram":7,"lines":{"1":{"title":"初六","interpretation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分 当前拉扯在于：内在意愿已经出现，外部条件尚未完全成形，而想快速跨越与现实承载力不匹配也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“先确认一项必要条件，不急着扩大投入”；若出现“用重大决定逃避日常修正，而不是把在细节未稳时扩大风险当成解决办法，而小过第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，就暂停扩大动作。","classic":"飛鳥以凶。","source":"《周易》爻辞","modern":{"image":"“飛鳥以凶。”是小过在“潜藏”阶段留下的具体图景。","situation":"变化尚在根部，先分清已经发生的事实和仍在期待的部分。","tension":"内在意愿已经出现，外部条件尚未完全成形，而想快速跨越与现实承载力不匹配也会在这一爻变得具体。","warning":"用重大决定逃避日常修正，而不是把在细节未稳时扩大风险当成解决办法，而小过第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论。","advice":["完成一个成本低但能提供反馈的动作。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"止损","meaning":"在小过第1爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪件小事做对后，会让下一步更清楚”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"止损","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“用重大决定逃避日常修正，而不是把在细节未稳时扩大风险当成解决办法，而小过第1爻处在“潜藏”阶段，还需防止把萌芽当成成熟结论”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录小过初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"这一爻把变化落在具体环节：事情开始进入现实协作，“小心与细节”要接受反馈检验 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“完成一个成本低但能提供反馈的动作”后再看反馈；同时留意用重大决定逃避日常修正会在此时放大。","classic":"過其祖，遇其妣，不及其君，遇其臣，无咎。","source":"《周易》爻辞","modern":{"image":"“過其祖，遇其妣，不及其君，遇其臣，无咎。”是小过在“接触”阶段留下的具体图景。","situation":"事情开始进入现实协作，“小心与细节”要接受反馈检验。","tension":"真正的拉扯来自想快速跨越与现实承载力不匹配，爻位又使自己的节奏需要与现实反馈相互校准成为眼前问题。","warning":"用重大决定逃避日常修正会在此时放大。","advice":["完成一个成本低但能提供反馈的动作。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"守正","meaning":"在小过第2爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“哪件小事做对后，会让下一步更清楚”核对判断"},"tone":"接触","extended":{"trigger":{"label":"守正","observe":"完成“完成一个成本低但能提供反馈的动作”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“完成一个成本低但能提供反馈的动作”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“完成一个成本低但能提供反馈的动作”，可以保持小步推进。","pause_if":"若出现“用重大决定逃避日常修正会在此时放大”，先暂停扩大投入。"},"action":{"do":"完成一个成本低但能提供反馈的动作","review":"完成后记录小过六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"局面正在显出边界：小过行至三位，旧方法的边界和新选择的代价同时出现 继续原路与承认需要调整之间发生冲突，而想快速跨越与现实承载力不匹配也会在这一爻变得具体 可以用“把最担心的后果写明，并准备可撤回方案”做一次验证；若用重大决定逃避日常修正，行动应当收束。","classic":"弗過防之，從或戕之，凶。","source":"《周易》爻辞","modern":{"image":"“弗過防之，從或戕之，凶。”是小过在“转折”阶段留下的具体图景。","situation":"小过行至三位，旧方法的边界和新选择的代价同时出现。","tension":"继续原路与承认需要调整之间发生冲突，而想快速跨越与现实承载力不匹配也会在这一爻变得具体。","warning":"用重大决定逃避日常修正。","advice":["完成一个成本低但能提供反馈的动作。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"止损","meaning":"在小过第3爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪件小事做对后，会让下一步更清楚”核对判断"},"tone":"转折","extended":{"trigger":{"label":"止损","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“用重大决定逃避日常修正”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录小过九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚 当前拉扯在于：真正的拉扯来自想快速跨越与现实承载力不匹配，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题 当现实条件尚不足以支持扩大动作时，变化才有现实依据。先做“完成一个成本低但能提供反馈的动作”；若出现“用重大决定逃避日常修正”，就暂停扩大动作。","classic":"无咎，弗過遇之，往厲必戒，勿用永貞。","source":"《周易》爻辞","modern":{"image":"“无咎，弗過遇之，往厲必戒，勿用永貞。”是小过在“越界”阶段留下的具体图景。","situation":"这一阶段的关键不是更勇敢，而是位置、授权和沟通是否清楚。","tension":"真正的拉扯来自想快速跨越与现实承载力不匹配，爻位又使向外推进的需要与边界尚未说清之间互相牵制成为眼前问题。","warning":"用重大决定逃避日常修正。","advice":["完成一个成本低但能提供反馈的动作。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"暂停","meaning":"在小过第4爻里，爻辞给出明确的收势信号，眼下不宜把意愿直接变成大动作，可用“哪件小事做对后，会让下一步更清楚”核对判断"},"tone":"越界","extended":{"trigger":{"label":"暂停","observe":"完成“完成一个成本低但能提供反馈的动作”后，观察是否出现“现实条件尚不足以支持扩大动作”的现实反馈。","threshold":"只有当现实中出现与“完成一个成本低但能提供反馈的动作”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“完成一个成本低但能提供反馈的动作”，可以保持小步推进。","pause_if":"若出现“用重大决定逃避日常修正”，先暂停扩大投入。"},"action":{"do":"完成一个成本低但能提供反馈的动作","review":"完成后记录小过九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"这一爻把变化落在具体环节：局面要求从个人得失转向整体结果和持续责任 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“请受影响的人指出一项自己未看到的代价”后再看反馈；同时留意用重大决定逃避日常修正，而不是把在细节未稳时扩大风险当成解决办法，而小过第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","classic":"密雲不雨，自我西郊，公弋取彼在穴。","source":"《周易》爻辞","modern":{"image":"“密雲不雨，自我西郊，公弋取彼在穴。”是小过在“担当”阶段留下的具体图景。","situation":"局面要求从个人得失转向整体结果和持续责任。","tension":"扩大影响与照顾整体承接能力之间需要平衡，而想快速跨越与现实承载力不匹配也会在这一爻变得具体。","warning":"用重大决定逃避日常修正，而不是把在细节未稳时扩大风险当成解决办法，而小过第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围。","advice":["完成一个成本低但能提供反馈的动作。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在小过第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“哪件小事做对后，会让下一步更清楚”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“用重大决定逃避日常修正，而不是把在细节未稳时扩大风险当成解决办法，而小过第5爻处在“担当”阶段，还需防止只看成果而忽略责任范围”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录小过六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"局面正在显出边界：当前循环接近上限，“小心与细节”需要从继续加力转向收束复盘 真正的拉扯来自想快速跨越与现实承载力不匹配，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题 可以用“完成一个成本低但能提供反馈的动作”做一次验证；若用重大决定逃避日常修正会在此时放大，行动应当收束。","classic":"弗遇過之，飛鳥離之，凶，是謂災眚。","source":"《周易》爻辞","modern":{"image":"“弗遇過之，飛鳥離之，凶，是謂災眚。”是小过在“收束”阶段留下的具体图景。","situation":"当前循环接近上限，“小心与细节”需要从继续加力转向收束复盘。","tension":"真正的拉扯来自想快速跨越与现实承载力不匹配，爻位又使维持既有成果与允许阶段结束之间存在拉扯成为眼前问题。","warning":"用重大决定逃避日常修正会在此时放大。","advice":["完成一个成本低但能提供反馈的动作。","列出应当停止、保留和移交的事项。"],"signal":{"label":"止损","meaning":"在小过第6爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“哪件小事做对后，会让下一步更清楚”核对判断"},"tone":"收束","extended":{"trigger":{"label":"止损","observe":"完成“完成一个成本低但能提供反馈的动作”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“完成一个成本低但能提供反馈的动作”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“完成一个成本低但能提供反馈的动作”，可以保持小步推进。","pause_if":"若出现“用重大决定逃避日常修正会在此时放大”，先暂停扩大投入。"},"action":{"do":"完成一个成本低但能提供反馈的动作","review":"完成后记录小过上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"局面不宜冒进时，细节和小步比宏大动作可靠","strengths":["眼前仍有许多可完成的小事","不宜冒进。把注意力放在细节、日常和眼前可完成的事上"],"tensions":["想快速跨越与现实承载力不匹配"],"risks":["用重大决定逃避日常修正"],"actions":["完成一个成本低但能提供反馈的动作"],"avoid":["在细节未稳时扩大风险"],"questions":["哪件小事做对后，会让下一步更清楚？"],"extended":{"situation":{"direct":"眼下的重点是局面不宜冒进时，细节和小步比宏大动作可靠。","support":"已经可以利用的是：眼前仍有许多可完成的小事。","constraint":"仍需核实的是：想快速跨越与现实承载力不匹配。"},"relationship":{"inner":"下卦艮，内部动力偏向边界、停止与重新定位。","outer":"上卦震，外部处境更受启动、震动与迅速反应影响。","interaction":"内部想以“边界、停止与重新定位”回应外部的“启动、震动与迅速反应”；两边能否对接，要看“想快速跨越与现实承载力不匹配”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“眼前仍有许多可完成的小事”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“完成一个成本低但能提供反馈的动作”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“在细节未稳时扩大风险”，风险会被放大。","effect":"最需要防止的是：用重大决定逃避日常修正。"},"paths":{"ready":"如果关键条件得到确认，可以继续“完成一个成本低但能提供反馈的动作”，但仍以小步反馈决定是否扩大。","not_ready":"如果“想快速跨越与现实承载力不匹配”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"完成一个成本低但能提供反馈的动作","observe":"哪件小事做对后，会让下一步更清楚？","continue_if":"出现与“眼前仍有许多可完成的小事”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“在细节未稳时扩大风险”或“用重大决定逃避日常修正”的迹象。"}}}},{"id":63,"name":"既济","pinyin":"jì jì","theme":"完成与守成","reflection":"阶段完成后更要维护秩序。复盘、收尾与防微杜渐同样重要。","source_note":"据《周易》既济卦意象整理","upper_trigram":6,"lower_trigram":3,"lines":{"1":{"title":"初九","interpretation":"这一爻把变化落在具体环节：事情刚在“完成与守成”的起点露出端倪，可用条件还不多 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“先确认一项必要条件，不急着扩大投入”后再看反馈；同时留意因为已经成功就忽略微小偏差。","classic":"曳其輪，濡其尾，无咎。","source":"《周易》爻辞","modern":{"image":"“曳其輪，濡其尾，无咎。”是既济在“潜藏”阶段留下的具体图景。","situation":"事情刚在“完成与守成”的起点露出端倪，可用条件还不多。","tension":"此时一面是内在意愿已经出现，外部条件尚未完全成形，另一面是庆祝完成与继续守成之间容易失衡，两者要放在同一次权衡里。","warning":"因为已经成功就忽略微小偏差。","advice":["安排一次复盘并明确维护责任。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"守正","meaning":"在既济第1爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“什么细小问题最可能破坏已经完成的成果”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"守正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“因为已经成功就忽略微小偏差”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录既济初九所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"六二","interpretation":"局面正在显出边界：既济来到二位，个人判断正与资源、规则或他人发生接触 若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大庆祝完成与继续守成之间容易失衡 可以用“安排一次复盘并明确维护责任”做一次验证；若因为已经成功就忽略微小偏差，而不是把立刻开启新项目而不做收尾当成解决办法，而既济第2爻处在“接触”阶段，行动应当收束。","classic":"婦喪其茀，勿逐，七日得。","source":"《周易》爻辞","modern":{"image":"“婦喪其茀，勿逐，七日得。”是既济在“接触”阶段留下的具体图景。","situation":"既济来到二位，个人判断正与资源、规则或他人发生接触。","tension":"若只顾推进，容易忽略自己的节奏需要与现实反馈相互校准，若只顾防守，又会放大庆祝完成与继续守成之间容易失衡。","warning":"因为已经成功就忽略微小偏差，而不是把立刻开启新项目而不做收尾当成解决办法，而既济第2爻处在“接触”阶段。","advice":["安排一次复盘并明确维护责任。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"观察","meaning":"在既济第2爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么细小问题最可能破坏已经完成的成果”核对判断"},"tone":"接触","extended":{"trigger":{"label":"观察","observe":"完成“安排一次复盘并明确维护责任”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“安排一次复盘并明确维护责任”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“安排一次复盘并明确维护责任”，可以保持小步推进。","pause_if":"若出现“因为已经成功就忽略微小偏差，而不是把立刻开启新项目而不做收尾当成解决办法，而既济第2爻处在“接触”阶段”，先暂停扩大投入。"},"action":{"do":"安排一次复盘并明确维护责任","review":"完成后记录既济六二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"九三","interpretation":"这一爻处在容易用力过度的位置，调整比加码更重要 当前拉扯在于：此时一面是继续原路与承认需要调整之间发生冲突，另一面是庆祝完成与继续守成之间容易失衡，两者要放在同一次权衡里 当现实条件尚不足以支持扩大动作时，变化才有现实依据。先做“把最担心的后果写明，并准备可撤回方案”；若出现“因为已经成功就忽略微小偏差会在此时放大”，就暂停扩大动作。","classic":"高宗伐鬼方，三年克之，小人勿用。","source":"《周易》爻辞","modern":{"image":"“高宗伐鬼方，三年克之，小人勿用。”是既济在“转折”阶段留下的具体图景。","situation":"这一爻处在容易用力过度的位置，调整比加码更重要。","tension":"此时一面是继续原路与承认需要调整之间发生冲突，另一面是庆祝完成与继续守成之间容易失衡，两者要放在同一次权衡里。","warning":"因为已经成功就忽略微小偏差会在此时放大。","advice":["安排一次复盘并明确维护责任。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"暂停","meaning":"在既济第3爻里，爻辞给出明确的收势信号，眼下不宜把意愿直接变成大动作，可用“什么细小问题最可能破坏已经完成的成果”核对判断"},"tone":"转折","extended":{"trigger":{"label":"暂停","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实条件尚不足以支持扩大动作”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“因为已经成功就忽略微小偏差会在此时放大”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录既济九三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"六四","interpretation":"这一爻把变化落在具体环节：局面已经接近新的层级，旧角色未必还能容纳当前变化 已有信号仍不足以形成单一结论，是接下来值得核对的信号。完成“安排一次复盘并明确维护责任”后再看反馈；同时留意因为已经成功就忽略微小偏差。","classic":"繻有衣袽，終日戒。","source":"《周易》爻辞","modern":{"image":"“繻有衣袽，終日戒。”是既济在“越界”阶段留下的具体图景。","situation":"局面已经接近新的层级，旧角色未必还能容纳当前变化。","tension":"若只顾推进，容易忽略向外推进的需要与边界尚未说清之间互相牵制，若只顾防守，又会放大庆祝完成与继续守成之间容易失衡。","warning":"因为已经成功就忽略微小偏差。","advice":["安排一次复盘并明确维护责任。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"观察","meaning":"在既济第4爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么细小问题最可能破坏已经完成的成果”核对判断"},"tone":"越界","extended":{"trigger":{"label":"观察","observe":"完成“安排一次复盘并明确维护责任”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“安排一次复盘并明确维护责任”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“安排一次复盘并明确维护责任”，可以保持小步推进。","pause_if":"若出现“因为已经成功就忽略微小偏差”，先暂停扩大投入。"},"action":{"do":"安排一次复盘并明确维护责任","review":"完成后记录既济六四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"九五","interpretation":"局面正在显出边界：关键资源与决定权趋向集中，“完成与守成”开始影响更多人 此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是庆祝完成与继续守成之间容易失衡，两者要放在同一次权衡里 可以用“请受影响的人指出一项自己未看到的代价”做一次验证；若因为已经成功就忽略微小偏差，行动应当收束。","classic":"東鄰殺牛，不如西鄰之禴祭，實受其福。","source":"《周易》爻辞","modern":{"image":"“東鄰殺牛，不如西鄰之禴祭，實受其福。”是既济在“担当”阶段留下的具体图景。","situation":"关键资源与决定权趋向集中，“完成与守成”开始影响更多人。","tension":"此时一面是扩大影响与照顾整体承接能力之间需要平衡，另一面是庆祝完成与继续守成之间容易失衡，两者要放在同一次权衡里。","warning":"因为已经成功就忽略微小偏差。","advice":["安排一次复盘并明确维护责任。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"观察","meaning":"在既济第5爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么细小问题最可能破坏已经完成的成果”核对判断"},"tone":"担当","extended":{"trigger":{"label":"观察","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“因为已经成功就忽略微小偏差”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录既济九五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上六","interpretation":"既济来到上位，已有路径可能完成使命，也可能因过度而失衡 当前拉扯在于：若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大庆祝完成与继续守成之间容易失衡 当已有信号仍不足以形成单一结论时，变化才有现实依据。先做“安排一次复盘并明确维护责任”；若出现“因为已经成功就忽略微小偏差，而不是把立刻开启新项目而不做收尾当成解决办法，而既济第6爻处在“收束”阶段”，就暂停扩大动作。","classic":"濡其首，厲。","source":"《周易》爻辞","modern":{"image":"“濡其首，厲。”是既济在“收束”阶段留下的具体图景。","situation":"既济来到上位，已有路径可能完成使命，也可能因过度而失衡。","tension":"若只顾推进，容易忽略维持既有成果与允许阶段结束之间存在拉扯，若只顾防守，又会放大庆祝完成与继续守成之间容易失衡。","warning":"因为已经成功就忽略微小偏差，而不是把立刻开启新项目而不做收尾当成解决办法，而既济第6爻处在“收束”阶段。","advice":["安排一次复盘并明确维护责任。","列出应当停止、保留和移交的事项。"],"signal":{"label":"观察","meaning":"在既济第6爻里，爻辞没有把结果写成单一结论，更适合把其中的处境和动作当作观察线索，可用“什么细小问题最可能破坏已经完成的成果”核对判断"},"tone":"收束","extended":{"trigger":{"label":"观察","observe":"完成“安排一次复盘并明确维护责任”后，观察是否出现“已有信号仍不足以形成单一结论”的现实反馈。","threshold":"只有当现实中出现与“安排一次复盘并明确维护责任”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“安排一次复盘并明确维护责任”，可以保持小步推进。","pause_if":"若出现“因为已经成功就忽略微小偏差，而不是把立刻开启新项目而不做收尾当成解决办法，而既济第6爻处在“收束”阶段”，先暂停扩大投入。"},"action":{"do":"安排一次复盘并明确维护责任","review":"完成后记录既济上六所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"阶段完成后，维护、复盘和防止松散同样重要","strengths":["已有成果和可运行的秩序","阶段完成后更要维护秩序。复盘、收尾与防微杜渐同样重要"],"tensions":["庆祝完成与继续守成之间容易失衡"],"risks":["因为已经成功就忽略微小偏差"],"actions":["安排一次复盘并明确维护责任"],"avoid":["立刻开启新项目而不做收尾"],"questions":["什么细小问题最可能破坏已经完成的成果？"],"extended":{"situation":{"direct":"眼下的重点是阶段完成后，维护、复盘和防止松散同样重要。","support":"已经可以利用的是：已有成果和可运行的秩序。","constraint":"仍需核实的是：庆祝完成与继续守成之间容易失衡。"},"relationship":{"inner":"下卦离，内部动力偏向辨识、表达与显明。","outer":"上卦坎，外部处境更受风险、试探与信息缺口影响。","interaction":"内部想以“辨识、表达与显明”回应外部的“风险、试探与信息缺口”；两边能否对接，要看“庆祝完成与继续守成之间容易失衡”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“已有成果和可运行的秩序”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“安排一次复盘并明确维护责任”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“立刻开启新项目而不做收尾”，风险会被放大。","effect":"最需要防止的是：因为已经成功就忽略微小偏差。"},"paths":{"ready":"如果关键条件得到确认，可以继续“安排一次复盘并明确维护责任”，但仍以小步反馈决定是否扩大。","not_ready":"如果“庆祝完成与继续守成之间容易失衡”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"安排一次复盘并明确维护责任","observe":"什么细小问题最可能破坏已经完成的成果？","continue_if":"出现与“已有成果和可运行的秩序”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“立刻开启新项目而不做收尾”或“因为已经成功就忽略微小偏差”的迹象。"}}}},{"id":64,"name":"未济","pinyin":"wèi jì","theme":"未成与希望","reflection":"还没完成并不代表失败。检查最后的关键环节，耐心走完过程。","source_note":"据《周易》未济卦意象整理","upper_trigram":3,"lower_trigram":6,"lines":{"1":{"title":"初六","interpretation":"局面正在显出边界：未济落在初位，眼下更像在辨认方向，而不是兑现结果 真正的拉扯来自接近终点的急切可能破坏已有积累，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题 可以用“先确认一项必要条件，不急着扩大投入”做一次验证；若在最后阶段因焦虑而改变全部方案，行动应当收束。","classic":"濡其尾，吝。","source":"《周易》爻辞","modern":{"image":"“濡其尾，吝。”是未济在“潜藏”阶段留下的具体图景。","situation":"未济落在初位，眼下更像在辨认方向，而不是兑现结果。","tension":"真正的拉扯来自接近终点的急切可能破坏已有积累，爻位又使内在意愿已经出现，外部条件尚未完全成形成为眼前问题。","warning":"在最后阶段因焦虑而改变全部方案。","advice":["找出唯一尚未闭合的关键环节。","先确认一项必要条件，不急着扩大投入。"],"signal":{"label":"修正","meaning":"在未济第1爻里，爻辞指出了不适或代价，及时调整仍比勉强维持更有余地，可用“距离完成真正还差哪一个可验证条件”核对判断"},"tone":"潜藏","extended":{"trigger":{"label":"修正","observe":"完成“先确认一项必要条件，不急着扩大投入”后，观察是否出现“原有做法显出明确代价，需要及时调整”的现实反馈。","threshold":"只有当现实中出现与“先确认一项必要条件，不急着扩大投入”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“先确认一项必要条件，不急着扩大投入”，可以保持小步推进。","pause_if":"若出现“在最后阶段因焦虑而改变全部方案”，先暂停扩大投入。"},"action":{"do":"先确认一项必要条件，不急着扩大投入","review":"完成后记录未济初六所指环节的事实变化，不用一次结果替代长期判断。"}}}},"2":{"title":"九二","interpretation":"这一阶段不再只靠设想，回应和基本功开始决定走向 当前拉扯在于：自己的节奏需要与现实反馈相互校准，而接近终点的急切可能破坏已有积累也会在这一爻变得具体 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“找出唯一尚未闭合的关键环节”；若出现“在最后阶段因焦虑而改变全部方案”，就暂停扩大动作。","classic":"曳其輪，貞吉。","source":"《周易》爻辞","modern":{"image":"“曳其輪，貞吉。”是未济在“接触”阶段留下的具体图景。","situation":"这一阶段不再只靠设想，回应和基本功开始决定走向。","tension":"自己的节奏需要与现实反馈相互校准，而接近终点的急切可能破坏已有积累也会在这一爻变得具体。","warning":"在最后阶段因焦虑而改变全部方案。","advice":["找出唯一尚未闭合的关键环节。","用一次真实沟通确认双方理解是否一致。"],"signal":{"label":"可行","meaning":"在未济第2爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“距离完成真正还差哪一个可验证条件”核对判断"},"tone":"接触","extended":{"trigger":{"label":"可行","observe":"完成“找出唯一尚未闭合的关键环节”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“找出唯一尚未闭合的关键环节”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“找出唯一尚未闭合的关键环节”，可以保持小步推进。","pause_if":"若出现“在最后阶段因焦虑而改变全部方案”，先暂停扩大投入。"},"action":{"do":"找出唯一尚未闭合的关键环节","review":"完成后记录未济九二所指环节的事实变化，不用一次结果替代长期判断。"}}}},"3":{"title":"六三","interpretation":"这一爻把变化落在具体环节：事情跨入转折带，焦虑可能比事实更快推动决定 现实中出现了可以核对的新反馈，是接下来值得核对的信号。完成“把最担心的后果写明，并准备可撤回方案”后再看反馈；同时留意在最后阶段因焦虑而改变全部方案，而不是把把暂时未成解释为彻底失败当成解决办法，而未济第3爻处在“转折”阶段。","classic":"未濟，征凶，利涉大川。","source":"《周易》爻辞","modern":{"image":"“未濟，征凶，利涉大川。”是未济在“转折”阶段留下的具体图景。","situation":"事情跨入转折带，焦虑可能比事实更快推动决定。","tension":"真正的拉扯来自接近终点的急切可能破坏已有积累，爻位又使继续原路与承认需要调整之间发生冲突成为眼前问题。","warning":"在最后阶段因焦虑而改变全部方案，而不是把把暂时未成解释为彻底失败当成解决办法，而未济第3爻处在“转折”阶段。","advice":["找出唯一尚未闭合的关键环节。","把最担心的后果写明，并准备可撤回方案。"],"signal":{"label":"止损","meaning":"在未济第3爻里，爻辞直接提示风险，需要先缩小暴露面，再讨论推进，可用“距离完成真正还差哪一个可验证条件”核对判断"},"tone":"转折","extended":{"trigger":{"label":"止损","observe":"完成“把最担心的后果写明，并准备可撤回方案”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“把最担心的后果写明，并准备可撤回方案”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“把最担心的后果写明，并准备可撤回方案”，可以保持小步推进。","pause_if":"若出现“在最后阶段因焦虑而改变全部方案，而不是把把暂时未成解释为彻底失败当成解决办法，而未济第3爻处在“转折”阶段”，先暂停扩大投入。"},"action":{"do":"把最担心的后果写明，并准备可撤回方案","review":"完成后记录未济六三所指环节的事实变化，不用一次结果替代长期判断。"}}}},"4":{"title":"九四","interpretation":"局面正在显出边界：事情正由内部走向外部，“未成与希望”需要重新确认位置和权限 向外推进的需要与边界尚未说清之间互相牵制，而接近终点的急切可能破坏已有积累也会在这一爻变得具体 可以用“找出唯一尚未闭合的关键环节”做一次验证；若在最后阶段因焦虑而改变全部方案会在此时放大，行动应当收束。","classic":"貞吉，悔亡，震用伐鬼方，三年有賞于大國。","source":"《周易》爻辞","modern":{"image":"“貞吉，悔亡，震用伐鬼方，三年有賞于大國。”是未济在“越界”阶段留下的具体图景。","situation":"事情正由内部走向外部，“未成与希望”需要重新确认位置和权限。","tension":"向外推进的需要与边界尚未说清之间互相牵制，而接近终点的急切可能破坏已有积累也会在这一爻变得具体。","warning":"在最后阶段因焦虑而改变全部方案会在此时放大。","advice":["找出唯一尚未闭合的关键环节。","确认谁能决定、谁需知情、谁承担后果。"],"signal":{"label":"可行","meaning":"在未济第4爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“距离完成真正还差哪一个可验证条件”核对判断"},"tone":"越界","extended":{"trigger":{"label":"可行","observe":"完成“找出唯一尚未闭合的关键环节”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“找出唯一尚未闭合的关键环节”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“找出唯一尚未闭合的关键环节”，可以保持小步推进。","pause_if":"若出现“在最后阶段因焦虑而改变全部方案会在此时放大”，先暂停扩大投入。"},"action":{"do":"找出唯一尚未闭合的关键环节","review":"完成后记录未济九四所指环节的事实变化，不用一次结果替代长期判断。"}}}},"5":{"title":"六五","interpretation":"未济来到五位，能力之外还要衡量整体承接和长期后果 当前拉扯在于：真正的拉扯来自接近终点的急切可能破坏已有积累，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题 当现实中出现了可以核对的新反馈时，变化才有现实依据。先做“请受影响的人指出一项自己未看到的代价”；若出现“在最后阶段因焦虑而改变全部方案”，就暂停扩大动作。","classic":"貞吉无悔，君子之光，有孚，吉。","source":"《周易》爻辞","modern":{"image":"“貞吉无悔，君子之光，有孚，吉。”是未济在“担当”阶段留下的具体图景。","situation":"未济来到五位，能力之外还要衡量整体承接和长期后果。","tension":"真正的拉扯来自接近终点的急切可能破坏已有积累，爻位又使扩大影响与照顾整体承接能力之间需要平衡成为眼前问题。","warning":"在最后阶段因焦虑而改变全部方案。","advice":["找出唯一尚未闭合的关键环节。","请受影响的人指出一项自己未看到的代价。"],"signal":{"label":"可行","meaning":"在未济第5爻里，爻辞显示事情存在可行空间，成效取决于能否把条件落实，可用“距离完成真正还差哪一个可验证条件”核对判断"},"tone":"担当","extended":{"trigger":{"label":"可行","observe":"完成“请受影响的人指出一项自己未看到的代价”后，观察是否出现“现实中出现了可以核对的新反馈”的现实反馈。","threshold":"只有当现实中出现与“请受影响的人指出一项自己未看到的代价”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“请受影响的人指出一项自己未看到的代价”，可以保持小步推进。","pause_if":"若出现“在最后阶段因焦虑而改变全部方案”，先暂停扩大投入。"},"action":{"do":"请受影响的人指出一项自己未看到的代价","review":"完成后记录未济六五所指环节的事实变化，不用一次结果替代长期判断。"}}}},"6":{"title":"上九","interpretation":"这一爻把变化落在具体环节：这一爻处在阶段末端，下一步先要判断什么已经结束 做法、位置与责任边界能够保持一致，是接下来值得核对的信号。完成“找出唯一尚未闭合的关键环节”后再看反馈；同时留意在最后阶段因焦虑而改变全部方案。","classic":"有孚于飲酒，无咎。濡其首，有孚，失是。","source":"《周易》爻辞","modern":{"image":"“有孚于飲酒，无咎。濡其首，有孚，失是。”是未济在“收束”阶段留下的具体图景。","situation":"这一爻处在阶段末端，下一步先要判断什么已经结束。","tension":"维持既有成果与允许阶段结束之间存在拉扯，而接近终点的急切可能破坏已有积累也会在这一爻变得具体。","warning":"在最后阶段因焦虑而改变全部方案。","advice":["找出唯一尚未闭合的关键环节。","列出应当停止、保留和移交的事项。"],"signal":{"label":"守正","meaning":"在未济第6爻里，爻辞并非保证自然顺利，而是说在位置和做法恰当时可以免于过失，可用“距离完成真正还差哪一个可验证条件”核对判断"},"tone":"收束","extended":{"trigger":{"label":"守正","observe":"完成“找出唯一尚未闭合的关键环节”后，观察是否出现“做法、位置与责任边界能够保持一致”的现实反馈。","threshold":"只有当现实中出现与“找出唯一尚未闭合的关键环节”相关的反馈，才把它视为局面开始转向。"},"decision":{"continue_if":"若反馈支持“找出唯一尚未闭合的关键环节”，可以保持小步推进。","pause_if":"若出现“在最后阶段因焦虑而改变全部方案”，先暂停扩大投入。"},"action":{"do":"找出唯一尚未闭合的关键环节","review":"完成后记录未济上九所指环节的事实变化，不用一次结果替代长期判断。"}}}}},"modern":{"core":"未完成意味着仍有调整空间，最后环节尤其需要耐心","strengths":["方向尚未关闭，关键步骤仍可修正","还没完成并不代表失败。检查最后的关键环节，耐心走完过程"],"tensions":["接近终点的急切可能破坏已有积累"],"risks":["在最后阶段因焦虑而改变全部方案"],"actions":["找出唯一尚未闭合的关键环节"],"avoid":["把暂时未成解释为彻底失败"],"questions":["距离完成真正还差哪一个可验证条件？"],"extended":{"situation":{"direct":"眼下的重点是未完成意味着仍有调整空间，最后环节尤其需要耐心。","support":"已经可以利用的是：方向尚未关闭，关键步骤仍可修正。","constraint":"仍需核实的是：接近终点的急切可能破坏已有积累。"},"relationship":{"inner":"下卦坎，内部动力偏向风险、试探与信息缺口。","outer":"上卦离，外部处境更受辨识、表达与显明影响。","interaction":"内部想以“风险、试探与信息缺口”回应外部的“辨识、表达与显明”；两边能否对接，要看“接近终点的急切可能破坏已有积累”是否得到确认。","boundary":"这里只描述互动结构，不据此断定他人的真实想法。"},"opportunity":{"condition":"当“方向尚未关闭，关键步骤仍可修正”能够转化为真实回应、资源或权限时，机会才算出现。","evidence":"先用“找出唯一尚未闭合的关键环节”取得一次可核对的反馈。"},"risk":{"trigger":"如果开始出现“把暂时未成解释为彻底失败”，风险会被放大。","effect":"最需要防止的是：在最后阶段因焦虑而改变全部方案。"},"paths":{"ready":"如果关键条件得到确认，可以继续“找出唯一尚未闭合的关键环节”，但仍以小步反馈决定是否扩大。","not_ready":"如果“接近终点的急切可能破坏已有积累”仍无证据支持，先停止加码，回到事实核对与边界澄清。"},"validation":{"do":"找出唯一尚未闭合的关键环节","observe":"距离完成真正还差哪一个可验证条件？","continue_if":"出现与“方向尚未关闭，关键步骤仍可修正”一致的现实反馈，而且新增代价仍可承受。","pause_if":"出现“把暂时未成解释为彻底失败”或“在最后阶段因焦虑而改变全部方案”的迹象。"}}}}];
